INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v11i3.1585', 'RANDOMIZED CLINICAL TRIAL TO EVALUATE THE EFFICACY OF ASHTAMANGAL GHRITA ORAL AND NASYA IN THE MANAGEMENT OF CEREBRAL PALSY.', '1. Shabnam Rajput, 2. Kalpana Patni.', 2020,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Background: Cerebral palsy is one of the most common childhood disabilities, which hinder the development of a child, causing extensive suffering to affected children and their families. According to world health organization about 10% of population have some form of disabilities. Cerebral Palsy can be compared with Vatavyadhi (neurological disorder) manifested in various form like sarvangavata (quadri-plegia), pakshaghata (hemiparesis), ekangavata(monoplegia), pangu and khanja (motor disorder), kampavata, jadatva (mental retadation), mukatva (dumbness)etc. Objective: To evaluate the efficacy of Ashtamangalghrita, in the form of oral medication and as nasya in the management of cerebral palsy. Material and Methods: Total 24 Children with physical and mental developmental disabilities of of age group 01 to 10 years of either sex were randomly divided into two groups, group A received Ashtamangal ghrita (orally) - 1 ml/kg body weight in two divided doses for 3 months and Group B received Pratimarsh Nasya with Ashtamangal ghrita – 2 drops in each nostril 2 times a day for 3 months. Assessments were done on the basis of 5 point grading score of Clinical symptoms of Cerebral Palsy as per standard classification scale for CP, i.e, motor functions were assessed on the basis of CDC Grading Scale for Motor milestones and Teacher’s drooling test. Follow up visit was on every 15th day. Result: Overall effect of therapy shows that there was 34.79% improvement in group A &amp;amp; 37.74% improvement in group B. Results were slightly superior in group B than group A in most of the parameters. Although intergroup comparison of both groups was not-significant or there were no differences in both groups statistically. Group A was slightly superior than group B in following parameters –Head holding, sitting, teacher drooling scale and spasticity. In all the other parameters group B was slightly superior. Conclusion: Clinical efficacy of both Ashtamangal ghrita orally and as nasya on various parameters of Cerebral Palsy showed that both were effective, safe and comparable.', '{"arp_id": "ARP_AYU014138", "portal_id": 14138, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "11", "issue": "3", "pages": "483 - 490", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "NEUROLOGICAL", "disease": "CEREBRAL PALSY (ICD-G80.9)", "keywords": ["Ashtamangal Ghrita"], "original_url": "https://www.ijam.co.in/index.php/ijam/article/view/1585", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=14138", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU014138.pdf", "pdf_sha256": "cbc98ac3270f166ca13454ebf23facbfadfef8fb410c2592dad23ba8305ccc32", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5455/AAM.88853', 'THERAPEUTIC RESPONSE OF AYURVEDIC PREPARATION RAJ NIRWAN BATI ON SEVERE COVID-19 PATIENTS: A DOUBLE-BLIND RANDOMIZED PLACEBO CONTROLLED CLINICAL TRIAL.', '1. Raj Kumar, 2. Ramakant Yadav, 3. Usha Shukla, 4. Naresh Pal Singh, 5. Sushil Kumar Yadav, 6. Sushil Kumar Shukla, 7. Manoj Kumar, 8. Amit Singh.', 2021,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Background: The burden of present pandemic of COVID-19 is increasing exponentially day by day. There is a felt need for research on various treatment options available in the indigenous system of medicine. Ayurvedic (Indian system of medicine) preparations have been proven previously to be effective in many viral illnesses and play an important role in boosting the immunity of the human body. Aim and Objectives: To evaluate the therapeutic response of ayurvedic preparation RNB on severe COVID-19 patients. Methodology: A double-blind randomized placebo controlled clinical trial was conducted on 49 severely ill patients of COVID19 with one arm receiving RNB and the other placebo. Patients were evaluated on day-to-day basis and clinical improvement was assessed by a two-point reduction in patients’ admission status on a six-point ordinal scale. Results: Statistically significant (p=0.003) difference in proportion of conversion of Real Time Polymerase Chain Reaction (RT-PCR) result after six days of intervention was observed in both groups. The mean &amp;#177; SD days required for the patients to become negative by RT-PCR test was shorter in RNB compared (10.1 &amp;#177; 4.1 days) versus 14.4 &amp;#177; 5.9 days in control group of patients and was found to be statistically significant (p=0.012). Average days to achieve two-point improvement on “sixpoint clinical improvement ordinal scale” was shorter in RNB group in comparison to placebo control group (7.9 &amp;#177; 4.1 days versus 11.7 &amp;#177; 4.7, p=0.009). The duration of hospital-stay and oxygen therapy required for management of COVID-19 cases was shorter in RNB intervention patients than in control group. Conclusion: Immunomodulatory, anti-inflammatory, anti-viral and broncho-dilatory properties in ayurvedic formulation makes RNB an ideal drug to act as an adjuvant to standard allopathic treatment against COVID-19 illness even in severely and critically ill patients in the present scenario.', '{"arp_id": "ARP_AYU014846", "portal_id": 14846, "medical_system": "AYURVEDA", "journal": "Annals of Ayurvedic Medicine", "volume": "10", "issue": "3", "pages": "231 - 243", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "INTERNATIONAL PROVISIONAL ASSIGNMENT OF NEW DISEASES OF UNCERTAIN AETIOLOGY AND EMERGENCY USE (COVID-19 (ICPC- A-77|ICD-RA-01))", "keywords": ["Ayurvedic Medicine"], "original_url": "https://www.aamjournal.in/?mno=88853", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=14846", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU014846.pdf", "pdf_sha256": "35e5b2c2115d496d6c806832bdf9eda76685637cce2583a0c4569e2f5ffd7431", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2019/22867', 'RANDOMIZED, DOUBLE-BLIND, PLACEBO-CONTROLLED PHASE II CLINICAL TRIAL ON THE USE OF UNCARIA TOMENTOSA (CAT''S CLAW) FOR AROMATASE INHIBITOR-INDUCED ARTHRALGIA: A PILOT STUDY.', '1. Renan Sordi, 1. Suellen Nastri Castro, 1. Anea Thaumaturgo Lera, 1. Macilon Nonato Irene, 1. Marilia de Melo Farinazzo, 2. Claudia Sette, 2. Daniel de Iracema Gomes Cubero, 2. Ana Luisa de Castro Baccarin, 2. Auro del Giglio.', 2022,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Introduction: Aromatase inhibitors (AI) are widely used in adjuvant breast cancer treatment, and diffuse articular pain secondary to AI use is the most common cause of treatment discontinuation. Uncaria tomentosa (cats claw) has antiinflammatory activity and is used to treat arthrosis and arthritis. Patients and Methods: This prospective, single-center, double-blind, randomized, placebo-controlled phase II study analyzed 70 patients with breast cancer undergoing AI therapy with complaints of arthralgia. The patients received 100 mg of the dry extract of Uncaria tomentosa three times daily for 4 weeks. At the beginning and end of the study, patients answered the Brief Pain Inventory (BPI), Disability Arm, Shoulder, and Hand (DASH), Lequesne, SF-36 Quality of Life questionnaires, completed a visual analog scale (VAS) for pain, and underwent laboratory testing. Results: U. tomentosa was not more effective than the placebo. No evidence of grade 3 or 4 toxicity was found. In addition, no significant differences were seen in laboratory results or inflammatory markers between the two study groups. Conclusion: Dry extract of U. tomentosa was safe but ineffective in reducing AI-induced arthralgia compared with the placebo. Furthermore, the plant extract had no detectable anti-inflammatory activity.', '{"arp_id": "ARP_AYU015810", "portal_id": 15810, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "19", "issue": "1", "pages": "24 - 31", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "OSTEOARTHROSIS OTHER(ICPC-L91|ICD-M13, M15, M18, M19)", "keywords": ["Aromatase Inhibitor"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/22867", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15810", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015810.pdf", "pdf_sha256": "9972df1fa9215cbea080e1106993700d3774b3d795179a25d21582781060d1f3", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v13i3.3036', 'RANDOMIZED CONTROLLED CLINICAL TRIAL TO EVALUATE THE EFFICACY OF ELADI CHURNA IN THE MANAGEMENT OF URDHWAG AMLAPITTA WITH SPECIAL REFERENCE TO GERD.', '1. Jagruti Pagare, 2. Swati Soman.', 2022,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Amlapitta is one of the most common diseases seen in society. The word Amlapitta is made up of Amla and Pitta. Aacharya Kashyapa was the first person who described Amlapitta as a separate disease. Madhav Nidan, Bhavprakash, and Yogratnakara have also described it very well.The disease in which the sour quality of Pitta dosha aggravates and changes to extreme acidic sourness is called Amlapitta. Amlapitta is Annavaha Strotas Vyadhi (gastrointestinal disease), which is caused due to Agnimandya and vitiations of Pachaka Pitta. Urdhwag Amlapitta can be correlated with GERD. Gastroesophageal reflux disease (GERD) is one of the most common gastrointestinal diseases. It is defined on the basis of both esophageal and extra-esophageal symptoms and/or lesions resulting from the reflux of gastric contents into the esophagus. The sign and symptoms of Urdhwag Amlapitta (GERD) are Avipak (Indigestion), Klama (Tiredness), Utklesha (Nausea), Tikta amla udgar (Sour and bitter Belching), Gaurvata (Heaviness), Hruth Kantha Daha (Heart and Throat Burning), and Aruchi (Anorexia).In the present era, consumption of fast food, junk food, anxiety, and depression are the main causes of Amlapitta.In this clinical study, Eladi churna was used, which is described by Yogratnakar in Amlapitta chikitsa .A total of 70 patients were taken, which were divided into two groups of 35 patients for each group. Group A-Eladi Churna (Trial)and Group B- Amlapittapinashak yog as a control drug mentioned in Bhaishajyaratnawali.', '{"arp_id": "ARP_AYU015933", "portal_id": 15933, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "13", "issue": "3", "pages": "792 - 796", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "DIGESTIVE", "disease": "OESOPHAGUS DISEASE(ICPC-D84|ICD-K20, K21, K22, K23)", "keywords": ["Ama"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/3036", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15933", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015933.pdf", "pdf_sha256": "7429034f0a5aa877399d4575bc7eee532b4386e741d7ce4a019b1c60a1bce5f1", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v13i4.3039', 'A RANDOMIZED SINGLE BLIND CONTROLLED CLINICAL TRIAL TO EVALUATE THE EFFICACY OF NIMBA-JAMBU-VASA KWATH YONIPRAKSHALAN IN THE MANAGEMENT OF KAPHAJ YONIVYAPAD W.S.R. TO TRICHOMONAS VAGINITIS.', '1. Tejal Shevkari, 2. Amit Dattatray Shinde, 3. Sonal Suresh Wagh, 4. Ganesh Naikwadi.', 2022,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Kaphaj yonivyapad is one of twenty Yonivyapadas (gynaecological disorders) which shows the symptoms of Picchila Yonistrava (unctuous discharge) and Yonikandu (itching sensation in vagina), yonigat alpavedana (pain in abdomen), yonigat shitata (coldness per vagina) as described by Acharya Charak. According to modern this condition can be compaired with trichomonas vaginitis i.e., type of vaginal infections. On the topic of kaphaj yonivyapad many researchers have done work by taking different drugs, this study was aimed to evaluate the efficacy of Nimba-Jambu-Adulasa Kwath (decoction) yoniprakshalan (vaginal douche). Study was done after ethical committee clearance on 90 patients of kaphaj yonivyapad in OPD of streerog-prasutitantra department of SST’s Ayurved Medical College, Sangamner. Patients were divided into two groups trial group had given Nimba-Jambu-Adulasa Kwath yoniprakshalan and control group had given Triphala Kwath yoniprakshalan for continues 7 days.', '{"arp_id": "ARP_AYU016338", "portal_id": 16338, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "13", "issue": "4", "pages": "873 - 877", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "FEMALE GENITAL SYSTEM INCLUDING BREAST", "disease": "GENITAL TRICHOMONIASIS FEMALE(ICPC-X73|ICD-A59.0)", "keywords": ["Ayurveda"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/3039", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16338", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016338.pdf", "pdf_sha256": "9c747c7e304c7205f376cac8abee5a6557981c8a947bee9e428db92bd6a9e1df", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v13i4.3077', 'A RANDOMIZED CLINICAL TRIAL OF EFFICACY OF MURVADHYA CHURNA IN KAPHAJA KASA WITH SPECIAL REFERENCE TO CHRONIC BORNCHITIS.', '1. Sonali Babasaheb Kamble, 2. Swati Soman, 3. Pallavi Muneshwar.', 2022,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Kaphaj kasa is one of the conditions in which the vitiated cough causes obstruction to the marga of pranavataproducing Ghana (thick sputum), Snigdha (slimy), Bahala (profuse sputum) and Sandra kapham (viscid sputum). Chronic bronchitis is characterized by cough associated with sputum on most days for at least 3 consecutive months for more than 2 successive years. Coughing is stimulated by irritation or inflammation of the respiratory tract which is caused most frequently by infection or sinus drainage secondary to rhinitis. Oral administration of the medicines is one among the important Shamana line of treatment which is easily administered, well accepted and also effective shodhana in adults. Many more herbal combinations are described in Ayurveda and their therapeutic effect on kasa is not yet explored. Hence it is need of us to bring out permanent remedy which will be safe, cheap and effective. Aim: To study the efficacy of Murvadhya Churna in the management of Kaphaj kasa with special reference to chronic bronchitis. Material and methods: A total 90 patients of the age group 16-60 years presenting with signs and symptoms of Kaphaj kasa w.s.r. to Chronic Bronchitis were selected randomly from OPD of the department of Kayachikitsa. The 45 patients of trial group were treated with Murvadhya Churna and 45 patients of control group were subjected to Haritakyadi Gutika', '{"arp_id": "ARP_AYU016349", "portal_id": 16349, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "13", "issue": "4", "pages": "1033 - 1042", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "RESPIRATORY", "disease": "CHRONIC BRONCHITIS(ICPC-R79|ICD-J41, J42)", "keywords": ["Chronic Bronchitis"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/3077", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16349", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016349.pdf", "pdf_sha256": "68f73224a21a1befe6fd2047611ceab54cc629b30d297ab28da05f6d8381a6f8", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v14i1.3265', 'BONE HEALING EFFICACY OF LAKSHAGRISHTIKSHEERADI CHURNA OVER CALCIUM VIT D3 IN AVRANA KANDA BHAGNA (CLOSED FRACTURES OF LONG BONES) - A RANDOMIZED CONTROLLED CLINICAL TRIAL.', '1. Shivay Gupta, 2. Pradeep S Shindhe, 3. Amit Pingat, 4. Ramesh S Killedar.', 2023,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Delayed bone healing or non-union of fractures owns high rate of complications, morbidity and mortality. It possesses enormous burden to both patients and healthcare system. Till now there is no proven molecule which could enhance the process of bone healing. Hence, time tested Lakshagrishtiksheeradi churna, an Ayurvedic formulation is explored for its efficacy in the management of Avrana Kanda Bhagna. Objective: To Evaluate Bone healing efficacy of Lakshagrishtiksheeradi churna in Avrana Kanda Bhagna. Methods: Total 30 patients meeting the inclusion criteria of Avrana Kanda Bhagna, with age group 14-50 years participated in the study. They were randomly divided into two groups. Group A received Lakshagrishtiksheeradi churna 6 grams and group B Tab Calcium 500 mg +VitD3 respectively twice a day for 30days. Assessments were done through various variables like Pain, Tenderness, Swelling and Bone callus index. Follow up visit was on 30th day and 45th day. Results: Study showed that both Lakshagrishtiksheeradi churna and Calcium + Vit D3 produced improvement in most of the variables and were comparable. However, marked improvements were seen in various variables like Pain, Tenderness, Swelling and Bone callus Index. Conclusion: Clinical efficacy showed that Lakshagrishtiksheeradi churna is safe, effective oral medication in the management of Avrana Kanda Bhagna (Closed Fractures of long bones).', '{"arp_id": "ARP_AYU016454", "portal_id": 16454, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "14", "issue": "1", "pages": "145 - 150", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "FRACTURE: OTHER(ICPC-L76|ICD-S02.2, S02.3, S02.4, S02.6, S02.7, S02.8, S02.9, S12, S22, S32, S42, S82.0, T08, T10, T12, T14.2)", "keywords": ["Avrana Kanda Bhagna"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/3265", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16454", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016454.pdf", "pdf_sha256": "90aa44df5d6b34bcaa92ea69d4bb8604a3b6bd74ec327df28e9617aa96d83ab9", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v14i4.3972', 'EFFICACY OF JATYADI KWATHA GANDUSHA IN MANAGEMENT OF PITTAJA MUKHAPAKA WITH SPECIAL REFERENCE TO APHTHOUS ULCER: A RANDOMIZED CONTROLLED CLINICAL TRIAL.', '1. Queency Evangaline Sutnga, 1. Savita S Angadi, 2. Innocent Sutnga.', 2023,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The condition known as Pittaja Mukhapaka is frequently encountered by patients seeking treatment at the outpatient department of the Ears, Nose, and Throat department. This condition is characterized by inflammation, ulceration, and a burning sensation in the oral mucosa, and is often associated with Aphthous ulcers (Pittaja Mukhapaka). Although modern medicine has several treatment options, including anti-inflammatory drugs, topical corticosteroids, and topical tetracyclines, these treatments have limitations. In contrast, Jatyadi Kwath Churna is a traditional polyherbal composition in ayurvedic medicine that has been used to treat oral problems for centuries. This herbal preparation contains Jati Patra, Guduchi, Draksha, Daru Haridra, Yavasa, Haritaki, Vibhitaki, Madhu, and Amlaki, and is indicated for oral problems in the texts Yogaratnakara and Bhaishajya Ratnavali. Material and Methods: This study aims to evaluate the efficacy of Jatyadi Kwatha Gandusha for Mukha Rogas, a study was conducted with 30 subjects randomly allocated to either Group A (receiving Gandusha of Jatyadi Kwatha and Madhu) or Group B (receiving Triphala Kwatha). Result: Both groups experienced complete relief from discomfort, burning sensations, and excessive salivation, on analysis between the groups with a statistically significant p-value results are equally effective in both groups. Conclusion: The study successfully demonstrated the effectiveness of Jatyadi Kwatha Gandusha and Triphala Kwatha in managing Pittaja Mukhapaka.', '{"arp_id": "ARP_AYU017348", "portal_id": 17348, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "14", "issue": "4", "pages": "963 - 975", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "MOUTH/TONGUE/LIP DISEASE(ICPC-D83|ICD-A69.0, A69.1, B00.2, B37.0, K11, K12, K13, K14)", "keywords": ["Ayurvedic Polyherbal Drug"], "original_url": "https://www.ijam.co.in/index.php/ijam/article/view/3972", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=17348", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU017348.pdf", "pdf_sha256": "3883eeaf2d76bc0a4895280b6d5f113ac4d10e683d836d26b64e0b02dfa8a913", "relevance_score": 59.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '21455426', '10.4103/0253-7613.75674', 'A DOUBLE-BLIND, RANDOMIZED, MULTICENTRIC, PLACEBO-CONTROLLED CLINICAL TRIAL OF ANTARTH, A PHYTOMEDICINE, IN THE TREATMENT OF OSTEOARTHRITIS', '1. Anil K Gupta, 2. Kirankumar Acharya, 3. Parag S Sancheti, 4. Ramchana S Joshi.', 2011,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Objective : To test Antarth, a polyherbal phytomedicine, for its efficacy and safety in patients with osteoarthritis (OA) and compared with placebo. Material and Methods : A total of 90 male or female adult patients who were diagnosed clinically and radiologically with OA were recruited in the study. Antarth or placebo was given 2 capsules b.i.d. for 3 months and the patients were assessed every month for its efficacy. Diclofenac sodium was allowed to be taken as rescue medication. Results : After 3 months of treatment, the reduction in severity of pain on Visual Analog Scale (VAS) was more in Antarth group compared to placebo but the difference between the two groups was not significant. However, pain during functioning of disabled joints while walking distance, squatting, sitting cross-legged and climbing steps were significantly reduced in Antarth group compared to placebo (P &amp;lt; 0.05). Reduction in consumption of rescue medication, diclofenac sodium, was more in Antarth than in placebo group.Conclusions : In Patients&#39; Global Assessment, patients treated with Antarth were more satisfied than the ones treated with placebo. Observations were similar in Physicians&#39; Global Assessment too. There were no adverse events in both the groups.', '{"arp_id": "ARP_AYU021805", "portal_id": 21805, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmacology", "volume": "43", "issue": "1", "pages": "69 - 72", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "MUSCULOSKELETAL", "disease": "OSTEOARTHROSIS OF KNEE(ICPC-L90|ICD-M17)", "keywords": ["Functional Disability"], "original_url": "https://journals.lww.com/iphr/fulltext/2011/43010/a_double_blind,_randomized,_multicentric,.15.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=21805", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU021805.pdf", "pdf_sha256": "280be7265acb5bf738a378305640e4ecf0b60a0ce2a0667b4f9a63f01293c43c", "relevance_score": 58.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '23049188', '10.4103/0974-8520.100316.', 'A RANDOMIZED CONTROLLED CLINICAL TRIAL TO ASSESS THE EFFICACY OF NASYA IN REDUCING THE SIGNS AND SYMPTOMS OF CERVICAL SPONDYLOSIS', '1. Radhika C, 2. Vinod Kumar G, 3. Mihirjan K.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: This work was designed to assess the efficacy of Nasya in reducing the signs and symptoms of cervical spondylosis. The patients attending the O. P. D of Department of Kaya Chikitsa and Panchakarma, Government Ayurveda College Hospital, Thiruvananthapuram were enrolled and subjected to the treatment schedule. Total duration of treatment was 21days. The schedule for the first 14 days was similar in both the groups. It included Rooksha Sveda for 7days followed by Patra Pottali Sveda for 7days. During this period, 90 ml Gandharvahastadi Kashaya twice and Guggulu Tiktaka Kashaya once were given internally. After this, in the Nasya group Nasya was done for 7days with Dhanwantaram Tailam (21times Aavartita), Mridu Paka in Madhyama Matra (8Bindu). Along with this Guggulu Tiktaka Kashaya was given thrice. In the control group, Guggulu Tiktaka kashaya alone was given thrice daily. Assessments were done with regard to pain, tenderness, radiation of pain, numbness, range of movements and hand grip strength. These were done before treatment, before nasya, after treatment and after 1month follow-up. The statistical hypothesis was tested using paired &#39;t&#39; test and &#39;Z&#39; test for proportion. The trial proved that conventional management along with Nasya was more efficacious than conventional management alone in reducing the signs and symptoms of cervical spondylosis.', '{"arp_id": "ARP_AYU022249", "portal_id": 22249, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "33", "issue": "1", "pages": "73 - 77", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "NECK SYNDROME(ICPC-L83|ICD-M43.3, M43.4, M43.6, M47.8, M47.9, M48, M50, M53.0, M53.1)", "keywords": ["Cervical Spondylosis"], "original_url": "https://journals.lww.com/aayu/fulltext/2012/33010/a_randomized_controlled_clinical_trial_to_assess.15.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=22249", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU022249.pdf", "pdf_sha256": "3aad974cd571ef421398eb44bbba2cd65c2be5c4faf2898ca29f45aad0dd4005", "relevance_score": 58.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '31408679', '10.1016/j.jep.2019.112153', 'THE ROLE OF GUT MICROBIOTA FOR THE ACTIVITY OF MEDICINAL PLANTS TRADITIONALLY USED IN THE EUROPEAN UNION FOR GASTROINTESTINAL DISORDERS.', '1,2. Timo A.Thumann, 1,2. Eva-MariaPferschy-Wenzig, 2,3. ChristineMoissl-Eichinger, 1,2. RudolfBauer.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance: Many medicinal plants have been traditionally used for the treatment of gastrointestinal disorders. According to the monographs published by the Committee on Herbal Medicinal Products (HMPC) at the European Medicines Agency, currently 44 medicinal plants are recommended in the European Union for the treatment of gastrointestinal disorders based on traditional use. The main indications are functional and chronic gastrointestinal disorders, such as functional dyspepsia and irritable bowel syndrome (IBS), and typical effects of these plants are stimulation of gastric secretion, spasmolytic and carminative effects, soothing effects on the gastrointestinal mucosa, laxative effects, adstringent or antidiarrheal activities, and anti-inflammatory effects. A possible interaction with human gut microbiota has hardly been considered so far, although it is quite likely.Aim of the study: In this review, we aimed to identify and evaluate published studies which have investigated interactions of these plants with the gut microbiome.Results: According to this survey, only a minor portion of the 44 medicinal plants considered in EMA monographs for the treatment of gastrointestinal diseases has been studied so far with regard to potential interactions with gut microbiota. We could identify eight relevant in vitro studies that have been performed with six of these medicinal plants, 17 in vivo studies performed in experimental animals involving seven of the medicinal plants, and three trials in humans performed with two of the plants.The most robust evidence exists for the use of inulin as a prebiotic, and in this context also the prebiotic activity of chicory root has been investigated quite intensively. Flaxseed dietary fibers are also known to be fermented by gut microbiota to short chain fatty acids, leading to prebiotic effects. This could cause a health-beneficial modulation of gut microbiota by flaxseed supplementation. In flaxseed, also other compound classes like lignans and polyunsaturated fatty acids are present, that also have been shown to interact with gut microbiota. Drugs rich in tannins and anthocyanins also interact intensively with gut microbiota, since these compounds reach the colon at high levels in unchanged form. Tannins and anthocyanins are intensively metabolized by certain gut bacteria, leading to the generation of small, bioavailable and potentially bioactive metabolites. Moreover, interaction with these compounds may exert a prebiotic-like effect on gut microbiota.Gut microbial metabolization has also been shown for certain licorice constituents, but their potential effects on gut microbiota still need to be investigated in detail. Only a limited amount of studies investigated the interactions of essential oil- and secoiridoid-containing drugs with human gut microbiota. However, other constituents present in some of these drugs, like curcumin (curcuma), shogaol (ginger), and rosmarinic acid have been shown to be metabolized by human gut microbiota, and preliminary data also indicate potential gut microbiome modulatory effects.To conclude, the interaction with gut microbiota is still not fully investigated for many herbal drugs traditionally used for gastrointestinal disorders, which offers a vast field for future research.', '{"arp_id": "ARP_AYU029269", "portal_id": 29269, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "245", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Drug"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S0378874119312772", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29269", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029269.pdf", "pdf_sha256": "d9b62bbf4a6a7732c8f915c52e1ecff622b65e2afbd7a7185f8b7f484c5c1b6c", "relevance_score": 57.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16091146', '10.1186/1475-2891-4-23', 'CONTROLLED, DOUBLE-BLIND, RANDOMIZED CLINICAL TRIAL TO EVALUATE THE IMPACT OF FRUIT JUICE CONSUMPTION ON THE EVOLUTION OF INFANTS WITH ACUTE DIARRHEA', '1. Valois S, 1. Costa-Ribeiro H Jr, 1. Mattos A, 1. Ribeiro TC, 1. Mendes CM, 2. Lifshitz F.', 2005,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: In order to assess the effects of juice feedings during acute diarrhea a double-blind, randomized study was performed in 90 children, mean age of 10 +/- 4.28 months. Thirty patients with acute diarrhea were fed twice-daily 15 ml/kg of Apple Juice (AJ), 30 received White Grape Juice (WGJ), and 30 were given colored and flavored water (WA) as part of their age appropriate dietary intake. The duration and severity of diarrhea were the main endpoint variables of the study performed in a metabolic unit. The patients were similar among the 3 groups, had diarrhea for 50-64 hours prior to admission, and were dehydrated when admitted to the unit for study. Half of the patients in each group were well nourished and the others had mild to moderate degrees of malnutrition. Rotavirus infection was the agent causing the illness in 63% of the patients. The infants fed juice ingested 14-17% more calories than those given WA, (those receiving AJ and WGJ ingested 95 and 98 Calories/Kg/d respectively) whereas those receiving WA consumed 81 cal/kg/d). The increased energy intake was not at the expense of other foods or milk formula. The mean body weight gain was greater among patients receiving WGJ (+ 50.7 gm) as compared with the patients in the AJ group (+ 18.3 gm) or the patients fed WA (- 0.7 gm) (p = 0.08). The duration of the illness was longer in the infants fed juice as compared with those given WA (p = 0.006), the mean +/- SD duration in hours was 49.4 +/- 32.6, 47.5 +/- 38.9 and 26.5 +/- 27.4 in patients fed AJ, WGJ and WA respectively. All patients improved while ingesting juice and none of them developed persistent diarrhea; most recovered within 50 hours of the beginning of treatment and less than one fourth had diarrhea longer than 96 hours in the unit. The fecal losses were also increased among the juice fed patients (p = 0.001); the mean +/- SD fecal excretion in g/kg/h was 3.94 +/- 2.35, 3.59 +/- 2.35, and 2.19 +/- 1.63 in AJ, WGJ and WA respectively. The stool output was highest during the first day of treatment among all the patients, though those fed AJ had the highest volume of fecal losses and those who received WA had the lowest stool excretion. After the first day of treatment the differences in fecal excretion were not significant. The ability to tolerate carbohydrates during the illness and immediately after recovery was similar among the 3 groups of patients. Intake of juices with different fructose/glucose ratios and osmolarities resulted in more fecal losses and more prolonged diarrhea as compared with water feedings, but the patients given juice ingested more calories and gained more weight, particularly among those being fed the juice with equimolar concentrations of fructose and glucose.', '{"arp_id": "ARP_AYU021825", "portal_id": 21825, "medical_system": "AYURVEDA", "journal": "Nutrition Journal   August", "volume": "4", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "DIGESTIVE", "disease": "FISTULA IN ANO (ICD-K-60.3)", "keywords": ["Acute Diarrhoea"], "original_url": "https://nutritionj.biomedcentral.com/articles/10.1186/1475-2891-4-23", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=21825", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU021825.pdf", "pdf_sha256": "7b772451f74b0f6cab9143523614fde76593b6b004161cd30e108d439384e5f8", "relevance_score": 56.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '26775274', '10.1016/j.jep.2016.01.001', 'METABOLIC ALTERATION IN OBESE DIABETES RATS UPON TREATMENT WITH CENTELLA ASIATICA EXTRACT', '1. Maulidiani, 1. 2. Abas F, 3. Khatib A, 1. Perumal V, 4. Suppaiah V, 4. Ismail A, 5. Hamid M, 1. Shaari K, 1. 6. Lajis NH.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance:‘Pegaga’ is a traditional Malay remedy for a wide range of complaints. Among the &#39;pegaga’, Centella asiatica has been used as a remedy for diabetes mellitus. Thus, we decided to validate this claim by evaluating the in vivo antidiabetic property of C. asiatica (CA) on T2DM rat model using the holistic 1H NMR-based metabolomics approach.Method:In this study, an obese diabetic (mimic of T2DM condition) animal model was developed using Sprague–Dawley rats fed with a high-fat diet and induced into diabetic condition by the treatment of a low dose of streptozotocin (STZ). The effect of C. asiatica extract on the experimental animals was followed based on the changes observed in the urinary and serum metabolites, measured by 1H NMR of urine and blood samples collected over the test period.Results:A long-term treatment of obese diabetic rats with CA extract could reverse the glucose and lipid levels, as well as the tricarboxylic acid cycle and amino acid metabolic disorders, back towards normal states. Biochemical analysis also showed an increase of insulin production in diabetic rats upon treatment of CA extract.Conclusion:This study has provided evidence that clearly supported the traditional use of CA as a remedy for diabetes. NMR-based metabolomics was successfully applied to show that CA produced both anti-hyperglycemic and anti-hyperlipidemic effects on a rat model. In addition to increasing the insulin secretion, the CA extract also ameliorates the metabolic pathways affected in the induced diabectic rats. This study further revealed the potential usage of CA extract in managing diabetes mellitus and the results of this work may contribute towards the further understanding of the underlying molecular mechanism of this herbal remedy', '{"arp_id": "ARP_AYU002913", "portal_id": 2913, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "180", "issue": "-", "pages": "60 - 69", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Centella Asiatica"], "original_url": "http: //www.sciencedirect.com/science/article/pii/S0378874116300034", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2913", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002913.pdf", "pdf_sha256": "3005df8c12cc57e01f6f3e9a30516343e2452cb5a82cdf94c190489ec19567d4", "relevance_score": 55.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '27473604', '10.1016/j.jep.2016.07.071', 'DOSHA PHENOTYPE SPECIFIC AYURVEDA INTERVENTION AMELIORATES ASTHMA SYMPTOMS THROUGH CYTOKINE MODULATIONS: RESULTS OF WHOLE SYSTEM CLINICAL TRIAL.', '1. Kalpana S. Joshi, 2. Tanuja M. Nesari, 2. Amrish P. Dedge, 2. Vikram R. Dhumal, 1. Sushant A. Shengule, 1. Maithili S. Gadgil, 3. Sundeep Salvi, 4. Marthanda Varma Sankaran Valiathan.', 2017,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Ethnopharmacological relevance:Over the past few decades, there have been significant scientific advances leading to improved understanding of asthma as a disease and treatment providing immediate relief. However, prevention of recurrent attacks, exacerbations and disease cure remains a challenge. Ayurveda refers to bronchial asthma as Tamaka Swasa and it is well explained in Charaka Samhita. Management of asthma in Ayurveda includes removal of vitiated Kapha through Shodhana, Shamana procedures, herbal and herbomineral formulations in addition to advising a healthy lifestyle and diet. Several clinical trials on Ayurvedic formulations for treatment of asthma are reported, however, whole system management of asthma has rarely been studied in the manner in which it is actually being practiced. Ayurveda therapeutics provides Dosha specific approaches, which needs biological investigation.Aim of the study:The objective of our study was to investigate lung functions and cytokine changes in Asthmatic individuals in response to Ayurvedic intervention.Methods:The study design was approved by the Institutional Ethics Committee of Tilak Ayurveda Mahavidyalaya (TAMV) &amp;amp; Sheth Tarachand Ramnath Charitable Ayurveda Hospital and followed guidelines of the Declaration of Helsinki and Tokyo for humans. It was conducted as a whole system individualized pragmatic clinical trial and written consent of patients was collected before enrollment.One hundred and fifteen patients with mild-to-moderate asthma were divided into 2 sub-groups depending on their disease subsets and administered phenotype specific ayurvedic interventions. Seventy six asthma patients completed the treatment. Serum IgE levels, blood eosinophil counts, spirometry and blood cytokine levels were measured before the start of treatment and six months at the end of treatment. Age and sex matched healthy participants (n=69) were recruited in the study for comparison of cytokines levels.Results:Significant improvements in FEV1(% predicted) (p&amp;lt;0.0001) and FVC (% predicted) (p=0.0001) was observed in asthmatic patients who underwent Ayurvedic treatment. Circulating levels of IgE (p&amp;lt;0.03) and eosinophil numbers (p=0.001) reduced significantly in the asthmatics after Ayurvedic treatment. This was associated with significant reduction in levels of circulating cytokines. Levels of Th2, Th1 and inflammatory cytokines in the peripheral blood were higher than healthy control participants at baseline (p values &amp;lt;0.0001) and reduced significantly after ayurvedic intervention.Conclusion:This proof of concept study highlights the potential benefits and possible mechanism of Ayurvedic interventions in patients with mild-to-moderate asthma. The interventions significantly reduced IgE and eosinophil count, also improved lung function and reduced levels of circulating Th2 cytokines.', '{"arp_id": "ARP_AYU028425", "portal_id": 28425, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "197", "issue": "-", "pages": "110 - 117", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "RESPIRATORY", "disease": "ASTHMA(ICPC-R96|ICD-J45, J46)", "keywords": ["Asthma"], "original_url": "http: //www.sciencedirect.com/science/article/pii/S0378874116304962", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=28425", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU028425.pdf", "pdf_sha256": "cf8878e5c7b869b96f1c95f30541176c4e37d4248b47ff2db45dee28938034a0", "relevance_score": 55.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '29870788', '10.1016/j.jep.2018.06.001', 'FICUS CARICA AQUEOUS EXTRACT ALLEVIATES DELAYED GASTRIC EMPTYING AND RECOVERS ULCERATIVE COLITIS-ENHANCED ACUTE FUNCTIONAL GASTROINTESTINAL DISORDERS IN RATS.', '1,2. Kais Rtibi, 1. Dhekra Grami, 1. Dalanda Wannes, 1. Slimen Selmi, 2. Mohamed Amri, 1. Hichem Sebai, 1,2. Lamjed Marzouki.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance: Ficus carica fruit, a source of bioactive functional ingredients, have been traditionally long time used for its medicinal benefits as they improve the digestive system, treating constipation and used as a natural laxative.Aim of the study: The recent study was investigated the ameliorative effect of Ficus carica L. aqueous extract (FCAE) on delayed gastric emptying and ulcerative colitis-improved motility disturbances in dextran sulfate sodium (DSS)-induced acute colitis in rats.Materials and methods: Wistar rats were assigned randomly and received 5% DSS for seven days. Ulcerative colitis diagnosis was confirmed by clinical signs, visible fecal blood and histopatological evaluation. The estimation of the action of colitis on TGI and constipation as well as the protective effect of extract, the intestinal biochemical and physiological parameters were measured using the charcoal meal test, loperamide (Lop)-induced constipation as well as spectrophotometric assays. FCAE (150 and 300?mg?kg-1) was administered orally once per day for seven days 1?h after the loperamide treatment. Phenol-red colorimetric method was used to explore the action of FCAE on gastric emptying process.Results: Ulcerative colitis caused a significantly gastrointestinal motility inhibition in normal rats and notably aggravated the constipation in LOP group. Oppositely, FCAE oral intake significantly increased levels of the gastrointestinal transit ratio and gastric emptying by accelerating of their times. Moreover, constipation severity induced by colitis was remarkably reduced in the FCAE treatment group, as demonstrated by a marked management of fecal parameters, water content, oxidative stress indicators, lipid metabolism, and intracellular mediators. Phytochemical analysis of FCAE revealed the presence of carbohydrates, polysaccharides, phenolic acids as gallic acid, chlorogenic acid, syringic acid and ellagic acid, and flavonoids (e.g. rutin, catechin, epicatechin and apeginine).Conclusions: The obtained results indicated that FCAE exhibits a natural laxative effect without provoking diarrhea and ameliorates functional gastrointestinal (GI) and motility disorders thus justifying its traditional usage.', '{"arp_id": "ARP_AYU028888", "portal_id": 28888, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "224", "issue": "-", "pages": "242 - 249", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Acute Gastrointestinal Dysmotility"], "original_url": "https: //www.sciencedirect.com/science/article/pii/S0378874118310821", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=28888", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU028888.pdf", "pdf_sha256": "3a2fa9405534a9ec886d3b46e95490a6a6f371a43eb336628483264e21839fe3", "relevance_score": 55.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '29636788', '10.1155/2018/8159261', 'THERAPEUTIC EFFECT OF CUCUMIS MELO L. EXTRACT ON INSULIN RESISTANCE AND THE GUT MICROBIOME IN LEPOB/LEPOB MICE.', 'Daeun Lee, Jung HwaYoo, Byung-Cheol Lee.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Obesity results in the progression of metabolic disorders, especially type 2 diabetes (T2DM). Obesity-induced insulin resistance (IR) is a causative factor of T2DM morbidity in obese people. It is generally held by clinicians that IR is caused by adiposity related inflammation that is mediated by changes in composite ions in the gut microbiome. This experimental study was designed to investigate the effects of Cucumismelo L. (Cucumis) on obesity-induced IR in genetically leptin-defcientLepob/Lepob mice. Specifically, we examined the anti-inflammatory effects of Cucumis and the effects of Cucumis on the gut microbiota. We evaluated glucose control by measuring FBS, performing the OGTT, quantifying serum IR, calculating the HOMA-IR, and determining the lipid profiles. To see whether inflammation was reduced, we analyzed adipose tissue macrophages as well as monocytes in the blood. We also profiled the gut microbiota to determine whether the ratios of microbial phyla changed. We found that Cucumis improved IR in obese mice and relieved inflammation in adipose tissue and blood. Simultaneously, the microbiota composition ratios changed. In conclusion, administration of Cucumis improved IR by reducing inflammation, thereby changing the gut microbiota composition. Cucumis is thus a promising treatment for obesity-induced insulin resistance and the inflammatory state.', '{"arp_id": "ARP_AYU023335", "portal_id": 23335, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2018", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Inflammatory Effect"], "original_url": "https://www.hindawi.com/journals/ecam/2018/8159261/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23335", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023335.pdf", "pdf_sha256": "3975a579bf97ca23bab22dc5e7866358ad0b20edbf0ff43d9fb2cdb8e42a2ba8", "relevance_score": 55.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '25954317', '10.1155/2015/915087', 'THE EFFECT OF GINGER (ZINGIBER OFFICINALIS) AND ARTICHOKE (CYNARA CARDUNCULUS) EXTRACT SUPPLEMENTATION ON FUNCTIONAL DYSPEPSIA: A RANDOMISED, DOUBLE-BLIND, AND PLACEBO-CONTROLLED CLINICAL TRIAL', '1. Attilio Giacosa, 2. Davide Guido, 2. Mario Grassi, 3. Antonella Riva, 3. PaoloMorazzoni, 3. Ezio Bombardelli, 4. Simone Perna, 4. Milena A. Faliva, 4. Mariangela Rondanelli.', 2015,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Objective:Functional dyspepsia (FD) is a frequent clinical finding in western world. The aimof this study is to compare the efficacy of a ginger and artichoke supplementation versus placebo in the treatment of FD. Methods: A prospective multicentre, double blind, randomized, placebo controlled, parallel-group comparison of the supplement and placebo over a period of 4 weeks was performed. Two capsules/daywere supplied (before lunch and dinner) to 126 FD patients (supplementation/placebo: 65/61). Results:After 14 days of treatment, only supplementation group (SG) showed a significant amelioration (SG: ??S = +1.195 MCA score units (u), ?? = 0.017; placebo: ??P = +0.347 u, ?? = 0.513). The intercept (??) resulted to be significantly higher in SG than in placebo (??S - ??P = +0.848 u, ?? &amp;lt; 0.001). At the end of the study, the advantage of SG versus placebo persists without variation (??S - ??P = +0.077 u, ?? = 0.542). In SG, a significant advantage is observed for nausea (??S - ??P = -0.398 u, ?? &amp;lt; 0.001), epigastric fullness (??S - ??P = -0.241, ?? &amp;lt; 0.001), epigastric pain (??S - ??P = -0.173 u, ?? = 0.002), and bloating (??S - ??P = -0.167 u, ?? = 0.017). Conclusions:The association between ginger and artichoke leaf extracts appears safe and efficacious in the treatment of FD and could represent a promising treatment for this disease.', '{"arp_id": "ARP_AYU022829", "portal_id": 22829, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2015", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "DIGESTIVE", "disease": "FLATULENCE/GAS/BELCHING (ICPC-D08| ICD-R14)", "keywords": ["Functional Dyspepsia"], "original_url": "https://www.hindawi.com/journals/ecam/2015/915087/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=22829", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU022829.pdf", "pdf_sha256": "ad30f52d251e6ff1b4104b86c9ddefc79b3f9089b950f9ea26970c6de7d29ef0", "relevance_score": 55.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '26989426', '10.1155/2016/3948795', 'EFFECTS OF SAFFLOWER YELLOW ON THE TREATMENT OF SEVERE SEPSIS AND SEPTIC SHOCK: A RANDOMIZED CONTROLLED CLINICAL TRIAL', '1. Xiao-jin Li, 1. Ru-rongWang,2. Yan Kang, 1. Jin Liu, 1. Yun-xia Zuo, 3. Xue-feng Zeng, 4. Gong Cheng', 2016,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Objective: To evaluate the clinical effect of safflower yellow on the treatment of severe sepsis and septic shock. Methods: 85 patients with severe sepsis and septic shock were randomly selected to receive either therapy according to the international guidelines for management of severe sepsis and septic shock (Surviving Sepsis Campaign 2012) (control group, n = 45) or conventional therapy plus safflower yellow (study group, n = 40). The 28-day mortality and 28-day Kaplan-Meier survival curves were compared as primary outcomes. Results:The 28-day mortality from all causes and in-hospital mortality were significantly lower in the study group (50%, 17.5%) as compared to the control group (78.58%, 54.76%) (P = 0.007, all causes, P &amp;lt; 0.001, in-hospital), and the 28-day Kaplan-Meier survival curve was higher in the study group than in the control group (P = 0.008, all causes, P &amp;lt; 0.001, in-hospital, Log Rank). 72 hours after treatment, secondary outcomes including heart rate, leukocyte counts, lactate levels, and platelet counts of patients in the study group were ameliorated significantly as compared with the control group. Conclusion: This study offers a potential new strategy employing safflower yellow to more effectively treat patients with severe sepsis and septic shock. This trial is registered with identifier ChiCTR-TRC-14005196.', '{"arp_id": "ARP_AYU022912", "portal_id": 22912, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2016", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "GENERAL/UNSPECIFIED", "disease": "INFECTIOUS DISEASE OTHER/NOS(ICPC-A78|ICD-A20, A21, A22, A23, A24, A25, A26, A27, A28, A30, A31, A32, A38, A39.1, A39.2, A39.3, A39.4, A39.8, A39.9, A40, A41, A42, A43, A44, A48.0, A48.2, A48.3, A48.4, A48.8, A49, A59.8, A59.9, A64, A68, A69.2, A69.8, A69.9, A70, A74.8, A74.9, A75, A77, A78, A79,)", "keywords": ["Safflower Yellow"], "original_url": "http://www.hindawi.com/journals/ecam/2016/3948795/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=22912", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU022912.pdf", "pdf_sha256": "85e235808306ea4728adbe585ee94711568749fa502ee6cf6d1010217c56c9ab", "relevance_score": 55.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '27621519', '10.4103/0257-7941.188174', 'EFFECT OF KARAMARDADI YOGA VERSUS DICLOFENAC SODIUM IN POST-OPERATIVE PAIN MANAGEMENT: A RANDOMIZED COMPARATIVE CLINICAL TRIAL', '1. Rahul Hegana, 2. Hemant Devaraj Toshikhane, 3. Sangeeta Toshikhane, 4. Hetal Amin', 2016,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Introduction: Postoperative pain is Nociceptive i.e., anticipated unavoidable physiological pain which is caused due to tissue trauma. Drugs such as NSAIDs (Non Steroidal Anti Inflammatory Drugs) and Opioids are used for postoperative pain management but are associated with their own drawbacks. Karamardadi Yoga has been in use in Ayurvedic practice for analgesia. It is known to relieve pain and can be used to supplement anaesthesia and also get rid of adverse effect of modern analgesic drugs.Aims and Objective: To study the comparative effect of Karamardadi Yoga and Diclofenac sodium in postoperative pain management.Materials and Methods: Randomized clinical trial with Group A (Control Group: Tab Diclofenac sodium 50 mg as a single dose) and Group B (Trial Group: Cap Karamardadi Yoga 500 mg as a single dose). Those who had undergone haemorrhoidectomy operation under local anaesthesia were selected as per inclusion criteria. Vitals, desirable effect and undesirable effect, total surgical time, requirement of 1st dose of analgesic, requirement of rescue analgesic and pain determined by VAS (Visual Analog Scale) were the assessment criteria and were observed and recorded.Results: Karamardadi Yoga does not show any undesirable or serious ill effects and altered values of vitals as per statistical analysis. As per VAS scale, pain felt by Trial group was earlier than control group. Conclusions: Karamardadi Yoga has analgesic property but its analgesic property and pain threshold capacity is lesser than those of Diclofenac sodium.', '{"arp_id": "ARP_AYU023019", "portal_id": 23019, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "35", "issue": "4", "pages": "217 - 221", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "HAEMORRHOIDS(ICD-K64.8)", "keywords": ["Anaesthesia"], "original_url": "https://journals.lww.com/asol/fulltext/2016/35040/effect_of_karamard_di_yoga_versus_diclofenac.6.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23019", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023019.pdf", "pdf_sha256": "05c714898c1cdddafb72e3c0fac63724208166c3baa4f53f95d12d914b443362", "relevance_score": 55.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '29200747', '10.4103/ayu.AYU_54_15', 'DHATAKYADI VARTI - AN EFFECTIVE LOCAL TREATMENT FOR UPAPLUTA YONIVYAPAD (VULVOVAGINITIS DURING PREGNANCY): A STANDARD CONTROLLED RANDOMIZED CLINICAL TRIAL.', 'Nilofar Mohamad Shafi Shaikh, Laxmipriya Dei, Shilpa Donga.', 2016,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Pregnant women are more prone to vulvovaginitis which is a great challenge for obstetricians today. In Ayurveda, Upapluta Yonivyapad described by Acharya Charaka, Sharangadhara, and both Vagbhata can be compared to vulvovaginitis during pregnancy.Aims: The present study aimed to evaluate efficacy of Dhatakyadi Varti in the management of Upapluta Yonivyapad (vulvovaginitis during pregnancy). Materials and Methods: A total of 80 female patients in the age group of 19-40 years were registered and divided into two groups. In Group A (n = 46), Dhatakyadi Varti was inserted intravaginally, and in Group B (n = 34), Clingen vaginal suppository was inserted intravaginally once at bed time for 14 days. The effect of therapy was assessed on the basis of relief in subjective and objective criteria, i.e., vaginal smear test. Results: In subjective parameters, such as Yoni Srava, Yoni Kandu, Yoni Vedana, Yoni Daha and Yoni Daurgandhya, better result was observed in trial Group A receiving Dhatakyadi Varti. Highly significant relief (P &amp;lt; 0.001) was observed in fungal infection, and significant relief (P = 0.005) was observed in Gram - negative bacterial infection and pus cells in Group A. In Group A, 34.88% patients had complete remission, marked improvement was found in 34.88% cases, and only 2.32% patients remained unchanged, while in Group B, 33.33% patients reported complete remission, marked improvement was found in 10% cases, and 20% patients remained unchanged. Conclusion: It was concluded from the clinical trial that Dhatakyadi Varti is highly effective in reducing subjective and objective variables of Upapluta Yonivyapad and can be introduced as a safe herbal therapy of vaginal discharge during pregnancy.', '{"arp_id": "ARP_AYU023177", "portal_id": 23177, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "37", "issue": "2", "pages": "98 - 104", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "FEMALE GENITAL SYSTEM INCLUDING BREAST", "disease": "VAGINITIS/VULVITIS NOS(ICPC-X84|ICD-N76, N77)", "keywords": ["Clingen Vaginal Suppository"], "original_url": "https://journals.lww.com/aayu/fulltext/2016/37020/dhatakyadi_varti___an_effective_local_treatment.4.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23177", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023177.pdf", "pdf_sha256": "44741859da43f0c8f64b09401862b423b49d270cbb3334b2d6895ab60e982368", "relevance_score": 55.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '29861591', '10.4103/ayu.AYU_17_17', 'SELF-CONTROLLED CLINICAL TRIAL TO EVALUATE THE EFFICACY OF MUKHAKANTIVARDHAKA LEPA AND PATOLADI GHANAVATI IN TWAKVAIVARNYA (HYPERMELANOSIS).', '1. Madhumita Panigrahi, 2. Mahesh Vyas, 3. Kabi Prasad Mohanty.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Beauty is not only a source of joy but also gives confidence to some extent. Ayurvedic cosmetology starts from mother&#39;s womb and continues with Dinacharya (daily routines), Ratricharya (diet and regimen for night), Ritucharya (seasonal diet and regimen), etc. The symbiosis between cosmetology and Ayurveda is the most ancient one. With this research interest, the present study has been undertaken to assess the efficacy of Mukhakantivardhaka Lepa and Patoladi Ghanavati in Tvakvaivarnya (hypermelanosis). Objectives: To evaluate the efficacy of Mukhakantivardhaka Lepa and Patoladi Ghanavati in Tvakvaivarnya (hypermelanosis). Materials and Methods: This study was a double-armed clinical trial in which 62 patients having signs and symptoms of Tvakvaivarnya were selected belonging to the age group of 16–40 years and received Mukhakantivardhaka Lepa and Patoladi Ghanavati for 60 days with follow-up after every week. For the purpose of perfect diagnosis and assessment of all aspects of the disease, a special research proforma was prepared. Results: Both the groups showed 100% improvment in associated symptoms. Regarding the overall effect of therapy in both the groups, moderate improvement was high following marked improvement. No adverse reactions were documented. Conclusion: Mukhakantivardhaka Lepa and Patoladi Ghanavati work excellently on Tvakvaivarnya (hypermelanosis) and improve skin complexion.', '{"arp_id": "ARP_AYU023297", "portal_id": 23297, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "38", "issue": "1-2", "pages": "39 - 45", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "SKIN DISEASE OTHER(ICPC-S99|ICD-L10, L11, L12, L13, L14, L26, L28, L30.2, L30.5, L41, L43, L44, L45, L51, L52, L53.0, L53.1, L53.2, L53.3, L53.8, L54, L60.2, L60.3, L60.8, L68, L71, L72.0, L72.2, L72.8, L72.9, L73.0, L73.1, L73.8, L73.9, L80, L81.1, L81.4, L81.5, L81.6, L81.7, L81.8, L81.9, L82, L8)", "keywords": ["Mukhakantivardhaka Lepa"], "original_url": "https://journals.lww.com/aayu/fulltext/2017/38010/self_controlled_clinical_trial_to_evaluate_the.9.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23297", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023297.pdf", "pdf_sha256": "b873a0581defbbfcbdbbcfc31668f97f20247188c69ece868a18d9e45b81de90", "relevance_score": 55.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '30728848', '10.1155/2019/5952742', 'THE EFFECTS OF SAFFLOWER YELLOW ON ACUTE EXACERBATION OF CHRONIC OBSTRUCTIVE PULMONARY DISEASE: A RANDOMIZED, CONTROLLED CLINICAL TRIAL.', '1,2,3. Xiao-jin Li,1. Yan Kang, 4. Ru-rong Wang, 1. Xue-lian Liao, 1. Xiao-feng Ou, 4. Jin Liu, 4. Yun-xia Zuo.', 2019,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Objectives: To evaluate the efficacy of safflower yellow in the acute exacerbation of chronic obstructive pulmonary disease (AECOPD). Methods. In a prospective, randomized, controlled trial, 127 patients who met the inclusion criteria were enrolled and were randomly divided into two groups. The control group included 64 patients treated according to the global strategy for diagnosis, management, and prevention of COPD (www.goldcopd.org, updated 2011). The intervention group included 63 patients who received intravenous infusions of safflower yellow (100 mg of safflower yellow dissolved in 250 ml 0.9% saline) once daily for 14 consecutive days in addition to standard diagnosis and treatment. The difference in the average length of the hospital stay between the two groups of patients was determined. The follow-up period was 28 days; the differences in symptoms, clinical indicators, and 28-day mortality in the two groups were compared. Statistical analysis was conducted using SPSS 22.0 software to determine whether there were statistically significant differences (P &amp;lt;0.05) between groups. Results. There were no statistically significant differences between the intervention group and the control group in changes in secondary indicators. There were no statistically significant differences in the 28-day mortality or in the survival curves of the two groups (P=0.496 and P=0.075, respectively). Safflower yellow treatment of AECOPD may relieve the patient’s clinical symptoms, such as dyspnoea, shorten the average length of hospital stay (P=0.006, respectively), and decrease the duration of mechanical ventilation.Conclusion: Safflower yellow in the treatment of AECOPD has a degree of clinical value. This trial is registered under the identifier ChiCTR-IPR-17014176.', '{"arp_id": "ARP_AYU023508", "portal_id": 23508, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2019", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "RESPIRATORY", "disease": "CHRON OBSTRUCTIVE PULMONARY DISEASE(ICPC-R95|ICD-J43, J44)", "keywords": ["Acute Exacerbation Of Chronic Obstructive Pulmonary Disease (Aecopd)"], "original_url": "https://www.hindawi.com/journals/ecam/2019/5952742/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23508", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023508.pdf", "pdf_sha256": "ef3205270a07c82150ada9c1eb78c63c0e08e31ddc8c98dfcf8b0be4f30eceac", "relevance_score": 55.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/pj.2021.13.23', 'GC-MS ANALYSIS OF BIOACTIVE COMPOUNDS AND SAFETY ASSESSMENT OF THE ETHANOL EXTRACT OF THE BARKS OF HOLARRHENA PUBESCENS WALL. EX.G.DON (FAMILY APOCYNACEAE): SUB-ACUTE TOXICITY STUDIES IN SWISS ALBINO MICE.', 'Sanjit Namasua, Pankaj Phukan, Meenakshi Bawari.', 2021,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Holarrhena pubescens Wall. ex G. Don belongs to the family Apocynaceae and has several therapeutic applications in traditional medicine. This plant has various pharmacological properties such as antihelmintic, antidiuretic and antidiabetic. One of the major concerns, as they are used, is the lack of adequate pharmacological and toxicological data to support their uses. Objective: The present investigation was carried out to evaluate the safety of an ethanolic extract of Holarrhena pubescens Wall.ex.G.Don (Apocynaceae) by determining its potential toxicity after oral administration for 28 days. Methods: In sub-acute toxicity, the extract at the doses of 250, 500 and 1000mg/kg, bw was administered orally for 28 days. After 28 days of treatment, the mice were decapitated; brain was homogenized for evaluating oxidative stress. The brain was fixed in 10 % formalin and processed for histopathological examinations. Phytochemical analysis of the plant extract was performed by (GC-MS). Result: In the sub-acute study in mice, daily oral administration of HP resulted in a significant increase in the lipid peroxidation of treated animals and a decrease in enzymes activity of CAT, SOD, GPX and GR in both, males and females mice. Histopathological analysis showed alterations in the mice brain cortex. From the GC-MS analysis of the plant extract, it was evident that major phytochemicals were present in the ethanol extract of HP. Some major phytochemicals namely, conessimine (17.81 %); lup-20(29)-en-3-one (16.50%); piperidine, 2-(tetrahydro-2-furanyl)-(6.44%); lup-20(29)-ene-3, 28-diol, (3.beta.) (4.82%) and 17- (1, 5-dimethyl-3-phenylsulfanyl-hex-4-enyl (4.37%) were found. Conclusion: H.pubsecne bark ethanol extract was found to be relatively safe in lower doses although at higher doses it can cause lipid peroxidation and damage to the neuronal cell of the brain and should therefore be used with caution.', '{"arp_id": "ARP_AYU013957", "portal_id": 13957, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Journal", "volume": "13", "issue": "1", "pages": "162 - 171", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Gc-Ms"], "original_url": "http://phcogj.com/article/1346", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=13957", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU013957.pdf", "pdf_sha256": "7d5e65e8fee9974c34621a021fe7962a7cbd4b99db729eb4f1f711092ea53812", "relevance_score": 54.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.7897/2277-4343.1106178', 'A COMPARATIVE RANDOMIZED CLINICAL TRIAL OF NAVAYAS LOUHA SYRUP AND NISHA LOUHA SYRUP IN THE MANAGEMENT OF IRON DEFICIENCY ANEMIA IN THE INDIAN CHILDREN WITH SPECIAL REFERENCE TO PANDU ROGA.', '1. Tiwari Bharti, 2. Tiwari Amar Singh, 3. Gupta Satish Chand.', 2020,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Iron deficiency is the most usual dietary deficiency worldwide, approximately 25% of the world’s population suffering from iron deficiency anemia according to the World Health Organization. A Neonate has total body iron of 250 mg (80 mg/kg), obtained from maternal sources. In the first 6 months of life, during the period when the infant gets an iron-deficient milk diet, this amount decreases to 60 mg/kg. Infants fed with cow’s milk are at greater risk to develop iron deficiency anemia because calcium from cow’s milk is competing with iron for absorption. There are a large number of formulations (like Navayas Louha Syrup, Nisha Louha Syrup etc.) that are mentioned to prevent iron deficiency anemia in Indian children. Despite lack of scientific data regarding the clinical efficacy of Navayas Louha Syrup and Nisha Louha Syrup, an effort has been done to present the current scenario. 60 anemic patients of either sex age between 1-15 years were randomly selected from Kaumarabhritya O.P.D. and I.P.D. of Rani Dullaiya Post Graduate Ayurvedic College and Hospital, Bhopal (M.P), India. Overall, in the study Navayas Louha is 74.53% and Nisha Louha is 69.34% having clinical efficacy. The study was showed in clinical trial efficacy of Navayas Louha syrup is better than Nisha Louha syrup in the management of iron deficiency anemia in Indian children.', '{"arp_id": "ARP_AYU014157", "portal_id": 14157, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Ayurveda and Pharmacy", "volume": "11", "issue": "6", "pages": "16 - 21", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "BLOOD, BLOOD FORMING ORGANS AND IMMUNE MECHANISM", "disease": "IRON DEFICIENCY ANAEMIA(ICPC-B80|ICD-D50)", "keywords": ["Anemia In Indian Children"], "original_url": "https://ijrap.net/index.php/login/abstractt?id=2490", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=14157", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU014157.pdf", "pdf_sha256": "1abbe58b473c50f729b0b10525c676b7e5918ae02dfbd1f5a86b5f84eb60c08c", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v13i2.2576', 'EFFECT OF RAJAT BHASMA AND SWETA MUSALI IN THE MANAGEMENT OF KSHEENASUKRA WITH SPECIAL REFERENCE TO OLIGOSPERMIA - A RANDOMIZED COMPARATIVE OPEN CLINICAL TRIAL.', '1. Prakash Ashok Kumbhar, 2. Huddar VG, 3. Sukumar NN.', 2022,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Male infertility can be defined as an inability to induce conception due to defect in spermatic functions. It is multifactorial condition. In more than 90% of cases, except some physical sperm defects low sperm count and poor sperm quality are responsible for the male infertility in more than 90% of cases. Sperm count less than 20 million/ml is considered as oligospermia. It is correlated to Kshinasukra condition. It is pathological condition of Sukra in which there may be reduced sperm count. In classics many Sukra-janaka (aphrodisiac) drugs have been explained in Kshinasukra. As Sweta musali and Rajata bhasma are explained as vrisya drugs and widely used by practitioners in the management of male infertility. So, present study wasaimedto know the effect of these drugs in the management of oligospermia. Methodology: Diagnosed cases of oligozoospermia were included in the study and divided into two groups by following a block randomization method. Group A received Sweta musali 10gms and Group B received Rajata bhasma 60mg daily for the duration of two months. Semen analysis was done before treatment and till the completion of study at the interval of 30 days. Results and conclusion: Sweta musali and Rajata bhasma were shown significant improvement in the sperm count, total motility and total abnormality as p&amp;lt;0.05. Comparative effect of drugs was shown almost similar effect on seminal parameters with mild variation.', '{"arp_id": "ARP_AYU015796", "portal_id": 15796, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "13", "issue": "2", "pages": "391 - 399", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MALE GENITAL", "disease": "MALE INFERTILITY/SUBFERTILITY (ICPC-Y10|ICD-N46, Z31.0, Z31.4, Z31.6, Z31.8, Z31.9)", "keywords": ["Kshina Sukra"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/2576", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15796", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015796.pdf", "pdf_sha256": "5d47bc818fcad2bdaa2d11f24d0d684de86aca4e0007036de21f15b659070088", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v13i4.3055', 'A SINGLE BLIND RANDOMIZED CONTROLLED CLINICAL TRIAL OF MUNDITIKA CHURNA ADJUVANT CHINNA KWATH IN THE MANAGEMENT OF VATARAKTA WITH SPECIAL REFERENCE TO GOUT.', '1. Rushikesh S Durkunde, 2. NIlesh Dere, 3. Swati Soman.', 2022,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Kayachikitsa is First branch of Ashtang ayurveda described by Vagbhatacharya. Samhitas like Charak Samhita, Shushrut, Vaghbhat Samhita etc. Vatarakta is described as a disease and symptoms also.Vatarakta is a Sammurchana Janit (combined) Vyadhi of Vata and Rakta. The aggravated Vata is being obstructed in its passage by Dushit Rakta. This Vata again vitiates the whole Rakta. This condition is known as Vatarakta. It can be corelated to the Gout disease in modern science due to similar sign and symptoms. Munditika Churna has been mentioned in Chakradutta and Bhaishajyaratnavali is effective in the management of Vatarakta and thus selected as a trial drug. Amrutadi Kwath Previously tested drug is selected for control group.Aim: To evaluate the clinical efficacy of Munditika Churna Adjuvant Chinna Kwath in Management of Vatarakta w.s.r. to Gout. Materials and Method: A total 70 patients of the age group 20-70 years presenting with signs and symptoms of Vatarakta w.s.r Gout were selected randomly from OPD of the department of Kayachikitsa. The 35 patients of trial group were treated with Munditika Churna Adjuvant Chinna Kwath and 35 patients of control group were subjected to Amrutadi Kwath. Results: Munditika Churna Adjuvant Chinna Kwath is effective on Vatarakta. Conclusion: Munditita Churna is an effective, safe and potent treatment of Vatarakta w.s.r. to Gout.', '{"arp_id": "ARP_AYU016353", "portal_id": 16353, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "13", "issue": "4", "pages": "1054 - 1060", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "GOUT(ICPC-T92|ICD-M10)", "keywords": ["Amrutadi Kwath"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/3055", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16353", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016353.pdf", "pdf_sha256": "40b9907f018a6903285184c3bc05dcabb66ba65194b6d4c8ccfd069d6f4c3c62", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2023/30616', 'THE EFFECT OF SIRA VEDHA (PHLEBOTOMY) AT RIGHT ELBOW JOINT IN THE MANAGEMENT OF NON-ALCOHOLIC FATTY LIVER DISEASE - RANDOMIZED CONTROLLED CLINICAL TRIAL.', '1. Gaurav Sawarkar, 2. Priti Desai, 3. Punam Sawarkar.', 2023,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Introduction: Sushruta stated that Sira Vedha (phlebotomy) at Right Elbow Joint was used as a cure for Liver Diseases. Modern science is likewise on the same page as phlebotomy treatment for some liver illnesses, although the specific location for phlebotomy has not been specified. Similarly, there is diversity in the amount of blood extracted and the time length, with each research study recommending a different amount to be removed and the gap between two sessions. Both of the previously listed things are mentioned in the context of Ayurveda. Nonetheless, due to a lack of clinical proof, it cannot be practiced reliably in normal exercise. As a result, clinical proof for liver illnesses is required to confirm Sushruta’s theory. Methodology: 111 eligible patients with Non-Alcoholic Fatty Liver Disease (NAFLD) Grade I/II were randomly assigned to the control (group A) or trial (group B) groups in the pilot research (group B). After obtaining written informed permission, blood samples from each patient were collected for LFT and lipid profile testing. The patients in Group A were then just counseled to make dietary changes. Group B patients underwent dietary changes as well as Sira Vedha (phlebotomy) with 65 cc blood three times in 15 days. Checked hemoglobin before each phlebotomy for safety considerations before discontinuing the patient. The blood sample was taken before enrollment in the study and after the final follow-up, which was on the 60th day. Results: The serum results from the first and last follow-ups were compared. This study found that group B considerably improved in liver enzymes and lipid profile (P&amp;lt;0.050) when compared to group A. As a result, we may infer that phlebotomy can enhance liver enzymes and lipid profiles in NAFLD patients.', '{"arp_id": "ARP_AYU016988", "portal_id": 16988, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "23", "issue": "3", "pages": "879 - 890", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "DIGESTIVE", "disease": "NON ALCOHOLIC FATTY LIVER DISEASE (ICD-K76.0)", "keywords": ["Blood Letting"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/30616", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16988", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016988.pdf", "pdf_sha256": "0bf5001c543c9143371a2c406dbadb5721b0fdd535588aa6cce5c9ff276e6aa7", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2023/32206', 'COMPARISON OF THE EFFECTIVENESS OF AROMATHERAPY MASSAGE WITH GINGER AND SESAME OIL ON JOINT PAIN AND STIFFNESS IN PATIENTS WITH KNEE OSTEOARTHRITIS: A RANDOMIZED CONTROLLED CLINICAL TRIAL.', '1. Ahmad Nasiri Forg, 1,2. Somayeh Hayati, 3. Rezvaneh Manzour, 4. Azam Saedikia, 5. Nahid Salehi Mashhad Taraghi,6. Elham Atabati.', 2023,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Background: This study aimed to compare the effectiveness of aromatherapy massage with ginger and sesame oil on joint pain and stiffness in patients with knee joint osteoarthritis. Methods: This study was performed as a single-blind randomized clinical trial. Ninety patients with osteoarthritis were selected via convenience sampling from patients referring to rheumatology clinics affiliated with Birjand University of Medical Sciences. The subjects were randomly assigned into three groups: massage with oils ginger and sesame, and a control group (no massage). Symptoms were assessed using the Western Ontario McMaster Universities Arthritis Scale (WOMAC) index at baseline at three stages after the intervention (immediately, two weeks, and four weeks). Data analysis was performed with SPSS19 using Chisquare, Friedman and Kruskal-Wallis tests. Results: The findings of the study revealed that the mean pain scores in the ginger and sesame oil groups had a decreasing course before and immediately after the intervention compared to 2 weeks after the intervention. However, the changes in mean score showed an increase again 4 weeks after the intervention (P&amp;lt;0.001). The mean score of joint stiffness in the ginger group suggested a decreasing course before intervention compared to immediately after and two weeks after intervention but showed an increase in changes in the mean score four weeks after intervention (P&amp;lt;0.001). Moreover, the mean score of joint stiffness showed a decreasing course in the sesame group before intervention compared to immediately after intervention but showed an increase in the mean score again two weeks and four weeks after intervention (P&amp;lt;0.001). Conclusions: The results of this study demonstrated that aromatherapy massage with ginger and sesame oils are both effective in improving joint pain and stiffness in patients with osteoarthritis; nonetheless, ginger is more effective in improving joint stiffness in patients with osteoarthritis. Moreover, ginger oil is more stable than sesame oil.', '{"arp_id": "ARP_AYU017187", "portal_id": 17187, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "23", "issue": "4", "pages": "1401 - 1410", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "MUSCULOSKELETAL", "disease": "OSTEOARTHROSIS OF KNEE(ICPC-L90|ICD-M17)", "keywords": ["Aromatherapy"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/32206", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=17187", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU017187.pdf", "pdf_sha256": "3421af89e8b3d86b42d09075c3a5e159cc5b9b078c250079519de36da340a0cc", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/joa.joa_117_20', 'RANDOMIZED CLINICAL TRIAL OF KARNAPICHU WITH GANDHAKATAILA, KARNADHUPANA, AND RASNADIGUGGULU IN THE MANAGEMENT OF KARNASRAVA W. S. R. TO CHRONIC SUPPURATIVE OTITIS MEDIA.', 'Meena Nagar, Gulab Chand Pamnani, Rajena Kumar Soni.', 2021,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Chronic suppurative otitis media (C.S.O.M.) is a chronic inflammation of the middle ear, which is the result of an initial episode of acute otitis media and characterized by the recurrent discharge from the middle ear through a tympanic perforation. In Ayurveda, C.S.O.M. can be correlated with Karnasrava. According to Acharya Sushruta, Karnasrava is &amp;quot;discharge of pus from a Vata affected ear which may result from a head injury or due to immersion in water or else due to suppuration or bursting of an abscess.&amp;quot; In modern science, most of the approaches for the treatment of C.S.O.M. have been surgical, which are often expensive, complicated, and do not provide satisfactory hearing improvement; also these are inaccessible in many developing countries. Considering all these points, there is a need to search for an effective, preventive, and safe treatment.Objective: The objective of this study is to evaluate the efficacy of Karnapichu and Karnadhupana along with Rasnadi Guggulu on Karnasrava. Materials and Methods: A total of 30 patients with signs and symptoms of Karnasrava (C.S.O.M.) were registered and randomly divided into two groups: Group A: 15 patients were treated with Gandhaka Taila Karnapichu (8–16 drops) along with Rasnadi Guggulu orally for 30 days and Group B: 15 patients were treated with Karnadhupana locally and Rasnadi Guggulu orally for 30 days. Results: Both the groups showed highly significant results in the subjective parameters and nonsignificant results in the objective parameters of Karnasrava. Conclusion: Gandhaka Taila Karnapichu, Rasnadi Guggulu, and Karnadhupana are effective in the management of Karnasrava (C.S.O.M.)', '{"arp_id": "ARP_AYU019888", "portal_id": 19888, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "15", "issue": "4", "pages": "249 - 254", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "EAR", "disease": "CHRONIC OTITIS MEDIA(ICPC-H74|ICD-H66.1, H66.2, H66.3, H70, H71, H73.1, H75)", "keywords": ["Chronic Suppurative Otitis Media"], "original_url": "https://journals.lww.com/joay/fulltext/2021/15040/a_randomized_clinical_trial_of_karnapichu_with.3.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19888", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019888.pdf", "pdf_sha256": "a3321dc340591ce627e7779aff175f28e45ec63474875410e92eb3ec9928ad28", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/joa.joa_29_21', 'AN OPEN-LABELLED RANDOMIZED CLINICAL TRIAL FOR THE EVALUATION OF BALAHARIDRADI LEPA WITH AND WITHOUT KHADIRA TWAKA KWATH IN VYANGA (MELASMA).', '1. Sukha Ram, 2. Mita Kotecha, 2. Krutika Jitena Chaudhary.', 2021,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Introduction: Vyanga (Melasma) is a common disorder appearing on the face, causing skin discoloration. Niruja (painless), Tanu (thin), Shyava Varnayukta (hyperpigmentation), and Mandala (circular patches) are the peculiar diagnostic features of the disease. It is categorized as a Kshudra Roga (minor disease) in Ayurveda. Lepa (pack) and Kwath (decoction) are well-known medicines for Vyanga (Melasma). Balaharidradi Lepa and Khadira Twaka Kwath are defined as Vyangahara Dravyas in Ayurvedic Samhitas as they are having Vyangahara, Kushthaghna, Varnya, Krimighna, and Kantikara activity. This study aims to evaluate the effect of Balaharidradi Lepa with and without Khadira Twaka Kwath in Vyanga (Melasma). Materials and Methods: (i) Design: Open-labelled randomized clinical trial of thirty patients of either sex. (ii) Intervention: Group A (15 patients) was given Balaharidradi Lepa and Khadira Twaka Kwath, while Group B (15 patients) treated with Balaharidradi Lepa. (iii) Duration: 2 months. (iv) Outcome measures: photography. Results: All the two groups were compared by Kandu and Von luschan&#39;s color scale statistically significant results were observed in both Groups A and Group B.Conclusion: The present study supports the use of Balaharidradi Lepa and Khadira Twaka Kwath in treating Vyanga with the good acceptance by all treated patients.', '{"arp_id": "ARP_AYU019907", "portal_id": 19907, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "15", "issue": "3", "pages": "163 - 169", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "SKIN DISEASE OTHER(ICPC-S99|ICD-L10, L11, L12, L13, L14, L26, L28, L30.2, L30.5, L41, L43, L44, L45, L51, L52, L53.0, L53.1, L53.2, L53.3, L53.8, L54, L60.2, L60.3, L60.8, L68, L71, L72.0, L72.2, L72.8, L72.9, L73.0, L73.1, L73.8, L73.9, L80, L81.1, L81.4, L81.5, L81.6, L81.7, L81.8, L81.9, L82, L8)", "keywords": ["Ayurveda"], "original_url": "https://journals.lww.com/joay/fulltext/2021/15030/an_open_labelled_randomized_clinical_trial_for_the.3.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19907", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019907.pdf", "pdf_sha256": "b5dc71dec449b6fccecf2c6e2a845da5af54ebb717e7d888365a887dbd548db2", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/joa.joa_198_21', 'STUDY OF TRAYODASHANGA GUGGULU AND SAHACHARADI KWATHA WITH AND WITHOUT GREEVA BASTI IN THE MANAGEMENT OF GREEVASANDHIGATA VATA WITH SPECIAL REFERENCE TO CERVICAL SPONDYLOSIS: A RANDOMIZED COMPARATIVE CLINICAL TRIAL.', '1. Ashok Kumar, 1. Bharatkumar Chhaganbhai Padhar, 1. Meena HML, 2. Sunita Rawat.', 2022,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Introduction: Cervical spondylosis is a common age-related condition characterized by degenerative changes in the intervertebral discs. Neck discomfort is the most prevalent symptom, and it continues to be one of the top causes of disability and growing health-care expenses. About 10 million persons per year suffer from cervical spondylosis in India. The incidence of neck pain is 25%–50% per year in the adult population. Nonsteroidal anti-inflammatory drugs are being used to provide relief in neck pain. The study was planned to assess the effect of Ayurvedic interventions in the management of cervical spondylosis. Methods: A total of 40 clinically diagnosed patients of Greeva Sandhigata Vata were randomly divided into two equal groups by computer generated randomization method. In Group A, patients were treated with Tryodashanaga Guggulu and Sahacharadi Kwath. In Group B, patients were treated with Tryodashanaga Guggulu and Sahacharadi Kwath, along with Greeva Basti (Prasarini Taila). Results: Tryodashanaga Guggulu and Sahacharadi Kwatha had provided 45.24% relief in pain (P = 0.001), 52.92% improvement in Neck Disability Index (P = 0.001), while Tryodashanaga Guggulu and Sahacharadi Kwatha along with Greeva Basti (Prasarini Taila) showed 56.47% relief in pain (P = 0.001) and 64.33% improvement in the Neck Disability Index (P = 0.001) which were statistically highly significant. On comparison, the difference in improvement in Pain (P = 0.007) Neck Disability Index (P = 0.026) was statistically significant.Conclusion: Tryodashanaga Guggulu and Sahacharadi Kwatha along with Greeva Basti (Prasarini Taila) are more effective in the management of cervical spondylosis (Greeva Sandhigata Vata) as compared to Tryodashanaga Guggulu and Sahacharadi Kwatha without Greeva Basti (Prasarini Taila).', '{"arp_id": "ARP_AYU019957", "portal_id": 19957, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "16", "issue": "4", "pages": "293 - 298", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "MUSCULOSKELETAL", "disease": "CERVICAL SPONDYLOSIS ((ICPC-L83|ICD-M47.8)", "keywords": ["Cervical Spondylosis"], "original_url": "https://journals.lww.com/joay/fulltext/2022/16040/study_of_trayodashanga_guggulu_and_sahacharadi.5.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19957", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019957.pdf", "pdf_sha256": "8524c135166312d5e4fa2eaed6e383a17ec520389ea1c285d8cab35a7e58513f", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/joa.joa_297_21', 'A RANDOMIZED CLINICAL TRIAL ON BALYA AND BRIMHANA EFFECT OF CONCENTRATED JUICES OF MADHOOKA PUSHPA (FLOWERS OF MADHUCA INDICA J.F. GMEL).', 'Manjula, Rath Sudipta, Kotecha Mita.', 2023,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Introduction: In present scenario of food crisis, there is a need to explore new plants which can serve nutrition.Methods: Randomized clinical trial was designed; to revalidate efficacy of Madhooka pushpa, quoted Balya-Brimhana by Madanpala-Bhavaprakasha-Priyanighantu; on 90 healthy volunteers (3 groups of 30each). Group A and B were administered Drug D and I 5 g BD with normal water empty stomach for 90 days. Group C was on normal routine diet without any intervention. Subjective and objective parameters analyzed using “Wilcoxon signed rank test,” “KruskalWallis test with posttest” and “Student’s paired t-test,” “ANNOVA” respectively.Results: There was significant improvement in symptoms of overall sarata, Samhanana, Pramana, Satmya, Satva, Aharasakti, Vyayamasakti with 30.92%, 9.09%, 3.75%, 10.59%, 27.46%, 20.31%, 42.73% improvement in Group A and 28.28%, 7.88%, 3.10%, 8.94%, 25.07%, 16.67%, 21.875% improvement in Group B; significant increase in weight, body mass index, chest-midarm-midthigh-abdominal circumference, chest expansion, handgrip power, foot pressure with 3.90%, 4.04%, 1.57%, 3.45%, 2.20%, 1.84%, 19.10%, 15.37%, 6.75% improvement in Group A and 3.81%, 3.18%, 0.50%, 3.34%, 1.93%, 1.28%, 13.77%, 8.73%, 5.98% improvement in Group B; significant decrease in walking time with 11.17% reduction in Group A and 8.71% reduction in Group B.Conclusion: Drugs D and I showed improvement in most parameters, former being slightly more efficacious. (Drug D/D1: Fresh flower juice concentrated by direct heat, Drug I/D2: Fresh flower juice concentrated by indirect heat).', '{"arp_id": "ARP_AYU020005", "portal_id": 20005, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "17", "issue": "4", "pages": "283 - 288", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "NO DISEASE(ICPC-A97|ICD-Z00, Z02)", "keywords": ["Balya"], "original_url": "https://journals.lww.com/joay/fulltext/2023/17040/a_randomized_clinical_trial_on_balya_and_brimhana.3.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20005", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020005.pdf", "pdf_sha256": "a250c9f0e8cff52d9e66a6a1ec8adabdd83348d739401154bdcbad1f30157649", "relevance_score": 54.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'BENEFICIAL EFFECT OF NISHAAKATHAKAADHI KASHAYAM ON STREPTOZOTOCIN INDUCED DIABETES AND GLUCOSE METABOLIC ENZYMES.', '1, 3. Yuvaraj P, 2, 3. Ann Shine Paul, 3. Joy Varghese, 4. Jolly CI.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Polyherbal traditional formulation Nishaakathakaadhi Kashayam elicit antihyperglycemic effects in streptozotocin induced hyperglycemic rats. Nishaakathakaadhi Kashayam 0.6 ml/kg, p.o. significantly reduced the fasted blood glucose level after 60 days of treatment in diabetic rats. The Kashayam also reduced serum cholesterol, triglycerides, LDL, VLDL, alanine transaminase, aspertate transaminase, alkaline phophatase and urea whereas increased HDL, albumin, protein and haemoglobin levels become normal after the treatment. Glycolytic enzyme showed a significant increases in Streptozotocin induced condition while a significant decrease were observed in levels of the gluconeogenic enzymes in Nishaakathakaadhi Kashayam treated diabetic rats. The Kashayam was non-significantly active with standard drug Glibenclamide (0.6 mg/kg, p.o.). The Kashayam has a positive effect on the histopathological changes of the pancreatic beta cells in Streptozotocin induced diabetic rats. The results suggest that Nishaakathakaadhi Kashayam possesses potential antihyperglycemic effect by regulating glucose homeostasis in streptozotocin induced diabetic rats. The scientific evidences to antidiabetic use suggest that administration of polyherbal formulation to rats, in a dosage used safely by humans, reduces the production of various diabetes causing biochemical parameters and concomitantly prevents the development of Type 2 (NIDDM) diabetes in established animal models. A combination of different herbals in NKK is used to get the enhanced desired activity.', '{"arp_id": "ARP_AYU011869", "portal_id": 11869, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda and Pharma Research", "volume": "5", "issue": "7", "pages": "20 - 25", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetes Mellitus"], "original_url": "https://ijapr.in/index.php/ijapr/article/view/714", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11869", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011869.pdf", "pdf_sha256": "3ceafe9e0dd94154031efe0df88cd2a84b730b3e60979359b149841014a4f710", "relevance_score": 53.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL EVALUATION OF BILVADI LEHA IN THE MANAGEMENT OF GRAHANI DOSHA WITH SPECIAL REFERENCE IRRITABLE BOWEL SYNDROME (IBS).', '1. Gurpreet Kaur, 2. Naresh K. Kumawat, 3. Munesh Kumar, 4. Daya Shankar Mishra.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: IBS is chronic relapsing disorder of gastrointestinal function, the main features are abdominal pain associated with an altered bowel habit (may present with diarrhea or constipation or intermittently both) in the absence of any structural pathology. A careful review of the clinical picture of various GIT diseases, described in Ayurveda reveals that some of the disorders definitely have some clinical symptoms which observed in patients of IBS. So according to pathogenesis and sign &amp;amp; symptom, IBS can be a stage of Grahani Dosha. The present study was interventional, open label, prospective with time and single group. There was fifty two patients which clinically diagnosed case of IBS as per Rome III criteria were administered trial drugs Bilvadi Leha 10 gm twice daily orally after taking meal with lukewarm water as a Anupana within duration of 12 weeks. For assessment of results, IBS severity score, WHO QOL score, Ayurvedic parameters, hematology and microscopic stool examination were used. The study was showed significant results in fifty one (one patient dropped) patients in management of IBS (Grahani Dosha) with safety profile as an important therapeutic agent.', '{"arp_id": "ARP_AYU000430", "portal_id": 430, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "11", "issue": "3", "pages": "11 - 16", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "IRRITABLE BOWEL SYNDROME(ICPC-D93|ICD-K58)", "keywords": ["Bilvadi Leha"], "original_url": "https://journals.lww.com/joay/citation/2017/11030/joa_xi_july_september_2017.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=430", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000430.pdf", "pdf_sha256": "8fafae0784c7ae5bf6c1f375cdea9e00f2ecbb6e30f4cc02976e54bad8d6984c", "relevance_score": 53.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '21170206', '10.4103/0974-7788.72486', 'MAHAYOGRAJ GUGGULU: HEAVY METAL ESTIMATION AND SAFETY STUDIES', '1. Lavekar GS, 2. Ravishankar B, 1. Gaidhani S, 2. Shukla VJ, 2. Ashok BK, 1. Padhi MM.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: This study was conducted to estimate the heavy metal profile and determine the safety of Mahayograj guggulu, an Ayurvedic herbo-mineral preparation. Design: Mahayograj guggulu, manufactured by Shree Baidynath Ayurved Bhawan Pvt. Ltd., Gwalior Road, Jhansi - 284 003 (of batch number-07 and manufacturing date October 2004) was procured from the local market. Heavy metal concentrations were measured using an atomic absorption spectrophotometer. A total of 40 Charles Foster strain albino rats of either sex with an average body weight of 160-250 g were divided into four groups (Groups I, II, III and IV), with 10 animals in each group. Group I served as the control, while Group II, III and IV rats received Mahayograj guggulu at a dose of 54 (dose equivalent to human therapeutic dose), 270 (five-times the dose equivalent to the human therapeutic dose) and 540 (10-times the dose equivalent to human therapeutic dose) mg/kg, p.o. for 120 days. The effect of drug administration was noted on the ponderal, biochemical, hematological and histopathological parameters. In addition, urine examination was also carried out. At the end of the study, only six rats per group were sacrificed as per the IAEC advice. Results: Mahayograj guggulu was found to be safe at all dose levels tested. No significant behavioral changes were noted in any of the groups studied. The effect on food and water consumption and fecal and urine output remained unaffected in all groups during the study period. No major alterations were observed in hematology, serum biochemistry, necropsy and histopathology at the therapeutically advocated dose level. Heavy metal content measurement indicated levels of 25.8 µg/g for lead, 0.07 µg/g for mercury and 5.19 µg/g for arsenic. Conclusions: The test drug is well tolerated as no changes of a serious nature could be observed in any of the parameters assessed.', '{"arp_id": "ARP_AYU019526", "portal_id": 19526, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda Research", "volume": "1", "issue": "3", "pages": "150 - 158", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Heavy Metal Content"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19526", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019526.pdf", "pdf_sha256": "b510623da178cfded834659a77349d8851dd5ea040a042e66adad1b8b6be41b4", "relevance_score": 53.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '20433751', '10.1186/1472-6882-10-17', 'RANDOMIZED CLINICAL TRIAL OF A PHYTOTHERAPIC COMPOUND CONTAINING PIMPINELLA ANISUM, FOENICULUM VULGARE, SAMBUCUS NIGRA, AND CASSIA AUGUSTIFOLIA FOR CHRONIC CONSTIPATION.', '1. Paulo D Picon, 2. Rafael V Picon, 2. Any F Costa, 2. Guilherme B Sander, 2. Karine M Amaral, 3. Ana L Aboy, 3. Amelia T Henriques.', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: BACKGROUND: A phytotherapic compound containing Pimpinella anisum L., Foeniculum vulgare Miller, Sambucus nigra L., and Cassia augustifolia is largely used in Brazil for the treatment of constipation. However, the laxative efficacy of the compound has never been tested in a randomized clinical trial. The aim of this study was to evaluate the efficacy and safety of the product.METHODS: This randomized, crossover, placebo-controlled, single-blinded trial included 20 patients presenting with chronic constipation according to the criteria of the American Association of Gastroenterology. The order of treatments was counterbalanced across subjects: half of the subjects received the phytotherapic compound for a 5-day period, whereas the other half received placebo for the same period. Both treatment periods were separated by a 9-day washout period followed by the reverse treatment for another 5-day period. The primary endpoint was colonic transit time (CTT), measured radiologically. Secondary endpoints included number of evacuations per day, perception of bowel function, adverse effects, and quality of life.RESULTS: Mean CTT assessed by X ray was 15.7 hours (95%CI 11.1-20.2) in the active treatment period and 42.3 hours (95%CI 33.5-51.1) during the placebo treatment (p &amp;lt; 0.001). Number of evacuations per day increased during the use of active tea; significant differences were observed as of the second day of treatment (p &amp;lt; 0.001). Patient perception of bowel function was improved (p &amp;lt; 0.01), but quality of life did not show significant differences among the study periods. Except for a small reduction in serum potassium levels during the active treatment, no significant differences were observed in terms of adverse effects throughout the study period.CONCLUSIONS: The findings of this randomized controlled trial allow to conclude that the phytotherapic compound assessed has laxative efficacy and is a safe alternative option for the treatment of constipation.', '{"arp_id": "ARP_AYU021826", "portal_id": 21826, "medical_system": "AYURVEDA", "journal": "BMC Complementary and Alternative Medicine", "volume": "10", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "FISTULA IN ANO (ICD-K-60.3)", "keywords": ["Cassia Angustifolia"], "original_url": "https://bmccomplementmedtherapies.biomedcentral.com/articles/10.1186/1472-6882-10-17", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=21826", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU021826.pdf", "pdf_sha256": "0902057091a0b78660bf1a8cfd55385798ea438be06b86330e2888e2c9574739", "relevance_score": 53.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '20415914', '10.1111/j.1834-7819.2009.01180.x', 'SHORT-TERM CLINICAL EFFECTS OF COMMERCIALLY AVAILABLE GEL CONTAINING ACACIA ARABICA: A RANDOMIZED CONTROLLED CLINICAL TRIAL.', 'Pradeep AR, Happy D, Garg G.', 2010,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Background: Certain plants used in folk medicine serve as a source of therapeutic agent by having antimicrobial and other multi-potential effects. This prospective, randomized, placebo and positively controlled clinical trial was designed to evaluate the short-term clinical effects of a commercially available gel containing Acacia arabica in the reduction of plaque and gingival inflammation in subjects with gingivitis. Methods: Ninety subjects diagnosed with chronic generalized gingivitis were selected and randomly divided into three groups: Group I - placebo gel, Group II - gumtone gel and Group III - 1% chlorhexidine gel. Clinical evaluation was undertaken using the gingival index of Loe and Silness and the plaque index at baseline, 2 weeks, 4 weeks and 6 weeks. A subjective evaluation was undertaken by questionnaire. Results: Gumtone gel showed significant clinical improvement in gingival and plaque index scores as compared to a placebo gel. This improvement was comparable to 1% chlorhexidine gel. Unlike chlorhexidine gel, gumtone gel was not associated with any discolouration of teeth or unpleasant taste. Conclusions: Gumtone gel may be a useful herbal formulation for chemical plaque control agent and improvement in plaque and gingival status.', '{"arp_id": "ARP_AYU021829", "portal_id": 21829, "medical_system": "AYURVEDA", "journal": "Australian Dental Journal", "volume": "55", "issue": "1", "pages": "65 - 69", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "DIGESTIVE", "disease": "TEETH/GUM DISEASE(ICPC-D82|ICD-K00.0, K00.1, K00.2, K00.3, K00.4, K00.5, K00.6, K00.8, K00.9, K01, K02, K03, K04, K05, K06, K07, K08, K09, K10)", "keywords": ["Acacia Arabica"], "original_url": "https://onlinelibrary.wiley.com/doi/10.1111/j.1834-7819.2009.01180.x", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=21829", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU021829.pdf", "pdf_sha256": "3cd66ecd41505b66d86082ffed50f7ce58094c5002eb5f631217628923a6a186", "relevance_score": 53.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '36931413', '10.1016/j.jep.2023.116385', 'ETHANOL EXTRACT OF PROPOLIS REGULATES TYPE 2 DIABETES IN MICE VIA METABOLISM AND GUT MICROBIOTA.', '1. Rui Guan, 1. Ning Ma, 1. Guolong Liu, 1. Qiu Wu a, 2. Shufang Su, 2. Jun Wang, 1. Yue Geng.', 2023,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance: Propolis is a traditional natural medicine with various activities such as antioxidant and anti-inflammatory, immunomodulatory, anti-tumour, gastroenteritis treatment and prevention, anti-microbial and parasitic, as well as glucose regulation and anti-diabetes, and is expected to be an anti-diabetic candidate with few side effects, but the mechanism of action of propolis on type 2 diabetes mellitus (T2DM) has not been fully elucidated. Aim of the study: The purpose of this study was to investigate the mechanism of the effect of ethanol extract of propolis (EEP) on the regulation of blood glucose in T2DM mice. Materials and methods: We studied the possible mechanism of EEP on T2DM using an animal model of T2DM induced by a combination of a high-fat diet and intraperitoneal injection of streptozotocin (STZ). The experiment was divided into four groups, namely, the normal group (HC), model group (T2DM), EEP and metformin group (MET). Biochemical indexes and cytokines were measured, and the differences of metabolites in the serum were compared by 1H-NMR. In addition, the diversity of intestinal flora in feces was studied by 16S rDNA amplicon sequencing. Results: The results showed that following treatment with EEP and MET, the weight-loss trend of mice was alleviated, and the fasting blood glucose, insulin secretion level, insulin resistance index, C peptide level and oral glucose tolerance level decreased, whereas the insulin sensitivity index increased, thereby EEP effectively alleviated the occurrence of T2DM and insulin resistance. Compared with the T2DM group, the concentrations of pro-inflammatory cytokines interleukin-1 beta (IL-1ß), interleukin-6 (IL-6) and tumor necrosis factor-alpha (TNF-a) decreased significantly in EEP and MET groups, whereas the concentrations of anti-inflammatory cytokine interleukin-10 (IL-10) increased significantly. Metabolomics results revealed that EEP and MET regulate carbohydrate metabolism and restore amino acid and lipid metabolism. Correlation analysis of intestinal flora in mouse feces showed that compared with the HC group, harmful bacteria such as Bilophila, Eubacterium_ventriosum_group, Mucispirillum and Desulfovibrio were found in the T2DM group, whereas the abundance of beneficial bacteria such as Lactobacillus was significantly reduced. Parabacteroides, Akkermansia, Leuconostoc, and Alloprevotella were abundantly present in the EEP group; however, the MET group showed an increase in the genus Parasutterella, which could regulate energy metabolism and insulin sensitivity. Conclusions: The results showed that EEP and MET reduce fasting blood glucose in T2DM mice, followed by alleviating insulin resistance, improving the inflammatory reaction of mice, regulating the metabolism of mice, and affecting the steady state of gut microbiota. However, the overall therapeutic effect of EEP is better than that of MET.', '{"arp_id": "ARP_AYU002974", "portal_id": 2974, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "310", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ethanol Extract Of Propolis (Eep)"], "original_url": "https: //www.sciencedirect.com/science/article/pii/S03788741230025", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2974", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002974.pdf", "pdf_sha256": "447b88da1e763dc04c8c5fffd7b6bd4803ca0bffbaddf2b89416fa51f8ab12c5", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '37201665', '10.1016/j.jep.2023.116619', 'POLYPHENOLIC COMPOUNDS OF PHYLLANTHUS AMARUS SCHUM & THONN. (1827) AND DIABETES-RELATED ACTIVITY OF AN AQUEOUS EXTRACT AS AFFECTED BY IN VITRO GASTROINTESTINAL DIGESTION.', '1,2. Melissa Matou, 1,3. Patrick Merciris, 4. Mayra Luz Sanchez-Villavicencio, 5. Gaetan Herbette, 2. Remi Neviere, 4. Pierre Haddad, 1,3. Therese Marianne-Pepin, 1,2,6. Sylvie Bercion.', 2023,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance:Extracts of the aerial part of Phyllanthus amarus have been extensively used in several countries to cure diabetes. No data is available on the impact of gastrointestinal digestion of such crude extracts on their antidiabetic activity.Aim of the study:The aim of this study was to identify active fractions and compounds of fresh aerial parts of P. amarus extracted by an infusion method that are responsible for antidiabetic effects occurring at the level of glucose homeostasis.Materials and methods:An aqueous extract was obtained by an infusion method and its polyphenolic composition was analysed by reverse phase UPLC-DAD-MS. The influence of in vitro gastrointestinal digestion was evaluated both on the chemical composition and on the antidiabetic effect of P. amarus infusion extract using glucose-6-phosphatase enzyme inhibition and stimulation of glucose uptake.Results:Analysis of the chemical composition of the crude extract revealed the presence of polysaccharides and various families of polyphenols such as phenolic acids, tannins, flavonoids and lignans. After simulated digestion, the total content of polyphenols decreased by about 95%. Caffeoylglucaric acid derivates and lignans exhibited strong stimulation of glucose uptake similar to metformin with an increase of 35.62 &amp;#177; 6.14% and 34.74 &amp;#177; 5.33% respectively. Moreover, corilagin, geraniin, the enriched polysaccharides fraction and the bioaccessible fraction showed strong anti-hyperglycemic activity with about 39–62% of glucose-6-phosphatase inhibition.Conclusion:Caffeoylglucaric acid isomers, tannin acalyphidin M1 and lignan demethyleneniranthin were reported for the first time in the species. After in vitro gastroinstestinal digestion, the composition of the extract changed. The dialyzed fraction showed strong glucose-6-phosphatase inhibition.', '{"arp_id": "ARP_AYU002981", "portal_id": 2981, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "315", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Enriched Polysaccharides Fraction"], "original_url": "https: //www.sciencedirect.com/science/article/pii/S0378874123004877", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2981", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002981.pdf", "pdf_sha256": "b952b76864bf5f7054770ee4330fecf5423e107db234c375a00a85119bbfd779", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.22159/ajpcr.2018.v11i4.23502', 'BLOOD GLUCOSE LEVELS AND THE MICROSCOPIC STRUCTURE OF KIDNEY WISTAR RAT DIABETES MELLITUS UNDER THE EFFECT OF LAWSONIA INERMIS (LINN.) LEAVES ETHANOLIC EXTRACT.', '1. Mutiara Indah Sari, 2. Maya Anjelir Antika, 3. Dwi Rita Anggraini.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background : - Keywords : Blood Glucose Levels , Diabetic Rats , Ethanolic Extract , Kidney , Lawsonia Inermis (Linn) URL (for Abstract/ Full paper) : https://innovareacademics.in/journals/index.php/ajpcr/article/view/23502 DOI : 10.22159/ajpcr.2018.v11i4.23502 Access : -', '{"arp_id": "ARP_AYU004428", "portal_id": 4428, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "11", "issue": "4", "pages": "257 - 261", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Blood Glucose Levels"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/23502", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4428", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004428.pdf", "pdf_sha256": "f5cd5d99ba88f7577f30a5afceb1445140c987d17147e09b935bd868cbc4201e", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v6i3.503', 'TRIPHALA IMPROVES GLUCOSE HOMEOSTASIS BY ALLEVIATING ATHEROGENIC LIPIDS AND OXIDATIVE STRESS IN HUMAN TYPE 2 DIABETES MELLITUS', '1. Nita Singh, 1. Sunil Mahajan,1. Senthil K Subramani,2. Dhananjay Yadav, 3. Lokena Singh, 1. Prasad GBKS.', 2015,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Aims: Triphala constituting equal parts of three medicinal dried plant fruits Emblica Officinalis Gaertn., Terminalia chebula Retz. and Terminalia bellerica Gaertn. is an antioxidant rich Ayurvedic formulation. The pre-sent study assessed therapeutic as well as protective effects of Triphala on human subjects with Type 2 diabetes mellitus (T2DM) and Impaired glucose tolerance (IGT).Materials and methods: Triphala at a dose of 5 gms BD was administered to two cohorts viz., IGT, N= 20 and T2DM, N=30 consecutively for a period of 12 months. The therapeutic efficacy was assessed quarterly by monitoring blood glucose and lipid levels; the protective effect by monitoring antioxidants level quarterly and DNA damage annually. Toxicity if any, to liver and kidney due to long term administration was assessed quarterly in both cohorts.Results: Continuous Triphala therapy for 12 months significantly reduced blood glucose (p=0.001) and li-pid levels (p=0.05) in both the cohorts. Triphala resisted oxidative stress generated during the course of hypergly-cemia by significantly increasing the activity of super oxide dismutase and Catalase (p=0.001) and the level of re-duced glutathione (p=0.001). Protective effect on DNA was accessed through significant reduction in the comet tail length (p=0.001).Conclusions: Triphala ameliorated not only the oxidative stress but also normalized glucose and lipid homeostasis in subjects with impaired glucose and T2DM.', '{"arp_id": "ARP_AYU009727", "portal_id": 9727, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "6", "issue": "3", "pages": "212 - 219", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Antioxidants"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/06262015", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9727", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009727.pdf", "pdf_sha256": "56f78771291cf26a356b8033dad3988d913eb06118136270be4c8c0800e53717", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/pj.2017.1.11', 'TOXICOLOGY AND ORAL GLUCOSE TOLERANCE TEST (OGTT) OF THAI MEDICINAL PLANT USED FOR DIABETES CONTROLS, PHYLLANTHUS ACIDUS L. (EUPHORBIACEAE).', '1. Napapach Chaimum-aom, 2. Sanong Chomko, 2. Chusri Talubmook.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aim: The present study aimed to investigate toxicity and oral glucose tolerance test (OGTT) of Phyllanthus acidus leaf extract (PAE) on Wistar rat. Methods: PAE was prepared and administered orally to experimental animals used. The extract was tested for toxicity in rats at a dose of 0, 1,000, 1,500 and 2,000 mg/kg body weight p.o once daily for 14 days. The hypoglycemic effects of PAE on normal rats and orally glucose-induced hyperglycemic rats were compared with distilled water and glibenclamide. A single dose (250 mg/kg body weight) of PAE was administered and blood glucose level was obtained by pricking the tail vain using glucometer at time -30, 0, 30, 60, 120 and 240 minutes. Results: All doses of the extract did not exert any sign or symptom of toxicity and the dead rat was not found. The body weight, white blood cell (WBC), mean corpuscular volume (MCV), platelet (PLT), plateletcrit (PCT), mean platelet volume (MPV), platelet distribution width (PDW), blood chemistry, blood urea nitrogen (BUN), creatinine, alkaling phosphatase (ALP) and organ weight of liver were not significantly different between control and treated rats. However, red blood cell (RBC), hematocrit (HCT), lymphocyte (LYM), and hemoglobin (Hb) at a dose 1,500 mg./kg body weight were significantly lower than those in the control group. The blood glucose levels of PAE treated groups were not different with control and Glybenclamide treated. Conclusion: The findings of the present study can be concluded that the PAE are practically non-toxic at a lower dose.', '{"arp_id": "ARP_AYU009960", "portal_id": 9960, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Journal", "volume": "9", "issue": "1", "pages": "58 - 61", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Blood Glucose"], "original_url": "http://www.phcogj.com/article/227", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9960", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009960.pdf", "pdf_sha256": "95714fcea96e1c9e6c5c20c6bc48325fa39941c2a94e84ff1bd030b38500fea2", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/pj.2018.2.56', 'PHARMACOGNOSTIC EVALUATION OF CURCUMIN ON DIABETIC RETINOPATHY IN ALLOXAN-INDUCED DIABETES THROUGH NF-KB AND BRN3A RELATED MECHANISM.', '1. DebasishPradhan, 2. ToffaDasmohapatra, 3. GitanjaliTripathy.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Diabetic retinopathy is one of the most common micro vascular complication of diabetes and involves an abnormal pathology of major retinal pigment epithelium, inter retinal oedema and intraocular neovascularisation where pro-inflammatory proteins including ICAM-1,iNOS and VEGF release by activation of enzyme CaMKII/NF-kB expression Diabetic induced oxidative stress followed by deactivation of Brn3a expression in the retinal ganglionic cells are also early events in pathogenesis of Diabetic retinopathy. These factors are important contributors to the development of clinically significant diabetic retinopathy. Objective: Objective of this study to examine the effect of curcumin with antioxidant and anti-inflammatory properties obtained from Curcuma longa against diabetes-induced retinal vascular damage and its mechanism of action by in-vivo in retinas of rat rendered diabetic by alloxan and in vitro in western blotting and RGC tissue culture. Method: We administered curcumin or saline vehicle to experimental animals daily for 12 weeks. Vascular permeability, expression of CaMK II/NF-kB, Retinal morphology and neuropathic change of the retinal ganglion cells were investigated. Results: As an anti-oxidant, curcumin raised Retinal Ganglionic cells by increasing Brn3a expression during oxidative stress condition and subsequently decreased the expression of inflammatory mediators such as VEGF, iNOS and ICAM-1 as an anti-inflammatory agent by inhibiting CaMKII and NF-kB expression. Conclusion: Curcumin, a common food additive has beneficial effects in experimental studies of diseases that are characterised by increased oxidative stress and inflammatory reactions. It appears to be a useful adjunct therapy to possibly inhibit the progression of retinopathy, sight threatening complication faced by diabetic patients.', '{"arp_id": "ARP_AYU011566", "portal_id": 11566, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Journal", "volume": "10", "issue": "2", "pages": "324 - 332", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cakmii"], "original_url": "http://www.phcogj.com/article/505", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11566", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011566.pdf", "pdf_sha256": "cafea71a2f67d6ff2c049748128eace452742e4c2339dbc27d88744266758bdc", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/fra.2018.2.21', 'ANTIOXIDANT, ANTI-INFLAMMATORY AND ANTI-DIABETIC EFFICIENCY OF INDIAN MEDICINAL PLANTS AGAINST STREPTOZOTOCIN INDUCED DIABETES IN MALE WISTAR RATS.', 'Satish Kumar Vemuri, Rajkiran Reddy Banala, Kumar Katragunta, VijayaMadhuri, KiruthikaRaju, Venkata Gurava Reddy Annapareddy, Pedda Venkata Subbaiah Goli.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: The study was aimed to assess the anti-oxidative and anti-diabetic efficacy of few dietary supplements such as Artocarpusheterophyllus (Raw Jackfruit), Zea mays (Corn Silk), Syzygiumcumini (Black plum), and Shilajit (Black asphaltum) in vitro and in vivo models. The phytoextracts were compared with the known commercial diabetic drugs (Aminoguanidine, Glibenclamide and Insulin) in controlling Streptozotocin induced hyperglycemia, advanced glycation end-products (AGEs), hyperlipidemia and activation of inflammatory mediators (iNOS) in in vivo. Methods: Collection and preparation of phytoextracts, superoxide anion scavenging assay, phosphomolybdate assay (total anti-oxidant capacity), Hydroxyl radical scavenging assay, quantification of hemoglobin glycation, body weights, lipid profile, Pro-inflammatory gene expression, agarose gel electrophoresis and histopathology. Results: We found that natural extracts of A. heterophyllus, S. cumini, Z. mays, and Shilajit exhibited considerable antioxidant capacity and inhibited hemoglobin glycosylation in a dose-dependent manner in in vitro. In STZtreated diabetic rats, the extracts showed clear effects on blood glucose and lipid levels, body weight and pro-inflammatory gene expression (iNOS). Histopathology of treated rat pancreas further supported our in vivo findings. Overall, our study indicates that the natural extracts we tested could be a useful source of antioxidant agents, functional foods and nutraceuticals, particularly in diabetes and related complications. Conclusion: The findings from our study showed reversal of the effects induced by Streptozotocin administration on phytoextracts supplementation in experimental diabetic rats and the therapeutic capacity was similar to that of commercial diabetic drugs, hence these extracts could serve as an alternate in management of diabetes and allied complications.', '{"arp_id": "ARP_AYU011714", "portal_id": 11714, "medical_system": "AYURVEDA", "journal": "Free Radicals and Antioxidants", "volume": "8", "issue": "2", "pages": "141 - 148", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Glycation"], "original_url": "https://www.antiox.org/index.php/fra/article/view/64", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11714", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011714.pdf", "pdf_sha256": "458e15a9a6e8f2b37e86561f2c1037ee9af52159d160388f880cc2c3a9831506", "relevance_score": 52.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '34980523', '10.1016/j.jaim.2021.11.002', 'A COMPARATIVE STUDY OF THE EFFICIENCY OF WITHANIA SOMNIFERA AND CARBAMAZEPINE ON LIFESPAN, REPRODUCTION AND EPILEPTIC PHENOTYPE - A STUDY IN DROSOPHILA PARALYTIC MUTANT.', 'Sara Moghimi, Harini BP.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background:Seizure disorders are considered a serious health issue because of the vast number of people affected globally and the limited treatment options. Approximately 15 million epileptic patients worldwide do not respond to any of the currently available medications. Carbamazepine (CBZ) is one of the most widely used antiepileptic drugs (AEDs) for the treatment of epilepsy, which is discontinued in less than 5% of epileptic patients due to its side effects. In traditional medicine, to establish the foundation of health care, plant extracts are utilized to a great extent to treat different pathologies. Withania somnifera (W. somnifera) is an herbal component with anticonvulsant properties.Objectives:To compare the medicinal effects of W. somnifera on lifespan, fecundity, fertility and epileptic phenotype in Drosophila paralytic mutant (parabss1) model system with CBZ, a commonly used AED.Material and methods:Flies were exposed to three different doses of W. somnifera or CBZ in standard wheat flour-agar media for six days. Drosophila Oregon-R strain was used as a control.Results:Results indicate that a high dose of W. somnifera increased the lifespan in Drosophila parabss1 while remaining safe for fecundity and fertility. CBZ decreased the lifespan of parabss1 mutant at higher dose (40 µg/ml), as expected, and also reduced the fecundity and fertility of the flies. Our findings indicate that W. somnifera was more effective than CBZ to control epileptic phenotype.Conclusion:W. somnifera is an effective medication with no side effects for treating epilepsy in Drosophila paralytic mutant.', '{"arp_id": "ARP_AYU025557", "portal_id": 25557, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Integrative Medicine", "volume": "13", "issue": "2", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Carbamazepine"], "original_url": "https://www.sciencedirect.com/science/article/pii/S0975947621002035", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=25557", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU025557.pdf", "pdf_sha256": "961727a278d1c9d7b7528f99dd4596e41d851eeac92796c6523c76e585e08521", "relevance_score": 52.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '32035878', '10.1016/j.jep.2020.112647', 'ANTI-HYPERGLYCAEMIC ACTIVITY OF H. ROSA-SINENSIS LEAVES IS PARTLY MEDIATED BY INHIBITION OF CARBOHYDRATE DIGESTION AND ABSORPTION, AND ENHANCEMENT OF INSULIN SECRETION.', '1. Prawej Ansari, 2. Shofiul Azam, 3. Hannan JMA,1. Peter R. Flatt, 1. Yasser H.A. Abdel Wahab.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance:Hibiscus rosa-sinensis (HRS) is a tropical flowery plant, widely distributed in Asian region and an important traditional medicine used in many diseases including cough, diarrhoea and diabetes.Aim of this study:Hibiscus rosa-sinensis (HRS) leaves have been reported to possess anti-hyperglycaemic activity, but little is known concerning the underlying mechanism. This study investigated effects of ethanol extract of HRS on insulin release and glucose homeostasis in a type 2 diabetic rat model.Materials &amp;amp; methods:Effects of ethanol extract of grinded H. rosa-sinensis (HRS) leaves on insulin release, membrane potential and intracellular calcium were determined using rat clonal ß-cells (BRIN-BD11 cells) and isolated mouse pancreatic islets. Effects on DPP-IV enzyme activity were investigated in vitro. Acute effects of HRS on glucose tolerance, gut perfusion in situ, sucrose content, intestinal disaccharidase activity and gut motility were measured. Streptozotocin induced type 2 diabetic rats treated for 28 days with ethanol extract of HRS leaf (250 and 500 mg/kg) were used to assess glucose homeostasis.Results:HRS, significantly increased insulin release from clonal rat BRIN-BD11 cells and this action was confirmed using isolated mouse pancreas islets with stimulatory effects equivalent to GLP-1. HRS induced membrane depolarization and increased intracellular Ca2+ in BRIN BD11 cells and significantly inhibited DPP-IV enzyme activity in vitro. HRS administration in vivo improved glucose tolerance in type 2 diabetic rats, inhibited both glucose absorption during gut perfusion and postprandial hyperglycaemia and it reversibly increased unabsorbed sucrose passage through the gut following sucrose ingestion. HRS decreased intestinal disaccharidase activity and increased gastrointestinal motility in non-diabetic rats. In a chronic 28-day study with type 2 diabetic rats, HRS, at 250 or 500 mg/kg, significantly decreased serum glucose, cholesterol, triglycerides and increased circulating insulin, HDL cholesterol and hepatic glycogen without increasing body weight.Conclusion:These data suggest the antihyperglycaemic activity of HRS is mediated by inhibiting carbohydrate digestion and absorption, while significantly enhancing insulin secretion in a dose dependent manner. This suggests that HRS has potential as a novel antidiabetic therapy or a dietary supplement for the treatment of type 2 diabetes.', '{"arp_id": "ARP_AYU029317", "portal_id": 29317, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "253", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetes"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S037887411934543X", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29317", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029317.pdf", "pdf_sha256": "2162135113d9fd3eb95d4f9b2b0d2fb3c4a24d74bd87aa42acf5a2d00e84c9ad", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '32971162', '10.1016/j.jep.2020.113398', 'INHIBITORY EFFECTS OF GYMNEMA INODORUM (LOUR.) DECNE LEAF EXTRACTS AND ITS TRITERPENE SAPONIN ON CARBOHYDRATE DIGESTION AND INTESTINAL GLUCOSE ABSORPTION.', '1. Wanwisa Srinuanchai, 1. Rawiwan Nooin, 2. Pornsiri Pitchakarn, 2. Jirarat Karinchai, 3. Uthaiwan Suttisansanee, 4,5. Chaisak Chansriniyom, 1. Suwatchai Jarussophon, 3. Piya Temviriyanukul, 1. Onanong Nuchuchua.', 2021,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance:Chiang-Da, Gymnema inodorum (Lour.) Decne. (GI), is an ethnomedicinal plant that has been used for diabetic treatment since ancient times. One of the anti-diabetic mechanisms is possibly related to the actions of triterpene glycoside, (3ß, 16ß)-16,28-dihydroxyolean-12-en-3-yl-O-ß-D-glucopyranosyl-ß-D-glucopyranosiduronic acid (GIA1) in decreasing carbohydrate digestive enzymes and intestinal glucose absorption in the gut system.Aims of the study:To observe the amount of GIA1 in GI leaf extracts obtained from different ethanol concentrations and to investigate the anti-hyperglycemic mechanisms of the extracts and GIA1.Materials and methods:The crude extracts were prepared using 50%v/v to 95%v/v ethanol solutions and used for GIA1 isolation. The anti-hyperglycemic models included in our study examined the inhibitory activities of a-amylase/a-glucosidase and intestinal glucose absorption related to sodium glucose cotransporter type 1 (SGLT1) using Caco-2 cells.Results:GIA1 was found about 8%w/w to 18%w/w in the GI extract depending on ethanol concentrations. The GI extracts and GIA1 showed less inhibitory activities on a-amylase. The extracts from 75%v/v and 95%v/v ethanol and GIA1 significantly delayed the glycemic absorption by lowering a-glucosidase activity and glucose transportation of SGLT1. However, the 50%v/v ethanolic extract markedly decreased the a-glucosidase activity than the SGLT1 function.Conclusion:Differences in the GIA1 contents and anti-glycemic properties of the GI leaf extract was dependent on ethanol concentrations. Furthermore, the inhibitory effects of the 75%v/v and 95%v/v ethanolic extracts on a-glucosidase and SGLT1 were relevant to GIA1 content.', '{"arp_id": "ARP_AYU029461", "portal_id": 29461, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "266", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Carbohydrate Digestion"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S0378874120332839", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29461", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029461.pdf", "pdf_sha256": "558f0687349bdbac6538e64a2b7dcc58e0ff2704004556fbf63e82b7f2da38bc", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '36618060', '10.1007/s13197-022-05601-2', 'SEQUENCE ALTERATIONS AFFECT THE ANTIDIABETIC ATTRIBUTES OF HAZELNUT PEPTIDE FRACTIONS DURING THE INDUSTRIAL MANUFACTURE AND SIMULATED DIGESTION OF HAZELNUT PASTE.', '1. Ayse Gulden Goksu, 2,3. Bilal Cakir,1,3. Ibrahim Gulseren.', 2023,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Press cakes are by-products of cold press oil manufacture and are characterized by significant protein concentrations. Our group has previously demonstrated potential bioactive attributes of hazelnut protein hydrolysates including their antidiabetic activities. Here, an effort was made to utilize DPP-IV (Dipeptidyl peptidase-IV)-inhibitory hazelnut peptides in industrial food manufacture. Hazelnut protein isolates (approx. 95% protein) were obtained via an alkali extraction-isoelectric precipitation method. Papain, bromelain and pepsin were used in the enzymatic hydrolysis and hydrolysates were fractionated via Fast Protein Liquid Chromatography. As a general observation, although fractionation lead to dilution of the samples, fractions were observed to be more bioactive than the total hydrolysates. In vitro antidiabetic activities of the fractions were tested and 3 antidiabetic fractions were added to hazelnut paste. Afterwards simulated gastrointestinal digestion and antidiabetic activity assays were performed. DPP-IV inhibition was the major antidiabetic mechanism in the fractions and digested paste, while some fractions were characterized by comparable IC50 values as the positive controls. Alpha-glucosidase inhibition was limited by digestion trials, whereas alpha-amylase inhibition was only slight in the digested paste (&amp;lt;?%6). In silico analyses predicted partial degradation of the peptides, whereas the interactions between DPP-IV or alpha-glucosidase and hazelnut peptides were predicted to be significant (p?&amp;lt;?0.05). Consequently hazelnut press cakes were regarded as a potential source of antidiabetic peptides that can be used in industrial manufacture of functional foods, while food processing conditions or gastrointestinal digestion could largely affect peptide bioactivity.', '{"arp_id": "ARP_AYU029778", "portal_id": 29778, "medical_system": "AYURVEDA", "journal": "Journal of Food Science and Technology", "volume": "60", "issue": "1", "pages": "171 - 180", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antidiabetic Peptides"], "original_url": "https://doi.org/10.1007/s13197-022-05601-2", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29778", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029778.pdf", "pdf_sha256": "01cd97a150fe3f1c441ddbed21fbff1ae67a673ad4cf27eb8ec0507eac116f97", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '33583685', '10.1016/j.jaim.2021.01.006', 'IMPROVEMENT IN GASTROINTESTINAL QUALITY OF LIFE INDEX (GIQLI) FOLLOWING MEDITATION: AN OPEN-TRIAL PILOT STUDY IN INDIA.', '1. Divya Kanchibhotla, 2. Peeyush Sharma, 3. Saumya Subramanian.', 2021,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background:Medical science is increasingly recognizing the role of gut health in achieving optimal wellbeing. A healthy gut improves digestion. Additionally, it has a positive impact on multiple physiological networks such as immune system, central nervous system and hepato-endocrine system, thus contributing to the overall quality of life. Functional gastrointestinal disorders: also known as disorders of gut-brain interaction, such as irritable bowel syndrome are increasing worldwide. Conditions like stress, anxiety and mental disorders are correlated with these disorders. Mind-body interventions have been shown to ameliorate stress, anxiety and related conditions that may aggravate functional gastrointestinal disorders.Objective:The present study aims to investigate the benefits of a novel meditation technique called the Vaishvanara Agni meditation (VAM) on the gastrointestinal quality of life.Materials and methods:54 subjects participated in the study and practiced VAM for 50 days. During the Vaishvanara Agni meditation (VAM), attention is directed to the navel region and the digestive system. The effect of the meditation was evaluated using the gastrointestinal quality of life (GI-QoL) questionnaire, which was administered to subjects at three different time points i.e. day 0, day 24 and day 50.Results:GI-QoL was significantly improved with the practice of VAM. Additionally, significant improvements were noticed in all sub domains especially core symptoms, physical strength and the psychological domain.Conclusion:Meditation practices that focus on improving digestion can be an effective tool for improving gut health.', '{"arp_id": "ARP_AYU025346", "portal_id": 25346, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Integrative Medicine", "volume": "12", "issue": "1", "pages": "107 - 111", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "GENERAL/UNSPECIFIED", "disease": "HEALTH MAINT/PREVENTIVE MEDICINE(ICPC-A98|ICD-Z01, Z10, Z11, Z12, Z13, Z40, Z70)", "keywords": ["Gastrointestinal Disorder"], "original_url": "https://www.sciencedirect.com/science/article/pii/S0975947621000085", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=25346", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU025346.pdf", "pdf_sha256": "ac0995e83eb0375640c4c6b35709a10184ca9a21eb08958c89358b2f56fb7f3e", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '31509779', '10.1016/j.jep.2019.112224', 'GASTROINTESTINAL AND UTERINE SMOOTH MUSCLES RELAXANT AND ANTI-INFLAMMATORY EFFECTS OF CORCHORUS OLITORIUS LEAF EXTRACT IN LABORATORY ANIMAL MODELS.', '1. DanielOrieke, 1. Obioma ChristopherOhaeri, 1. Ifeoma IreneIjeh, 2. Solomon NnahIjioma.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethno-pharmacological relevance: Corchorus olitorius is reportedly used in ethno-medicine to arrest threatened miscarriage and other conditions associated with excessive uterine contractions. The plant is also used as a purgative, demulscent and an anti-inflammatory agent.Aim of the study: Against the background of ethno-medicinal use, this current work was designed to evaluate the gastrointestinal and uterine smooth muscles relaxant and anti-inflammatory effects of Corchorus olitorius leaf extract (COLE). Materials and methods: Pieces of uterine and gastrointestinal tissues were suspended separately in organ baths containing ideal physiological salt solutions bubbled with air and were tested for responses to standard drugs and COLE, then repeated in the presence of antagonists. Anti-inflammatory study was carried out via the egg albumin-induced paw edema model in rats.Results: The application of COLE to pieces of uterine tissue significantly decreased the amplitudes of contractions in a dose dependent manner such that the highest dose applied (666.67?µg/ml) achieved a 100% inhibitory effect. Oxytocin induced contractions were also significantly inhibited by both salbutamol and COLE. On the isolated rabbit jejunum, the effect of COLE was also inhibitory and like atropine, significantly inhibited acetylcholine induced contractions. In the in vivo study, the extract inhibited charcoal meal movement in test rats when compared with control. Anti-inflammatory effect of COLE was significant and compared favourably with that of aspirin following in vivo trials.Conclusions: COLE therefore, may be a good tocolytic, anti-diarrheal and anti-inflammatory agent and offers hope of new drug discovery for such uses.', '{"arp_id": "ARP_AYU029274", "portal_id": 29274, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "247", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Acetylcholine"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S0378874119315132", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29274", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029274.pdf", "pdf_sha256": "f66122fd6cbb80ee3592dd3bed0848bcd2a3fcd29e1df09762075dfa103b9a05", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '31557509', '10.1016/j.jep.2019.112249', 'ANTHELMINTIC ACTIVITY OF CRUDE POWDER AND CRUDE AQUEOUS EXTRACT OF TRACHYSPERMUM AMMI ON GASTROINTESTINAL NEMATODES IN DONKEY (EQUUS ASINUS): AN IN VIVO STUDY.', '1. AbbasImani-Baran, 1. JalalAbdollahi, 2. HamidAkbari, 3. SaeedJafarirad, 3. SajjadMoharramnejad.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance: Trachyspermum ammi has been used traditionally as a popular ethnobotanical plant in human and animal parasitic infestations. Few scientific studies have been conducted on in vitro anthelmintic activity of T. ammi against various helminths and there is no study on its in vivo/in vitro anthelmintic properties against equine helminths.Aim of the study: The present study aimed to evaluate in vivo anthelmintic activity of crude powder (CP) and crude aqueous extract (CAE) of T. ammi seeds against gastrointestinal nematodes in the donkey.Materials and methods: Thirty donkeys, naturally and severely infected with Strongyle-type nematodes, were randomly divided into six groups and administered orally with graded doses of CP and CAE at single dose as follow: Two groups were treated with 1 and 3 gkg-1 body weight of CP, two groups were treated with CAE at the equivalent dose rate 1 and 3 gkg-1 bw of CP and one group was treated with 200 µgkg-1 bw of Ivermectin 0.2% (Positive Control). One group received no medication (Negative Control). Efficacy was determined by faecal egg count reduction (FECR) test. The faecal samples were taken from the donkeys on days 7, 14 and 28 post-treatments (PT) and the egg per gram (EPG) of faeces was determined for each animal. FECR for donkeys treated with CP, CAE, and Ivermectin 0.2% was calculated on days 7, 14, and 28?PT. In the present study, CAE was analyzed using gas chromatography-mass spectrometry (GC-MS) to determine CAE chemical components. High-performance liquid chromatography (HPLC) using a marker (thymol) was applied to confirm the existence of thymol as an active principle.Results: Based on the FECR findings, the maximum FECR (71.2%) was observed in the group treated with CAE3 on day 14?PT, while it was 66.2% for CP3 on the same day. The effects of different treatments (P?&amp;lt;?0.001), time (P?&amp;lt;?0.001) and their interactions (P?&amp;lt;?0.05) on EPG showed a significant difference. A dose-dependent response in the anthelmintic activity of CP and CAE was observed. GC-MS analysis indicated that thymol was the major component of CAE (Area?=?45.01%) with the respective peak at retention times (Rt) 10.41?min. On HPLC analysis of CAE, thymol was found to be the major constituent of CAE (Area?=?58.76%) with the same Rt at 13.233?min.Conclusion: The present study indicated that both CP and CAE of T. ammi had the dose-dependent anthelmintic effects. Due to the development of drug resistance against synthetic anti-helminthics, T. ammi seems to be a promising alternative for the treatment and prevention of helminths in livestock.', '{"arp_id": "ARP_AYU029280", "portal_id": 29280, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "248", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anthelmintic Activity"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S037887411932344X", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29280", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029280.pdf", "pdf_sha256": "65cff892a065af05db8d58a7213f664fb661b621dad0c369254f7560e5f54784", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '32464314', '10.1016/j.jep.2020.112937', 'USE OF SPECIFIC COMBINATIONS OF THE TRIPHALA PLANT COMPONENT EXTRACTS TO POTENTIATE THE INHIBITION OF GASTROINTESTINAL BACTERIAL GROWTH.', '1,2. GaganTiwana, 3.4. Ian E.Cock, 3. AlanWhite, 1,2. Matthew J.Cheesman.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance: Triphala is used in Ayurveda to treat a wide variety of diseases, including numerous bacterial infections. Interestingly, the plant components of triphala (Terminalia bellirica, Terminalia chebula and Emblica officinalis) are also good inhibitors of bacterial growth when used individually, yet plant preparations are generally used in combination in traditional medicine. Surprisingly, no previous studies have addressed the reason why the combination is preferred over the individual components to treat bacterial infections.Aim of the study: To test and compare the antibacterial efficacy of triphala and its component parts to quantify their relative efficacies. The individual plant components will also be tested as combinations, thereby determining whether combining the individual components potentiates the antibacterial activity of the components used alone.Materials and methods: Triphala and the three individual plant components were extracted using solvents of varying polarity (methanol, water, ethyl acetate) and the antibacterial activity of the aqueous resuspensions was quantified by disc diffusion and broth microdilution MIC assays. Combinations of extracts produced from the individual components were also tested against each bacterial species and the SFICs was calculated to determine the class of interaction. Where synergy was detected, isobologram analysis was used to determine the optimal component ratios. The Artemia nauplii bioassay was used to test for toxicity and GC-MS headspace profiling analysis was used to highlight terpenoid components that may contribute to the antibacterial activity of triphala.Results: The aqueous and methanolic triphala, T. bellirica, T. chebula and E. officinalis extracts displayed good inhibitory activity against all bacterial strains, with MICs often in the 250–750 µg/mL range. The methanolic extracts were generally more potent than the aqueous extracts and T. chebula was the most potent of the individual plant components. Combining the extracts of the different plant species resulted in potentiation of the growth inhibitory activity of most combinations compared to that of the individual components. Indeed, with the exception of S. flexneri, all bacterial species were potentiated by at least one combination of methanolic plant extracts, with a substantial proportion of these displaying synergistic interactions. All extracts were found to be either non-toxic, or of low to moderate toxicity in Artemia nauplii assays.Conclusion: Whilst the individual plant components of triphala all inhibit the growth of multiple pathogenic bacteria, the activity is potentiated for multiple combinations. Therefore, the traditional usage of the combination of the three plant materials in triphala not only extends the activity profile of the mixture over that of the individual components, but it also substantially potentiates the inhibitory activity towards multiple bacteria, partially explaining the preference of triphala compared to the individual components.', '{"arp_id": "ARP_AYU029363", "portal_id": 29363, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "260", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antibacterial Activity"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S0378874120309387?via%3Dihub", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29363", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029363.pdf", "pdf_sha256": "80d5580e624bcc26e78762e7d03d3fa79a3a0afd370569492751bd9c5af3f7cd", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '34956375', '10.1155/2021/1227876', 'CAPPARIS SPINOSA ALLEVIATES DSS-INDUCED ULCERATIVE COLITIS VIA REGULATION OF THE GUT MICROBIOTA AND OXIDATIVE STRESS.', 'Xiaoting Zhu, Yi Yang, Weizhen Gao, Bingjie Jiang, Lei Shi.', 2021,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ulcerative colitis (UC) is a chronic inflammatory disease. Here, the potential effects of Capparis spinosa water extract (CSWE) on colonic histopathology, inflammation, and gut microbiota composition in dextran sulfate sodium (DSS) induced UC mice were evaluated. Our results showed that CSWE treatment improved the colonic histopathology of UC mice, increased the levels of tight junction protein gene ZO-1 and Occludin in intestinal epithelial cells, and inhibited the expression of proinflammatory cytokines (IL-1ß, IL-6, and TNF-a). Furthermore, CSWE administration alleviated oxidative stress in the colon of UC mice. The effects of CSWE on the compositions and metabolomic profiles of the gut microbiota in UC mice were investigated. It was found that CSWE could enhance the diversity of gut microbes and the abundance of probiotics and metabonomics had the strongest association with Firmicutes. Our results indicated that CSWE might be an ideal candidate as a potential therapeutic natural product for the treatment of UC.', '{"arp_id": "ARP_AYU023974", "portal_id": 23974, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2021", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Capparis Spinosa"], "original_url": "https://www.hindawi.com/journals/ecam/2021/1227876/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23974", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023974.pdf", "pdf_sha256": "266855bb3030a2587498411552777f62fac252c13bae4ec265b26971d0fa1559", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35222665', '10.1155/2022/1345006', 'ETHNOPHARMACOLOGICAL-BASED VALIDATION OF POLYALTHIA SUBEROSA LEAF EXTRACT IN NEUROLOGICAL, HYPERALGESIC, AND HYPERACTIVE GUT DISORDERS USING ANIMAL MODELS.', '1. Ruhul Amin, 2. Cristina Quispe, 3,4. Jesus Herrera-Bravo, 5. Md. Mizanur Rahman, 6. Radmila Novakovic,7,8. Sevgi Durna Dastan, 9. Atul Kabra,10. Javad Sharifi-Rad.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Polyalthia suberosa (Roxb.) is a plant used to cure coughs, dysentery, fevers, joint aches, rheumatic pain, inflammation, and a variety of skin diseases. The aim of the study was to evaluate the ethyl acetate extract of Polyalthia suberosa (P. suberosa) leaves and their effects on mice for neuropharmacological, analgesic, and antidiarrheal activities. For neurological studies, the hole cross, hole board, open field, and thiopental sodium-induced sleep duration measurement methodologies were used. The castor oil-induced diarrhea inhibition test was used to assess antidiarrheal action, and the acetic acid-induced writhing inhibition test was used to determine analgesic effectiveness. The extract was given in doses of 250 and 500?mg?kg-1 body weight. As a standard drug, diazepam at a dosage of 3?mg kg-1 was used. The extract was also given to groups, and sleep time was measured and recorded. The onset of the anxiolytic effect of the extract at both doses was found to be significant (P&amp;lt;?0.001), and sleep time increased to 273 minutes. For assessing analgesic activity, the extract along with standard diclofenac was administered and found to be 55.02 percent and 64.33 percent, respectively, for the extracts, and diclofenac was found to be 67.44 percent (P?&amp;lt;?0.001). For antidiarrheal activity, it was compared with the standard drug, loperamide. The decrease for plant extracts was 50.07 percent and 70.06 percent at 250?mg kg-1 and 500?mg kg-1, respectively, whereas it was 85.01 percent for loperamide (3?mg kg-1) (P&amp;lt;?0.00). In this study, it was found that ethyl acetate extract of Polyalthia suberosa leaves had strong CNS depressant, analgesic, and antidiarrheal activities, which indicates that it may be used in contemporary medicine.', '{"arp_id": "ARP_AYU024021", "portal_id": 24021, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2022", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Analgesic"], "original_url": "https://www.hindawi.com/journals/ecam/2022/1345006/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24021", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024021.pdf", "pdf_sha256": "b1917d4b6f944223335fd1309bc0c153af25cb89051f7cb3312989cdc2793d3a", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '36632855', '10.1016/j.jep.2023.116143', 'CLINICAL POTENTIAL AND MECHANISTIC INSIGHTS OF MULBERRY (MORUS ALBA L.) LEAVES IN MANAGING TYPE 2 DIABETES MELLITUS: FOCUSING ON GUT MICROBIOTA, INFLAMMATION, AND METABOLISM.', '1. Cheng Tang, 2,3. Tingting Bao, 4. Qiqi Zhang, 1,5,6. Hongyu Qi, 3. Yishan Huang, 3. Boxun Zhang, 3. Linhua Zhao, 1,3. Xiaolin Tong.', 2023,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance:Natural herbs are gradually gaining recognition for their efficacy and safety in preventing diabetes and improving quality of life. Morus alba L. is a plant widely grown in Asia and is a traditional Chinese herb with a long history of use. Furthermore, several parts of Morus alba L. have been found to have significant health benefits. In particular, mulberry (Morus alba L.) leaves (ML) have been shown in human and animal studies to be promising hypoglycemic agents that can reduce or prevent glucolipid metabolism disorders caused by imbalances in the gut microbiota, inflammation, and oxidative stress and have demonstrated significant improvements in glucose metabolism–related markers, effectively lowering blood glucose, and reducing hyperglycemia–induced target organ damage.Aim of the study:This review briefly summarizes the methods for obtaining ML&#39;s bioactive components, elaborates on the clinical potential of the relevant components in managing type 2 diabetes mellitus (T2DM), and focuses on the therapeutic mechanisms of gut microbiota, inflammation, oxidative stress, and metabolism, to provide more inspiration and directions for future research in the field of traditional natural plants for the management of T2DM and its complications.Materials and methods:Research on ML and its bioactive components was mainly performed using electronic databases, including PubMed, Google Scholar, and ScienceNet, to ensure the review&#39;s quality. In addition, master&#39;s and doctoral theses and ancient documents were consulted.Results:In clinical studies, we found that ML could effectively reduce blood glucose, glycated hemoglobin, and homeostasis model assessment of insulin resistance in T2DM patients. Furthermore, many in vitro and in vivo experiments have found that ML is involved in various pathways that regulate glucolipid metabolism and resist diabetes while alleviating liver and kidney damage.Conclusions:As a potential natural anti–diabetic phytomedicine, an in–depth study of ML can provide new ideas and valuable references for applying traditional Chinese medicine to treat T2DM. While continuously exploring its clinical efficacy and therapeutic mechanism, the extraction method should be optimized to improve the efficacy of the bioactive components. in addition, further research on the dose–response relationship of drugs to determine the effective dose range is required.', '{"arp_id": "ARP_AYU024066", "portal_id": 24066, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "306", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Gut Microbiota"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S0378874123000119", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24066", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024066.pdf", "pdf_sha256": "ce3546869e147f68d8fd97f82c53644bcfd70f80472192f56607bfad42384b6f", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35795288', '10.1155/2022/4163008', 'PRECLINICAL STUDIES TO EVALUATE THE GUT STIMULATORY ACTIVITY OF ALOE MUSABBAR.', '1. Vijayamahantesh K. Tandur, 1. Mohammed Naseeruddin Inamdar, 2. Raha Orfali, 3. Syed Mohammed Basheeruddin Asdaq, 4. Syed Imam Rabbani.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background. Constipation is a common functional gastrointestinal disorder. Medicines derived from nature are routinely used to treat it. The present study evaluates the gut stimulatory activity of Aloe musabbar (processed powder of Aloe vera) using in vitro and in vivo models for gut stimulatory activity. Materials and Methods. In vitro tests were conducted on isolated rat colon, guinea pig ileum, and rabbit jejunum, while in vivo study was performed using mice intestinal transit time. Aloe musabbar (A. musabbar) was tested at doses 0.2–200?mg/mL (in-vitro study) and 86.6?mg/kg (in vivo study). In vitro studies were done in the presence and absence of atropine sulphate (1?ng/ml). The results were statistically analyzed, and p&amp;lt;0.05 was considered to indicate the significance. Results. A. musabbar exhibited dose-dependent increase in the smooth muscle contraction of isolated gut tissues. Presence of atropine minimized the contractile responses and shifted the dose-response curves towards the right-hand side. The intestinal transit time in mice was observed to be increased significantly (p&amp;lt;0.01) in A. musabbar-treated animals, when compared with normal animals. Conclusion. A mild smooth muscle contraction induced by A. musabbar suggests that it can stimulate intestinal bowel movement without causing spasms. The diminished responses in the presence of atropine indicated that the gut stimulatory activity could be mediated partially through parasympathetic innervations. More studies are needed to determine the precise mechanism of action including the specific active ingredient responsible for the gut stimulatory activity.', '{"arp_id": "ARP_AYU024332", "portal_id": 24332, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2022", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aloe Musabbar"], "original_url": "https://www.hindawi.com/journals/ecam/2022/4163008/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24332", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024332.pdf", "pdf_sha256": "692de31c8c6921ae8b3cb0744c32fac5c108d86c64f86ae13ac353e779e8fed1", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35795290', '10.1155/2022/7964018', 'CANNABIS EXTRACT EFFECTS ON METABOLIC PARAMETERS AND GUT MICROBIOTA COMPOSITION IN A MICE MODEL OF NAFLD AND OBESITY.', '1. Gil Zandani, 2. Sarit Anavi-Cohen, 1. Tal Assa-Glazer, 3. Jonathan Gorelick, 4. Abraham Nyska, 5. Noa Sela, 6. Nirit Bernstein, 1. Zecharia Madar.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Nonalcoholic fatty liver disease (NAFLD) is a major cause of chronic liver abnormalities and has been linked with metabolic syndrome hallmarks. Unfortunately, current treatments are limited. This work aimed to elucidate the effects of three cannabis extracts on metabolic alteration and gut microbiota composition in a mouse model of NAFLD and obesity. Male mice were fed with a high-fat diet (HFD) for 12 weeks. Following the establishment of obesity, the HFD-fed group was subdivided into HFD or HFD that was supplemented with one of three cannabis extracts (CN1, CN2, and CN6) for additional 8 weeks. Metabolic parameters together with intestinal microbiota composition were evaluated. Except for several minor changes in gene expression, no profound metabolic effect was found due to cannabis extracts addition. Nevertheless, marked changes were observed in gut microbiota diversity and composition, with CN1 and CN6 exhibiting microbial abundance patterns that are associated with more beneficial outcomes. Taken together, specific cannabis extracts’ addition to an HFD results in more favorable modifications in gut microbiota. Although no marked metabolic effect was disclosed, longer treatments duration and/or higher extracts concentrations may be needed. More research is required to ascertain this conjecture and to establish the influence of various cannabis extracts on host health in general and NAFLD in particular.', '{"arp_id": "ARP_AYU024338", "portal_id": 24338, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2022", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cannabis Extract"], "original_url": "https://www.hindawi.com/journals/ecam/2022/7964018/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24338", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024338.pdf", "pdf_sha256": "2865246da8bd0d9465720035006ce73f08b95bb486e2bbc7be22b26b16c37eb3", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '36636608', '10.1155/2023/5625222', 'PROTECTIVE EFFECTS OF CLINACANTHUS NUTANS (BURM.F.) LINDAU AQUEOUS EXTRACT ON HBV MOUSE MODEL BY MODULATING GUT MICROBIOTA AND LIVER METABOLOMICS.', '1,2. Rui Zhang, 1. Zhe Lu, 3. Yachen Xu, 4. Qian Peng, 3. Man Xiao 2, 4. Shenggang Sang', 2023,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background. Clinacanthus nutans (Burm.f.) Lindau (C. nutans) has been used in the therapy of hepatitis B (HB) and is effective; however, the mechanism of action has not been elucidated. Objective. To investigate the protective effects of C. nutans aqueous extract on the hepatitis B virus (HBV) mouse model based on correlation analysis between gut microbiota and liver metabolomics. Materials and Methods. We firstly constructed the animal model by high-pressure injection of pcDNA3.1(+)/HBV plasmid into the tail vein and treated it with C. nutans. The biomarkers and inflammatory cytokines of HB were detected by enzyme-linked immunosorbent assay and quantitative PCR; the Illumina-MiSeq platform was used for investigating gut microbiota; the LC-MS/MS method was utilized on screening liver tissue metabolites; multiomics joint analysis was performed using the R program. Results. Compared with the modeling group, C. nutans significantly decreased the expression levels of HBsAg, IL-1ß, TNF-a in the serum, and cccDNA in the liver tissues of mice. C. nutans dramatically reduced the ratio of Firmicutes and Bacteroidetes and significantly declined the proportion of Lactobacillaceae and Lactobacillus, dramatically increasing the relative abundance of Bacteroidales_S24-7_group, Rikenellaceae, and Alistipes; LC-MS/MS analysis results showed that C. nutans dramatically upregulate hippuric acid, L-histidine, trehalose, D-threitol, and stachyose and downregulate uridine 5&#39;-diphosphate, cholic acid, trimethylamine N-oxide, CDP-ethanolamine, and phosphorylcholine . The correlation analysis revealed that C. nutans affects the related metabolite levels of hippuric acid and cholic acid through the modulation of crucial bacteria (Alistipes) , exerting specific anti-inflammatory effects. Conclusion. These results suggest that C. nutans exerts protective effects in HBV model mice, showing the therapeutic potential for anti-HBV infection.', '{"arp_id": "ARP_AYU024680", "portal_id": 24680, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2023", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Hbv Infection"], "original_url": "https://www.hindawi.com/journals/ecam/2023/5625222/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24680", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024680.pdf", "pdf_sha256": "736472f57261cd998b66a1256a6c9dfde007638786bb530829575051bf07dd43", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '33022343', '10.1016/j.jep.2020.113445', 'ETHANOL EXTRACT OF CENTELLA ASIATICA ALLEVIATED DEXTRAN SULFATE SODIUM-INDUCED COLITIS: RESTORATION ON MUCOSA BARRIER AND GUT MICROBIOTA HOMEOSTASIS.', '1,2. Huibiao Li, 1,3. Xiaohong Chen, 1,4. Jiayao Liu, 1,2. Muyuan Chen, 1,4. Ming Huang, 5. Guoxin Huang, 1. Xinlin Chen, 1,4. Qin Du, 3. Jiyan Su, 1,4. Rongfeng Lin.', 2021,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Ethnopharmacological relevance:Ulcerative colitis (UC) is a relapsing inflammatory disease that still demands for effective remedies due to various adverse effects of the current principal treatments. Centella asiatica is a traditional medical herb with long application history in anti-inflammation.Aim of the study:To explore the anti-inflammatory effect and possible mechanism of C. asiatica ethanol extract (CA) in a murine colitis model induced by dextran sulfate sodium (DSS).Materials and methods:CA was analyzed by high performance liquid chromatograph (HPLC). The colitis model was induced by free access to 3% DSS in distilled water for 7 days. CA (100, 200, and 400?mg/kg) and 5-aminosalicylic acid (5-ASA, 400 mg/kg) were administrated by gavage during the 7-day DSS challenge. At the end of experiment, mice were sacrificed and the brain, colon and cecum contents were harvested for analysis. Colitis was evaluated by disease activity index (DAI), colon length and colon lesion macroscopic score with hematoxylin-eosin staining. Myeloperoxidase (MPO) activity in colon and 5-hydroxytryptamine (5-HT) in brain were determined by ELISA. Tight junction protein expressions (ZO-1, E-Cadherin, Claudin-1) and c-Kit in colon were assessed by western blot and immunohistochemistry, respectively. Microbiota of cecum content was analyzed by 16S rRNA sequencing.Results:Data showed that with recovery on the colon length and histological structure, CA prominently decreased DAI and macroscopic score for lesion in the suffering mice. CA relieved the colitis by suppressing inflammatory cell infiltration with decreased MPO activity in the colon, and up-regulated the expression of tight junction protein (ZO-1, E-cadherin) to enhance the permeability of intestinal mucosa. Moreover, CA restored intestinal motility by promoting c-Kit expression in the colon and 5-HT in the brain. Moreover, CA was able to reshape the gut microbiota in the suffering mice. It increased the a-diversity and shifted the community by depleting the colitis-associated genera, Helicobacter, Jeotgalicoccus and Staphylococcus, with impact on several metabolism signaling pathways, which possibly contributes to the renovation on the impaired intestinal mucosal barrier.Conclusions:CA displayed the anti-inflammatory activity against the DSS-induced colitis, which would possibly rely on the restoration on mucosa barrier and gut microbiota homeostasis, highlights a promising application of C. asiatica in the clinical treatment of UC.', '{"arp_id": "ARP_AYU029474", "portal_id": 29474, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "267", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Inflammatory Effect"], "original_url": "https: //www.sciencedirect.com/science/article/abs/pii/S0378874120333304", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=29474", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU029474.pdf", "pdf_sha256": "abc9521721c601c8ddaa7111c6d2822defea1037dd86c02bf9356d52656eb805", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.7897/2277-4343.1006132', 'A CASE STUDY TO EVALUATE THE EFFICACY OF PANCHAKOLA UDAKA AND AAROGYAVARDHINI VATI IN GRAHANI DOSHA WITH SPECIAL REFERENCE TO IRRITABLE BOWEL SYNDROME.', 'Anjali Goyal.', 2019,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background : - Keywords : Aarogyavardhini Vati And Ayurveda , Grahani Dosha , Irritable Bowel Syndrome , Panchakola Udaka URL (for Abstract/ Full paper) : https://ijrap.net/index.php/login/abstractt?id=2311 DOI : 10.7897/2277-4343.1006132 Access : -', '{"arp_id": "ARP_AYU002359", "portal_id": 2359, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Ayurveda and Pharmacy", "volume": "10", "issue": "6", "pages": "95 - 99", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "IRRITABLE BOWEL SYNDROME(ICPC-D93|ICD-K58)", "keywords": ["Aarogyavardhini Vati And Ayurveda"], "original_url": "https://ijrap.net/index.php/login/abstractt?id=2311", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2359", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002359.pdf", "pdf_sha256": "d7bf125aa90fbccfefb6e7b843e2e10fcf3f37ad4fa78362c8eac137f46c2178", "relevance_score": 52.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '36535329', '10.1016/j.jep.2022.116058', 'EFFICACY AND SAFETY OF ADD-ON VIOLA ODORATA L. IN THE TREATMENT OF COVID-19: A RANDOMIZED DOUBLE-BLIND CONTROLLED TRIAL.', '1,2. Mohammad Sadegh Adel Mehraban, 1,3. Meysam Shirzad, 4. Leila Mohammad Taghizadeh Kashani, 5. Mohammad Mahdi Ahmadian-Attari, 5. Ali Akbar Safari, 6. Narges Ansari, 7. Hossein Hatami, 8. Mohammad Kamalinejad.', 2023,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Ethnopharmacological relevance:Severe Acute Respiratory Syndrome (SARS) due to the novel coronavirus has become the highest priority that threatens human health. This situation demands widespread vaccination and the innovation of new therapeutic methods. Despite drug discoveries, the need for approving new medicaments is felt because of adverse effects and lack of efficacy. Several medicinal plants including Viola odorata L. are recommended in traditional Persian medicine for alleviating respiratory infection symptoms. Recent studies showed anti-inflammatory, antioxidant, anti-asthmatic, antitussive, analgesic, and antibacterial activities of sweet violet. These enhance respiratory functions, reduce pulmonary inflammation, and decline mucous membrane edema. This study aimed to evaluate the efficacy of sweet violet syrup in alleviating the manifestations of COVID-19 infection.Material and methods:A randomized parallel-group double-blind controlled trial was conducted at Al-Zahra general hospital, Isfahan, Iran. A total of 108 outpatients were enrolled in the study. The patients were randomly allocated to intervention and placebo groups, with 54 patients in each group. The allocation was concealed using sealed opaque envelopes. The intervention group received violet syrup and the control group received placebo syrup, an add-on to the conventional treatment. The outcomes were COVID-19 manifestations, such as dyspnea, cough, myalgia, headache, and diarrhea, considered as outcomes of the study and were evaluated twice using a visual analog scale before the intervention and after 7 days, at the end of the study. Patients were followed daily by phone calls to monitor proper drug consumption and possible side effects.Results:No significant difference was between groups regarding demographic characteristics and vital signs before and after the treatment. Although all symptoms have improved significantly in both groups, patients who received violet syrup recovered faster and the mean severity scores of cough (P = 0.025), myalgia (P = 0.036), headache (P = 0.037), and diarrhea (P = 0.044) decreased greater in comparison to control group.Conclusion:This study, the first clinical trial on the effectiveness of Viola odorata on SARS-CoV-2 patients, showed that Viola odorata L. effectively controls prevalent manifestations of COVID-19 including cough, myalgia, headache, and diarrhea. Regarding this survey, the violet syrup can be mentioned as a complementary treatment for viral influenza-like infections in which cough, myalgia, headache, and diarrhea are prominent.', '{"arp_id": "ARP_AYU002965", "portal_id": 2965, "medical_system": "AYURVEDA", "journal": "Journal of Ethnopharmacology", "volume": "304", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "INTERNATIONAL PROVISIONAL ASSIGNMENT OF NEW DISEASES OF UNCERTAIN AETIOLOGY AND EMERGENCY USE (COVID-19 (ICPC- A-77|ICD-RA-01))", "keywords": ["Covid-19"], "original_url": "https: //www.sciencedirect.com/science/article/pii/S0378874122010972", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2965", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002965.pdf", "pdf_sha256": "192f85e001001d630b953f48367fa8b28deaedb2537483987dd9f25b7ac93fbc", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5005/jp-journals-10059-0031', 'EVALUATION OF SAFETY OF KARNASPHOTA (CARDIOSPERMUM HALICACABUM L.) LEAF THROUGH ACUTE ORAL TOXICITY STUDY AND REPEATED DOSE: 28-DAY ORAL TOXICITY STUDY IN WISTAR ALBINO RATS.', '1. Natarajan Thamizhselvam, 2. Kandiyoor R Surabhi, 3. Yalwar R Sanjayakumar, 4. Kannanamkulam G Vasanthakumar, 5. Sudesh N Gaidhani, 6. Paravazhi Radhakrishnan.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aim: Cardiospermum halicacabum L. is a climbing plant under Sapindaceae family. The plant leaf is used by traditional healers for treatment of various illnesses. Considering the ethno-medicinal value of C. halicacabum, the present study was taken up to evaluate single-dose acute toxicity study and repeated dose 28-day oral toxicity study (subacute) in Wistar albino rats. Materials and methods: The hydroalcoholic extract of C. halicacabum leaf was administered orally to Wistar rats as single dose (2000 mg/kg bwt) in acute toxicity study and for continuous 28 days in repeated dose subacute toxicity study at three dose levels (250, 500, and 1000 mg/kg bwt). The study was carried out as per Organisation for Economic Cooperation and Development (OECD) guidelines 423 and 407. Animal mortality and general behavior were observed during the study period. Results: The study showed that there were no mortality and morbidity in the test groups. The detailed biochemical and hematological investigations evaluated in control and test groups evidenced the safety of the extract as there were no significant differences among control and test groups. Histopathology study in vital organs of test groups showed no significant abnormalities. Conclusion: The study concluded that the hydroalcoholic extract of C. halicacabum was safe at the prescribed dosages in Wistar albino rats.', '{"arp_id": "ARP_AYU004480", "portal_id": 4480, "medical_system": "AYURVEDA", "journal": "Journal of Drug Research in Ayurvedic Sciences", "volume": "3", "issue": "1", "pages": "15 - 22", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Acute And Repeated Dose 28-Day Oral Toxicity Study"], "original_url": "https://www.jaypeedigital.com/abstractArticleContentBrowse/JDRAS/52/3/1/12028/abstractArticle/Article", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4480", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004480.pdf", "pdf_sha256": "fd12c204f885e64bc8107f7dcb7458ffaca782493863d4a5e7d22a18cea44cec", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35252231', '10.3389/fmed.2022.761655', 'RANDOMIZED, DOUBLE BLIND, PLACEBO CONTROLLED, CLINICAL TRIAL TO STUDY ASHWAGANDHA ADMINISTRATION IN PARTICIPANTS VACCINATED AGAINST COVID-19 ON SAFETY, IMMUNOGENICITY, AND PROTECTION WITH COVID-19 VACCINE-A STUDY PROTOCOL.', '1. Arvind Chopra, 2. Preeti Chavan-Gautam, 2. Girish Tillu, 1. Manjit Saluja, 2. Swapnil Borse, 1. Sanjeev Sarmukaddam, 3. Susmita Chaudhuri, 4. Rao BCS, 4. Babita Yadav, 4. Narayanam Srikanth, 2. Bhushan Patwardhan.', 2022,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Introduction: Vaccines have emerged as the most effective tool in the fight against COVID-19. Governments all over the world have rolled out the COVID-19 vaccine program for their populations. Oxford-AstraZeneca COVID-19 vaccine (COVISHIELD™) is widely used in India. A large number of Indian people have been consuming various traditional medicines in the hope of better protection against COVID-19 infection. Several studies have reported immunological benefits of Withania somnifera (Ashwagandha) and its potential as a vaccine adjuvant. We propose to study the safety, immunogenicity and clinical protection offered by a 6-month regimen of Ashwagandha in participants who volunteer to be vaccinated against COVID-19 (COVISHIELDTM) in the ongoing national program of vaccination.Methods and Analysis: We designed a prospective, randomized, double-blind, parallel-group, placebo-controlled, two-arm, exploratory study on healthy volunteers receiving the COVISHIELDTM vaccine. The administration of Ashwagandha will begin within 7 days of the first or second dose of COVISHIELDTM. Primary outcome measure is immunogenicity as measured by SARS-CoV-2 spike (S1) and RBD-specific IgG antibody titres. Secondary outcome measures are safety, protective immune response and quality of life measures. All adverse events will be monitored at each time throughout the study. Participants will be tracked on a daily basis with a user-friendly mobile phone application. Following power calculation 600 participants will be recruited per arm to demonstrate superiority by a margin of 7% with 80% power. Study duration is 28 weeks with interim analysis at the end of 12 weeks.Ethics and Dissemination: Ethics approval was obtained through the Central and Institutional Ethics Committees. Participant recruitment commenced in December 2021. Results will be presented in conferences and published in preprints followed by peer-reviewed medical journals.', '{"arp_id": "ARP_AYU015558", "portal_id": 15558, "medical_system": "AYURVEDA", "journal": "Frontiers in Medicine", "volume": "9", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "INTERNATIONAL PROVISIONAL ASSIGNMENT OF NEW DISEASES OF UNCERTAIN AETIOLOGY AND EMERGENCY USE (COVID-19 (ICPC- A-77|ICD-RA-01))", "keywords": ["Ashwagandha"], "original_url": "https://www.frontiersin.org/articles/10.3389/fmed.2022.761655/full", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15558", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015558.pdf", "pdf_sha256": "efcd232ad9d1c8519778797e23106bbd9b097e70b421b187cea70ef1c014ba14", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5455/njppp.2019.9.1034131102019', 'SAFETY ASSESSMENT OF THE ETHANOL EXTRACT OF CAESALPINIA BONDUC (L.) ROXB. ROOT IN WISTAR RATS: ACUTE AND SUBACUTE (28-DAY) ORAL TOXICITY STUDIES.', '1. Mariette Sindete, 1. Adam Gbankoto, 2. Habib Ganfon, 3. Razack Osseni, 4. Achille Yemoa, 5. Anatole Laleye.', 2019,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Caesalpinia bonduc (CB) root is used in African Pharmacopoeia for the prevention and treatment of sexual failure.Aims and Objective: The current study performed to evaluate the acute and subacute oral toxicity of the ethanolic extract of CB root.Materials and Methods: Two groups of three female Wistar rats were used for acute oral toxicity test. A single dose of 2000 mg/kg body weight (BW) of the ethanolic extract of CB root was administered to the test group; the control group received dimethyl sulfoxide. Rats were observed individually during the first 4 h and then daily until days 14. For subacute toxicity model, the male rats were divided into four groups (n = 6). Experimental groups received 31, 25, 125, and 500 mg/kg of BW of the ethanolic extract of CB root orally daily for 28 days. The blood hematological and biochemical parameters, as well as histopathology of liver and kidneys, were studies.Results: No toxicological signs were observed in rats when acutely exposed to the ethanolic extract of CB root. After the repeated administration of CB root extract, hematological and biochemical parameters were unaltered except hemoglobin and erythrocyte number in the exposed animal, but they were considered to be temporary effects and not an indication of toxic effects. No macroscopic changes and no noticeable histological changes were seen in the histopathology analysis of kidneys and liver.Conclusion: Ethanolic extract of CB root at single dosage level up to 2000 mg/Kg BW is nontoxic and can show protection of some vital organs when administered to 28 days.', '{"arp_id": "ARP_AYU021651", "portal_id": 21651, "medical_system": "AYURVEDA", "journal": "National Journal of Physiology, Pharmacy and Pharmacology", "volume": "9", "issue": "12", "pages": "1267 - 1277", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Acute Toxicity"], "original_url": "http://www.njppp.com/index.php?mno=68491", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=21651", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU021651.pdf", "pdf_sha256": "ffd949522e083446d03d1386e3c098ada40c56b44914d97786636cda338d067a", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '33354219', '10.1155/2020/2891058', 'ACUTE AND SUBCHRONIC ORAL SAFETY PROFILES OF THE SUDARSHANA SUSPENSION.', '1. Weerakoon Achchige Selvi Saroja Weerakoon, 2. Pathirage Kamal Perera, 3. Kamani Samarasinghe,4. Dulani Gunasekera, 5. Thusharie Sugandhika Suresh.', 2020,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Sudarshana powder (SP) is an Ayurvedic preparation, which contains 53 herbal ingredients along with 50% of Andrographis paniculata and is clinically used with bees honey. +is study was aimed to determine the safety profile of the SP, and its novel preparation Sudarshana suspension (SS) on male Wistar rats and tolerance studies were conducted for healthy adult volunteers. Acute and subacute toxicity studies of the SS and hot water extract of SP were assessed in Wistar rats by observing the general behavior, analyzing biochemical and haematological parameters, and pathological observation. Healthy consented adult volunteers (n= 35) of either sex were selected, and tolerance studies of SS were tested by measuring the biochemical and haematological parameters. +ere were no significant (p &amp;gt; 0.05) changes observed in the treated animals with SS and hot water extract of SP compared with control in body weights, food intake, and water consumption as well as the biochemical and haematological parameters. Histopathological studies revealed no significant (p &amp;gt; 0.05) changes in the liver, heart, and kidney tissues. The experimental results suggest that novel formulation SS was potentially safe for chronic administration in rats, and no significant differences (p &amp;gt; 0.05) were observed in tested parameters on day 3 and day 8 when compared to the day 0 (baseline) values in healthy volunteers. Healthy volunteers did not report any adverse effects or any other complications during the treatment period and the follow-up period. Theerefore, it can be concluded that the novel preparation Sudarshana suspension does not cause any significant toxic effects on the blood parameters in animal and human models.', '{"arp_id": "ARP_AYU023815", "portal_id": 23815, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2020", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "HEALTH MAINT/PREVENTIVE MEDICINE(ICPC-A98|ICD-Z01, Z10, Z11, Z12, Z13, Z40, Z70)", "keywords": ["Andrographis Paniculata"], "original_url": "https://www.hindawi.com/journals/ecam/2020/2891058/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23815", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023815.pdf", "pdf_sha256": "d86c460b000de8bcdff82f489edd1577f7e6c2bee7bfb6af61ad3142ce7d3b81", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '32832131', '10.1155/2020/1308541', 'ANTIPLASMODIAL AND ANTIPYRETIC ACTIVITY AND SAFETY EVALUATION OF THE METHANOLIC LEAF EXTRACT OF MURRAYA EXOTICA (L.).', '1. Arnold Donkor Forkuo,1. Kwesi Boadu Mensah, 2. Elvis Ofori Ameyaw, 1. Aaron Opoku Antwi, 1. Nana Kofi Kusi-Boadum,1. Charles Ansah.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: The increasing mortality and morbidity of malaria in Africa coupled with the recent reports of antimalarial drug resistance reinforces the need for novel antimalarial agents from natural plant products with folkloric use for the disease. Murraya exotica (L.) (Rutaceae) is widely used as an ornamental plant used indigenously to treat fever, cough, and infectious wounds and eliminate pain from injury and trauma. This study was conducted to evaluate extracts of the leaves of Murraya exotica (L.) (Rutaceae) for its safety and antipyretic and antimalarial activity in rodent models. Method: In this study, the Peters 4-day suppressive and curative test in Plasmodium berghei-infected mice was used to demonstrate the antiplasmodial activity of the methanolic leaf extract of Murraya exotica (L.) (MEE). The study also evaluated the subacute toxicity study and the antipyretic activity of MEE on baker’s yeast-induced hyperthermia in rodent models. Results: Murraya exotica (L.) extract demonstrated curative antimalarial activity, with a percentage suppression of 45.84, 64:32 &amp;#177; 0:33, 56:74 &amp;#177; 2:16, and 64:61 &amp;#177; 0:67 at doses of 50, 100, 300, and 600 mg/kg, respectively. In the Peters 4-day suppressive test, MEE at dose 600 mg/kg had the highest chemosuppression (76:02 &amp;#177; 1:38%) compared with artesunate (2 mg/kg, p.o.) (82:56 &amp;#177; 0:97%). Subacute oral toxicity studies in Sprague-Dawley rats documented no deaths, with no significant changes in clinical signs, organ weights, and hematological and biochemical parameters. The LD50 of MEE was estimated to be above 1000 mg/kg in Sprague-Dawley rats. All doses of MEE and paracetamol reduced pyrexia in 1 h and 2 h after their administration. The percentage reduction of rectal temperature (TR) for the positive control (paracetamol, 150 mg/kg, p.o.) was 44.36% while the Murraya exotica extract at doses 50 mg/kg, 100 mg/kg, 300 mg/kg, and 600 mg/kg recorded 67.74%, 40.78%, 66.42%, and 59.42%, respectively. Murraya exotica at dose 100 mg/kg exhibited significant reduction (p &amp;lt; 0:05) in baker’s yeast-induced pyrexia.Conclusions: The findings in this study show the antipyretic, curative, and suppressive antiplasmodial activity as well as the safety of the methanolic leaf extract of Murraya exotica (L.) supporting its traditional use for malaria and fever.', '{"arp_id": "ARP_AYU023988", "portal_id": 23988, "medical_system": "AYURVEDA", "journal": "Journal of Parasitology Research", "volume": "2020", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antiplasmodial"], "original_url": "https://www.hindawi.com/journals/jpr/2020/1308541/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23988", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023988.pdf", "pdf_sha256": "6708d30a630e86300547db91c2e6a57537fc5d56dd6af5c8617bf69cb67250ba", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35370379', '10.4103/ayu.ayu_11_21', 'EFFICACY AND SAFETY OF GUDUCHIGHANA VATI IN ASYMPTOMATIC AND MILD-TO-MODERATE CASES OF CORONAVIRUS DISEASE-19: A RANDOMIZED CONTROLLED PILOT STUDY.', '1. Umesh Shukla, 2. Nitin Ujjaliya, 3. Pankaj Gupta, 4. Vivek Khare, 5. Babita Yadav, 5. Amit Kumar Rai, 5. Hetalben Amin, 6. Rakesh Rana, 6. Arunabh Tripathi, 5. Shruti Khanduri, 5. Bhagwan Sahay Sharma, 5. Bhogavalli Chanasekhararao, 7. Narayanam Srikanth, 8. Kartar Singh Dhiman.', 2020,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Currently, there is no approved treatment for the management of coronavirus disease (COVID-19). Drug repurposing of existing medications could be a possible way to find out a novel therapeutic entity to combat the COVID-19. Aim: To determine the clinical efficacy and safety of an Ayurveda intervention (Guduchighana Vati) in asymptomatic and mild-to-moderate cases of COVID-19. Materials and methods: This was an open-label randomized controlled pilot study with a sample size of 30 participants (15 in each arm). The participants were asymptomatic or mild to moderate cases of COVID-19. Guduchighana Vati 500 mg twice daily for 10 days was administered in the study group and Hydroxychloroquine for 5 days in the control group. Paracetamol, Vitamin C, Multivitamin, and Zinc were also provided in the control group. The main outcome measures were to negative real-time reverse transcription–polymerase chain reaction (RT-PCR) assay for COVID-19, proportion of participants with negative RT-PCR for COVID-19 at 5th and 10th day, proportion of participants with clinical recovery, improvement in laboratory parameters, and incidence of adverse drug reaction/adverse event (ADR/AE). The results of RT-PCR and clinical recovery were compared between groups using Chi-square test. The data related to laboratory parameters were compared within group using paired sample t-test/Wilcoxon signed-rank test and between groups using independent sample t-test/Mann–Whitney test. Results: The proportion of participants with negative RT-PCR for COVID-19 in the Guduchighana Vati group (93.3%) was better as compared to the control group (66.6%) till 10th day of the study period. Though, the results are statistically not significant (P = 0.068). All the symptomatic patients in the Guduchighana Vati group clinically recovered whereas one patient remained symptomatic in the control group on the 5th day. No symptoms of COVID-19 were observed at 10th day in both the groups. No ADR/serious adverse event were observed during the study period in either of the groups. Conclusion: In this study on asymptomatic and mild to moderate cases of COVID-19, Guduchighana Vati showed numerically better proportion of participants with negative RT-PCR assay for COVID-19 and reduced time to clinical improvement which requires confirmation through studies with larger sample size. Although, the study outcomes are statistically not significant which may be due to small sample size.', '{"arp_id": "ARP_AYU024006", "portal_id": 24006, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "41", "issue": "3", "pages": "188 - 196", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "GENERAL/UNSPECIFIED", "disease": "INTERNATIONAL PROVISIONAL ASSIGNMENT OF NEW DISEASES OF UNCERTAIN AETIOLOGY AND EMERGENCY USE (COVID-19 (ICPC- A-77|ICD-RA-01))", "keywords": ["Coronavirus Disease-19"], "original_url": "https://journals.lww.com/aayu/fulltext/2020/41030/efficacy_and_safety_of_guduchighana_vati_in.7.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24006", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024006.pdf", "pdf_sha256": "b60dbf2316b70d50d409c8b3f0d9361f60a74494fb2f538d58d6c90b632ad2cb", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35251213', '10.1155/2022/7943001', 'SAFETY EVALUATION IN HEALTHY COLOMBIAN VOLUNTEERS OF P2ET EXTRACT OBTAINED FROM CAESALPINIA SPINOSA: DESIGN 3 PLUS 3 PHASE I CLINICAL TRIAL.', '1. Maria I Duran, 1. Ricardo Ballesteros-Ramirez, 2. Angelica Tellez, 3. Lilian Torregrosa, 4. Peter A Olejua, 4. Silvia Galvis, 1. Claudia Uruena, 1. Susana Fiorentino.', 2022,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: The polyphenol-enriched extract called P2Et derived from Caesalpinia spinosa (C. spinosa) had antitumor and immunomodulatory activities reported in breast cancer, leukemia, and melanoma. The aim of this study was to evaluate the safety and maximum tolerated dose of P2Et extract in Colombian healthy volunteers in a phase 1 clinical trial, open labelled, single-arm, dose-escalation design 3?+?3. Seven healthy volunteers were included; P2Et was administrated in capsules of 600?mg/d for 28 days. Analysis by intention to treat was performed. 4 volunteers showed adverse events and discontinued the intervention. 94.6% of AE were grade 1, and most of AE had a reasonable possibility of a relationship with the P2Et (83.8%). We found that the oral administration of P2Et is safe in healthy humans with a maximum tolerated dose of 600?mg/d. There was no severe toxicity; most of the adverse events were mild, without significant changes in the safety parameters evaluated.', '{"arp_id": "ARP_AYU024058", "portal_id": 24058, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2022", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "NO DISEASE(ICPC-A97|ICD-Z00, Z02)", "keywords": ["Caesalpinia Spinosa"], "original_url": "https://www.hindawi.com/journals/ecam/2022/7943001/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24058", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024058.pdf", "pdf_sha256": "47e892cf3283bb5734770b4bcc19bf47473f64db17d721db5abd143c7a7006a5", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '32695156', '10.1155/2020/8197902', 'MORINGA OLEIFERA L. EXTRACTS AS BIOACTIVE INGREDIENTS THAT INCREASE SAFETY OF BODY WASH COSMETICS.', '1. Zofia Niziol-Lukaszewska, 1. Dominika Furman-Toczek, 1. Tomasz Bujak, 2. Tomasz Wasilewski, 3. Zofia Hordyjewicz-Baran.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The work attempts to obtain a multifunctional plant extract derived from Moringa tree leaves. Obtained results indicate a strong antioxidant potential of the tested extracts. It was shown that Moringa oleifera leaf extract is a rich source of flavonoid and phenolic compounds. Furthermore, it shows a strong antioxidant activity by scavenging free radicals. In vitro toxicity studies showed that the tested extracts in concentrations up to 5% showed a positive effect on cell proliferation and metabolism and may contribute to the reduction of oxidative stress in cells. It was noted that the tested model formulation of cosmetic (1% SCS) with the addition of different types of extracts might contribute to the reduction of skin irritation and improve the safety of the product.', '{"arp_id": "ARP_AYU024073", "portal_id": 24073, "medical_system": "AYURVEDA", "journal": "Dermatology Research and Practice", "volume": "2020", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Fibroblasts"], "original_url": "https://www.hindawi.com/journals/drp/2020/8197902/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24073", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024073.pdf", "pdf_sha256": "cbb2f979833b5d2f43e514f33d3c91db886accb5ccfc382bb3bff3d02e7c4ccf", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35368764', '10.1155/2022/1419146', 'PREPARATION AND SAFETY EVALUATION OF CENTELLA ASIATICA TOTAL GLYCOSIDES NITRIC OXIDE GEL AND ITS THERAPEUTIC EFFECT ON DIABETIC CUTANEOUS ULCERS.', '1,2. Yi-qiu Liu, 3. Dandan Zhang, 1,2. Junyu Deng, 1,2. Ye Liu, 1,2. Wei Li, 1,2. Xuqiang Nie.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Diabetic cutaneous ulcers (DCU) are a chronic and refractory complication of diabetes mellitus, which can lead to amputation or even death in extreme cases. Promoting the early healing of DCU and reducing the disability rate and treatment cost are important research topics in treating with integrated traditional Chinese and Western medicine. Centella asiatica total glycosides are extracted from the traditional Chinese medicine Centella asiatica and have angiogenic, anticancer, antioxidant, and wound healing effects. Nitric oxide (NO) is a critical component of wound healing. During the development of DCU, endogenous NO secretion is insufficient. It has been reported that exogenous nitric oxide can promote wound healing, but it is difficult to adhere to the skin because of its short half-life. Therefore, in this study, we used the polymer excipient hydroxyethyl cellulose as the matrix, combined with Centella asiatica total glycosides and NO, and developed a new type of topical gel that can promote wound healing. At the same time, we made a comprehensive research and evaluation on the preparation technology, quality standard, skin toxicity, reproductive toxicity, and pharmacodynamics against diabetic skin ulcers of the gel. According to our research results, the combination of Centella asiatica total glycosides and nitric oxide can accelerate the healing speed of DCU wounds, and 8% Centella asiatica total glycosides nitric oxide gel (CATGNOG) has the best effect in ulcer wound healing. CATGNOG has the advantages of feasible preparation method, controllable quality, good stability at low temperature, and no apparent skin toxicity and reproductive toxicity. It can effectively inhibit the growth of bacteria on the wound surface, relieve the inflammatory reaction of the wound surface, and promote the healing of ulcer wound, which provides a basis for further research of the preparation in the future.', '{"arp_id": "ARP_AYU024076", "portal_id": 24076, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2022", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Centella Asiatica"], "original_url": "https://www.hindawi.com/journals/ecam/2022/1419146/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=24076", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU024076.pdf", "pdf_sha256": "827b1b07b608d0fb14e2d4077fc185f2b58f6ec276be0b0055592a133c98b80b", "relevance_score": 52.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '35345372', '10.31557/APJCP.2022.23.3.985', 'CHEMOPREVENTIVE EFFECT OF DIETARY MARANTA ARUNDINACEA L. AGAINST DMBA-INDUCED MAMMARY CANCER IN SPRAGUE DAWLEY RATS THROUGH THE REGULATION OF AUTOPHAGY EXPRESSION.', '1,2. Ika Fidianingsih, 3. Teguh Aryandono, 4. Sitarina Widyarini, 5. Sri Herwiyanti, 6. Sunarti Sunarti.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Breast cancer prevention still needs to be improved. Calorie restriction is thought to prevent breast cancer through the induction of autophagy. Maranta arundinacea L. (MA) has the potential for calorie restriction because it contains high fiber. This research aimed to observe the effect of dietary MA against dimethylbenz(a)anthracene (DMBA)-induced mammary cancer in Sprague Dawley rats related to autophagy. Methods: Twenty-five Sprague Dawley rats were randomly divided into five groups: 1) control group without DMBA-induced with a standard diet, 2) 20 mg/kg BW of DMBA two times a week for five weeks with a standard diet, 3) DMBA and diet modification with 30% of MA, 4) DMBA and diet modification with 45% of MA, and 5) DMBA and diet modification with 60% of MA. Examination of the nodule was conducted once every week for 22 weeks. Breast tissue/tumor examination underwent histology examination with hematoxylin-eosin. Examinations of immunohistochemical staining against Beclin1, LC3B, and SQSTM1 were conducted to reveal autophagy. The difference of autophagy protein expression was analyzed using One way ANOVA with 95% confidence level and significance set as p&amp;lt;0.05. Results: Cancer was detected in four rats of DMBA standard diet, two rats of 30% MA, one rat of 45% MA. No cancer was detected in the rats of control and rats with 60% of MA group. The Beclin1 expressions showed that the 60% of MA group had the highest score (2.5&amp;#177;0.52) followed by the 45% of MA group (1.87&amp;#177;0.49), control group (1.77&amp;#177;0.11), 30% of MA group (1.28&amp;#177;0.75), and DMBA with standard diet had the lowest score (1.28&amp;#177;0.91). The difference of Beclin1 expressions was statistically significant (p-value=0.03). However, the difference of the LC3B expressions (p-value=0.11) and SQSTM1 expressions (p-value=0.225) were not statistically significant. Conclusion: Dietary modifications with MA potentially prevent breast cancer and induce initiation of autophagy.', '{"arp_id": "ARP_AYU015167", "portal_id": 15167, "medical_system": "AYURVEDA", "journal": "Asian Pacific Journal of Cancer Prevention", "volume": "23", "issue": "3", "pages": "985 - 993", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Dmba"], "original_url": "http://journal.waocp.org/article_90029.html", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15167", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015167.pdf", "pdf_sha256": "2c93ef941bded3538f45a1932b8e8c4045e94f9c76be5b59812a43586b75b086", "relevance_score": 52.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '14723327', NULL, 'EVALUATION OF THE EFFICACY OF BITTER GOURD (MOMORDICA CHARANTIA) AS AN ORAL HYPOGLYCEMIC AGENT -A RANDOMIZED CONTROLLED CLINICAL TRIAL', 'John AJ, Cherian R, Subhash HS, Cherian AM.', 2003,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Not Available (See full paper)', '{"arp_id": "ARP_AYU000927", "portal_id": 927, "medical_system": "AYURVEDA", "journal": "Indian Journal of Physiology and Pharmacology", "volume": "47", "issue": "3", "pages": "363 - 365", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes"], "original_url": "https://www.ijpp.com/IJPP%20archives/2003_47_3/363-365.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=927", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000927.pdf", "pdf_sha256": "3db1f321ca11c15d4558c7d05a543dae3bcc19332c4e8a58742a483927b5185a", "relevance_score": 52.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
