    'review', 'Evidence Synthesis & Literature Review', 0, 'Background : - Keywords : Anti‑Inflammatory , Flavonoid , Free Radicals , Kaempferol , Methanol Extract URL (for Abstract/ Full paper) : http://www.phcogres.com/text.asp?2020/12/3/250/292046 DOI : 10.4103/pr.pr_114_19 Access : -', '{"arp_id": "ARP_AYU006161", "portal_id": 6161, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Research", "volume": "12", "issue": "3", "pages": "250 - 259", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti‑Inflammatory"], "original_url": "http://www.phcogres.com/text.asp?2020/12/3/250/292046", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6161", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006161.pdf", "pdf_sha256": "3b5877bfb5c3a40801a7209ce215c7ffe08f5f278acf2e8d908347237939caca", "relevance_score": 49.0, "topic_domain": "traditional_diets_food"}'::jsonb
