INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF GINGER ON ZINC, LIPID PROFILE AND ANTIOXIDANTS LEVELS IN BLOOD AND LIVER OF STREPTOZOTOCIN INDUCED DIABETIC RATS FED ON ZINC DEFICIENCY DIET.', 'Imene Tebboub, Zine Kechrid.', 2021,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Diabetes mellitus is a non-communicable disease affecting 463 million people across the world. Ginger has enormous health promoting potential effects in number of ailments including diabetes. So, the purpose of this study was to evaluate the beneficial effect of ginger (Zingiber officinale Roscoe) supplementation on carbohydrate metabolism, antioxidant status and tissue zinc in diabetic rats fed zinc deficient diet. Rats were divided into four groups. The first group was non-diabetic rats fed adequate zinc diet. The second was diabetic group fed also adequate zinc diet. While, the third and the fourth groups were diabetic fed zinc deficient diet, one non-treated and the other treated with ginger 2% diet. The findings showed an increase of blood glucose, transaminases, lipids profile and malondialdehyde levels, whereasinsulin, liverzinc, alkaline phosphatase, lactate dehydrogenase, proteins, reduced glutathione and antioxidant enzymes were reduced in zinc deficient rats. However, treatment with ginger restored the previous parameters. The obtained results indicated that ginger has a powerful effect, which led to a reduction of diabetes development in zinc deficiency due to its antioxidant potential.', '{"arp_id": "ARP_AYU016228", "portal_id": 16228, "medical_system": "AYURVEDA", "journal": "Indian Journal of Experimental Biology", "volume": "59", "issue": "3", "pages": "168 - 176", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetes"], "original_url": "http://nopr.niscpr.res.in/handle/123456789/56398", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16228", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016228.pdf", "pdf_sha256": "40d3ed54eb233218304d80a22fbbb685efa02b0a31c88ccbcd04d780e91ccc8a", "relevance_score": 45.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A CLINICAL TRIAL TO EVALUATE THE ROLE OF PRANAYAMA IN PRE-HYPERTENSION.', '1. Shantanu Tiwari, 2. Sarvesh Kumar Agrawal, 3. Kamalesh Kumar Sharma.', 2020,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Introduction: In India about 23% peoples are Hypertensive while 38 % are pre- Hypertensive. Hypertension and Prehypertension is a major risk factor for the development of cardiovascular disease and cerebrovascular disease causing high rate of mortality and morbidity. Presents study throws a detailed light on preventive efficacy of pranayama in prehypertension. Method: The present study was undertaken to study the role of BharamariPranayam and Anulomviloma Pranayama on prehypertension. 34 patients of prehypertension were selected from OPD, NIA, Jaipur by random sampling for this study. The samples were divided in two groups, Group-A for Anulomaviloma Pranayama and group-B for Bhramari Pranayama. The Pranayamas were practiced by the subjects every day for two months. The Lipid profiles and blood pressures were compared one day prior and one day after experimental period. Results: On statistical analysis, Anulomaviloma and Bhramari Pranayama were found to have significant favorable effect on blood pressure and lipid profile. Conclusion: On the basis of the various observations and results obtained after completion of the current research study, it can be concluded that, Bhramari pranayama and Anoloma-viloma pranayama may be used in the prevention of hypertension in prehypertensive phase. On symptomatic analysis and percentage wise analysis in some symptoms, better results were observed in Group-B by Bibhitakagutika. So it is concluded that Bibhitakagutika is more effective than Pathyadigutika in management of Tamakashvasa.', '{"arp_id": "ARP_AYU000480", "portal_id": 480, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "14", "issue": "3", "pages": "9 - 15", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "CIRCULATORY", "disease": "HYPERTENSION UNCOMPLICATED(ICPC-K86|ICD-I10)", "keywords": ["Anulomaviloma"], "original_url": "https://journals.lww.com/joay/citation/2020/14030/joa_xiv_july_september_2020.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=480", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000480.pdf", "pdf_sha256": "82c98783dc2934a60ef606401c0d2f0cd66210d02d4c25a9e84c77a3fa40f1c9", "relevance_score": 45.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF AN AYURVEDIC INTERVENTION (AYUSH-64) AS A STAND-ALONE TREATMENT IN MILD TO MODERATE COVID-19: AN EXPLORATORY PROSPECTIVE SINGLE-ARM CLINICAL TRIAL.', '1. Singh NR, 2. Amit, 3. Babita Yadav, 4. Arun Gupta, 3. Rakesh Rana, 4. Vishakha Rajesh Wetal, 3. Neha Dubey, 3. Sophia Jameela, 3. Richa Singhal, 3. Shruti Khanduri, 3. Sharma BS, 3. Rao BCS, 2. Bharti, 3. Srikanth N, 3. Dhiman KS.', 2022,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: An Ayurvedic polyherbal formulation (Ayush-64) was repurposed for use in mild to moderate COVID-19 cases based on the supportive evidence obtained from a pilot study on its effect on In?luenza like illness (ILI) and molecular docking study which revealed that several compounds isolated from Ayush-64 demonstrated antiviral activity. The study aims at evaluating theeffect of an Ayurvedic intervention (Ayush-64) in mild to moderate COVID-19 patients. A prospective single arm, pilot study in mild to moderate COVID19 patients. The study was conducted at Chaudhary Brahm Prakash Ayurved Charak Sansthan (CBPACS), New Delhi, India. A total of 37 COVID-19 participants con?irmed through RT-PCR were included in the study. The proportion of participants with negative SARS-CoV-2 on nasal or throat swab in a 2-day consecutive real-time RT-PCR test was evaluated as the secondary outcome. In the study, 86.1% of participants demonstrated clinical recovery with 14 days of use of Ayush-64 as stand-alone treatment without any other conventional medicines, out of which 75% clinically recovered within 8 days. Further, 69.4% of participants turned negative by the 15th day, out of which 50% became COVID-19 negative on the 8th day. No AE/ ADR was observed during the study. Ayush-64 may signi?icantly facilitate clinical improvement in terms of duration for clinical recovery and attaining negative conversion in mild to moderate COVID-19 cases.', '{"arp_id": "ARP_AYU015559", "portal_id": 15559, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Pharmaceutical Sciences", "volume": "13", "issue": "1", "pages": "68 - 72", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "INTERNATIONAL PROVISIONAL ASSIGNMENT OF NEW DISEASES OF UNCERTAIN AETIOLOGY AND EMERGENCY USE (COVID-19 (ICPC- A-77|ICD-RA-01))", "keywords": ["Ayurveda"], "original_url": "https://ijrps.com/home/article/view/22", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15559", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015559.pdf", "pdf_sha256": "54cfd99573afc6a34daf025f20eb14f74b8babdec2763e53df562823d84347af", "relevance_score": 45.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '8270290', NULL, 'A DOUBLE-BLIND CLINICAL TRIAL OF KAMALAHAR, AN INDIGENOUS COMPOUND PREPARATION, IN ACUTE VIRAL HEPATITIS.', 'Govind Das D.', 1993,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: BACKGROUND: Kamalahar is an indigenous preparation reported to be beneficial in acute viral hepatitis.AIMS: To evaluate the efficacy of Kamalahain acute viral hepatitis in a double-blind, placebo-controlled study.METHODS: Fifty two patients with acute viral hepatitis were randomized to receive either Kamalahar 500 mg or a matched placebo three times a day for 15 days. Forty four patients (Kamalahar 20; placebo 24) completed the trial.RESULTS: Improvement in clinical signs was more marked with Kamalahar compared to placebo. The fall in serum bilirubin (p &amp;lt; 0.001), SGPT (p &amp;lt; 0.001) and serum alkaline phosphatase (p &amp;lt; 0.005) at day 15 was significantly greater with the drug. No significant side effects were observed.CONCLUSION: Kamalahar offers therapeutic promise in acute viral hepatitis.', '{"arp_id": "ARP_AYU018482", "portal_id": 18482, "medical_system": "AYURVEDA", "journal": "Indian Journal of Gastroenterology", "volume": "12", "issue": "4", "pages": "126 - 128", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "DIGESTIVE", "disease": "LIVER DISEASE NOS(ICPC-D97|ICD-B58.1, B94.2, K70, K71, K72, K73, K74, K75, K76, K77)", "keywords": ["Ayurvedic Drug"], "original_url": "https://www.indianjgastroenterol.org/IJG_pdf/oct1993/126-128.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18482", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018482.pdf", "pdf_sha256": "de25fa4bc3a7ac4a3724046085dfd0a0296df06b245fcf33ee40ef79d936d07b", "relevance_score": 45.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/joa.joa_9_21', 'EFFECT OF SWARNAMRITHAPRASHANA ON PROMOTION OF IMMUNITY IN CHILDREN: A RANDOMIZED DOUBLE-BLIND CLINICAL TRIAL.', 'Shailaja Uppinakuduru, S Nayan Kumar, Prasanna Narasimha Rao, GR Arun Raj.', 2021,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Introduction: To evaluate the effect of Swarnamrithaprashana on immunity (Bala) and general health status in children. Methods: The present study was a randomized double-blind placebo-controlled interventional prospective clinical trial wherein 221 healthy children within the age group of 6–12 years were enrolled from the schools of Hassan town. Registered children received one soft gel capsule in trial group – Swarnamrithaprashana (containing 2 mg of swarnabhasma) and in control group – sugar syrup, in morning empty stomach along with luke warm water for a duration of 30 days. Assessment of the effect of treatment was done by observing the changes seen in serum immunoglobulin G and salivary immunoglobulin A after 60 days of initiation of treatment as primary outcome parameter and changes in anthropometrical parameters, dehabala, agnibala, and manobala as secondary outcome measures. Renal function test (RFT) and liver function tests (LFTs) were done before and after treatment for assuring safety of the formulation. Results: The trial group showed better decrease in serum and salivary immunoglobulin levels, indicating a decrease in immunoglobulin recruitment in circulation, but the changes were not statistically significant at P = 0.05. The trial group showed better improvement in parameters suggesting Dehabala, Agnibala, and Manobala, which were statistically significant at P = 0.05. There were no significant changes seen in RFT and LFT values done before and after the treatment. Conclusion: Though the changes observed in the levels of immunoglobulins were not statistically significant in the present study setup, Swarnamrithaprashana helps in improving immunity at the level of immunoglobulins. Swarnamrithaprashana was found to be effective in the promotion of immunity in children reflected by improvements in parameters representing dehabala, manobala, and agnibala in children. The formulation was found to be safe as there were no signs of hepato and nephrotoxicity in RFT and LFT.', '{"arp_id": "ARP_AYU019867", "portal_id": 19867, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "15", "issue": "2", "pages": "91 - 103", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Immunity"], "original_url": "https://journals.lww.com/joay/fulltext/2021/15020/effect_of_swarnamrithaprashana_on_promotion_of.4.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19867", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019867.pdf", "pdf_sha256": "02bd581eea164c083b4c07fd4f5b7cc7754e8e23134e66fcbc59dea23d665b88", "relevance_score": 45.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/pm.pm_369_19', 'WILD- EDIBLE PLANTS OF MEGHALAYA STATE IN INDIA: NUTRITIONAL, MINERALS, ANTINUTRITIONAL, VITAMIN CONTENT AND TOXICITY STUDIES.', '1. Tapan Seal, 1. Kausik Chaudhuri, 1. Basundhara Pillai, 2. Shrabana Chakrabarti, 2. Biswajit Auddy, 3. Tanmoy Mondal.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aim: The point of the present investigation planned to assess the nutritive value, minerals content, vitamin content, antinutritional properties, and toxicity studies in five wild-consumable plants, for example, Begonia hatacoa, Embelia floribunda, Artemisia vulgaris, Cardamine hirsuta, and Plantago major, devoured by the distinctive innate individuals of Meghalaya State in India as their nourishment. Materials and Methods: The proximate parameters such as protein, fat, fiber, sugar, minerals, and harmful overwhelming metals were assessed in the chose wild-eatable plants utilizing standard sustenance examination procedures. The cyanogenic glycoside, oxalates, tannins, saponins, and phytate substances were done to decide the counter wholesome properties of the considered plants. The quantitations of water-dissolvable vitamins in these plants were completed by high-performance liquid chromatography. The in vitro hemolytic measure of plant concentrates was completed on rodent erythrocytes. Appraisal of cytotoxicity of eatable plants was assessed by 3-(4,5-dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide examine. The genotoxicity of the contemplated plants was tried by the single-cell gel electrophoresis comet assay. Results: The consequences of examination demonstrated that these plants are rich wellsprings of protein, sugar minerals, and vitamins, particularly the B gathering of vitamins. The substantial metals lead and chromium were distinguished in exceptionally low sum in all the consumable plants. The largest amount of phytate was found in P. major (0.38% &amp;#177; 0.03%); oxalate was most astounding in E. floribunda (0.261% &amp;#177; 0.06%) though tannin was most elevated in P. major (1.04% &amp;#177; 0.12%). The estimations of antinutrients and overwhelming metals in all above-considered plants are underneath the harmful levels. Conclusion: These wild-eatable plants contribute gigantically to sustenance, nourishment security, well-being, and remedial advantages. The aftereffects of poisonous quality of every single eatable plant ensure the security at cell and genomic level and furthermore safe to expend.', '{"arp_id": "ARP_AYU013414", "portal_id": 13414, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Magazine", "volume": "16", "issue": "68", "pages": "142 - 151", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antinutrients"], "original_url": "https://phcog.com/article/view/2020/16/68/142-151", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=13414", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU013414.pdf", "pdf_sha256": "6e48ad331308c576f7664a5550d76d6254ef127a245afa9eea0489d48e8bcff6", "relevance_score": 44.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.56042/ijnpr.v11i2.27716', 'NUTRITIONAL COMPOSITION, BIOACTIVE COMPOUNDS AND FREE RADICAL SCAVENGING ACTIVITY OF WHEATGRASS (TRITICUM AESTIVUM L.) AS INFLUENCED BY HARVESTING STAGES AND CULTIVATION METHOD.', '1. Chingakham Basanti Devi,1. Kiran Bains,1. Harpreet Kaur, 2. Hari Ram.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Wheatgrass is a rich source of protein (24.08 to 30.40 g/100 g DM) when cultivated under indoor and outdoor conditions and harvested at different stages. The ash ranged being 7.68 to 8.46 g/100 g DM. The crude fibre content was high especially under indoor cultivation, the values were in the range of 19.06 to 27.68 g/100 g. Indoor cultivation was far better than outdoor cultivation in terms of higher protein and ash. Late harvesting stage was better for crude fibre but for proteins, the early stage i.e 7th day was superior. The early harvesting (7th day and indoor cultivation) was superior for obtaining maximum ascorbic acid from the wheatgrass. For maximum &amp;#223;-carotene in wheatgrass, the optimum stage of harvesting was the 10th day from the day of sowing during indoor conditions while 7th day was the right stage for harvesting wheatgrass during the outdoor cultivation. It has an abundant amount of chlorophyll and flavonoids, the content was varying between 4.14 to 17.72 g/100 g and 115.67 to 460.18 QE/g, respectively under different harvesting stages and cultivation conditions. The free radical scavenging activity of indoor-grown wheatgrass was significantly (P =0.05) higher in comparison to outdoor cultivated wheatgrass on 7th and 10th day of harvesting.', '{"arp_id": "ARP_AYU013711", "portal_id": 13711, "medical_system": "AYURVEDA", "journal": "Indian Journal of Natural Products and Resources", "volume": "11", "issue": "2", "pages": "118 - 123", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Bioactive Compounds"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/55180", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=13711", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU013711.pdf", "pdf_sha256": "ed0b5d5a3e1b8feb300495a9ca322ed31f8d8600359f25e05d2c0b3095c3f875", "relevance_score": 44.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v11i2.1393', 'NUTRITIONAL STATUS AMONG CHILDREN RECEIVING ASHWAGANDHADI CHURNA WITH MILK IN RESIDENTIAL HOMES, TAMIL NADU, INDIA.', '1. Sangeeta Sharma, 2. Deepa Jagan, 3. Niraimathi K, 4. Sridhar Sukumar, 5. Mohan Ramachanan.', 2020,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Background: Children of residential homes (RH) have a high rate of health problems including malnutrition. Ayurveda has several drugs to alleviate malnutrition, Ashwagandhadi being one of the most commonly used drug. This study evaluated the changes in nutritional status of children in RH consuming Ashwagandhadi churna (AC) for 1-3 years. Methods: This was a retrospective descriptive record review study of children consuming AC regularly for 1-3 years of two RH of Tamilnadu during 2018-2019. The children of age 6-9 and 10-13 years received a dosage of 2 and 4g of AC respectively in milk once a day. Socio-demographic details, anthropometric measurements and clinical details were assessed. Data at three time points with an interval of three months were extracted and analysed using Friedman’s tests. Important observations and Results: Out of 289 children, 173, who had complete details of three assessments, were included for analysis. Irrespective of the years of consumption of AC, at the first assessment, 61.6% were stunted or severely stunted; 71.2% underweight or severely underweight. Significant improvement in height-for-age and weight-for-age were observed in children consuming AC for 1 and 2 years. BMI did not show significant difference in 3 years of consumption. Males of 10 to 13 years having 1 and 2 years of consumption and females of both age groups having 2 years of consumption showed difference in BMI. Conclusion: Approximately three in ten children were malnourished in RH. Consumption of AC over a period of time improved the nutritional status of these children. Further large scale trials could prove the efficacy of AC in alleviating malnutrition.', '{"arp_id": "ARP_AYU014109", "portal_id": 14109, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "11", "issue": "2", "pages": "205 - 211", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "VITAMIN/NUTRITIONAL DEFICIENCY(ICPC-T91|ICD-E40, E41, E42, E43, E44, E45, E46, E50, E51.1, E51.8, E51.9, E52, E53, E54, E55, E56, E58, E59, E60, E61, E63, E64)", "keywords": ["Body Mass Index"], "original_url": "https://www.ijam.co.in/index.php/ijam/article/view/1393/568", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=14109", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU014109.pdf", "pdf_sha256": "9403aa8bae8c9ecb4b589412bf192c85fbe541630f0b3de7ecf27347ede1c591", "relevance_score": 44.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/ijper.56.4s.216', 'CHROMATOGRAPHIC CHARACTERIZATION FOR QUANTITATIVE MEASUREMENT OF PHYTOCONSTITUENTS IN POLYHERBAL SUSPENSION AND EVALUATION OF ITS NUTRITIONAL EFFICACY ON MALNOURISHED RATS.', '1. Ashish Majumdar, 2. Shiv Shankar Shukla, 1. Ravina Kumar Pandey.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: The present study demonstrated HPLC method development for quantitative measurement of phytoconstituents present in food-grade polyherbal suspension (PHS) and evaluated its nutritional efficacy in the rat. Procedure: The PHS was prepared by mixing the dried extracts of Nelumbo nucifera (NN) seeds, seeds of Euryale ferox (EF) and fruits of Trapa natans (TN) with other excipients. The PHS was analyzed using the HPLC method for the development and validation of the phytoconstituents present in PHS as compared to standard biomarkers. The nutritional efficacy of PHS was evaluated on malnourished rats by observing body weight, food intake, biochemical and haematological data. Results: Results exhibited that the developed HPLC method was simple, rapid, sensitive and cheap for the determination of phytoconstituents in the PHS. The nutritional composition of NN, EF and TN revealed that protein content was highest in TN (21.30%), NN (14.30%) and EF (13.16%) respectively. PHS restored the haematological data of malnourished rats with values of 7.37 103/µL, RBC; 11.75 g/dL, Hb; and 1147 103/µL, platelets at 400 mg/kg dose compared to the control group. The result of biochemical data exhibited that cholesterol and triglyceride levels were 36.08 and 60.28 mg/dL, respectively after treatment with PHS (400 mg/kg). PHS also enhanced the bodyweight of animals in comparison to the control group. Conclusion: Thus, PHS may be an alternative nutritional formulation against protein deficiency-induced malnutrition.', '{"arp_id": "ARP_AYU015920", "portal_id": 15920, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmaceutical Education and Research", "volume": "56", "issue": "4s", "pages": "s703 - s712", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Biomarkers"], "original_url": "https://www.ijper.org/article/1853", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15920", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015920.pdf", "pdf_sha256": "23fc57d5b8a7b5003dc3ba2383843244cd190f025710ec05668cbd004ac65aee", "relevance_score": 44.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/ijper.54.2s.89', 'STRUCTURAL ELUCIDATION OF ISOLATED PHYTOCHEMICALS FROM SELECTED MEDICINAL PLANTS WITH ANTIHYPERLIPIDEMIC ACTIVITY AND DEVELOPMENT OF POLYHERBAL FORMULATION WITH DENSITOMETRIC ANALYSIS OF ISOLATED PHYTOCONSTITUENTS.', '1.Deepa Iyer, 2.Umesh K Patil.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background : - Keywords : Flash Chromatography , Hptlc Densitometric Analysis , Hyperlipidemia , Isolated Phytoconstituents , Medicinal Plants URL (for Abstract/ Full paper) : https://www.ijper.org/article/1202 DOI : 10.5530/ijper.54.2s.89 Access : -', '{"arp_id": "ARP_AYU001643", "portal_id": 1643, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmaceutical Education and Research", "volume": "54", "issue": "2s", "pages": "s316 - s329", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Flash Chromatography"], "original_url": "https://www.ijper.org/article/1202", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1643", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001643.pdf", "pdf_sha256": "3dfc2c72d29b38f4fad1fb0855397f7a028143c93944189ab1a86770b6c55fea", "relevance_score": 44.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
