INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A CLINICAL EFFICACY OF HARISHANKAR RAS AND KHADIR-KRAMUKKWATH IN MADHUMEHA WITH SPECIAL REFERENCE TO DIABETES MELLITUS TYPE II.', '1. Vikas Nariyal, 2. Ajay Kumar Sahu, 3. Chanabhanu Sharma.', 2018,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Diabetes is a disease known from the dawn of civilization. Sedentary life style, lack of exercise, faulty food habits and improper medication and urbanization precipitate the disease. Madhumeha is one of the twenty type of Prameha described in Ayurvedic literature. Madhumeha is related primarily with Mutravaha and Medovaha Srotasa but along with these many other Srotasa are also involves. This study was taken by looking at the present statistics of the incidence and prevalence of Diabetes Mellitus TypeII. Two indigenous drugs Harishankar Ras and Khadir-kramuk Kwath were taken and efficacy and safety profile of both the formulations were carried out in a group of 10 patients. Group was administered with Harishankar Ras (125 mg tablet twice a day in empty stomach for 30 days) and Khadir-kramuk Kwath (40 ml kwath twice a day in empty stomach for 30 days). Result and Discussion reveal that Group administered with above formulations have shown the good result in relieving both subjective and objective criteria after the course of 1 month.', '{"arp_id": "ARP_AYU000345", "portal_id": 345, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "12", "issue": "3", "pages": "17 - 22", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes Mellitus"], "original_url": "https://journals.lww.com/joay/citation/2018/12030/joa_xii_july_september_2018.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=345", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000345.pdf", "pdf_sha256": "fd5b32f129f298d93c790c6c47b54c5824106849cc2e053f7a5f385d66f86514", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF THE EFFICACY OF DARVYADI KWATHA AND MADHUMEHARI CHURNA IN THE MANAGEMENT OF MADHUMEHA W.S.R. TO DIABETES MELLITUS TYPE-2 (NIDDM).', '1. Bhanu Tank, 2. Deepak Kumar, 3. Sharma CB, 4. Udai Raj Saroj.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background : - Keywords : Ayurveda , Diabetes , Madhumeha URL (for Abstract/ Full paper) : https://journals.lww.com/joay/citation/2013/07010/joa_vii_january_march_2013.1.aspx DOI : No Access : -', '{"arp_id": "ARP_AYU000385", "portal_id": 385, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "11", "issue": "1", "pages": "36 - 42", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Ayurveda"], "original_url": "https://journals.lww.com/joay/citation/2013/07010/joa_vii_january_march_2013.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=385", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000385.pdf", "pdf_sha256": "5e35df8352d266f0b6d0c2e4c8fff6c7e05fa0ad59f8f72150bc4c86f137f3b8", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
