INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF MEDHUMEHARI CHURNA (A HERBAL PREPARATION) IN DIABETES MELLITUS TYPE II- A CASE SERIES STUDY.', '1. Mukti Manki Mita Singh, 2. Shailza Bhatnagar, 3. Suman Meghwal.', 2019,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Diabetes mellitus (DM) is a metabolic disorder characterised by polyuria, polydipsia, and polyphagia. The glucose metabolism is affected in this disease leading to raised blood sugar level which later on results into grave consequences. Though modern system of medicine have succeeded with very advanced treatment consisting of oral hypoglycaemic drugs and insulin therapy which very effectively lowers the blood sugar level, but the symptoms like weakness, burning sensation and constipation etc. are usual complaints of patients of DM which do not get relieved by this treatment. Ayurveda plays an effective role in the management of this disorder as ayurveda herbs have both anti diabetic effect and symptomatic relief. In this study five newly diagnosed patient of DM II were given a formulation named as madhumehahari churna in the dose of 5 grams before meal for 3 months. All the cases showed improvement both in symptoms and blood parameters.', '{"arp_id": "ARP_AYU000412", "portal_id": 412, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "13", "issue": "4", "pages": "164 - 169", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Ayurveda"], "original_url": "https://journals.lww.com/joay/citation/2019/13040/joa_xiii_october__december_2019.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=412", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000412.pdf", "pdf_sha256": "345b271eb979e67541fcc0cca412bdb0a0295bcdf98d0fbbb1e32fe6fe1e1b3e", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A CLINICAL STUDY OF MM 21 (FORMULATED HYPOTHETICAL COMPOUND) IN THE MANAGEMENT OF MADHUMEHA (DIABETES MELLITUS TYPE-2).', '1. Radhey Shyam Sharma, 2. Brahmanand Sharma.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The incidence of diabetes mellitus is increasing rapidly because of changes in lifestyle and dietary habits. Scientists of various fields are doing continuous research in order to achieve an effective management for diabetes mellitus. Ayurvedic research scholars on various herbal and mineral drugs to find an effective treatment for madhumeha have also done a great deal of work. MM 21 (Formulated Hypothetical Compound) has been used in for the present study. The study was conducted with an objective of evaluating the role of MM 21 (Formulated Hypothetical Compound) in clinically diagnosed cases of madhumeha. 200 patients of both sexes of 18 year to 70 year age group were registered for this project and all were thoroughly examined at certain intervals during entire project period. Out of that 20 patients discontinued the treatment therefore study was conducted on 180 patients that were equally divided into 2 groups; Group A (Oral Hypoglycemic Agent i.e. OHA + MM 21 (Formulated Hypothetical Compound)) and Group B (MM 21 (Formulated Hypothetical Compound)). Statistically significant improvement was observed in objective and subjective parameters in both groups after completion of the course of treatment. Based on the results, it is been concluded that, MM 21 (Formulated Hypothetical Compound) is an effective therapeutic regimen in the management of uncomplicated cases of Madhumeha.', '{"arp_id": "ARP_AYU000439", "portal_id": 439, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "11", "issue": "4", "pages": "4 - 16", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes Mellitus"], "original_url": "https://journals.lww.com/joay/citation/2017/11040/joa_xi_october__december_2017.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=439", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000439.pdf", "pdf_sha256": "7b5c6c0fe42456f10d65f036982d2f589e53fd23b92a03862049b658412e04ee", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-DIABETIC ACTIVITY OF THE ETHANOLIC EXTRACT OF PSEUDARTHRIA VISCIDA ROOT AGAINST ALLOXAN-INDUCED DIABETES IN ALBINO RATS', 'Surve GM, Masirkar VJ, Sakarkar DM.', 2020,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Root powder of Pseudarthria viscida was subjected to hot extraction (soxhlet) with ethanol. After preliminary phytochemical investigation, ethanolic extract of the roots of P. viscida was evaluated for anti-diabetic activity against alloxan-induced diabetes in Albino rats. The ethanolic extracts showed significant activity as compared to standard glibenclamide.', '{"arp_id": "ARP_AYU000508", "portal_id": 508, "medical_system": "AYURVEDA", "journal": "Proceedings of th World Ayurveda Congress and Arogya Expo Proceedings  December  Bengaluru, Karnataka, India Page:", "volume": "-", "issue": "-", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan-Induced"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=508", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000508.pdf", "pdf_sha256": "8bce9492ddbce6fe685bc399c5970299577951adea15e71bc27ef6c96d7e10ee", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF THE STANDARDIZED EXTRACT OF HOLARRHENA ANTIDYSENTERICA SEEDS AGAINST STEPTOZOTOCIN INDUCED DIABETES IN RATS', '1. Vinay Kumar Pathak, 1. Anup Maiti, 2. Shyam Sundar Gupta, 2. Ila Shukla, 2. Rao ChV.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Holarrhena antidysenterica is found in Himalayan and sub-Himalayan tracts and is used traditionally for a range of health disorders, including colic, diarrhea, dysentery, constipation, flatulence, and urethrosis, as well as being considered functional as carminative, antispasmodic, astringent, anthelmintic, lithotriptic, diuretic, aphrodisiac, tonic, cardiosuppressant, and antihypertensive, antimutagenic, antibacterial and immunomodulatory properties. In this study, the effects of seeds of H. antidysenterica on fasting blood glucose levels in streptozotocin induced diabetic rats were examined, together with its effects on the lipid profile in-vivo. The oral glucose tolerance test revealed that animals treated with seeds of ethanolic extract of H. antidysenterica showed significant reductions in plasma glucose level compared with control group treated with gum acacia. H. antidysenterica seeds induced noteworthy reduction in serum glucose level in streptozotocin diabetic rats after 14 and 21 days, reducing the glucose concentration by 39.7 and 48.0%, respectively, when administered at 300 mgkg-1. When administered to streptozotocin induced diabetic rats at 300 mgkg-1 H. antidysenterica seeds had strong effects on their lipid profile by significantly decreasing total lipid, triglyceride and cholesterol. This pharmacological activity investigation has confirmed that H. antidysenterica seeds confers moderate defense against diabetes in-vivo. In addition, the potential of H. antidysenterica seeds to reduce triglyceride and total cholesterol levels while increasing high density lipoprotein may contribute to its beneficial effects in diabetic rats.', '{"arp_id": "ARP_AYU002082", "portal_id": 2082, "medical_system": "AYURVEDA", "journal": "International Journal of Pharma Research & Review", "volume": "4", "issue": "4", "pages": "1 - 6", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cholesterol"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2082", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002082.pdf", "pdf_sha256": "adeccc2db83aadcbb75d9ea59245291526c3737f68c62a8bc1833be0fe76f6b7", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EXPERIMENTAL STUDY ON HOLOPTELIA INTEGRIFOLIA PLANCH. IN RELATION TO DIABETES MELLITUS TYPE 2.', '1. Surena Nath, 2. Poonam Sharma, 2. Dwivedi KN.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Holoptelea integrifolia (Ulmaceae) is a very important medicinal plant used in various indigenous systems of medicine for curing several diseases, diabetes mellitus is one of them. It is traditionally used in the treatment and prevention of several ailments like leprosy, inflammation, rickets, leucoderma, scabies, rheumatism, ringworm, eczema, malaria, intestinal cancer, and chronic wounds. In experimental study it was found that it has no toxic effect along with it has no hypoglycemic effect in normoglycemic rats. In Streptozotocin and hydrocortisone induced hyperglycemic rats the hypoglycemic activity of the drug was found highly significant. So this drug seems to be very rationale for the treatment of Diabetes mellitus. It has also antibacterial, antifungal, analgesic, antioxidant, anti-inflammatory, anthelmintic, antidiabetic, antidiarrhoeal, adaptogenic, anticancer, wound healing, hepatoprotective, larvicidal, antiemetic, CNS depressant, and hypolipidemic activities. This drug works on diabetes mellitus according to Ayurveda by its properties like it has Tikta, Kashaya Rasa, Laghu. Ruksha Guna, Ushna Virya and Katu Vipaka it subsides the Kaphapitta Dosha. So it is also helpful in following diseases like Shotha, Agni mandya, Chhardi, Udararoga, Shoola, Gulma, Arsha, Krimi, Raktavikara, Prameha, Kushtha, Charmaroga, Medoroga. So in spite of treating only Prameha it is used as a multipurpose drug also for curing several diseases.', '{"arp_id": "ARP_AYU002235", "portal_id": 2235, "medical_system": "AYURVEDA", "journal": "International Journal of Pharma Research & Review", "volume": "4", "issue": "9", "pages": "21 - 25", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antidiabetic"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2235", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002235.pdf", "pdf_sha256": "fcbe7023506a261631245a754e1bdc3508d7c64491e00148ebcdeae06a1bd76b", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ROLE OF SAPTARANGYADI GHANAVATI ON S. INSULIN IN TYPE 2 DIABETES MELLITUS: A PILOT STUDY', '1. Kanwar Singh, 2. Mandip Kaur, 3. Chandola HM.', 2020,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Type 2 diabetes can be correlated to apathyanimittaja prameha or avarana janya madhumeha. Here insulin antagonists are not allowing it to metabolize blood glucose. This paper tries to evaluate the effect of Saptarangyadi Ghanavati in apathyanimittaja Prameha. Saptarangyadi Ghanavati has been administered to six patients with type 2 diabetes to evaluate its role in FBS, PPBS, and serum insulin levels. Most of the ingredients of the formulation are pramehahara and rasayana. The results show statistically significant (paired ‘t’ test) increase in the postprandial serum insulin level along with statistically significant decrease in the BMI and serum cholesterol level and statistically insignificant decrease in FBS and PPBS levels. It ensures good glycemic control in these cases in which sulphonylurea group of oral anti-hyperglycemic agents is not much of use. It can also reduce the dosage of exogenous insulin or oral anti-diabetic synthetic drugs, thereby preventing higher cost and adverse effects associated with use of these modern drugs.', '{"arp_id": "ARP_AYU002817", "portal_id": 2817, "medical_system": "AYURVEDA", "journal": "Proceedings of th World Ayurveda Congress and Arogya Expo Proceedings  December  Bengaluru, Karnataka, India Page:", "volume": "-", "issue": "-", "pages": "- - -", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Exogenous Insulin"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2817", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002817.pdf", "pdf_sha256": "d349ab64efdde7568740ed926cbd99227b3ea648738eaecd7e123753cf852778", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL STUDY ON AYURVEDIC HERBAL DRUG (MUSTADI KWATHA GHANAVTI) THERAPY IN PATIENTS WITH TYPE 2 DIABETES.', 'Vibhukant Kushwaha, Anjana Kar', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Mustadi kwatha ghanavati (MKG) consists of 9 medicinal herbs with anti-hyperglycemic, antihyperlipidemic and antihypertensive potential. The aim of this study was to examine the effect of treatment with MKG on metabolic profile and symptomatic distress related parameters in patients with Type 2 diabetes (T2D). A total of 100 patients with T2D were recruited from outpatient diabetes clinic (50 men and 50 women; aged 35-60 yrs). They were randomly and equally divided into a control group and a treatment group. People in the treatment group were given 500 mg twice/day of MKG before meal for 60 days, whereas the control group had received placebo (Godanti bhasma, 2 pills 125 mg/day, before meal for 60 days. For management of symptomatic distress, patients were assigned to practice yoga, vedic meditation and received cinnamon oil body massage in addition to diet restrictions. Symptomatic distress related parameters and treatment satisfaction of the patients were evaluated with the help of visual analog scale and diabetes treatment satisfaction questionnaires. Assessment of all these parameters were done at the baseline (day 0) and at endline (day 60) treatment. Efficacy of treatment was measured on the basis of relief in observed symptoms of diabetes and clinical parameters. Data was analyzed with t-test, ANCOVA and chi-square test. We observed a statistically significant reducing effect (p &amp;lt; 0.001) of MKG interventions on fasting blood glucose, post prandial blood glucose, urine glucose, total-cholesterol, systolic blood pressure and diastolic blood pressure levels than placebo treatment. Overall, Mustadi kwatha ghanavati demonstrated several beneficial effects on metabolic profile, provides relief in levels of symptomatic distress related parameters and treatment satisfaction, thus showing therapeutic potential for T2D patients.', '{"arp_id": "ARP_AYU003841", "portal_id": 3841, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "16", "issue": "Supplement", "pages": "S40 - S46", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diet"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/42282", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3841", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003841.pdf", "pdf_sha256": "bfb16c984b1b2a3594fd8ede8309cdadf097a3abfa34c977784d3e417f3fdf1b", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL EVALUATION OF TALAPOTAKA CHURNA - A  POLYHERBAL AYURVEDIC FORMULATION IN TYPE 2 DIABETES MELLITUS.', '1. Guruprasad C Nille, 1. Reddy KRC, 2. Tripathi JS.', 2018,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: To evaluate and compare the antidiabetic effect of Talapotaka Churna in Type II Diabetes mellitus patients were registered from S. S. Hospital, Banaras Hindu University, Varanasi. Patients were randomly divided in four groups for treatment of four different medicine groups: [Group A- Talapotaka Churna (4 g TID) with Takra (Buttermilk) before meal; Group B- Talapotaka Churna (4 g TID) with warm water before meal; Group C- Talapotaka Churna (4 g TID) with ongoing allopathic treatment with water before meal . Group D- Glimepride treated (1 mg BD) before meal]. The treatment was given for a period of two months. Fasting blood sugar, postprandial blood sugar, HbA1c, SGOT, SGPT, Sr. Creatinine and lipid profile level were estimated biochemically. The results were promising and reveal that Talapotaka Churna can be a safe, acceptable and effective alternative or adjuvant to the conventional oral hypoglycemic agents.Holistic principles of Ayurveda when used as supplementary for modern drugs in diabetes show their effects on all bodily symptoms and helps to minimize them in which modern drug fails. So, it is the need of time to support the modern medications with Ayurvedic therapy.', '{"arp_id": "ARP_AYU003843", "portal_id": 3843, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "17", "issue": "1", "pages": "168 - 175", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Churna"], "original_url": "http://nopr.niscpr.res.in/handle/123456789/43135", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3843", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003843.pdf", "pdf_sha256": "c002fe20f57a1f65dc958c1909bc49afb5c8a3df467324027fc1ca613eab83e7", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIDIABETIC AND ANTIHYPERLIPIDEMIC EFFECTS OF ARTEMISIA ABSINTHIUM L., CITRULLUS COLOCYNTHIS (L.) SCHRAD. AND GYMNEMA SYLVESTRE (RETZ.) R.BR. EX SM. ON TYPE II DIABETES HYPERLIPIDEMIC PATIENTS.', '1. Mukhtiar Hassan, 1. Aneela Tariq Niazi, 2. Samiullah Khan, 1. Farzana Gul.', 2018,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Artemisia absinthium L., Citrullus colocynthis (L.) Schrad. and Gymnema sylvestre (Retz.) R.Br. ex Sm. have been used in Asian countries for thousands of years to treat diabetes. This study was conducted to evaluate hypoglycemic and antihyperlipidemic effects in type II hyperlipidemic diabetic patients. Study is blind randomized placebo-controlled clinical trials over 40 days. Individuals were divided randomly into 4 groups 1, 2, 3 &amp;amp; 4. Ten individuals were in each group. Group 1 was allocated for G. sylvestre, 2 for A. absinthium, 3 for C. colocynthis and 4 for placebo. Medication (1.0 g/day) was administered for 40 days. From each individual of each group on day 0, 10, 20, 30 and 40 blood samples were collected in fasting condition. Serum glucose values in group 1 dropped most considerably (p &amp;lt; 0.05). Diabetic individuals of all 3 groups as compared to control and placebo group, showed significantly lowered fasting serum glucose level (p &amp;lt; 0.05). Fasting serum triglycerides, cholesterol, HDL-cholesterol and LDL-cholesterol of all 3 groups were not reduced significantly at (p &amp;lt; 0.05) as compared to control and placebo groups. So it may be suggested that a type II diabetic patient can safely be switched from costly conventional antidiabetic medicine to cheap natural products.', '{"arp_id": "ARP_AYU003846", "portal_id": 3846, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "17", "issue": "2", "pages": "233 - 239", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Clinical Trials"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/43657", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3846", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003846.pdf", "pdf_sha256": "dd583da09be17e7d30fd94cc09c8038d75f8df7262f4d4612a3340f34cd5ee29", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECTS OF THE TRIGONELLA FOENUM-GRAECUM L. SEED EXTRACT AND CHROMIUM PICOLINATE SUPPLEMENTATION IN STREPTOZOTOCIN INDUCED DIABETES IN RATS.', '1. Gozde Atila, 2. Abdurrauf Yuce.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Our objective was to determine the effects of the Trigonella foenum-graecum seed extract and chromium picolinate in streptozotocin (STZ) induced diabetes in rats. We used 60 female Sprague Dawley rats aged between 2-3 months, who were divided into 6 groups: control (C);vehicle received physiological saline solution intraperitoneally (i.p.) + physiological saline solution orally, diabetescontrol group (DC); 50 mg/kg STZ i.p. + physiological saline solution orally, T. foenum-graecum (TFG); 50 mg/kg STZ i.p + 150 mg/kg TFG seed extract orally, chromium picolinate (Crpic); 50 mg/kg STZ i.p + 30 &amp;#181;g/kg Chromium picolinate orally, T. foenum-graecum + chromium picolinate (TFG+Crpic); 50 mg/kg STZ i.p. + received 150 mg/kg TFG + 30 &amp;#181;g/kg Crpic orally, insulin (I); 50 mg/kg STZ i.p. + 1 IU insulin subcutaneously. The treatment lasted for 21 days. On the 14th and 21st days, we found a decrease in theFBG of animals treated with insulin, TFG, TFG + Crpic combined (all p ? 0.001), and Crpic (p &amp;lt; 0.01) compared with the diabetes control group. Moreover, there was a significant decrease in the plasma triglyceride and very low density lipoprotein (VLDL) levels after a treatment with Crpic, I, TFG, and TFG+Crpic compared with diabetes control group (p &amp;lt; 0.001). Administration of TFG+Crpic caused a significant increase in plasma high density lipoprotein (HDL) levels (p ? 0.05) compared with diabetes control group. There was a significant decrease in the plasma tumor necrosis factor alpha (TNF-a) level after a treatment with Crpic (p &amp;lt; 0.05). The TFG, TFG and Crpic combined, and insulin treatment significantly increased the insulin-positive ß cells compared with diabetes control group (p ? 0.001). These results show that the TFG extract may have an insulinotropic effect on the ß cells of the islets of Langerhans, or may prevent the damage of the pancreatic ß cells. Crpic did not stimulate insulin secretion from the ß cells in the Langerhans islets. We concluded that Crpic may exert its antihyperglycemic effects by facilitating the interaction between insulin and its receptor. It is recommended that the TFG seed extract and Crpic supplements may help in alleviating or reducing the hyperglycemia-related chronic complications of diabetes.', '{"arp_id": "ARP_AYU003859", "portal_id": 3859, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "15", "issue": "3", "pages": "447 - 452", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Chromium Picolinate"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/34282", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3859", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003859.pdf", "pdf_sha256": "a244169ec6791af3f1f0815c805c10eb1cba8972f0a8b54d516a9b26451e3952", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIOXIDANT AND ANTI-INFLAMMATORY EFFECTS OF ACROCARPUS FRAXINIFOLIUS ON HYPERGLYCEMIA, HYPERLIPIDEMIA AND LIVER/KIDNEY DYSFUNCTIONS AGAINST ALLOXAN INDUCED TYPE 1 DIABETES IN RATS.', '1. Eman Ali Abd El-Ghffar, 2. Safia Mohamed Shehata.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Many factors such as oxidative stress and pro-inflammatory cytokines cause ß-cell dysfunction and death. The aim of this study was to investigate antioxidant and anti-inflammatory effects of Acrocarpus fraxinifolius (A. fraxinifolius) on hyperglycemia, hyperlipidemia and liver/kidney dysfunctions against alloxan induced Type 1 diabetes in rats. Thirty six male white albino rats were divided into 6 groups: Control group, diabetic group and two prophylactic group with two different doses and two therapeutic group with two different doses (250 or 500 mg/kg b.w; for 28 consecutive days). Diabetes was induced by i.p. injection of 75 mg/kg b.walloxan monohydrate for 5 consecutive days. In this study showed that A. fraxinifolius extract [especially prophylactic treatment] significantly suppressed diabetic complications in alloxan-induced diabetes in rat model by alleviating body weight loss, hyperglycemia, hypo-insulinemia and dyslipidemia through activating the antioxidant defense system, decreasing of oxidative/nitrosative stress as well as lipid peroxidation, and increasing/decreasing the production of anti-inflammatory/pro-inflammatory cytokines, respectively. The percentage of disease recovery was 15.00 &amp;#177; 5.472 % in high dose A. fraxinifolius of prophylactic treatment compared with alloxan only group 73.70 &amp;#177; 22.09 % (p &amp;lt; 0.05).The data confirmed property of A. fraxinifolius as an antioxidant and anti-inflammatory that ameliorates oxidative/nitrosative stress and revealed that it is efficiently improves diabetic complication in alloxan-induced diabetic rats.', '{"arp_id": "ARP_AYU003900", "portal_id": 3900, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "17", "issue": "2", "pages": "223 - 232", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Acrocarpus Fraxinifolius"], "original_url": "http://nopr.niscpr.res.in/handle/123456789/43658", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3900", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003900.pdf", "pdf_sha256": "117631444952c2d4632da62b7e527fa9839be9d9b2731f81e52ea50654cc1551", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4314/tjpr.v3i1.7', 'EFFECT OF CHRONIC ADMINISTRATION OF BOERHAAVIA DIFFUSA LINN. LEAF EXTRACT ON EXPERIMENTAL DIABETES IN RATS', '1. Rao K. Nalamolu, 2,3. Krishna M. Boini, 2,3. Srinivas Nammi.', 2004,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Purpose: The root and aerial parts of Boerhaavia diffusa Linn. (Nyctaginaceae) were used in Ayurveda for the treatment of diabetes. The present study is aimed at evaluating the antidiabetic activity of chloroform extract of Boerhaavia diffusa leaves on chronic administration in streptozotocin-induced non-insulin-dependent diabetes mellitus (NIDDM) model diabetic rats.Methods: The blood glucose lowering activity of the leaf extract was studied in streptozotocininduced (65 mg/kg, i.v.) NIDDM model diabetic rats after oral administration of the extract at daily doses of 50, 100 and 200 mg/kg body weight for four weeks and compared with glibenclamide. Blood samples were collected from the tail vein before and also at weekly intervals for four weeks from the first dose of drug administration and blood glucose was analyzed by glucose-oxidase method using a visible spectrophotometer.Results: The leaf extract of B. diffusa produced dose-dependent reduction in blood glucose in streptozotocin-induced NIDDM rats comparable to that of glibenclamide. The results indicate that the reduction in blood glucose produced by the extract is probably through rejuvenation of pancreatic b-cells or through extrapancreatic action.Conclusion: The chloroform extract of Boerhaavia diffusa has significant antidiabetic activity and this supports the traditional usage of the plant by Ayurvedic physicians for the control of diabetes.', '{"arp_id": "ARP_AYU005118", "portal_id": 5118, "medical_system": "AYURVEDA", "journal": "Tropical Journal of Pharmaceutical Research", "volume": "3", "issue": "1", "pages": "305 - 309", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Blood Glucose"], "original_url": "https://www.tjpr.org/home/abstract.php?id=892&amp;aTitle=Effect%20of%20chronic%20administration%20of%20Boerhaavia%20diffusa%20Linn.%20leaf%20extract%20on%20experimental%20diabetes%20in%20rats", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=5118", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU005118.pdf", "pdf_sha256": "bcd3fbba87fd186aac1296c944bb9a27e5b680783a208c67f786f138b5da3218", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4314/tjpr.v8i5.3', 'HYPOGLYCEMIC EFFECTS OF CLITORIA TERNATEA LINN. (FABACEAE) IN ALLOXAN-INDUCED DIABETES IN RATS', '1. Daisy P, 2. Rajathi M.', 2009,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Purpose: This study aims to investigate the therapeutic effects of the aqueous extract of Clitoria ternatea Linn. Fabaceae leaves and flowers on alloxan-induced diabetes in rats.Methods: The effect of orally administered aqueous extracts (400 mg/kg body weight) of Clitoria ternatea leaves and flowers on serum glucose, glycosylated hemoglobin, and insulin were examined in control and extract-treated diabetic rats. The glycogen content of the liver and skeletal muscles of the rats was evaluated while the activities of the glycolytic enzyme, glucokinase, and the gluconeogenic enzyme, glucose-6-phosphatase in the liver were assessed. The extracts were administered over a period of 84 days.Results: The aqueous extracts of Clitoria ternatea leaves and flowers significantly (P&amp;lt;0.05) reduced serum glucose, glycosylated hemoglobin and the activities of gluconeogenic enzyme, glucose-6-phosphatase, but increased serum insulin, liver and skeletal muscle glycogen and the activity of the glycolytic enzyme, glucokinase. For all the biochemical tests performed, the leaf extract-treated rat showed essentially the same profile as those treated with the flower extract.Conclusion: The present investigation suggests that Clitoria ternatea leaf and flower extracts exhibit antihyperglycaemic effect in rats with alloxan-induced diabetes mellitus.', '{"arp_id": "ARP_AYU006566", "portal_id": 6566, "medical_system": "AYURVEDA", "journal": "Tropical Journal of Pharmaceutical Research", "volume": "8", "issue": "5", "pages": "393 - 398", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "https://www.tjpr.org/home/abstract.php?id=1047&amp;aTitle=Hypoglycemic%20Effects%20of%20Clitoria%20ternatea%20Linn.%20(Fabaceae)%20%20in%20Alloxan-induced%20Diabetes%20in%20Rats", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6566", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006566.pdf", "pdf_sha256": "aee034aceab9c1c5fd5032ee45eedf5a38501a1175f8c89923a7939f5785ddd2", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.32725/jab.2008.014', 'BIOCHEMICAL STUDIES ON THE EFFECT OF TERMINALIA CHEBULA ON THE LEVELS OF GLYCOPROTEINS IN STREPTOZOTOCIN-INDUCED EXPERIMENTAL DIABETES IN RATS', 'Gandhipuram Periasamy Senthilkumar, Sorimuthu Pillai Subramanian.', 2008,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study was designed to evaluate the effect of Terminalia chebula fruit extract on the levels of plasma and tissue glycoprotein components in streptozotocin-induced-diabetic rats. Oral administration of T. chebula fruit extract at a concentration of 200 mg/kg body weight for 30 days significantly reduced the levels of blood glucose, glycosylated hemoglobin, urea, and creatinine as well as fucose, hexose, hexosamine and sialic acid in the diabetic rats treated with the fruit extract. The observed decrease in the levels of plasma insulin and C-peptide in the diabetic rats was elevated to near normal by T. chebula fruit extract treatment. Histological observations made on the pancreatic tissue of control and experimental groups also revealed the beneficial effect of T. chebula fruit extract. The efficacy of the fruit extract was comparable with glibenclamide, a known hypoglycaemic drug.', '{"arp_id": "ARP_AYU007841", "portal_id": 7841, "medical_system": "AYURVEDA", "journal": "Journal of Applied Biomedicine", "volume": "6", "issue": "-", "pages": "105 - 115", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["C-Peptide"], "original_url": "https://jab.zsf.jcu.cz/artkey/jab-200802-0008_biochemical-studies-on-the-effect-of-terminalia-chebula-on-the-levels-of-glycoproteins-in-streptozotocin-induce.php", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7841", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007841.pdf", "pdf_sha256": "a3f6f938bb098f7530a9d6efd3db62bfe332516247990124d86e083d219d2d60", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIDIABETIC EFFECT OF PUNICA GRANATUM PEEL EXTRACT, SPILANTHES PANICULATA FLOWER EXTRACT AND SELENIUM IN STREPTOZOTOCIN INDUCED DIABETES.', 'Shaikh Asma Afreen, Mohammed Mukhtar Khan, Syed Ayaz Ali.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present study was aimed to evaluate the antidiabetic potential of combination of punica granatum peel extract, spilanthes paniculata flower extract and selenium in streptozotocin (STZ) induced diabetes in mice. Group A was used as control and Group B was used as diabetic control (STZ, 40mg/kg for 3 days, i.p.). A placebo was given to both the group orally. Metformin (120mg/kg) was given intraperitoneally as standard drug to Group C. Ethanolic peel extract of punica granatum (EPP 600mg/kg, p.o.) was administered to group D, (EPP) in combination with ethyl acetate extract of spilanthes paniculata flower (EAS) was administered to group E (EPP 300mg/kg, p.o. + EAS 200mg/kg, p.o.), Sodium selenite was given with combination of herbal extract (EPP 300 mg/kg, p.o.+ EAS 200mg/kg, p.o. + Se 0.3mg/kg, i.p.) to group F. STZ was given in multiple low doses of 40mg/kg, i.p. for 3 consecutive days &amp;amp; hyperglycemia was observed on 7th day. Blood glucose was determined on 0th, 7th, 14th, and 21st day. Diabetic mice in all group showed significant (P&amp;lt;0.01) increase in serum blood glucose as compared to control animals. Blood glucose level of animals treated with metformin &amp;amp; herbo-mineral combination lowers the glucose level significantly (P&amp;lt;0.01) as compared to diabetic control. The herbo-mineral combination shown significant (P&amp;lt;0.01) increase in the antioxidant enzymes Catalase, SOD, GSH and reduction in MDA &amp;amp; NO levels as compared to diabetic control. Thus, the present study indicates decreased blood glucose level &amp;amp; significant improvement in the biomarkers of oxidative stress by using the combination of sodium selenite with herbal extracts. The results confirm that the herbo-mineral combination is not only useful in controlling blood glucose level but also helps to prevent oxidative stress induced damage.', '{"arp_id": "ARP_AYU010055", "portal_id": 10055, "medical_system": "AYURVEDA", "journal": "International Journal of Pharmaceutical Research & Allied Sciences", "volume": "4", "issue": "2", "pages": "112 - 118", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Punica Granatum"], "original_url": "https://ijpras.com/article/antidiabetic-effect-of-punica-granatum-peel-extract-spilanthes-paniculata-flower-extract-and-selenium-in-streptozotocin-induced-diabetes", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10055", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010055.pdf", "pdf_sha256": "c78e05b24fc13be1d8339279f4421d15560e530870382b7a303a9587328988ce", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'COMBINED EFFECT OF AQUEOUS EXTRACT OF CURCUMA LONGA LINN. WITH METFORMIN IN DIABETES INDUCED NEUROPTAHIC PAIN IN RATS.', 'Roman Adhikari, Jyothi Y, Deepika Bora, Vaee Veena A.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objectives: A number of studies previously conducted have shown that the progression of severity of diabetic neuropathy relates the increased oxidative stress due to hyperglycemia describing the probable underlying mechanism as changes in the anti-oxidant enzyme level leading to several vascular and neuronal changes. The present investigation was carried out to observe the combined effect of aqueous extract of Curcuma longa Linn. (Curcumin [CUR]) with metformin (Met) in delaying of diabetes-induced neuropathic pain in rats.Methods: The high-fat diet (HFD) treated male Sprague–Dawley (SD) rats were induced diabetic by a single intra-peritoneal injection of streptozocin (35 mg/kg). Eddy’s hot plate and hot water tail immersion test were the models used to assess the neuropathic pain. The HFD treated and diabetic rats were treated with Met (500 mg/kg), CUR (300 mg/kg) and a combination of low dose of Met with CUR, followed by the oral glucose tolerance test before and after the treatment on both normal and diabetic rats. After 7 weeks of treatment thiobarbituric acid reactive substances, superoxide dismutase, catalase, and glutathione levels were also estimated in the sciatic nerve homogenate of diabetic rats and compared with the control, followed by a supporting histopathological examination of sciatic nerve.Results: Diabetic rats treated with C. longa Linn. and Met alone and in combination showed a significant improvement in control of blood glucose level and restoration of anti-oxidant enzyme levels. There was a significant improvement in the hyperalgesia (p&amp;lt;0.001) due to diabetic neuropathy and also the reaction time to the nociceptive stimuli in neuropathic pain models was increased after the treatment.Conclusion: Curcumin has a property of protecting the islets ß cells, decrease the insulin resistance and decrease the oxidative stress. Hence the use of Curcumin along with the Oral Hypoglycemic Agents could be useful in preventing the complications associated with Diabetes when subjected to prolonged treatment.', '{"arp_id": "ARP_AYU010287", "portal_id": 10287, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "8", "issue": "5", "pages": "166 - 170", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Oxidant"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/7137", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10287", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010287.pdf", "pdf_sha256": "3748c3a561487c7690119197843ac5ff99f929b4faa1d0a1660beb0d4590b762", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'COMBINED EFFECT OF AQUEOUS EXTRACT OF CURCUMA LONGA LINN.WITH METFORMIN IN DIABETES INDUCED NEUROPATHIC PAIN IN RATS.', 'Jyothi Yachamaneni, Roman Adhikari, Deepika Bora,Vaee Veena A.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objectives: A number of studies previously conducted have shown that the progression of severity of diabetic Neuropathy relates the increased oxidative stress due to hyperglycemia describing the probable underlying mechanism as changes in the anti-oxidant enzyme level leading to several vascular and neuronal changes. The present investigation was carried out to observe the combined effect of Aqueous Extract of Curcuma longa Linn.(Curcumin) with Metformin in delaying of Diabetes induced Neuropathic Pain in Rats.Methods: The high-fat diet treated male SD rats were induced diabetic by a single intra-peritoneal injection of Streptozocin (35mg/kg). Eddy’s Hot Plate and Hot Water Tail Immersion test were the Models used to assess the Neuropathic pain. The high Fat diet treated and Diabetic Rats were treated with Metformin (500mg/kg), Curcumin (300mg/kg) and a combination of low dose of Metformin with Curcumin, followed by the oral glucose tolerance test before and after the treatment on both Normal and Diabetic Rats. After 7 weeks of treatment TBARS, SOD, Catalase and GSH levels were also estimated in the sciatic nerve homogenate of Diabetic Rats and compared with the control followed by a supporting histopathological examination of Sciatic Nerve.Results: Diabetic Rats treated with Curcuma longa Linn. and Metformin alone and in combination showed a significant improvement in control of blood glucose level and restoration of anti-oxidant enzyme levels. There was a significant improvement in the hyperalgesia (P&amp;lt;0.001) due to Diabetic Neuropathy and also the reaction time to the nociceptive stimuli in Neuropathic pain models was increased after the treatment.Conclusion: Curcumin has a property of protecting the islets ß cells, decrease the insulin resistance and decrease the oxidative stress. Hence the use of Curcumin along with the Oral Hypoglycemic Agents could be useful in preventing the complications associated with Diabetes when subjected to prolonged treatment.', '{"arp_id": "ARP_AYU011676", "portal_id": 11676, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "8", "issue": "5", "pages": "166 - 170", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/7137", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11676", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011676.pdf", "pdf_sha256": "1ac43dfe68092b1cbeeab7494df4462ca5ec9005518eb48b75db7a88efda4cbe", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOGLYCEMIC AND ANTIHYPERLIPIDEMIC EFFECTS OF ADIANTUM CAUDATUM IN ALLOXAN INDUCED DIABETES IN RATS.', '1. Dipankar Saha, 2. Surajit Kumar Ghosh, 1. Trishna Das, 3. Shanti Bhushan Mishra.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: To investigate the hypoglycemic and antihyperlipidemic effect of a successive ethanolic extract of Adiantum caudatum (EEAC) whole plant in alloxan induced diabetic rats. Methods: Diabetes was induced in Wistar albino rats by the administration of alloxan (140 mg/kg b. w., i.p.). EEAC (200 mg/kg b. w., p.o.) was administered to diabetic rats for 21 days in alloxan induced diabetic rats. The effect of EEAC on blood glucose and body weight was studied in alloxan induced diabetic rats. All these effects were compared with glibenclamide (10 mg/kg b. w., p.o.) as a reference antidiabetic drug. Results: The administration of EEAC (200 mg/kg b. w., p.o.) resulted in a significant decrease in blood glucose level and a significant increase in body weight in alloxan induced diabetic rats. Furthermore, EEAC showed antihyperlipidemic activity as evidenced by a significant decrease in serum total cholesterol and triglyceride levels in alloxan induced diabetic rats. Conclusion: The results suggest that the EEAC possess a promising hypoglycemic effect in alloxan induced diabetic rats.', '{"arp_id": "ARP_AYU011761", "portal_id": 11761, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "9", "issue": "1", "pages": "361 - 363", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Adiantum Caudatum"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/8974", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11761", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011761.pdf", "pdf_sha256": "e11c466a3dad90579094a269e0f6974340bfd86c8b1917fa02e779b73d0433c5", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'IN VITRO HYPOGLYCEMIC EVALUATION OF SEVEN CULINARY PLANTS OF NORTH EAST INDIA AGAINST TYPE 2 DIABETES.', 'Jayashree Dutta, Kalita MC.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: The goal of the present study is to provide an in vitro evidence for potential inhibition of the a-amylase and a-glucosidase enzyme by seven culinary plants of North east India followed by their phytochemical screening. Methods: The different parts (leaves, seeds, bark, and fruit) of the selected plants were chosen for the study. Collected plant parts were a shade dried, powdered, and successively extracted using petroleum ether, acetone, and methanol. The obtained extracts were quantitatively assayed for in vitro a-amylase and a-glucosidase enzyme inhibitory activity. The collected plant materials were screened qualitatively for detection of several bioactive compounds. Results: In our study, we found that among all the screened culinary plants the highest a-amylase inhibitory activity was demonstrated by Dillenia indica Linn. fruit methanol extract with a minimum IC50 value of 02.45 &amp;#177; 0.305 mg/ml, and the highest a-glucosidase inhibitory activity was demonstrated by D. indica leaves methanol extract with a very minimal IC50 value of 01.78 &amp;#177; 0.331 mg/ml compared to the standard drug acarbose IC50 - 05.43 &amp;#177; 0.280 mg/ml for a-amylase and IC50 -03.06 &amp;#177; 0.072 mg/ml for a-glucosidase, respectively. Phytochemical screening reveals the presence of several bioactive groups such as carbohydrate, protein, saponin, tannin, flavonoid, alkaloid, and terpenoids in all studied plants. Conclusion: The study concludes that selected culinary plants of North East India are capable of inhibiting carbohydrate metabolizing enzyme a-amylase and a-glucosidase, and the presence of bioactive compounds in these plants add on the potentiality of these plants to reduce the postprandial hyperglycemia.', '{"arp_id": "ARP_AYU011825", "portal_id": 11825, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "9", "issue": "2", "pages": "209 - 212", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Culinary Plants"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/10416", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11825", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011825.pdf", "pdf_sha256": "1491ae863bc16d5c91db43ccf508d4977cdae1be658829d56bb467898ce39a5d", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CONTROLLED CLINICAL EVALUATION OF MAMAJJAK CHOORNA IN STHULA MADHUMEHA VIZ-A-VIZ TYPE 2 DIABETES MELLITUS.', '1. Surse Yogesh Shankarrao, 2. Aparna Raut, 3. Phartale Vaibhav D, 1. Shinde Kiran P.', 2017,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Sthula Madhumeha (viz-e-viz type 2Diabetes Mellitus) is the vital problem in present era. The change in lifestyle and food habit is the major concern of the problem. The available drug therapy concentrating on levels of blood sugar rather than symptoms of patients like excessive thirst, Nocturnal enuresis, burning sensation in hands, feet and many more. Ayurveda emphasized more on these symptoms. These symptoms affects the patient’s routine life and work capacity. On behalf of these symptoms the role of Mamajjak Choorna which is described by Acharya Priyavrat Sharma in his book Dravya guna Vidnyan Vol. 2 page 705 found to be more effective in comparison to modern oral hypoglycemic and well practiced drug Metformin. Total 40 patients of newly diagnosed of Diabetes Mellitus were taken and divided in two groups as Trial group 20 patients on Mamajjak Choorna 5 gm B.I.D. given for 12 weeks. Control Group 20 patients on tab. Metformin 500 mg B.I.D. given for 12 weeks.On consumption of Mamajjak Choorna for 12 weeks it was found that there is improvement in the symptoms Pipasati Pravrutti (74.27%), Nakta mutrata (83.33%), Hasta-padatala daha (82.5%) Pippalika Sancharvaat prachti (85.71%), Prabhuta Avila mutrata (77.5%), Swedatipravritti (82.5%) so far as consumption of Metformin is concern, it was found as follows Pipasati Pravrutti (64.71%), Nakta mutrata (72.94%), Hasta-padatala daha (51.28%), Pippalika Sancharvaat prachti (50%), Prabhuta Avila mutrata (71.88%), Swedatipravritti (51.16%). With P&amp;lt;0.05 (that highly significant results in Mamajjak Choorna group).', '{"arp_id": "ARP_AYU011933", "portal_id": 11933, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda and Pharma Research", "volume": "5", "issue": "7", "pages": "26 - 31", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes Mellitus"], "original_url": "https://ijapr.in/index.php/ijapr/article/view/715", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11933", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011933.pdf", "pdf_sha256": "7ff1c8581e30a89e7f1400576d6a95a46c1ba8fb2e5cc113e73d100ee66b3205", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOGLYCAEMIC EFFECT OF LEAF DECOCTION OF PANASA(ARTOCARPUS HETEROPHYLLUS LAM) IN TYPE II DIABETES MELLITUS- A CLINICAL STUDY.', '1. Sree Deepthi GN, 2. Jollykutty Eapen, 3. Roopesh Kumar CB.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Panasa (Artocarpus hetrophyllus Lam.), the well known jackfruit tree, is a tree with wide ethnomedicinal uses. It is a drug used by the traditional Ayurveda physicians of Kerala for the treatment of diabetes mellitus. Hypoglycaemic effect of leaves of Artocarpus hetrophyllus Lam. is experimentally proven through in vitro and in vivo studies. Estimates shows that by the year 2025, the number of people suffering from diabetes in the world will be 350 million, of which 70 million will be in India. As diabetic patients have to take lifelong medication the medicines chosen should be safe, cost effective and free from side effects. So it is the need of the hour to find out a safer and cost effective medicine for diabetes. The present study is on the hypoglycemic effect of leaf decoction of Panasa (Atrocarpus hetrophyllus Lam.) in type 2 diabetic patients. The clinical trial was undertaken as a before and after trial with 30 patients for a period of 30 days. The trial drug showed a highly significant effect in reducing the Fasting Blood Sugar (FBS, P&amp;lt;0.001), Post Prandial Blood Sugar (PPBS, P=0.001) &amp;amp; total cholesterol (P&amp;lt;0.001). Also it showed a significant role in relieving associated symptoms like Polyuria, polyphagia, Polydipsia, lassitude, joint pain, excessive sweating and dryness of mouth. This study throws light into the scope of Artocarpus heterophyllus Lam in future researches as it is a drug available in various parts of the world, which is cost effective and proven to be safe for diabetes mellitus.', '{"arp_id": "ARP_AYU012024", "portal_id": 12024, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda and Pharma Research", "volume": "5", "issue": "10", "pages": "20 - 25", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Artocarpus Heterophyllus"], "original_url": "https://ijapr.in/index.php/ijapr/article/view/807", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=12024", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU012024.pdf", "pdf_sha256": "38e7f550ca722b277f4ca94eb73a44f25524a8cc829ff5a2c78f6e4cbbeb3405", "relevance_score": 43.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '25298584', '10.4103/0253-7613.140587', 'CHEMOPREVENTIVE POTENTIAL OF APIUM LEPTOPHYLLUM (PERS.) AGAINST DMBA INDUCED SKIN CARCINOGENESIS MODEL BY MODULATORY INFL UENCE ON BIOCHEMICAL AND ANTIOXIDANT BIOMARKERS IN SWISS MICE', 'Himanshu Bhusan Sahoo, 1. Dev Das Santani, 2. Rakesh Sagar.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aim: The study was designed to investigate the chemopreventive potential of fl avonoidal fractions of Apium leptophyllum fruits (FFALF) on Swiss mice.Materials and Methods: Skin tumor or papilloma was developed by topical application of DMBA (25 µg in 0.1 ml acetone) on intrascapular region of mice, twice weekly for 8 weeks. The animals were divided into six groups: Group I (vehicle control); group II (FFALF control, 5 mg/kg); group III (carcinogenic control, DMBA treated initially for 8 weeks); and group IV, V and VI as pre-treated group (FFALF 5, 10 and 20 mg/kg respectively for 16 weeks along with DMBA treatment). After the 16th week of treatment; the tumor morphology, skin histopathology, and biochemical and antioxidant biomarkers were measured and compared with carcinogenic control as well as vehicle control.Results: The co-administration of FFALF with DMBA-treated groups showed significant (P = 0.001) prevention against skin papilloma and normalized the status of lipid peroxidation with antioxidant biomarkers in a dose-dependent manner as compared to carcinogenic control.Conclusions: Thus, the present study suggests that the FFALF is non-carcinogenic and has chemopreventive potential on DMBA-induced carcinogenesis in mouse, which may be due to the modulation of cutaneous lipid peroxidation or enhancement of total antioxidant capacity.', '{"arp_id": "ARP_AYU022659", "portal_id": 22659, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmacology", "volume": "46", "issue": "5", "pages": "531 - 537", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant Biomarker"], "original_url": "https://journals.lww.com/iphr/fulltext/2014/46050/chemopreventive_potential_of_apium_leptophyllum.13.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=22659", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU022659.pdf", "pdf_sha256": "9f0a74f49b4ba8cef097ae6c58a3f30e65f88f42f1655ba25b8adcd68b04bc6e", "relevance_score": 43.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5897/JPP.9000022', 'EFFECTS OF THE AQUEOUS EXTRACT OF FICUS CAPENSIS THUNB. (MORACEAE) LEAF ON GASTROINTESTINAL MOTILITY', '1. Ayinde BA, 2. Owolabi OJ.', 2009,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Medicinal plants have always played a great role in preventing, controlling and alleviating various disease conditions. Ficus capensis Thunb. (Moraceae) leaves have been reported in literatures to possess anti-diarrhea properties and have been used as such by herbal practitioners in some parts of Benue State, Nigeria. This work examined the preliminary phytochemical constituents of the plant part using standard procedures and also the anti-diarrhea effects of the leaves of the plant in adult mice and albino rats using three models. Preliminary phytochemical screening of the powdered leaves revealed the presence of saponins, steroidal glycosides, flavonoids and tannins. In mice, between 100 - 400 mg/kg (orally administered), the crude aqueous extract of the leaves exhibited a dose-related reduction in the gastrointestinal tract motility as indicated by the distance moved by the charcoal meal. In albino rats, the aqueous extract also displayed significant delay in the onset of stooling, and produced remarkable decrease in the number and weight of stools produced with 100 - 400 mg/kg of the aqueous extract. In the organ bath model, the aqueous extract at concentrations of 50, 100 and 200 mg/ml was observed to have relaxant effects on the isolated rat ileum as it remarkably reduced the ileal contractions occasioned by administration of acetylcholine. The activities of the extract were comparable with that of atropine (0.1 mg/kg). The results of this work validated the claimed use of the leaves of F. capensis in controlling diarrhea among the Igede people of Benue State, Nigeria.', '{"arp_id": "ARP_AYU007978", "portal_id": 7978, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacognosy and Phytotherapy", "volume": "1", "issue": "3", "pages": "31 - 35", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aqueous Extract"], "original_url": "https://academicjournals.org/journal/JPP/article-abstract/418BEE71007", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7978", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007978.pdf", "pdf_sha256": "1f3e4166c132fc029c91b6d2d95be6636d14c03bbc55a056ac54cd80fbeab24f", "relevance_score": 43.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'AN IN VITRO EVALUATION OF TRIBULUS TERRESTRIS L. FRUIT EXTRACT FOR EXPLORING THERAPEUTIC POTENTIAL AGAINST CERTAIN GUT AILMENTS.', 'Sonal Chauhan, Dhara Sharma, Harish Chana Goel.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The enteric pathogens and oxidative stress are known to generate intestinal inflammation, chronic gut ailments and oncogenesis. Modulation of the gut microbial peak populations through herbal agents, offers a promising therapeutic modality. Tribulus terrestris Linn. (Tt), a widely documented medicinal herb in Ayurveda, was investigated for antioxidant, anti-inflammatory and antimicrobial activities in vitro. Fruit extract of Tt and quercetin, evaluated for free radical scavenging by DPPH method, revealed IC50 values as 98.83 and 24.77 &amp;#181;g/mL, respectively. Anti-inflammatory attributes of Tt fruit extract and indomethacin, a known anti-inflammatory drug, rendered IC50 values as 10.8 and 12.9 &amp;#181;g/mL against protein denaturation. MTT assay on HCT-15 cells revealed a decrease in viability from 78 to 22% against 30 and 70 &amp;#181;g/mL of Tt fruit extract, respectively. Zone of inhibition against E. coli increased from 0.19 to 9.82 cm2 at 200 and 1000 &amp;#181;g/mL of Tt, respectively. The fruit extract of Tt enhanced the growth of probiotic Lactobacillus rhamnosus (L.rh) by 19, 44 and 50 % over the control at 100, 150 and 200 &amp;#181;g/mL, respectively. This study indicated the potential of Tribulus terrestris fruit extract against inflammatory, oxidative and microbe generated pathogenic ailments in the digestive system.', '{"arp_id": "ARP_AYU016608", "portal_id": 16608, "medical_system": "AYURVEDA", "journal": "Indian Journal of Experimental Biology", "volume": "56", "issue": "6", "pages": "430 - 436", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anticancer"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/44535", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16608", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016608.pdf", "pdf_sha256": "d33d1ccc1d4409efc3349e4fa2994cf1bc6c269e4f53e6f261df5e623938170a", "relevance_score": 43.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22131714', '10.4103/0974-8520.72404', 'A CLINICAL STUDY ON KRIMIDANTA WITH REFERENCE TO DENTAL CARIES AND ITS MANAGEMENT WITH JATIPATRADI GUTIKA AND YAVANADI CHURNA_x005F_x005F_x005F_x005F_x005F_x005F_x005F_x000D_
_x005F_x005F_x005F_x005F_x005F_x005F_x005F_x000D_', 'Makbul Mansuri, Manjusha Rajagopala, Narayan Bavalatti', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Dental caries is progressive destruction of enamel, dentine and cementum, initiated by microbial activity at the tooth surface. It is one of the major problems in dentistry. On the basis of clinical features, it can be compared with Krimidanta which is one among the eight diseases of tooth. In the management of Krimidanta, Krimighna, Vataghna and Ushna Veerya dravyas are to be used which can relieve the toothache and discoloration. In this study, the trial drugs used were Jatipatradi Gutika for Pratisarana and Yavanadi Churna for oral administration. In this study, the patients of Krimidanta (dental caries) were selected from OPD of Shalakya Department and allotted randomly in different groups. In Group A, the patients were treated with Jatipatradi Gutika for Pratisarana for 30 days. In Group B, the patients were treated with Yavanadi Churna orally and Group C patients were treated with combined therapy for 30 days. The clinical study has shown that combined therapy gives better results than individual therapies.', '{"arp_id": "ARP_AYU021780", "portal_id": 21780, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "31", "issue": "2", "pages": "223 - 227", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "TEETH/GUM DISEASE(ICPC-D82|ICD-K00.0, K00.1, K00.2, K00.3, K00.4, K00.5, K00.6, K00.8, K00.9, K01, K02, K03, K04, K05, K06, K07, K08, K09, K10)", "keywords": ["Dental Caries"], "original_url": "https://journals.lww.com/aayu/fulltext/2010/31020/a_clinical_study_on_krimidanta_with_reference_to.16.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=21780", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU021780.pdf", "pdf_sha256": "b6070974c65560b2525c42f96c7c81653e77ccb0386dd50633393db29d986b8e", "relevance_score": 43.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
