) VALUES (
    NULL, NULL, 'A COMPARATIVE STUDY OF EFFICACY & SAFETY OF PUSHKARMOOLADI YOGA AND BHARANGI NAGARA KWATHA IN MANAGEMENT OF TAMAKA SHWASA W.S.R. TO CHRONIC OBSTRUCTIVE PULMONARY DISEASE (COPD).', '1. Udai Raj Saroj, 2. Mandeep Kaur, 3. Ram Kishor Joshi', 2019,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background : - Keywords : Bharangi Nagara Kwatha , Fev1 , Gold Stage , Pushkarmooladi Yoga , Tamaka Shwasa URL (for Abstract/ Full paper) : https://journals.lww.com/joay/citation/2019/13020/joa_xiii_april_june_2019.1.aspx DOI : No Access : -', '{"arp_id": "ARP_AYU000269", "portal_id": 269, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "13", "issue": "2", "pages": "125 - 135", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "RESPIRATORY", "disease": "CHRON OBSTRUCTIVE PULMONARY DISEASE(ICPC-R95|ICD-J43, J44)", "keywords": ["Bharangi Nagara Kwatha"], "original_url": "https://journals.lww.com/joay/citation/2019/13020/joa_xiii_april_june_2019.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=269", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000269.pdf", "pdf_sha256": "74790a5186bd0a73b5668671c5422141689d94eac414874c1ce247ad2c5fb0e2", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
