INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL EVALUATION OF SAFETY AND EFFICACY OF  AVALGUJA BEEJA CHURNA AND ARKA TAIL IN THE MANAGEMENT OF  VICHARCHIKA (ATOPIC DERMATITIS)-  A RANDOMIZED CONTROLLED TRIAL.', '1. Devesh Jaiman, 2. Harish Bhakuni, 3. Ajay Kumar Sahu, 4. Puneet Bhargava.', 2019,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Due to ignorance towards dietetic, seasonal and daily regimen people are more prone to various kinds of skin disorders. Vicharchika (Atopic dermatitis) is the most common skin disorders. Due to wide spectrum of disease, much prevalence in the society and lack of effective medicament, so disease being chosen for the study. The study was conducted in 50 clinically diagnosed patients of Vicharchika (Atopic dermatitis) and randomly divided into two groups. In group A patients were treated with Avalguja Beeja Churna (6 gms) ) with Ghrita, before meal twice daily for 30 days and Arka Tail twice daily for 30 days, on the lesion for local application. In group B patients were treated with Cetrizine tab. (oral 10mg in night) and Clobetasol ointment twice daily for 30 days, on the lesion of Atopic dermatitis. Conclusions: ‘Avalguja Beeja Churna’ and ‘Arka Tail’ is safe, cost effective and free from any side effects in the management of Vicharchika [Atopic dermatitis]”. It also prevents the relapse considerably.', '{"arp_id": "ARP_AYU000278", "portal_id": 278, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "13", "issue": "3", "pages": "22 - 31", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "SKIN", "disease": "DERMATITIS/ATOPIC ECZEMA(ICPC-S87|ICD-L20)", "keywords": ["Arka Tail"], "original_url": "https://journals.lww.com/joay/citation/2019/13030/joa_xiii_july_september_2019.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=278", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000278.pdf", "pdf_sha256": "9f4d437149e66d8d116e06d673c8b6b86cfcbe51104c387dde06329a8c942211", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF EFFICACY AND SAFETY OF NIGELLA SATIVA OIL SUPPLEMENTATION IN PATIENTS OF CHRONIC KIDNEY DISEASE.', '1. Zafar M Ansari, 1. Mohammad Nasiruddin, 1. Rahat A Khan, 2. Shahzad F Haque.', 2016,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Objective: To evaluate efficacy and safety of add-on therapy of Nigella sativa oil in patients of stage 3 and 4 of chronic kidney disease (CKD). Materials and Methods: The study was conducted in a tertiary care center of north India in stage 3 and 4 patients of CKD. It was a prospective, comparative, and open label study. Patients were randomly divided into two interventional groups. Group I (Control) received conservative management of CKD while Group II (Test) received conservative management along with N. sativa oil (2.5 mL, per orally, once daily) for 12 weeks. Hemogram and renal function tests were done, and adverse events were recorded at 0, 6, and 12 weeks of treatment. Results: After 12 weeks of treatment, there was a progressive improvement in clinical features and biochemical parameters in both the groups, but it was more marked in the test group compared to control group. Both groups showed gradual improvement in the biochemical parameters as compared to their pre-treated values which were more marked in N. sativa oil supplemented group. There was a reduction in blood glucose, blood urea, serum creatinine, and 24-hr total urine protein. There was an increase in hemoglobin, 24-hr total urine volume, and glomerular filtration rate. Conclusion: N. sativa oil supplementation along with conservative management is efficacious and safe in averting the progression of disease in stage 3 and 4 patients of CKD.', '{"arp_id": "ARP_AYU011861", "portal_id": 11861, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "9", "issue": "2", "pages": "107 - 110", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "URINARY SYSTEM", "disease": "CHRONIC KIDNEY DISEASE ((ICPC-U99|IICD-N18.9)", "keywords": ["Chronic Kidney Disease"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/9994", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11861", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011861.pdf", "pdf_sha256": "8633cfabe7a15ba9760a28a13440d7c94a99c488af5fa8e17af9f87668e3e606", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A CLINICAL COMPARATIVE EVALUATION OF EFFICACY AND SAFETY OF KUMARYASAVA AND RAJAHPRAVARTANI VATI IN THE MANAGEMENT OF PRATHMIK KASTARTAVA W.S.R. TO (PRIMARY DYSMENORRHOEA): A PROSPECTIVE OPEN LABEL SINGLE CENTER STUDY.', '1. Pravesh Tomar, 2. Sudeep Kumar Lal, 3. Saloni Garg.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Primary dysmenorrhoea is most prevailing symptom in young adolescent girls. It can start before menarche and may be present continuously for years even after the patient get married and have children. Kashtartava can be expressed as- “kashten munchyati iti kastartava” i.e. the condition where Artava is shaded with great difficulty and pain is termed as “Kashtarava”. Kashtartava is mentioned as a specific symptom in Vatala, Paripluta, Udavartini Yonivyapad, Vataja Artava Dusti, Kshina Artava-Dusti And Asrigdar and the diseases in which whole symptomatology denotes Kashtartava, are Pittala, Sannipataki, Suchimukhi Yonivyapada and Artavakshaya. Aims and objectives: To compare and evaluate the efficacy and safety of Kumaryasava with Rajahpravartani Vati in the patients suffering from Prathmik- Kashtartava. Material and methods: A prospective open label study was carried out at OPD of Prasuti –Tantra and Stri Roga department. 76 patients satisfying the selection criteria were enrolled, however data of fifty patients was used for analysis and comparative study. 50 patents were divided into two groups (A and B) with twenty five patients in each. Patients of group A were administered Kumaryasava 20 ml with equal amount of water and that of group B were administered tab Rajahpravartini vati (125 mg) 2BD after meal with normal water before 7 days of menses and during menstrual cycle. Total duration of course of medicine was 3 consecutive cycles. Follow-up was done at every menstrual cycle during the treatment and follow- up without treatment was done for next three cycles. Assessment of intensity of pain was done by VAS and VMSS according to the memory and presentation of the patient. The pain was assessed at baseline and at every menstrual cycle. Results: After three month of treatment, in both groups the baseline pain was found to be improved in every cycle But when the overall result was observed highly significant results were found in group B in comparison to group A. The effect of Kumaryasava on associated symptoms was found to be more than Rajahpravartini vati.Conclusion: Kumaryasava and Rajahpravartani Vati administered in cases of dysmenorrhea in above mentioned doses were found safe and effective in pain but Rajahapravartini Vati showed more effect on overall symptoms of dysmenorrhea including pain and menstrual pattern though Kumaryasava was found to be more effective in associated sign and symptoms of dysmenorrhea.', '{"arp_id": "ARP_AYU012113", "portal_id": 12113, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda and Pharma Research", "volume": "5", "issue": "11", "pages": "1 - 13", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "FEMALE GENITAL SYSTEM INCLUDING BREAST", "disease": "DYSMENORRHOEA(ICD-N94.4)", "keywords": ["Kumaryasava"], "original_url": "https://ijapr.in/index.php/ijapr/article/view/806", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=12113", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU012113.pdf", "pdf_sha256": "2be0cf42fefa15bd7d47dfc4da56a917e3ef4e34e2feb230da598a147e127ff4", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'SAFETY ASSESSMENT ON CHRONIC ADMINISTRATION OF SWARNA BINDU PRASHAN-A POPULAR AYURVEDIC PREPARATION OF INCINERATED GOLD ASH USED AS IMMUNE BOOSTER TO CHILDREN IN SOUTHERN INDIA.', '1. Vinamra Sharma, 2. Ruamma R Hiremath, 3. Patil PA, 4. Prasad BS.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Swarna Bindu Prashan (SBP) is an Ayurvedic proprietary preparation of incinerated gold ash (Swarna Bhasma) administered frequently with ghee and honey to children as immune booster in southern-India. In this study, we assessed the safety parameters of SBP and its vehicle’s effect on chronic administration. The groups of Wistar strain male albino rats were identified as control, vehicle group of ghee, honey and both ghee-honey and group of SBP, respectively. In SBP group, Swarna Bhasma was administered in dose of 5.625 mg/ kg body wt. alongwith 0.4 mL of each ghee and honey. Vehicles group also received same dose of 0.4 mL/kg of each substance in graded quantities by oral route for 90 days. During the course of study, no mortality and no significant behavioral changes were noticed in any group studied. The effect on food and water consumption and fecal and urine output remained unaffected. No major alterations were observed in hematology and serum biochemistry. Histopathology of vital organs also supported the nontoxic effect of SBP. It is concluded that the chronic use of SBP is safe and non-toxic at this tested dose level when compared to other vehicle groups.', '{"arp_id": "ARP_AYU016591", "portal_id": 16591, "medical_system": "AYURVEDA", "journal": "Indian Journal of Experimental Biology", "volume": "55", "issue": "4", "pages": "217 - 224", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ayurvedic Therapy"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/41182", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16591", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016591.pdf", "pdf_sha256": "caa36560acf4ecc422a97de0bf0feb55a0aa7df19b2f05f79131707943e5454e", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'SAFETY EVALUATION OF ALOE VERA PULP AQUEOUS EXTRACT BASED ON HISTOARCHITECTURAL AND BIOCHEMICAL ALTERATIONS IN MICE.', '1. Shashi Bala, 1. Neha Arora Chugh, 2. Subhash Chand Bansal, 1. Mohan Lal Garg, 1. Ashwani Koul.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aloe vera has a long history as a popular herbal remedy. A scrutiny of literature reveals that it possesses beneficial as well as harmful effects, thus making it essential to assess its toxicity profile before employing it as a medicinal agent. Various authors have reported conflicting observations on different applications of Aloe vera in experimental animals. Qualitative phytochemical analysis of Aloe vera extract used in the present study revealed the presence of tannins, carbohydrates and anthraquinone glycosides. For assessing the toxicity profile, Balb/c mice were divided into four groups— control and Aloe vera treated @ 250, 100 and 50 mg/kg body weight, and were administered with respective doses for 30 days. Histopathological examination of various tissues revealed significant structural alterations on administration of higher doses of Aloe vera indicating the toxicity, which was also associated with enhanced peroxidative damage and serum LDH activity. Low dose of Aloe vera revealed normal histoarchitecture of various tissues along with biochemical parameters studied. Considering these results 50 mg/kg body weight Aloe vera extract is considered safe and shall be employed for further studies.', '{"arp_id": "ARP_AYU016593", "portal_id": 16593, "medical_system": "AYURVEDA", "journal": "Indian Journal of Experimental Biology", "volume": "55", "issue": "8", "pages": "568 - 575", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cosmetics"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/42553", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16593", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016593.pdf", "pdf_sha256": "62eb60f20c28e112ab0289010643717d6970aff026ff1e3f52a36fcba5328c15", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A STUDY TO EVALUATE THE EFFICACY AND SAFETY USE OF AYURVEDIC REMEDIES IN TREATING MALE INFERTILITY', 'Hiremath CS.', 2015,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Infertility is a global problem affecting the couple as a unit. It is a combination of both male &amp;amp; female factor. WHO reveals 2 to 10% of worldwide are unable to conceive primarily. In recent era, the occupational hazards have contributed to increase the ratio of infertility in both. Experience has shown that about 30% cases responsibility lies with male side. The cause for male infertility can be divided into 3 main categories. Low sperm count, low motility and anatomical disorders. Here in this research case study Male infertility patients having history of married life 2 – 10 years, age under 26 – 50 years &amp;amp; reports of low sperm count &amp;amp; motility (oligospermia) were included. Anatomical disorders, systematic disorders &amp;amp; Positive reports of VDRL Hbs Ag &amp;amp; HIV were excluded. Herbal remedies have been used since ancient times to treat infertility. Here to treat male infertility Polyherbal formulation consisting of Kapikachu, shweta musli, vidarkand, Ashwagand, shatavari, Gokshura, Kokilaksha, makaradwaja rasa, &amp;amp; purna chandrodaya rasa was given in dose of 2 capsules twice daily for 6 months.Kapikachu contains high level of L – Dopa which is converted to Dopamine, that stimulates the release of growth hormone by pituitary gland. So act has a prophylactic agent in patient with oligospermia to increase sperm count. Along with shwet musli, vidarikand, makardwaja, purna chandrodaya rasa also a powerful aphrodisiac and increase count and motility. Shatavari helps to regeneration of seminiferous tubules and hence increase spermatogenesis. Ashwaganda also a main drug used in treating male infertility which acts as antioxidiant, maintaine genetic integrity of sperm cell, by preventing damage to sperm. Kokilaksha &amp;amp; gokshura controls spermatorrhoea &amp;amp; treat disease of genitourinary system, impotence and sexual debility also.The spermatogenic action of these drugs in mainly is because they increase the testicular blood supply and stimulates the seminiferous epithelium. They also improve the quality of semen by increasing concentration and motility of sperm and reduce the abnormal sperms. Hence these drugs prevents male infertility and acts as nervine tonic physically and mentally.Thus study have shown good results in treating male infertility as it increases sperm count, concentration, sperm motility and morphology without any side effects. So I wish to conduct in a larger multi centric study to substantiate the encouraging results obtained by me.References no 4', '{"arp_id": "ARP_AYU018436", "portal_id": 18436, "medical_system": "AYURVEDA", "journal": "Deerghayu International", "volume": "31-3", "issue": "123", "pages": "432 - 436", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MALE GENITAL", "disease": "MALE INFERTILITY/SUBFERTILITY (ICPC-Y10|ICD-N46, Z31.0, Z31.4, Z31.6, Z31.8, Z31.9)", "keywords": ["Infertility"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18436", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018436.pdf", "pdf_sha256": "a29e8a55f08be9c2ece94867717a9475c7c85fa88a207b56a5f96fa60297ed17", "relevance_score": 43.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-OBESITY POTENTIAL OF MEDOHAR ARK: A TRADITIONAL AYURVEDIC PREPARATION IN HIGH FAT DIET-INDUCED RAT MODEL.', '1. Akash A Laturiya, 1. Komal M Parmar, 1. Satyena K Prasad, 2. Nandini Bhojraj, 1. Prakash R Itankar.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The aim of the present study was to develop a phytochemical profile of Medohar Ark, one of the Ayurvedic formulation used as a potent tool for reducing weight in obese patients and also to perform preclinical evaluation for anti-obesity activity. The physicochemical parameters such as pH, viscosity, specific gravity and total solid content of Medohar Ark marketed (MAM), Medohar Ark in-house (MAIH) and distilled cow urine (DCU) were performed along with phytochemical screening and chromatographic (HPTLC and HPLC) study using Crocin as a biomarker. Phytochemical screening revealed the presence of alkaloids, flavonoids, tannins, sterol, carbohydrates and saponins in MAIH and MAM. The HPTLC analysis revealed that, MAIH contained 4.58 % w/w of Crocin, whereas in MAM, Crocin was not detected. However, HPLC analysis of MAIH and MAM showed that MAIH and MAM contained 4.56 % w/w and 1.23 % w/w of crocin, respectively. The pharmacological evaluation concluded that, MAIH showed better result as compared to MAM in reduction of body weight of rats in high fat diet (HFD) rat model. From the lipid profile and antioxidant evaluations of animals, it was observed that there was a significant restoration in altered lipid profile and antioxidant status of HFD induced rats treated with MAM and MAIH, which was also confirmed through histopathological studies showing very less fat deposition. The overall study concludes that the Medohar Ark has a significant anti-obesity activity especially in case of in-house formulation, which can be used as a major tool for obesity management in human healthcare.', '{"arp_id": "ARP_AYU003914", "portal_id": 3914, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "17", "issue": "4", "pages": "745 - 753", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Crocin"], "original_url": "http://nopr.niscpr.res.in/handle/123456789/45058", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3914", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003914.pdf", "pdf_sha256": "8d0ce29719aea8de3614d86f58583b52232238793ff3011195e112aaff3bf302", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF DIETARY SUPPLEMENTATION OF ARJUNA (TERMINALIA ARJUNA) BARK POWDER ON HEMATOLOGY OF BROILER CHICKS', '1. Jumman Ali Ansari, 2. Neeraj, 3. Ramesh Pandey, 4. Ajit Singh, 5. Sushma.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The research was to investigate the effect of different schedules of administration of Arjuna (Terminalia Arjuna) bark powder on hematology of broilers chicks. A total of 72 (Arbor-Acres) day old chicks were used in this study. Four levels of a Arjuna (Terminalia Arjuna) bark powder at the rate of 0.00%, 0.50%, 0.75%, and 1% were incorporated into the basal diet for five weeks. Feeding period for all groups was lasted for 35 days. Relevant data was recorded throughout the experiment till the termination of experiment. Significant increase in hemoglobin concentration, and heterophils was observed in Treatment T4. Significant decreased in lymphocyte was observed in Treatment T4. It is concluded that schedule on the basis receiving infusion three days in a week is more potent than other schedule of research study.', '{"arp_id": "ARP_AYU009696", "portal_id": 9696, "medical_system": "AYURVEDA", "journal": "European Journal of Biomedical and Pharmaceutical Sciences", "volume": "3", "issue": "1", "pages": "402 - 404", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Arjuna"], "original_url": "http://www.ejbps.com/ejbps/abstract_id/823", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9696", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009696.pdf", "pdf_sha256": "5c3b3c3612ab06de344d0c707f4b65d817e0e94a4a9d0d248728a232d77e7af7", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIDIABETIC AND ANTIHYPERLIPIDEMIC EFFCETS OF THE ETHANOLIC EXTRACT OF ALOCASIA INDICA RHIZOMES IN HIGH FAT DIET/STREPTOZOTOCIN AND
STREPTOZOTOCIN/NICOTINAMIDE-INDUCED TYPE 2 DIABETIC RATS', '1. Talha Jawaid, 1. Saumya Argal, 2. Mehnaz Kamal.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: The investigate the antidiabetic and antihyperlipidemic effect of ethanolic extract of Alocasia indica (EEAI) rhizomes in high-fat diet/streptozotocin (HFD/STZ) and STZ/nicotinamide-induced Type 2 diabetic rats.Methods: Diabetes was induced in male Wistar rats by the administration of a HFD for 15 days/STZ (35 mg/kg b.w., i.p.) and STZ (60 mg/kg b.w., i.p.)/nicotinamide (110 mg/kg b.w., i.p.). EEAI (100 and 200 mg/kg b.w., p.o.) was administered to diabetic rats for 28 days in HFD/STZ-induced Type 2 diabetic rats and for 15 days in STZ/nicotinamide-induced Type 2 diabetic rats. The effect of EEAI on blood glucose and body weight was studied in Type 2 diabetic rats. All these effects were compared with glibenclamide (5 mg/kg b.w., p.o.) as a reference antidiabetic drug.Results: The administration of the EEAI (100 and 200 mg/kg b.w., p.o.) resulted in a significant decrease in blood glucose level and significant increase in body weight in the HFD/STZ and STZ/nicotinamide-induced Type 2 diabetic rats. Further EEAI showed antihyperlipidemic activity as evidenced by significant decrease in serum total cholesterol, triglycerides, low-density lipoprotein cholesterol (LDL-C), very LDL-C levels coupled together with elevation of high-density lipoprotein cholesterol level in diabetic rats in the HFD/STZ and STZ/nicotinamide-induced Type 2 diabetic rats.Conclusion: The results suggest that the EEAI rhizomes possess a promising effect on the HFD/STZ and STZ/nicotinamide-induced Type 2 diabetes.', '{"arp_id": "ARP_AYU010300", "portal_id": 10300, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "8", "issue": "6", "pages": "58 - 62", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alocasia Indica"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/7084", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10300", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010300.pdf", "pdf_sha256": "3168ad4815b0b960b4e72cfc94ac2644f64a1f53d51c97f69c29d625d5c8faa9", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-HYPERLIPIDEMIC ACTIVITY OF METHANOLIC EXTRACT OF SYZYGIUM ALTERNIFOLIUM BARK AGAINST HIGH-FAT DIET AND DEXAMETHASONE-INDUCED HYPERLIPIDEMIA IN RATS.', 'Suvarchala Reddy NVL, Swetha Aveti, Anjum M, Ganga Raju M.', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: The present study is an attempt to investigate its anti-hyperlipidemic activity of methanolic extract of Syzygium alternifolium (MESA) using high-fat diet (HFDs) and dexamethasone-induced hyperlipidemia.Methods: MESA bark was evaluated for anti-hyperlipidemic activity in HFD and dexamethasone-induced hyperlipidemic rats. A comparison was also made between the action of S. alternifolium bark extract and a known anti-hyperlipidemic drug atorvastatin (10 mg/kg body weight). The results of the study were expressed as mean &amp;#177; standard error, and data were analyzed using one-way analysis of variance test followed by Dunnett’s t-test for multiple comparisons. Values of p&amp;lt;0.05 were considered as significant.Results: Oral administration of 100, 200 mg/kg body weight of the MESA bark exhibited a significant reduction (p&amp;lt;0.01) in serum lipid parameters such as total cholesterol, triglycerides, low-density lipoprotein (LDL), very LDL, and increase in high-density lipoprotein in hyperlipidemic rats of both models as compared to hyperlipidemic control statistically. These extracts were found to possess better anti-hyperlipidemic potential.Conclusion: Our results demonstrated that MESA bark possessed significant anti-hyperlipidemic activity and hence it could be a potential herbal medicine as an adjuvant with existing therapy for the treatment of hyperlipidemia.', '{"arp_id": "ARP_AYU010310", "portal_id": 10310, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "8", "issue": "6", "pages": "165 - 168", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["High-Fat Diet"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/8107", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10310", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010310.pdf", "pdf_sha256": "c9ebe92fe542c08c4676fd599f025c4eef4a8ab602893affd40decb9f1f962a4", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ROLE OF GUDADI MODAK IN THE MANAGEMENT OF AMLAPITTA W.S.R TO DIET AND LIFESTYLE.', '1. Rinky Thakur, 2. Naresh Sharma, 3. Gopal C. Nanda.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: In present scenario with hasty and agonizing mental stress in competitive life and incompatible diet, people are suffering from many lifestyle diseases. Amlapitta is one of them. It has adverse effect on the digestion and metabolism, with presence of symptoms like Avipaka, Klama, Utklesha, Amlodgara, Gauravta, Hrit Kantha Daha and Aruchi. Ayurveda is a holistic science which provides solutions with the help of natural resources as a principle of management. Different Ayurvedic literatures were scrutinized for description of Aahar (Diet) - Vihar (lifestyle) and drug Gudadi modaka has been taken from Chakradutta Amlapitta chikitsa for the management of Amlapitta. The 30 patient were selected for the study between the age group of 20-70 years from the OPD of Rajiv Gandhi Government Post Graduate Ayurvedic College and Hospital, Paprola, H.P. Patients were selected on the basis of specially prepared assessment criteria. Patients of both groups showed good improvement in the symptoms of Amlapitta. Patients of group II (Gudadi modak + Aahar -Vihara) showed slightly more significant results. Gudadi modak &amp;amp; proper dietary routine discipline has important role to achieve early and better result. To follow the code of Pathya &amp;amp; Apatyha and drug intake is the basic management of this disease. It is devoid of any side effect.', '{"arp_id": "ARP_AYU010967", "portal_id": 10967, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda and Pharma Research", "volume": "5", "issue": "3", "pages": "14 - 19", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "PEPTIC ULCER OTHER(ICPC-D86|ICD-K25, K27, K28)", "keywords": ["Ahara-Vihara"], "original_url": "http://ijapr.in/index.php/ijapr/article/view/614", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10967", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010967.pdf", "pdf_sha256": "f3627935ac8208a88814e3b66fe08d53545609ee76869ba42f1ee396236cd321", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'BIOSYNTHESIS, CHARACTERIZATION AND EVALUATION OF SILVER NANOPARTICLES OF ALTERNANTHERA SESSILIS (LINN.) AND ITS ETHANOLIC EXTRACT IN HIGH FAT DIET INDUCED DEMENTIA MODEL.', '1. Jahanara Hameed, 2. Sibi P. Ittiavirah.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Nanoparticles biosynthesis employing plants can potentially reduce the toxicity problems. These nanoparticles can be prepared by different physical, chemical and biological approaches. The biological approach is an emerging approach for preparation as this is eco friendly and easier than the other methods. The synthesis of silver nanoparticles was done by Alternanthera sessilis (Linn.) ethanolic extract and silver nitrate. The nootropic action of ethanolic extract of Alternanthera sessilis (Linn.) (EAS) and Alternanthera sessilis (Linn.) silver nanoparticles (ASNPs) were evaluated using High Fat diet (DHF) Model. By administration of DHF, dementia was induced. The effect of EAS (200 mg/kg) and ASNPs (20mg/kg) were assessed by determining plasma corticosterone level. Behavioural parameters like inflexion ratio, reference memory and working memory, were analysed using elevated plus maze and radial arm maze. The administration of DHF created cognitive dysfunctions like RME and WME. EAS and ASNPs have shown protective effect against model of DHF induced dementia. Significant nootropic activity was created by EAS. It resulted in a significant (p &amp;lt; 0.001) decrease in RME and WME with significant increase in inflexion ratio as compared to the DHF group. An increase in the learning memory with a reduction in the corticosterone level indicated nootropic activity. It was concluded that Alternanthera sessilis (Linn.) may be used as a phytomedicine for dementia.', '{"arp_id": "ARP_AYU011190", "portal_id": 11190, "medical_system": "AYURVEDA", "journal": "International Journal of Pharmaceutical Sciences Review and Research", "volume": "42", "issue": "2", "pages": "160 - 165", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alternanthera Sessilis (Linn) Silver Nanoparticles (Asnps)"], "original_url": "http://globalresearchonline.net/journalcontents/v42-2/30.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=11190", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU011190.pdf", "pdf_sha256": "39d4d4a5ec0f4a00788b480c1aeadbbcbbca1f6a7c09e8d96235e86ec86457a0", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2007/201', 'ANTI-OBESE ACTIVITY OF ZIZIPHUS JUJUBA LAM LEAVES EXTRACT IN DIETARY OBESE RATS.', '1. Ganachari MS, 2. Shiv Kumar, 3. Alagawadi KR.', 2007,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: To evaluate the effect of Ziziphus jujuba leaves extract in cafeteria diet and atherogenic diet induced obesity. Methods: Obesity was induced in albino rats by feeding cafeteria diet/atherogenic diet daily for 40 days in addition to normal diet ad libitum. Body weight was measured on day 1 and then on alternate days for 40 days. Daily food intake for group of 6 rats was assessed. Serum glucose and lipid levels and internal organs and fat pad weight analysis was carried out on day 41. Results: The Z. jujuba leaves extract treatment caused significant reduction in body weight, daily food intake, serum glucose and lipid levels, internal organs and fat pad weights in cafeteria and atherogenic diet fed rats when compared with control group of rats. Conclusion: The results of the present study conclude that alcoholic extract of Z. jujuba leaves showed anti-obese property by decreasing the body weight, food intake, serum glucose and lipid levels and internal organs and fat pad weights in dietary obese rats. The effect produced was comparable with that produced by standard anti-obese drug, Sibutramine.', '{"arp_id": "ARP_AYU015353", "portal_id": 15353, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "7", "issue": "1", "pages": "102 - 108", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Obese"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/201", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15353", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015353.pdf", "pdf_sha256": "465a23b0564442c57cd6ade3a5e68daabdb077eb7e33b10d07343263a6d6a573", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'BAUHINIA VARIEGATA L. LEAF EXTRACT AMELIORATES OXIDATIVE STRESS, RENAL APOPTOTIC DAMAGE AND DIETARY-INDUCED OBESITY IN WISTAR ALBINO MALE RATS.', '1. Azza M. El-Wakf, 1. Hanaa M. Serag, 2. Rehab Elmougy 3. Awat Omar.', 2019,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Association between obesity and chronic kidney disease has received great attention in the recent years. This study aimed to characterize the efficiency of the Camel&#39;s foot tree, Bauhinia variegata L. ethanolic leaves extract (BEX) against kidney damage in high fat diet (HFD) fed male rats, as a model of obesity. Rats were randomly divided into five groups, the first three served as control, vehicle and BEX (40 mg/100 g body wt.), while the other two groups were fed HFD with and without BEX at the same mentioned dose, daily for 12 weeks. Results showed significantly increased weight gain, absolute and relative kidney weights, serum and kidney lipids, accompanied by elevated levels of urea and creatinine in serum of HFD-fed rats. Results also revealed marked reduction of kidney nitric oxide, alkaline phosphatase and gamma glutamyl transferase, with elevation in their activities in serum of the obese rats. An increase in the oxidative stress markers; malondialdehyde and hydrogen peroxide, paralleled by reduction of total antioxidant capacity, glutathione, glucose-6-phosphatase dehydrogenase and the antioxidant enzymes; superoxide dismutase, catalase and glutathione peroxidase were also detected. This goes with decline of the anti-apoptotic Bcl2 and elevation in the pro-apoptotic Bax and caspase-3, followed by increased apoptosis% and cell cycle arrest with decline in cells at S and G2/GM phases. Meanwhile, a significant reduction in RBCs count, Hb content and related indices was demonstrated. In contrast, administration of BEX to HFD-fed rats significantly ameliorated increased weight gain, oxidative stress, apoptosis, cell cycle arrest and hematological changes, thereby restored kidney functional parameters near the normal values, suggesting BEX as a promising natural therapy for managing obesity and associated kidney disease.', '{"arp_id": "ARP_AYU016480", "portal_id": 16480, "medical_system": "AYURVEDA", "journal": "Indian Journal of Experimental Biology", "volume": "57", "issue": "7", "pages": "478 - 485", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anaemia"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/48481", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16480", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016480.pdf", "pdf_sha256": "36da75297d0c7f1a957c635ad398c491ae96aad713455e7f9223b84b644ab4c1", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HIGH SUCROSE DIET INDUCED DIABETES IN WNIN/GR-OB OBESE RATS: BIOCHEMICAL AND HISTOLOGICAL CHANGES.', '1. Aruna Potukuchi, 4. Uma Addepally, 2. Chiranjeevi Potu, 1. Malathi Upaasta, 2. Surekha Mullapudi, 3. Suresh Pothani,1. Raghunath Manchala.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Acceleration of natural ageing occurs due to multiple reasons such as stress, obesity and Type 2 diabetes working in a vicious cycle. In the present study, we tested if superimposing type 2 diabetes in a rat model of obesity accelerates ageing or not. We aggravated insulin resistance/ induced type 2 diabetes by feeding high sucrose diet (HSD) to 9-10 wk old, male, WNIN/Gr-Ob obese rats. We report here the changes in physiological, biochemical and histological parameters after 3 and 6 months of feeding. Rats fed HSD had the highest insulin resistance as evident from increased HOMA IR and AUC insulin during OGTT. Body weight gain and Food efficiency ratio (FER) were also significantly higher in HSD fed than the control rats after 6 months of feeding. Further, liver steatosis and kidney damage were the highest in the HSD fed rats as evident from ORO staining. Interestingly, HSD fed rats also had the highest intensity of &amp;#223;-cell staining and functioning (as indicated by higher HOMA-&amp;#223;). The findings indicate that parameters associated with ageing were accelerated in WNIN/Gr-Ob rats fed HSD, implying that aggravating insulin resistance in obese rats may be associated with accelerated ageing.', '{"arp_id": "ARP_AYU016604", "portal_id": 16604, "medical_system": "AYURVEDA", "journal": "Indian Journal of Experimental Biology", "volume": "56", "issue": "3", "pages": "149 - 157", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Accelerated Ageing"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/43667", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16604", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016604.pdf", "pdf_sha256": "3a8079ebccb7f7831f8cce7e44f816594362c1806130397ef3555144cda17339", "relevance_score": 43.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF ABHYANGA ON LIPID PROFILE  AN OPEN CLINICAL TRIAL ON HEALTHY INDIVIDUALS.', '1. Kamath M, 2. Malagi KJ, 3. Adiga SH.', 2015,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Abhyanga has been considered as an important part of the external Snehana. It produces relaxation of soft tissues and relives the pain. Abhyanga causes relaxation to mind, useful in the treatment in Aches, Hypertension, helpful in Bipolar disorders, and pain management. The main aim of the study is to assess the role of Abhyanga on Lipid profile of healthy individuals. Tila taila obtained from the seeds of Sesamum indicum Linn. was used for abhyanga. Fifteen healthy volunteers were selected irrespective of Religion, age and sex. The Routine Hematological, Biochemical tests were done before and after 7 days course of abhyanga in seven positions. The results showed clinically insignificant reductions in Lipid profile. In this study an attempt was made to observe the efficacy of abhyanga on lipid profile of healthy individuals. But the result showed abhyanga is not at all having a significant intervention in the lipid profile. Findings indicate that Abhyanga is not having an active intervention in Lipid profile. As the sample size is very small, further studies are required to find the exact action of Abhyanga on the healthy individual’s lipid profile', '{"arp_id": "ARP_AYU002288", "portal_id": 2288, "medical_system": "AYURVEDA", "journal": "Ayurpharm  International Journal of Ayurveda and Allied Sciences", "volume": "4", "issue": "5", "pages": "117 - 121", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "LIPID DISORDER(ICPC-T93|ICD-E78)", "keywords": ["Abhyanga"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2288", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002288.pdf", "pdf_sha256": "32edfc3b9229195442ce98cf443ff18dec72f3ab16b64296ac237068011e9769", "relevance_score": 43.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'VARANADIGANA KASHAYA IN THE MANAGEMENT OF STHAULYA (OBESITY) A CLINICAL TRIAL.', '1. Vishnu Mohan PM, 2. Shripathi Acharya.', 2017,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: “Sthaulya” (obesity) is such a disease, which leads to so many complications like Hypertension, Diabetes Mellitus, Osteo-arthritis, infertility, impotency as well as psychological disturbances like stress, anxiety, depression etc. Thus, the mortality and morbidity rate was high in obese person compared to others. This shows the importance of the disease and the need for further researches and adoption of effective measures in the management of the same. Effective treatment measures are needed for the successful management of Sthaulya. Hence in the present study a clinical trial was carried out with varanadigana kashaya in the management of sthaulya (obesity) and found intake of Varanadiganakashaya for 30 days gave good result in relieving the symptoms of Sthaulya', '{"arp_id": "ARP_AYU002316", "portal_id": 2316, "medical_system": "AYURVEDA", "journal": "Ayurpharm  International Journal of Ayurveda and Allied Sciences", "volume": "6", "issue": "7", "pages": "149 - 156", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "OBESITY(ICPC-T82|ICD-E66)", "keywords": ["Ayurveda"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2316", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002316.pdf", "pdf_sha256": "1e899ff314a3cc9a271c8b24cefd0c5f07204f80c185edf0df9ae1de6fe7d593", "relevance_score": 43.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'SAPTHASARAM KASHAYAM AND KOTTAM CHUKKADI TAILA IN THE MANAGEMENT OF KATIGRAHA (LUMBAR SPONDYLOSIS) A CLINICAL TRIAL.', '1. Pooja Sharada Jagadeesh Shanbough, 2. Shripathi Acharya, 3. Naveen K', 2018,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Low back pain (LBP) affects approximately 60–85% of adults during some point in their lives. The lifestyle changes in diet and habits of individuals have made Katigraha a very common disease now- a- days. In most of the cases, people are not able to manage the disease with modern medicines and also by quitting their diet and habits or changing their lifestyle. So, keeping these points in view, here an attempt has been made with Sapthasaram kashayam (internal) and Kottam chukkadi taila (external application) mentioned in Sahasrayoga. 20 Subjects diagnosed as Katigraha and who fulfil the inclusion criteria was randomly selected. Sapthasaram kashayam was given in two divided doses of 50ml each; morning and evening 1 hour before food and Kottam chukkadi taila applied at Kati region twice daily for 30 days. Results showed that there was relief in pain (27.3%), stiffness (39.9%), tenderness (44.7) and difficulty in walking (23.8), Schober’s test (20%), VAS (24.3%) and Oswestry test (17.2%) which was statistically significant. (P = &amp;lt;0.001). To conclude, the patients had shown improvement in most of the assessment criteria of Katigraha. According to this study Sapthasaram kashaya and kottam chukkadi taila can be opted for all the Katigraha i.e. lumbar spondylosis', '{"arp_id": "ARP_AYU002366", "portal_id": 2366, "medical_system": "AYURVEDA", "journal": "Ayurpharm  International Journal of Ayurveda and Allied Sciences", "volume": "7", "issue": "6", "pages": "92 - 100", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "SPONDYLOSIS (ICPC-L83|ICD-M47.2)", "keywords": ["Katigraha"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2366", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002366.pdf", "pdf_sha256": "b3c37dc219273987232899f4ae8229d0d577ed9d80238e85dba2e063b3afa541", "relevance_score": 43.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v7i3.853', 'AN OPEN LABEL RETROSPECTIVE, CONTROLLED STUDY TO EVALUATE EFFICACY OF SINHYADI GHRITA IN THE MANAGEMENT OF BALSOSHA WITH SPECIAL REFERENCE TO UNDERNUTRITION.', '1. Rajkumar Harinkhede, 2. Chavan DB, 3. Gawai VU, 4. Minakshi Patle.', 2016,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Balshosha which can be correlated with undernutrition (P.E.M.) is one of such disease occurring in children due to hampered nutrition or dhatuposhana. Nutrition is necessary for maintaining growth, the effect of nutrition reflects on development. Today nutrition deficiency constitutes a major public health problem in India. The goal of treatment is to be provided adequate calories for dual purpose, to replace losses and build up nutrition to promote growth. HPERM is indicated for home remedial treatment for mild to moderate PEM (Undernutrition / Malnutrition) however condition needs to be medically intervented to prevent the worsening of the situation and to provide adequate correction. Sinhyadi Ghrita mentioned in Ashtanghridya by Vagbhata is best in balshosha. Hence an attempt was made to study the effect of sinhyadi ghrita in the management of Balshosha (undernutrition).In present study two groups containing 30 patients each suffering from undernutrition were selected randomly irrespective to sex, gestational age. Sinhyadi ghrita and HPERM combination was used as a trial group. Parameters such as weight, height, MUAC, skin elasticity, BMI, dehabla, agnibala were taken in to consideration for assessing results. At the end of study it was found that trial drug was very effective in the management of undernutrition.', '{"arp_id": "ARP_AYU009938", "portal_id": 9938, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "7", "issue": "3", "pages": "181 - 191", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "VITAMIN/NUTRITIONAL DEFICIENCY(ICPC-T91|ICD-E40, E41, E42, E43, E44, E45, E46, E50, E51.1, E51.8, E51.9, E52, E53, E54, E55, E56, E58, E59, E60, E61, E63, E64)", "keywords": ["Agnibala"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/07332016", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9938", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009938.pdf", "pdf_sha256": "87b5f7417a7bc029d2096f56cc83e110dcaf98c8dfdc49516bdfeab999f84ee4", "relevance_score": 42.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/fra.2016.1.5', 'COOKING EFFECT ON ANTI-OXIDATIVE AND ALPHA-AMYLASE INHIBITORY POTENTIAL OF AQUEOUS EXTRACT OF LAGENARIA SICERARIA FRUIT AND ITS NUTRITIONAL PROPERTIES.', 'Dildar Ahmed, Norina Ejaz, Raha Saeed, Parsa Dar.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: To evaluate effect of boiling for different durations on total phenolic content, total flavonoid content, antioxidant activity and alpha-amylase inhibitory activity of water extract of Lagenaria siceraria fruit, and to compare nutritional properties of its epicarp, mesocarp, seedsa pulp and pedicle. Methods: The bioactivities of aqueous extract of fruit was evaluated after boiling for 10, 20, and 30 min. Moisture, ash, fiber, protein, carbohydrate and lipid contents and vitamin C of epicarp, mesocarp, seeds pulp and pedicle were determined using standard methods. Mineral elements (Fe, Cr, Cu, Ag, Mn, Zn, Ni, Co and Pb) were estimated by atomic absorption spectrophotometer. Results: DPPH (1,1-diphenyl- 2-picrylhydrazyl) antioxidant and alpha-amylase inhibitory activities, and phenolic content drastically decreases with increase in duration of boiling. Flavonoid content and antioxidant capacity in phosphomolybdate assay exhibited a slight increase. Epicarp had higher percentage of protein, carbohydrate and vitamin C than other parts of the fruit, while pedicle had the highest content of fiber, zinc, silver and chromium. Epicarp had the highest content of Copper. Iron was in the range of 3.4-5.13, cobalt 0.14-0.31 and lead 0.5-1.8 mg/100 g. Amount of zinc in pedicle was highest among all the trace elements (6.5%) in all parts. Conclusion: The study revealed that boiling duration affects antioxidant and alpha-amylase inhibitory activities of the fruit of L. siceraria. Peel and pedicle of the fruit should not be discarded as they are rich in nutritional properties.', '{"arp_id": "ARP_AYU010369", "portal_id": 10369, "medical_system": "AYURVEDA", "journal": "Free Radicals and Antioxidants", "volume": "6", "issue": "1", "pages": "44 - 50", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Diabetic"], "original_url": "https://www.antiox.org/index.php/fra/article/view/57", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10369", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010369.pdf", "pdf_sha256": "b5b7edc462092464aa57f8651e8123a9e9d8a9f7bd26dc1fe31dbec58ed0575b", "relevance_score": 42.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/pm.pm_494_18', 'NUTRITIONAL VALUE AND NEPHROTOXICITY EFFECT OF DILLENIA PENTAGYNA FRUIT ON ALLOXAN-INDUCED DIABETIC RATS.', '1. Ranjeet Kumar Yadav, 2. Arpit Azad, 1. Srivastava SK, 3. Sharma B, 2. Mahesh Pal.', 2019,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Dillenia pentagyna Roxb. (Dilleniaceae) is an endangered medicinal plant, commonly known as “agai” and distributed randomly in the Terai belt of North East states of India. D. Pentagyna extract has been studied for therapeutic possessions. Objective: The proximate parameters and high-performance thin layer chromatography (HPTLC) analysis in the same plant of D. pentagyna of four-time harvest stage during the maturation of fruits were studied and also the antihypoglycemic activity of hydroalcoholic extract of D. pentagyna fruit. Materials and Methods: The proximate compositions were determined by measuring the amount of water removed from the food AOAC method and the chemical fingerprinting was carried out by HPTLC method. An acute oral toxicity study was carried out in healthy male Wister rats (110 g). The dose was finally made to 200 and 400 mg/kg body weight for oral administration after the LD50 estimation. Results: The most phenolic concentration was continuously decrease with during the maturation of fruits. After 21 days of treatment, level of blood glucose, as well as albumin, protein, creatinine, urea, and uric acid were significantly decreased when compared with the diabetic control. Hydroalcoholic (80% alcohol to 20% DW) extracts will be subjected to further extensive studies to isolate and identify their active constituents which are useful for against antidiabetic. Conclusion: D. pentagyna fruit could act as a source of functional compounds for the control of diabetes mellitus.', '{"arp_id": "ARP_AYU012725", "portal_id": 12725, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Magazine", "volume": "15", "issue": "62", "pages": "118 - 122", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetic Nephropathy"], "original_url": "https://phcog.com/article/view/2019/15/62/118-122", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=12725", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU012725.pdf", "pdf_sha256": "36d3bab953082b87a217049452b2f9321bbe4a63eb1de95993f4a693ac32f5a8", "relevance_score": 42.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.56042/ijnpr.v10i1.19795', 'NUTRITIONAL COMPOSITION AND ANTIOXIDATIVE STRESS PROPERTIES IN BOILED TUBEROUS RHIZOME OF NEEL KAMAL (NYMPHAEA NOUCHALI BURM. F.)', '1,2. Ajay Anand,1. Ukkujuri Priyanka,1. Vadithe Lakshma Nayak,1. Amtul Zehra,1. Katragadda Suresh Babu,1,2. Ashok Kumar Tiwari.', 2019,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Nymphaea nouchali (Burm. f.) is known as Neel Kamal, Utpal, Kumud and Indeevar in India. Its tuberous rhizome is used for the preparation of various vegetable items, curries and pickles, and is also consumed boiled or roasted. It finds application in folk medicine for the treatment of a number of disease conditions. In this research macro- and micronutrients profiling along with phytochemical analysis of the boiled tuberous rhizome of N.nouchali was carried out. Furthermore, antioxidant activities and antioxidative stress potentials of aqueous methanol extract of boiled tuber were also evaluated. Boiled tuber presents a rich source of carbohydrate, protein, fat, fibres, essential amino acids and fatty acids. Simultaneously, vitamins and minerals were also present in ample amounts. The aqueous methanol extract of boiled tuber contains potent antioxidant phytochemicals. In vitro analysis on HEK-293, CHO and NIH 3T3 cell lines reveal that it effectively quashes H2O2 induced oxidative stress and protects DNA against free radical-induced damage. This research demonstrates that N. nouchali tuber can become an economical dietary adjunct and functional food full of macro- and micronutrient that can help fight against oxidative stress originating due to modern lifestyle induced metabolic disorders. This is the first report presenting nutritional composition and antioxidative stress properties in the boiled tuber of N. nouchali.', '{"arp_id": "ARP_AYU013269", "portal_id": 13269, "medical_system": "AYURVEDA", "journal": "Indian Journal of Natural Products and Resources", "volume": "10", "issue": "1", "pages": "59 - 67", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/50425", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=13269", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU013269.pdf", "pdf_sha256": "54d38ced96b457b3208393b9d1cd8517d8da63afa7d232756b250aba47eb8f32", "relevance_score": 42.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '17017752', NULL, 'RANDOMIZED TRIAL OF A WHOLE- SYSTEM AYURVEDIC PROTOCOL FOR TYPE 2 DIABETES', 'Elder C, Aickin M, Bauer V, Cairns J, Vuckovic N.', 2006,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: CONTEXT: Though complementary and alternative medicine (CAM) treatments are popular, evidence to support their application to diabetes care is scarce. Previous CAM diabetes research has generally focused on single modalities, but CAM practitioners more commonly prescribe complex, multimodality interventions.OBJECTIVES: The aims of this study were to determine the feasibility and clinical impact of a whole-system, Ayurvedic intervention for newly diagnosed people with type 2 diabetes.DESIGN: Patients were randomly assigned to either an experimental or control arm.SETTING: Group model health maintenance organization.PARTICIPANTS: We recruited 60 adult patients with baseline glycosylated hemoglobin (HbA1c) values between 6.0 and 8.0.INTERVENTION: Treatment for the experimental group included exercise, an Ayurvedic diet, meditation instruction, and an Ayurvedic herb supplement (MA 471). Control patients attended standard diabetes education classes with primary care clinician follow-up.MEASUREMENTS: Clinical outcomes were assessed at 3 and 6 months and included HbA1c, fasting glucose, lipids, blood pressure, and weight.RESULTS: Ninety-two percent of randomized patients completed the study, and there were no significant adverse study-related events. Using analysis of co-variance (ANCOVA), we found no significant differences for clinical outcomes at 6 months between on-study patient groups, though trends favored the Ayurvedic group. When we included a factor measuring how much baseline HbA1c exceeded the mean (6.5%), however, we found statistically significant improvements in the Ayurvedic group for HbA1c (P = .006), fasting glucose (P = .001), total cholesterol (P = .05), low-density lipoprotein (LDL) cholesterol (P = .04), and weight (P = .035).CONCLUSIONS: These results suggest that the Ayurvedic intervention may benefit patients with higher baseline HbA1c values, warranting further research.', '{"arp_id": "ARP_AYU002603", "portal_id": 2603, "medical_system": "AYURVEDA", "journal": "Alternative Therapies in Health and Medicine", "volume": "12", "issue": "5", "pages": "24 - 30", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Cam"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2603", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002603.pdf", "pdf_sha256": "b21767cd153f1bf8acd695519c942cdb3def7230ef5439cf37c21d01eb98e34d", "relevance_score": 42.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11976562', NULL, 'EFFECTS OF YOUNG BARLEY LEAF EXTRACT AND ANTIOXIDATIVE VITAMINS ON LDL OXIDATION AND FREE RADICAL SCAVENGING ACTIVITIES IN TYPE 2 DIABETES', 'Yu YM, Chang WC, Chang CT, Hsieh CL, Tsai CE.', 2002,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: BACKGROUND: The effects of supplementation of young barley leaf extract (BL) and/or antioxidative vitamins C and E on different low-density lipoprotein (LDL) subfractions susceptibility to oxidation and free radical scavenging activities in patients with type 2 diabetes were evaluated.METHODS: Thirty-six type 2 diabetic patients were enrolled in this study. The subjects received one of the following supplements daily for 4 weeks: 15 g BL, 200 mg vitamin C and 200 mg vitamin E (CE), or BL plus CE (BL + CE).RESULTS: The lucigenin-chemiluminescence (CL) and luminol-CL levels in blood were significantly reduced in all groups. Vitamin E content of LDL subfractions increased significantly following supplements, especially for BL + CE group. The percent increase of lag times in the BL + CE was significantly higher than those in the BL or CE group. The antioxidative effect of BL + CE was the greatest for small, dense LDL (Sd-LDL) with further increases in percentage of lag times 4 folds compared to BL alone.CONCLUSION: Our results indicate that supplementation with BL may help to scavenge oxygen free radicals, save the LDL-vitamin E content, and inhibit LDL oxidation. Furthermore, the addition of vitamins C and E to BL can inhibit the Sd-LDL oxidation more effectively, which may protect against vascular diseases in type 2 diabetic patients.', '{"arp_id": "ARP_AYU002606", "portal_id": 2606, "medical_system": "AYURVEDA", "journal": "Diabetes and Metabolism", "volume": "28", "issue": "2", "pages": "107 - 114", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Barley Leaf Extract"], "original_url": "http://www.em-consulte.com/article/80089", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2606", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002606.pdf", "pdf_sha256": "6a06f05cc7f3d3a2119a956ddc96b24dd02bb88d813889a1dbff8a2d584c1712", "relevance_score": 42.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '17105712', NULL, 'CLINICAL INVESTIGATION OF HYPOGLYCEMIC EFFECT OF SEEDS OF AZADIRACHTA-INIDCA IN TYPE-2 (NIDDM) DIABETES MELLITUS', 'Waheed A, Miana GA, Ahmad SI.', 2006,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The present study was designed to investigate clinically the hypoglycemic effect of seeds of Azadirachta indica in Type-2 diabetes mellitus. After assaying fasting plasma and urinary glucose, 10 patients of type-2 diabetes mellitus with no previous medication, 10 patients of type-2 diabetes mellitus taking oral hypoglycemic agents with history of inadequate control and six control subjects were given low (0.5 g t.i.d.) and high (2 g t.i.d.) doses of powdered part, aqueous extract and alcoholic extract of Azadirachta indica for 14 days. On 15th day blood and urine samples for glucose were taken. Based on results obtained it was found that Azadirachta indica has significant hypoglycemic activity in high dose and can be successfully combined with oral hypoglycemic agents in type-2 diabetic patients whose diabetes is not controlled by these agents.', '{"arp_id": "ARP_AYU002615", "portal_id": 2615, "medical_system": "AYURVEDA", "journal": "Pakistan Journal of Pharmaceutical Sciences", "volume": "19", "issue": "4", "pages": "322 - 325", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Azadirachta Indica"], "original_url": "http://www.ncbi.nlm.nih.gov/pubmed/17105712", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2615", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002615.pdf", "pdf_sha256": "3ba1ab3b62fb06170ef10979976842cd563596cb0455f064c7558cc8ab7fa0e3", "relevance_score": 42.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16320801', NULL, 'EFFECTS OF GARLIC ON DYSLIPIDEMIA IN PATIENTS WITH TYPE 2 DIABETES MELLITUS', 'Ashraf R, Aamir K, Shaikh AR, Ahmed T.', 2005,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: BACKGROUND: Garlic (Allium Sativum) has been used in herbal medicine for centuries for various ailments. In recent years garlic has been the focus of serious medical and clinical attention because of beneficial effects on several cardiovascular risk factors like reduction of serum lipids, blood pressure and plasma viscosity. There is also wide spread belief among general public that garlic has beneficial effects on cardiovascular system. The purpose of present study was to evaluate the effects of garlic on one of the major cardiovascular risk factors i.e. dyslipidemia in patients with type 2 diabetes mellitus.METHOD: This 12 week randomized, single-blind, placebo controlled study was conducted on Type 2 diabetic patients with newly diagnosed dyslipidemia (n=70). Patients were selected from Diabetic OPD of Jinnah Post Graduate Medical Centre, Karachi and were divided into two groups each comprising of 35 patients, they were given tablet garlic (Garlex-Bosch Pharmaceuticals) 300 mg (containing 1.3 % allicin) twice daily and identical placebo tablets respectively. Both groups were given diet and exercise plan.RESULTS: After 12 weeks the garlic treated group (n = 33) had a significant reduction in total cholesterol (-28 mg/dl, - 12.03 % P= &amp;lt;0.001), LDL - C (-30 mg/dl, - 17.99 % P=&amp;lt;0.001) while the placebo treated group ( n=32) had a non significant decrease in total cholesterol (- 2 mg/dl, - 0.9 % p= ns) and LDL-C (-3 mg/dl, -1.6 % p=ns). HDL cholesterol was significantly increased in patients treated with garlic (3.35 mg/dl, 8.81% P= &amp;lt;0.05) compared with placebo group (0.62, 1.6% P= n.s) but there was no significant difference in triglyceride was observed between two groups.CONCLUSION: This study suggests possible small short term benefits of garlic on dyslipidemia in type 2 diabetic patients. Garlic significantly reduced serum total cholesterol and LDL cholesterol and moderately raised HDL cholesterol as compared to placebo. Controlled Clinical Trials of longer duration are needed to assess the long term benefit of garlic on vascular and circulatory disease processes.', '{"arp_id": "ARP_AYU002616", "portal_id": 2616, "medical_system": "AYURVEDA", "journal": "Journal of Ayub Medical College Abbottabad", "volume": "7", "issue": "3", "pages": "60 - 64", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "LIPID DISORDER(ICPC-T93|ICD-E78)", "keywords": ["Dyslipidemia"], "original_url": "https://pubmed.ncbi.nlm.nih.gov/16320801/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2616", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002616.pdf", "pdf_sha256": "a3341a69900c972c9462a0588b47dbbfb75dd3ac1629f434b0d897374cdc9bd0", "relevance_score": 42.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/ijper.50.1.21', 'MODULATORY ROLE OF SELENIUM NANOPARTICLES AND GRAPE SEED EXTRACT MIXTURE ON OXIDATIVE STRESS BIOMARKERS IN DIABETIC IRRADIATED RATS.', '1. Rasha Mohamed Ahmed Abdelaleem, 1. Hanan Fahmyabdelhameed, 2. Mervat El-SayedAskar, 1. Seham Hassan Mohamed Hassan,1. Ahmed Ibrahim Elbatal.', 2016,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Introduction: Diabetes is a metabolic disorder of several etiologies, many oral anti-hyperglycemic agents such as sulfonylurea, biguanides are obtainable, but these agents have side effects, thus there is need of a new natural anti-hyperglycemic agent. Methods: The present study was performed to evaluate the protective role of selenium nanoparticles-grape seed extract (SeNPs-GSE) mixture in ameliorating the changes in the oxidative stress biomarkers induced by gamma radiation in diabetic rats. Experimental model of diabetic irradiated rats was induced by single intrapertoneal injection of streptozotocin (STZ 45 mg/kg) followed by ?-radiation exposure (4 Gy). Forty eight rats were randomly classified into 6 experimental groups: normal, diabetic, irradiated, diabetic irradiated, diabetic treated with either SeNPs-GSE mixture or glimepiride(1 mg) for (14) days followed by ?-radiation. Results: Results of the present study indicated that rats exposed to ?-radiation and, or STZ significantly increase serum glucose&amp;amp; liver MDA levels. This increase was accompanied by a decrease in the levels of serum insulin, total antioxidant (TAC), liver enzyme activities of catalase (CAT), glutathione peroxidase (GPx), superoxide dismutase (SOD), as well as liver tissue contents of vitamin C (Vit.C) and vitamin E (Vit.E). Diabetic rats treated with (SeNPs–GSE) mixture or glimepiride before ?-radiation exert a significant improvement in all tested biochemical parameters. Conclusion: The present study showed that a mixture of (SeNPs -GSE) possesses antioxidant and anti-diabetic activities by decreasing oxidative stress biomarkers as well as blood glucose level tested in this study. The tested combination (SeNPs–GSE) mixture is more or less equally active as that of the standard tested anti-diabetic drug glimepiride.', '{"arp_id": "ARP_AYU010672", "portal_id": 10672, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmaceutical Education and Research", "volume": "50", "issue": "1", "pages": "170 - 178", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetes Mellitus"], "original_url": "https://www.ijper.org/article/388", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10672", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010672.pdf", "pdf_sha256": "0c4a43262084266197cabf4cc9103cab93fade3a500d8952ec96591161fc8755", "relevance_score": 42.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.20959/wjpps20197-14099', 'THE ROLE OF AVIPATTIKAR CHURNA IN STOMACH SPECIFIC BIOMARKERS OF URDHWAG AMLAPITTA', '1. Madhavi P. Mahajan, 2. Sharda M. Hene', 2019,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Amlapitta is a common disorder caused by vidagdha pitta such asaruchi (anorexia) tikta amlodgara (sour or bitter belching), hrud kanthadaha (burning sensation in heart and throat), avipaka (indigestion) dueto acid peptic digestion affecting more people in India. and prevalenceis more. The sudy material comprised of 10 Urdhwag Amlapittapatients from OPD of Department of Kayachikitsa, Bharati VidyapeethUniversity’s College Of Ayurveda,Pune. Patients were treated withAvipattikar Churna for 30 days and arbitrary scoring pattern wasadapted for the assessment of Amlapitta. The results showed thatAvipattikar Churna is more effective drug in Urdhwag Amlapittawithout any Adverse Drug Reaction and no any study available onbiomarkers level. The result of the present study revealed the concept of Ayurvedic principaland practice of Urdhwag Amlapitta in Ayurveda with the help of biomarkers.', '{"arp_id": "ARP_AYU013979", "portal_id": 13979, "medical_system": "AYURVEDA", "journal": "World Journal of Pharmacy and Pharmaceutical Sciences", "volume": "8", "issue": "7", "pages": "760 - 766", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "FLATULENCE/GAS/BELCHING (ICPC-D08| ICD-R14)", "keywords": ["Avipattikar Churna"], "original_url": "https://www.wjpps.com/Wjpps_controller/abstract_id/10831", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=13979", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU013979.pdf", "pdf_sha256": "b3075d70c039a1a27fd422d609a828c008e09ea248509300644aebc4bce3db30", "relevance_score": 42.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.7897/2277-4343.094140', 'EFFECT OF OODHAL BLOWING IN IYYA MANTHAM INDIGESTION A CASE STUDY', '--', 2018,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: In Siddha system indigestion can be correlated with Iyya Mantham. In Iyya mantham due to aggravation of Kapha humour, ingested food does not get digested, remains in the stomach for long time causing abdominal distension, abdominal pain, dyspnoea, excessive salivation, polydipsia and restlessness. Indigested food remains in the stomach without being vomited or belched. Oodha (Blowing) is one of the treatment procedures which is comes under the 32 External therapies of Siddha system. Generally, Oodhal (Blowing) can be done in Ear, Nose and Eyes. In Siddha literature Oodhal (Blowing) is usually mentioned for Varma treatments. But this paper deals with the Traditional Oodhal (Blowing) procedure practiced in Theni district for Indigestion. Though there are many Shastric Medicines mentioned for Indigestion, Oodhal (Blowing) is a cost effective, different in approach and simple remedy that can be used in Clinical practices. It also gives immediate relief to the patient. This is a single case study which showed significant result in Indigestion. It can also be performed as a pre-treatment procedure while initiating other External therapies for various illnesses. So, it has to be extended further as a Clinical trial to create scientific evidence.', '{"arp_id": "ARP_SID004791", "portal_id": 87724, "medical_system": "SIDDHA", "journal": "International Journal of Research in Ayurveda and Pharmacy", "volume": "9", "issue": "4", "pages": "182 - 184", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "DIGESTIVE", "disease": "DYSPEPSIA/INDIGESTION (ICPC-D07| ICD-K30)", "keywords": [], "original_url": "https://ijrap.net/admin/php/uploads/2128_pdf.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=87724", "pdf_status": "downloaded", "pdf_filename": "ARP_SID004791.pdf", "pdf_sha256": "1796aac3458db84cc149adfcf94c2065cf56382f9f94fb1e2a06067b1b80de62", "relevance_score": 42.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16646998', NULL, 'EFFICACY OF HOMEOPATHIC TREATMENT AGAINST NATURAL INFECTION OF SHEEP BY GASTROINTESTINAL NEMATODES.', '1. Raquel A da Rocha, 2. Rodrigo Dias L Pacheco, 3. Alessandro F T Amarante', 2006,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The efficacy of the homeopathic treatment with the Fator Vermes, administered according to the manufacturer&#39;s recommendations, was evaluated against gastrointestinal nematodes infections in sheep. The experiment was divided into two phases: in the first phase (January/06/2004 to April/30/2004), the animals of the treated (n=10) and control (n=10) groups were treated individually with conventional anthelmintics to avoid deaths. In the second phase (April/30/2004 to July/06/2004), the sheep from the group that received the Fator Vermes were treated as they had been in the previous phase, while the control group animals were treated with conventional anthelmintics at 14 day intervals. In the first phase of the experiment, there was no significant difference (P&gt;0.05) between group means regarding egg counts in feces (EPG), weight gain, or packed cell volume (PCV). Meanwhile, in the second phase, the control group sheep had a significantly higher weight gain, higher PCV values, and lower EPG counts. Infective larvae of Haemonchus spp., Trichostrongylus spp., Cooperia spp., and Oesophagostomum spp. were identified in the fecal cultures. After six months of daily treatment with the Fator Vermes, it was not possible to substantiate the product&#39;s benefits in both sheep health and productivity or in the prophylaxis of gastrointestinal nematode infections.

Access: Access-1', '{"arp_id": "ARP_HOM001539", "portal_id": 42350, "medical_system": "HOMOEOPATHY", "journal": "doi:", "volume": "15", "issue": "1", "pages": "23 - 27", "category": "PRECLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "WORMS/OTHER PARASITES(ICPC-D96|ICD-B65, B66, B67, B68, B69, B70, B71, B72, B73, B74, B75, B76, B77, B78, B79, B80, B81, B82, B83)", "keywords": ["gastrointestinal nematodes", "anthelmintics"], "original_url": "https://www.redalyc.org/pdf/3978/397841457005.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=42350", "pdf_status": "downloaded", "pdf_filename": "ARP_HOM001539.pdf", "pdf_sha256": "c8de7cace588aade9baa48be5debba955f9794e991fce6fb424f19d8979f441c", "relevance_score": 42.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '14696681', NULL, 'USE OF ACUPRESSURE TO IMPROVE GASTROINTESTINAL MOTILITY IN WOMEN AFTER TRANS-ABDOMINAL HYSTERECTOMY', '--', 2003,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: The purpose of this study was to evaluate the effectiveness of acupressure on gastrointestinal (GI) motility in women after trans-abdominal hysterectomy (TAH). Patients were randomly assigned into two groups of 21 and 20 patients each. The experimental group received acupressure for 3 minutes at each of three meridian points: Neiguan (PC-6), Zusanli (ST-36) and Sanyinjiao (SP-6). The control group received 3 minutes of acupressure on sham points. Acupressure was performed twice a day. A questionnaire was used to determine patients&#39; satisfaction prior to and after afternoon acupressure. GI contractions were measured with a multifunctional stethoscope before and after acupressure. Acupressure of these three meridian points significantly (p &amp;lt; 0.05) increased GI motility in the experimental group, but there was little change in the control group (p &amp;gt; 0.05). Our conclusions are that non-invasive acupressure of these meridian points can significantly improve GI motility and can be incorporated into the technical curriculum and clinical education program of nursing schools. Patients and their family members can be taught to continue this procedure at home to enhance GI motility in patients who have undergone TAH.', '{"arp_id": "ARP_Y&N000378", "portal_id": 43809, "medical_system": "YOGA & NATUROPATHY", "journal": "doi:", "volume": "31", "issue": "5", "pages": "781 - 90", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "DIGESTIVE", "disease": "DISEASE DIGESTIVE SYSTEM OTHER(ICPC-D99|ICD-K31, K38, K52.1, K52.2, K52.8, K52.9, K55, K56.0, K56.1, K56.2, K56.3, K56.5, K56.6, K56.7, K59.2, K59.3, K59.8, K59.9, K62.2, K62.3, K62.4, K62.6, K62.7, K62.8, K62.9, K63, K65, K66, K67, K85, K86, K87.1, K90, K91.1, K91.2, K91.5, K91.8, K91.9, K92.2, K9)", "keywords": [], "original_url": "https://www.worldscientific.com/doi/10.1142/S0192415X03001466?rfr_dat=cr_pub++0pubmed&amp;rfr_id=ori%3Arid%3Acrossref.org&amp;url_ver=Z39.88-2003", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=43809", "pdf_status": "downloaded", "pdf_filename": "ARP_Y&N000378.pdf", "pdf_sha256": "1b3ee84eb0f950ed40a7e2b59a62423b518999e9985f13be2e48d955fc6dcd36", "relevance_score": 42.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.7897/2277-4343.09360', 'THE EFFECT OF PARIKARA GUTIKA IN NON-ALCOHOLIC FATTY LIVER DISEASE: A CASE STUDY.', '1. Nisha MG, 2. L Mahadevan, 3. Lekshmi R, 2. Arun Pratap, 4. Miharjan K.', 2018,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Non-Alcoholic Fatty Liver Disease (NAFLD) is a broad term which describes the buildup of excessive fat in the liver cells in the absence of excessive alcohol intake. In recent years the number of chronic liver diseases, including Non-Alcoholic Fatty Liver Disease (NAFLD) has recorded steady growth, according to the World Health Organization. NAFLD is an added risk factor for extra hepatic diseases such as CVD, Chronic kidney disease, Colorectal Cancer, Endocrine disorders (including Type 2 DM and Thyroid dysfunction) and Osteoporosis. Ayurveda also vividly describes Liver Diseases in the context of Kamala (Jaundice) and Yakrut Roga (Liver diseases) in different classical texts. It can be interpreted as a Santharpanotha Vikara (disease which caused by taking excessive nourishing diet) with Kaphamedo Dushti, getting Sthanasamsraya in Yakrut (Liver) which is Rakthavahasrothomoola and Pittasthana (location of body humour Pitta). A 45-year-old male patient, with complaints of fatigue for 2 months came with an USG report which showed elevated liver echogenicity (Grade 2 fatty liver). On investigation, slight increase of SGPT was noted. Patient was advised to take 4 tablets (500mg each) Parikara Gutika thrice daily after food with hot water as Anupana for a period of 2 months. Parikara Gutika is a formulation mentioned in Chakradattam, Yakrut Pliha Adhikara, having Kapha Medohara, Rakta Prasadana, Deepana (appetizer) and Pachana (digestive) properties. At the end of study, the echogenicity of liver was reduced to Grade 1. The drug Parikara Gutika was effective in reducing the echogenicity and size of liver.', '{"arp_id": "ARP_AYU012584", "portal_id": 12584, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Ayurveda and Pharmacy", "volume": "9", "issue": "3", "pages": "44 - 46", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "NON ALCOHOLIC FATTY LIVER DISEASE (ICD-K76.0)", "keywords": ["Nafld"], "original_url": "https://ijrap.net/index.php/login/abstractt?id=2047", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=12584", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU012584.pdf", "pdf_sha256": "2b779c4af29ba6a35f5c194dc5490afbc072353e303ff1a40abb8f5fbd746d36", "relevance_score": 42.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.13040/IJPSR.0975-8232.14(5).2442-46', 'EFFECTIVENESS OF SIDDHA MEDICINE FOR THE MANAGEMENT OF ERYTHEMA DYSCHROMICUM PERSTANS (KARUNGUTTAM) ''- A CASE REPORT', '--', 2019,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: A 30 years male patient from Chennai has presented with asymptomatic, grey-blue hyperpigmented patches of variable shape and size and an elevated erythematous border; the eruption has been symmetrically distributed on the face, the trunk, and the upper extremities for 4 years. This condition was diagnosed as “erythema dyschromicum perstans” which resembles to karunguttam one of the skin diseases in siddha system of medicine. He was treated with siddha medicines as Meganathakulikai for purgation to rearrange three humours (vatham, pitham &amp;amp; kabham), internal medicines (Rasaganthi mezhugu Capsules (RGM), Amukkarachooranam tablet, Seenthilsarkarai chooranam, Keelanelli chooranam tablets) &amp;amp; external medicine (Aruganthylam) @ Sirappu Maruthuvam OPD No3, Ayothidass Pandithar Hospital, National Institute of Siddha, Chennai-47 for 48 days. There were no adverse reactions or events observed during the course of treatment. The skin lesion of EDP reduced spontaneously in the treatment period, which is compared by before &amp;amp; after photocopies. This is the first case report in siddha for management of EDP larger study needs to confirm these findings.', '{"arp_id": "ARP_SID005272", "portal_id": 88205, "medical_system": "SIDDHA", "journal": "International Journal of Pharmaceutical Sciences and Research", "volume": "14", "issue": "5", "pages": "2442 - 2446", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "SKIN DISEASE OTHER(ICPC-S99|ICD-L10, L11, L12, L13, L14, L26, L28, L30.2, L30.5, L41, L43, L44, L45, L51, L52, L53.0, L53.1, L53.2, L53.3, L53.8, L54, L60.2, L60.3, L60.8, L68, L71, L72.0, L72.2, L72.8, L72.9, L73.0, L73.1, L73.8, L73.9, L80, L81.1, L81.4, L81.5, L81.6, L81.7, L81.8, L81.9, L82, L8)", "keywords": [], "original_url": "https://ijpsr.com/bft-article/effectiveness-of-siddha-medicine-for-the-management-of-erythema-dyschromicum-perstans-karunguttam-a-case-report/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=88205", "pdf_status": "downloaded", "pdf_filename": "ARP_SID005272.pdf", "pdf_sha256": "0b4728e75cfe562c9ce0d3e0057306e79c3673da23eff30cbff53e75b39147aa", "relevance_score": 42.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '20027866', NULL, 'PROTECTIVE ROLE OF CASSIA AURICULATA LEAF EXTRACT ON HYPERGLYCEMIA-INDUCED OXIDATIVE STRESS AND ITS SAFETY EVALUATION.', '1. Shipra Gupta, 1. Suman Bala Sharma, 1. Krishna Madhava Prabhu, 2. Surena Kumar Bansal.', 2009,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Cassia auriculata L. (Caesalpiniaceae) is widely used from the ancient period to treat diabetes mellitus. In the present study, the antioxidant activity of C. auriculata aqueous leaf extract (CLEt) was evaluated in streptozotocin-induced mild diabetic (MD) and severe diabetic (SD) rats. A short-term toxicity assessment was also conducted in healthy rats to examine toxic effects of the extract. Oral administration of CLEt to MD and SD rats (100, 200 and 400 mg/kg body weight per day for a period of 21 days) produced significant fall in fasting blood glucose (FBG) in a dose-dependent manner. Treatment with the extract (400 mg/kg) showed significant reduction in serum levels of thiobarbituric acid reactive substances (TBARS) and oxidized low-density lipoprotein (OxLDL) in both MD and SD rats. The antioxidant defense system was also found to be improved in CLEt-treated (400 mg/kg) MD and SD rats, as revealed by significant increase in activities of erythrocyte’s antioxidant enzymes i.e. superoxide dismutase (SOD) and catalase (CAT) with a concomitant elevation in erythrocyte’s reduced glutathione (GSH) content. Moreover, there were no toxic signs in rats treated with high doses of the extract (1000 and 2000 mg/kg body weight per day for 21 days). Blood glucose, hepatic and renal function parameters in these rats were found within normal limits. Phytochemical screening of CLEt revealed the presence of alkaloids, flavonoids, saponins, tannins and cardiac glycosides with antihyperglycemic and antioxidant properties. This study suggests that CLEt possesses potent antioxidant activity along with antihyperglycemic potential, hence protective against diabetic complications.', '{"arp_id": "ARP_AYU016130", "portal_id": 16130, "medical_system": "AYURVEDA", "journal": "Indian Journal of Biochemistry and Biophysics", "volume": "46", "issue": "5", "pages": "371 - 377", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant Activity"], "original_url": "http://nopr.niscpr.res.in/handle/123456789/6294", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=16130", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU016130.pdf", "pdf_sha256": "281497f08c809ea9c559c0d641d6fcdd6e0243e0d482b01de318a9160ebe8d39", "relevance_score": 42.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5005/jp-journals-10059-0024', 'EVALUATION OF HYPOLIPIDEMIC ACTIVITY OF CARDIOSPERMUM HALICACABUM L. LEAF IN ATHERODIET-INDUCED WISTAR ALBINO RATS.', '1. Natarajan Thamizhselvam, 2. Kandiyoor R. Surabhi, 3. Yalwar R. Sanjayakumar, 4. Kannanamkulam K. G. Vasanthakumar,5. Sudesh N. Gaidhani, 6. Paravazhi Radhakrishnan.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aim: Hyperlipidemia has been ranked as one of the greatest risk factors contributing to prevalence and severity of coro- nary heart diseases. The present study has been taken up to evaluate hypolipidemic activity of hydro alcoholic extract of Cardiospermum halicacabum L. leaf, as this plant is widely used by the local healers of South India for treatment of various illnesses.Materials and methods: The experiment was carried out in atherodiet-induced hyperlipidemia in Wistar Albino rats. The experiment duration was 28 days and it comprised six groups, such as healthy control, extract control, disease control, treat- ment group low dose, treatment group high dose, and standard drug (SD). The biochemical investigations including lipid profile with Atherogenic Index and Coronary Risk Index, and other metabolic parameters were evaluated using standard protocols. Histopathology studies for vital organs of animals were also carried out.Results: The study showed that the hydroalcoholic extract of C. halicacabum L. leaf has significant hypolipidemic activity in the atherodiet-induced hyperlipidemia in Wistar rats when compared with the disease control group. The histopathology study also evidenced the safety of the extract.Conclusion: The study concluded that the hydroalcoholic extract of C. halicacabum L. has significant hypolipidemic activity at the prescribed dosages.', '{"arp_id": "ARP_AYU004463", "portal_id": 4463, "medical_system": "AYURVEDA", "journal": "Journal of Drug Research in Ayurvedic Sciences", "volume": "2", "issue": "4", "pages": "281 - 288", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Atherodiet"], "original_url": "https://www.jaypeedigital.com/abstractArticleContentBrowse/JDRAS/52/2/4/6563/abstractArticle/Article", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4463", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004463.pdf", "pdf_sha256": "743b91c0bd9b3e06646bc3b4d7547d61b2df15c9083323e34d52f826f8449e7f", "relevance_score": 42.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16101317', NULL, 'DIETARY CARDAMOM INHIBITS THE FORMATION OF AZOXYMETHANEINDUCED ABERRANT CRYPT FOCI IN MICE AND REDUCES COX-2 AND INOS EXPRESSION IN THE COLON', 'Archana Sengupta, Samit Ghosh, Shamee Bhattacharjee.', 2005,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Recently, considerable attention has been focused on identifying naturally occurring chemopreventive compounds capable of inhibiting, retarding, or reversing the multi-step carcinogenesis. The primary aim of the present study was to identify the effects of a commonly consumed spice, viz., cardamom against azoxymethane (AOM) induced colonic aberrant crypt foci (ACF) in Swiss Albino mice. The secondary aim, was to explore the ability of cardamom to modulate the status of proliferation and apoptosis, and to understand its role in altering cyclooxygenase-2 (COX- 2) and inducible nitric oxide synthase (iNOS) expression. Male Swiss albino mice were injected with AOM (dose: 5mg/Kg body weight) or saline (Group 1) weekly once for two weeks. The AOM-injected mice were randomly assigned to two groups (Groups 2 and 3). While all the groups were on standard lab chow, Group 3 received oral doses of 0.5% cardamom, in aqueous suspension, daily for 8 weeks. Following treatment, significant reduction in the incidences of aberrant crypt foci (p&amp;lt;0.05) was observed. This reduction in ACF was accompanied by suppression of cell proliferation (mean Brdu LI in carcinogen control=13.91+3.31, and 0.5%cardamom=2.723+0.830) and induction of apoptosis (mean AI in carcinogen control=1.547+0.42 and 0.5% cardamom= 6.61+0.55). Moreover, reduction of both COX-2 and iNOS expression was also observed. These results suggest that aqueous suspensions of cardamom have protective effects on experimentally induced colon carcinogenesis. Cardamom as a whole and its active components require further attention if the use of this spice is to be recommended for cancer prevention.', '{"arp_id": "ARP_AYU006123", "portal_id": 6123, "medical_system": "AYURVEDA", "journal": "Asian Pacific Journal of Cancer Prevention", "volume": "6", "issue": "2", "pages": "118 - 122", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aberrant Crypt Foci"], "original_url": "https://journal.waocp.org/article_24326.html", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6123", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006123.pdf", "pdf_sha256": "9ad46ff9f9dae77f8b3049524f43937e4497b139a5113d49670b3a59a06b8825", "relevance_score": 42.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4314/tjpr.v14i7.13', 'EFFECT OF CARTHAMUS TINCTORIUS L EXTRACT ON DIETHYLNITROSAMINE-INDUCED LIVER CIRRHOSIS IN RATS', 'Zhi-wei Hu, Wei-xing Wang', 2015,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Purpose: To explore the effects of Carthamus tinctorius L. extract (CTLE) on diethylnitrosamine (DEN)-induced liver cirrhosis in rats.Methods: CTLE was obtained by extracting the dried Carthamus tinctorius L. in water. Liver cirrhosis was induced by injecting the rats with DEN once a week for 8 weeks. Following this treatment, clinical biochemical assessments, as well as oxidative stress test and histopathological examination were performed.Results: Compared with the control group, plasma concentrations of alanine transaminase (ALT) and aspartate aminotransferase (AST) both decreased significantly (p &amp;lt; 0.01) after 8 weeks. The degree of liver fibrosis, cirrhosis and necrosis decreased in CTLE-treated rats. CTLE significantly inhibited malondialdehyde (MDA) and superoxide dismutases (SOD) in DEN-induced rat liver (p &amp;lt; 0.01) compared with control group.Conclusion: CTLE has significant inhibitory effect on diethylnitrosamine-induced liver cirrhosis in rats, which can be developed for future clinical applications.', '{"arp_id": "ARP_AYU009431", "portal_id": 9431, "medical_system": "AYURVEDA", "journal": "Tropical Journal of Pharmaceutical Research", "volume": "14", "issue": "7", "pages": "1213 - 1216", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Oxidant"], "original_url": "https://www.tjpr.org/home/abstract.php?id=184&amp;aTitle=Effect%20of%20Carthamus%20tinctorius%20L%20extract%20on%20diethylnitrosamine-induced%20liver%20cirrhosis%20in%20rats", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9431", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009431.pdf", "pdf_sha256": "69daec28aedd97da9c614beae1e786eed87de5b95140e1a700a7ad3bf5f8b9c5", "relevance_score": 42.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.5530/ijper.52.4.71', 'ANTINEOPLASTIC APPROACH OF SEMECARPUS ANACARDIUM LEAVES AGAINST N-NITROSO DIETHYLAMINE INITIATED HEPATOCELLULAR CARCINOMA.', '1. Sabita Upreti, 1. Rajena SV, 2. Kuntal Das, 3. Arjan Aryal.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: To evaluate the effect of MESA on NDEA induced hepatocellular carcinoma on Sprague Dawley rats. Methodology: Semecarpus anacardium commonly known as ‘marking nut tree’ is a rich antioxidant and in Ayurveda it has been used for treatment of various forms of cancer. Methanolic extract of leaves of Semecarpus anacardium (MESA) was studied for its potential antioxidant property both in vitro and in vivo. NDEA 200 mg/kg, single i.p was the hepatocarcinogen while 200 mg/kg and 400 mg/kg of MESA was administered daily orally for 12 weeks. Protective effect of MESA was evaluated by measuring biochemical parameters like SGOT, SGPT, ALP and LDH. Alpha fetoprotein test was performed and histopathology changes of livers were assessed.Results: Preliminary phytochemical study revealed the presence of flavonoids, tannins, steroids, alkaloids, glycosides and vitamin C. MESA restored the level of antioxidants near to normal and reduced the elevated serum level of SGOT, SGPT, AST, LDH and AFP. The histopathology changes i.e. necrosis, widened sinusoids, elevated inflammatory cell infiltrate were partly or fully prevented in animals treated with the extract. Conclusion: The result of the present study indicates MESA to be rich in antioxidants and its active constituents mediated the free radical scavenging activity. 400 mg/kg extract showed promising effect in management of primary liver cancer.', '{"arp_id": "ARP_AYU012646", "portal_id": 12646, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmaceutical Education and Research", "volume": "52", "issue": "4", "pages": "610 - 617", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alpha Fetoprotein"], "original_url": "https://www.ijper.org/article/851", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=12646", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU012646.pdf", "pdf_sha256": "4c78ef5a53da65871a14522d0e85b0eef1c20cb3770e1cda5313145ba5be1b11", "relevance_score": 42.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '18813412', NULL, 'INVESTIGATION OF THE EFFECT OF GINGER ON THE LIPID LEVELS - A DOUBLE BLIND CONTROLLED CLINICAL TRIAL', 'Alizadeh-Navaei R, Roozbeh F, Saravi M, Pouramir M, Jalali F, Moghadamnia AA.', 2008,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: OBJECTIVE: To study the effect of fine powder of ginger on lipid level in volunteer patients.METHODS: This is a double blind controlled clinical trial study in 2 cardiac clinics Cardiac Disease Clinic, Babol, north of Iran, between April to May 2004. We randomly divided the patients with hyperlipidemia into 2 groups, treatment group (receiving ginger capsules 3 g/day in 3 divided doses) and placebo group (lactose capsule 3 g/day in 3 divided doses) for 45 days. All subjects with diabetes mellitus, hypothyroidism, nephrotic syndrome, and alcohol drinking, pregnancy and peptic ulcer were excluded. Lipid concentrations profile before and after treatment was measured by enzymatic assay.RESULTS: Forty-five patients in the treatment group and 40 patients in placebo group participated in this study. There was a significant reduce in triglyceride, cholesterol, low density lipoprotein (LDL), very low density lipoprotein (VLDL), levels of before and after study separately in each group (p&amp;lt;0.05). Mean changes in triglyceride and cholesterol levels of ginger group were significantly higher than placebo group (p&amp;lt;0.05). Mean reduction in LDL level and increase in high density lipoprotein level of ginger group were higher than the placebo group, but in VLDL level of placebo was higher than ginger (p&amp;gt;0.05).CONCLUSION: The results show that ginger has a significant lipid lowering effect compared to placebo.', '{"arp_id": "ARP_AYU004978", "portal_id": 4978, "medical_system": "AYURVEDA", "journal": "Saudi Medical Journal", "volume": "39", "issue": "9", "pages": "1280 - 1284", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "LIPID DISORDER(ICPC-T93|ICD-E78)", "keywords": ["Ginger"], "original_url": "https://smj.org.sa/content/29/9/1280", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4978", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004978.pdf", "pdf_sha256": "af0af77e440e6db651ba14c77847db0c5c231f19e6cc6a838ea295c66e5b14ce", "relevance_score": 42.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22557029', NULL, 'CLINICAL TRIAL OF AN INDGENOUS COMPOUND DRUG NISHAAMALKI IN THE MANAGEMENT OF MADHUMEHA VIS-A-VIS DIABETES MELLITUS', '1. Yadav RK, 2. Mishra R, 3. Chhipa RP, 4. Audichya KC.', 2001,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: A Clinical trial of Indigenous compound drug ‘Nishamalaki’ was carried out inthe CRI (Ayurveda) Hospital, Jaipur on the patient of Madhumeha. For this study, patients wererandomly divided into two groups of 25 individuals each and they were termed as group A andB. The individuals of group a were administered Nishamalaki in a dose of one gram twice dailyalong with diet control, the patients were followed every fort nightly. A significant improvementin the symptoms along with lowering of blood glucose level was observed in the individuals ofgroup B, while the individuals of group A responded initially but could not sustain the same.', '{"arp_id": "ARP_AYU018517", "portal_id": 18517, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "21", "issue": "1", "pages": "18 - 24", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes Mellitus"], "original_url": "https://journals.lww.com/asol/abstract/2001/21010/clinical_trial_of_an_indgenous_compound_drug.5.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18517", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018517.pdf", "pdf_sha256": "235eb348dc68074c10e44fa5d9fd38fab6b892d7c96d4a8bd2d6255acf3828f9", "relevance_score": 42.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22557087', NULL, 'CLINICAL TRIAL OF PHALAGHRITA ON FEMALE INFERTILITY', '1.Otta SP, 2.Tripaty RN.', 2002,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The present study was carried out in a sample of 30 numbers of female infertility cases with the use of phalagritam in the from of intra uterine insuffulation. After the treatment of three consecutive cycles an overall encouraging result was observed which will be represented in the full paper.', '{"arp_id": "ARP_AYU018571", "portal_id": 18571, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "22", "issue": "2", "pages": "56 - 63", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "FEMALE GENITAL SYSTEM INCLUDING BREAST", "disease": "FEMALE INFERTILITY/SUBFERTILITY (ICPC-W15|ICD-N97.0, N97.1, N97.2, N97.3, N97.4, N97.8, N97.9)", "keywords": ["Female Infertility"], "original_url": "https://journals.lww.com/asol/abstract/2002/22020/clinical_trial_of_phalaghrita_on_female.9.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18571", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018571.pdf", "pdf_sha256": "a6ea06df6aa054d8be15da64777f3f1614a3dcfd087a54f39a9dac50f75a1d8e", "relevance_score": 42.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'GUM GUGGULU (COMMIPHORA MUKUL) FRACTION ''A'' IN OBESITY-A DOUBLE-BLIND CLINICAL TRIAL', '1. Kotiyal JP, 2. Singh DS, 3. Bisht DB.', 1985,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: A double blind clinical trial of eighty four gum guggulu (Commiphora mukul) Fraction &#39;A&#39; was conducted on obese subjects. Analysis of the finding revealed that the fraction &#39;A&#39; of Guggulu is a potent hypolipidemic agent which reduces serum cholesterol, total lipids and triglycerides, significantly. Not much effect was seen on body weight and skin folds except for triceps skin fold which was reduced significantly.', '{"arp_id": "ARP_AYU020860", "portal_id": 20860, "medical_system": "AYURVEDA", "journal": "Journal of Research in Ayurveda and Siddha", "volume": "6", "issue": "1,3&4", "pages": "20 - 35", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "OBESITY(ICPC-T82|ICD-E66)", "keywords": ["Commiphora Mukul"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20860", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020860.pdf", "pdf_sha256": "2459cbbd435da1adb274dfd50160bbc4807aa93c309ae8aa1cb559e856324b54", "relevance_score": 42.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'THE ROLE OF INDIGENOUS RECIPE IN MANAGEMENT OF MALNUTRITION IN CHILDREN (PRE SCHOOL)', '1. Sumeeta S. Jain, 2. Jagmohan B. Rathi.', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Malnutrition is the state of not having enough food or enough right food. Extensive diet surveys carried out in our country over last several years have shown that the diets of good proportion of our population are inadequate, according to accepted standards with qualitative and quantitative deficiencies.The project was planned to develop an integrated approach to reduce prevalence of malnutrition in children by administrating a perfect combination of rejuvenating herbs and food material, which will prove best alternative in future, the need of national health program.Significant increase in Quitlet’s Index, Appetite and Haemoglobin shows that Indigenous Recipe is effective in Malnutrition. Herbs present in recipe like Ashwagandha, Shatavari etc. possess Rasayan properties. Rasayanas are dravyas-having properties of Rejuvenation of body (Sapta dhatu). They provide strength and are tonic for body. Along with Rasayan properties these dravyas are from Balya and Brumhaniya categories according to charak. They are agnideepak. It will be a best type of Vatatapik Rasayan, falling under Swasthahitkar, Annaswaroop and Aushadhi Rasayan category.It is Jeevaniya, Tarpaniya and Brimhaniya as it was supported by increase in Haemoglobin status, which is Rasa-Rakta according to Ayurvedic principles.', '{"arp_id": "ARP_AYU000054", "portal_id": 54, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "4", "issue": "2", "pages": "49 - 55", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "VITAMIN/NUTRITIONAL DEFICIENCY(ICPC-T91|ICD-E40, E41, E42, E43, E44, E45, E46, E50, E51.1, E51.8, E51.9, E52, E53, E54, E55, E56, E58, E59, E60, E61, E63, E64)", "keywords": ["Atikrish"], "original_url": "https://journals.lww.com/joay/citation/2010/04020/joa_iv_april_june.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=54", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000054.pdf", "pdf_sha256": "8ce97967b4b18a843a1d579fbb301df760477a39d161f9a67861087674b537f8", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '19839001', '10.1024/0300-9831.79.1.34', 'EFFECT OF FENUGREEK SEEDS ON BLOOD GLUCOSE AND LIPID PROFILES IN TYPE 2 DIABETIC PATIENTS', '1. Nazila Kassaian, 2. Leila Azadbakht, 3. Baolmolook Forghani, 3. Masud Amini.', 2009,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: BACKGROUND:Recently use of herbal medicines, have been considered as an alternative for therapeutic usage. So, this study was undertaken to evaluate the hypoglycemic and hypolipidemic effects of fenugreek seeds in type 2 diabetic patients.METHODS:In a clinical trial study, 24 type 2 diabetic patients were placed on 10 grams/day powdered fenugreek seeds mixed with yoghurt or soaked in hot water for 8 weeks. Weight, FBS, HbA(1)C, total cholesterol, LDL, HDL and food record were measured before and after the study. The differences observed in food records, BMI and serum variables were analyzed using paired-t-test and t-student and P&amp;lt;or=0.05 was considered as significant.RESULTS:After exclusion of 6 cases for changing in medication or personal problems, the results of 18 patients (11 consumed fenugreek in hot water and 7 in yoghurt) were studied. Findings showed that FBS, TG and VLDL-C decreased significantly (25 %, 30 % and 30.6 % respectively) after taking fenugreek seed soaked in hot water whereas there were no significantly changes in lab parameters in cases consumed it mixed with yoghurt. BMI, Energy, Carbohydrate, Protein and fat intake remained unchanged during study.CONCLUSION:This study shows that fenugreek seeds can be used as an adjuvant in the control of type 2 diabetes mellitus in the form of soaked in hot water.', '{"arp_id": "ARP_AYU001297", "portal_id": 1297, "medical_system": "AYURVEDA", "journal": "International Journal for Vitamin and Nutrition Research", "volume": "79", "issue": "1", "pages": "34 - 39", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Fenugreek"], "original_url": "https://econtent.hogrefe.com/doi/10.1024/0300-9831.79.1.34", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1297", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001297.pdf", "pdf_sha256": "9cdb6dd9716f68876c6c211aaa8090150d1d2437917cb20abf0ee2467b041f9c", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238804', '10.1093/jn/131.3.994S', 'STUDY OF GARLIC EXTRACTS AND FRACTIONS ON CHOLESTEROL PLASMA LEVELS AND VASCULAR REACTIVITY IN CHOLESTEROL-FED RATS.', 'Slowing K, Ganado P, Sanz M, Ruiz E, Tejerina T.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Garlic is known for its pharmacologic and nutritional properties. In previous studies, garlic elicited a reduction in plasma levels of lipids by inhibiting hepatic cholesterol synthesis. The aim of this study was to investigate in an in vivo model the effects of garlic extract and some fractions on cholesterol levels and vascular reactivity in cholesterol-fed rats. Rats were fed a cholesterol-enriched diet for 16 wk and were divided into 10 groups as follows: control and hypercholesterolemic diet groups, 4 groups fed frozen garlic fractions and 4 groups fed raw garlic fractions with different doses. Blood samples were obtained to analyze HDL and LDL cholesterol levels. After treatment, rats were killed. The heart, liver and kidneys were weighed; the aorta was isolated, mounted in organ chambers and vascular reactivity was tested. Plasma concentration of cholesterol was 58 mg/dL (100%) at the beginning of the study and increased to 102 mg/dL (153%; hypercholesterolemic group) at the end of the treatment. Plasma total cholesterol decreased in all groups treated with garlic; moreover, this effect was higher in rats fed raw garlic fractions and extracts. LDL decreased significantly with respect to the hypercholesterolemic group in all groups treated with garlic fractions and extracts (P: &amp;lt; 0.01); however, an increase in HDL was found in those treated with frozen fractions and extracts. The liver:body weight ratio decreased in all treated groups. The relaxing effect of acetylcholine (ACh) was enhanced in arteries contracted with noradrenaline (NE). These data suggest that garlic fractions could prevent diet-induced hypercholesterolemia and vascular alterations in the endothelium-dependent relaxation associated with atherosclerosis.', '{"arp_id": "ARP_AYU004901", "portal_id": 4901, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "994S - 999S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Allium Sativum Fractions"], "original_url": "http://jn.nutrition.org/content/131/3/994S.full.pdf+html", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4901", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004901.pdf", "pdf_sha256": "df8de4db38aa414ea08049817e1338b652660d99c1b9d3d018a0b832b8044c70", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16046716', '10.1093/jn/135.8.1911', 'GRAPE POLYPHENOLS EXERT A CARDIOPROTECTIVE EFFECT IN PRE- AND POSTMENOPAUSAL WOMEN BY LOWERING PLASMA LIPIDS AND REDUCING OXIDATIVE STRESS.', 'Tosca L. Zern, Richard J. Wood, Christine Greene, Kristy L. West, Yanzhu Liu,1. Dimple Aggarwal,1. Neil S. Shachter,1. Maria Luz Fernandez.', 2005,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: To evaluate the effects of grape polyphenols on plasma lipids, inflammatory cytokines, and oxidative stress, 24 pre- and 20 postmenopausal women were randomly assigned to consume 36 g of a lyophilized grape powder (LGP) or a placebo for 4 wk. The LGP consisted of 92% carbohydrate and was rich in flavans, anthocyanins, quercetin, myricetin, kaempferol, and resveratrol. After a 3-wk washout period, subjects were assigned to the alternate treatment for an additional 4 wk. The placebo consisted of an equal ratio of fructose and dextrose and was similar in appearance and energy content (554 kJ) to LGP. Plasma triglyceride concentrations were reduced by 15 and 6% in pre- and postmenopausal women, respectively (P &amp;lt; 0.01) after LGP supplementation. In addition, plasma LDL cholesterol and apolipoproteins B and E were lower due to LGP treatment (P &amp;lt; 0.05). Further, cholesterol ester transfer protein activity was decreased by approximately 15% with intake of LGP (P &amp;lt; 0.05). In contrast to these beneficial effects on plasma lipids, LDL oxidation was not modified by LGP treatment. However, whole-body oxidative stress as measured by urinary F(2)-isoprostanes was significantly reduced after LGP supplementation. LGP also decreased the levels of plasma tumor necrosis factor-alpha, which plays a major role in the inflammation process. Through alterations in lipoprotein metabolism, oxidative stress, and inflammatory markers, LGP intake beneficially affected key risk factors for coronary heart disease in both pre- and postmenopausal women.', '{"arp_id": "ARP_AYU004979", "portal_id": 4979, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "135", "issue": "8", "pages": "1911 - 1917", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "FEMALE GENITAL SYSTEM INCLUDING BREAST", "disease": "MENOPAUSAL AND OTHER PERIMENOPAUSAL DISORDERS", "keywords": ["Coronary Heart Disease"], "original_url": "http://jn.nutrition.org/content/135/8/1911.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4979", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004979.pdf", "pdf_sha256": "d018ee7f27a726b8bf1db8b19384a4b9718a3793199cad7aaea493e730b69741", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '12230234', '10.1046/j.1440-6047.2002.00292.x', 'ANTIOXIDANT EFFECT OF PHASEOLUS VULGARIS IN STREPTOZOTOCIN-INDUCED DIABETIC RATS', 'Subramanian Venkateswaran, Leelavinothan Pari.', 2002,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The antioxidant effect of an aqueous extract of Phaseolus vulgaris pods, an indigenous plant used in Ayurvedic medicine in India, was studied in rats with streptozotocin-induced diabetes. Oral administration of Phaseolus vulgaris pod extract (PPEt; 200 mg/kg body weight) for 45 days resulted in a significant reduction in thiobarbituric acid reactive substances and hydroperoxides. The extract also causes a significant increase in reduced glutathione, superoxide dismutase, catalase, glutathione peroxidase and glutathione-S-transferase in the liver and kidneys of rats with streptozotocin-induced diabetes. These results clearly show the antioxidant property of PPEt. The effect of PPEt at 200 mg/kg body weight was more effective than glibenclamide.', '{"arp_id": "ARP_AYU005144", "portal_id": 5144, "medical_system": "AYURVEDA", "journal": "Asian Pacific Journal of Clinical Nutrition", "volume": "11", "issue": "3", "pages": "206 - 209", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aqueous Extract"], "original_url": "https://onlinelibrary.wiley.com/doi/abs/10.1046/j.1440-6047.2002.00292.x", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=5144", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU005144.pdf", "pdf_sha256": "fe1d7c0dfef72fa9e5525235d8258e52153d049a3bc834430a1afad2b8647763", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484565', '10.1093/jn/136.3.793S', 'AGED GARLIC EXTRACT MAY BE SAFE FOR PATIENTS ON WARFARIN THERAPY1,3', 'Henry Macan, Rolando Uykimpang, Marcionila Alconcel, Junichiro Takasu, Rafael Razon, Harunobu Amagase,y, Yutaka Niihara.', 2006,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Garlic has been known to have antiplatelet properties. Because of the lack of major clinical data regarding the safety of concomitant use of garlic supplements and anticoagulants, we decided to evaluate the safety of using garlic extract along with oral anticoagulation therapy. During this project we tested aged garlic extract (AGE), a commercial garlic preparation, with warfarin (Coumadin). Sixty-six (66) patients were screened for a double-blind, randomized, placebo-controlled pilot study. Fifty-two (52) patients were randomized for the project. Forty-eight patients (30 men and 18 women, with a mean age of 56 &amp;#177; 10 years) completed the study. Eighteen patients (14 before randomization, 4 after randomization) were dropped from the study. The study medication (AGE or placebo) was administered at a dose of 5 mL twice a day for 12 wk. Potential bleeding and thromboembolic episodes were monitored. There was no evidence of increased hemorrhage in either the placebo or the AGE group. Adverse events included headache, fatigue, colds, and dizziness. However, no significant difference was found in the incidence of these minor adverse events between the groups. Thus, the adverse events are unlikely to be attributable to AGE. The results suggest that AGE is relatively safe and poses no serious hemorrhagic risk for closely monitored patients on warfarin oral anticoagulation therapy. Although the risk-benefit ratio of AGE use needs to be considered carefully when warfarin therapy is necessary, its positive effects may be beneficial to people with a high-risk background or who are taking cardiovascular medications.', '{"arp_id": "ARP_AYU007177", "portal_id": 7177, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "793S - 795S", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "CIRCULATORY", "disease": "ISCHAEMIC HEART DIS WITHOUT ANGINA(ICPC-K76|ICD-I24, I25)", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/136/3/793S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7177", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007177.pdf", "pdf_sha256": "c8959ecf40aadb4dc23afd9e34e6150c7cdbf2ff3e0f22e3e26a4e5674fbd2e2", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484572', '10.1093/jn/136.3.816S', 'AGED GARLIC EXTRACT PREVENTS A DECLINE OF NK CELL NUMBER AND ACTIVITY IN PATIENTS WITH ADVANCED CANCER1,2', '3. Hideki Ishikawa, Tomoko Saeki, Toru Otani, Takaichiro Suzuki, Kojiro Shimozuma, Hoyoku Nishino, Sanae Fukuda, Kanehisa Morimoto.', 2006,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Aged garlic extract (AGE) has manifold biological activities including immunomodulative and antioxidative effects. It is used as a major component of nonprescription tonics and cold-prevention medicines or dietary supplements. Advanced-cancer patients decline in immune functions and quality of life (QOL). The study’s subjects were patients with inoperable colorectal, liver, or pancreatic cancer. In a randomized double-blind trial, AGE was administered to one group and a placebo was administered to another for 6 mo. The primary endpoint was a QOL questionnaire based on the Functional Assessment of Cancer Therapy (FACT). The sub end points were changes in the natural-killer (NK) cell activity the salivary cortisol level from before and after administering AGE. Out of 55 patients invited to participate in the trial, 50 (91%) consented to enroll. They consisted of 42 patients with liver cancer (84%), 7 patients with pancreatic cancer (14%), and 1 patient with colon cancer (2%). Drug compliance was relatively good in both the AGE and placebo groups. Although no difference was observed in QOL, both the number of NK cells and the NK cell activity increased significantly in the AGE group. No adverse effect was observed in either group. The study showed that administering AGE to patients with advanced cancer of the digestive system improved NK cell activity, but caused no improvement in QOL.', '{"arp_id": "ARP_AYU007235", "portal_id": 7235, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "816S - 820S", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "GENERAL/UNSPECIFIED", "disease": "MALIGNANCY NOS(ICPC-A79|ICD-C38.1, C38.2, C38.3, C38.8, C45.7, C45.9, C46.7, C46.8, C46.9, C76, C78, C79, C80, C97, D09.7, D09.9)", "keywords": ["Advanced Cancer"], "original_url": "http://jn.nutrition.org/content/136/3/816S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7235", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007235.pdf", "pdf_sha256": "8c7c66e106231bd51897abcafb870ca4c38603888e0fb91c19bb87714d3e6789", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484575', '10.1093/jn/136.3.832S', 'DIALLYLSULFIDE AND ALLYLMETHYLSULFIDE ARE UNIQUELY EFFECTIVE AMONG ORGANOSULFUR COMPOUNDS IN INHIBITING CYP2E1 PROTEIN IN ANIMAL MODELS1-3', 'Michael J. Wargovich.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Garlic is a popular culinary herb that is also used throughout the world as a traditional medicine for the prevention and treatment of disease. Epidemiologic studies have suggested that long-term consumption of garlic reduces risk for certain cancers, most notably stomach and colon cancer. This article summarizes the key findings behind one important mechanism explaining the anticarcinogenic effects of garlic-derived agents in animal models: the inhibition of cytochrome p4502E1 (CYP2E1), with some commentary on other aspects of carcinogen metabolism modified by these unique phytochemicals.', '{"arp_id": "ARP_AYU007292", "portal_id": 7292, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "832S - 834S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Carcinogenesis"], "original_url": "http://jn.nutrition.org/content/136/3/832S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7292", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007292.pdf", "pdf_sha256": "17d8841cce47ee4beca03c824202104fdb1db08fae5f1f791b3e3eef5ad31f52", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238821', '10.1093/jn/131.3.1080S', 'PHARMACOLOGIC ACTIVITIES OF AGED GARLIC EXTRACT IN COMPARISON WITH OTHER GARLIC PREPARATIONS1', 'Kasuga S, Uda N, Kyo E, Ushijima M, Morihara N, Itakura Y.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: We investigated the pharmacologic activities of four garlic preparations, raw garlic juice (RGJ), heated garlic juice (HGJ), dehydrated garlic powder (DGP) and aged garlic extract (AGE). The study used three animal models, i.e., testicular hypogonadism (hypospermatogensis and impotence) induced by warm water treatment, intoxication of acetaldehyde and growth of inoculated tumor cells. RGJ was found to be effective only in recovery of testicular function. The efficacy of HGJ was observed in three models; however, it did not improve impotence. DGP was effective in recovery of spermatogenesis and stimulated acetaldehyde detoxification. Significant beneficial effects of AGE were found in all three models. Although all four garlic preparations significantly enhanced natural killer (NK) and killer cell activities of the spleen cells of tumor-bearing mice, only AGE and HGJ inhibited the growth of inoculated tumor cells. These results suggest that different types of garlic preparations have different pharmacologic properties, and among the four garlic preparations studied, AGE could be the most useful garlic preparation', '{"arp_id": "ARP_AYU007293", "portal_id": 7293, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1080S - 1084S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Garlic"], "original_url": "http://jn.nutrition.org/content/131/3/1080S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7293", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007293.pdf", "pdf_sha256": "3b1a752df291fc4af3b1a257814c43a9aac17b56b29c05bb78ba9c46a0b8c5d3", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '10801908', '10.1093/jn/130.5.1124', 'GINGER EXTRACT CONSUMPTION REDUCES PLASMA CHOLESTEROL, INHIBITS LDL OXIDATION AND ATTENUATES DEVELOPMENT OF ATHEROSCLEROSIS IN ATHEROSCLEROTIC, APOLIPOPROTEIN E-DEFICIENT MICE', 'Bianca Fuhrman, Mira Rosenblat, Tony Hayek, Raymond Coleman, Michael Aviram.', 2000,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Oxidative modification of LDL is thought to play a key role in the pathogenesis of atherosclerosis. Consumption of nutrients rich in phenolic antioxidants has been shown to be associated with attenuation of development of atherosclerosis. This study was undertaken to investigate the ex vivo effect of standardized ginger extract on the development of atherosclerosis in apolipoprotein E-deficient (E0) mice, in relation to plasma cholesterol levels and the resistance of their LDL to oxidation and aggregation. E0 mice (n = 60; 6-wk-old) were divided into three groups of 20 and fed for 10 wk via their drinking water with the following: group i) placebo (control group), 1.1% alcohol and water (11 mL of alcohol in 1 L of water); group ii) 25 µg of ginger extract/d in 1.1% alcohol and water and group iii) 250 µg of ginger extract/day in 1.1% alcohol and water. Aortic atherosclerotic lesion areas were reduced 44% (P &amp;lt; 0.01) in mice that consumed 250 µg of ginger extract/day. Consumption of 250 µg of ginger extract/day resulted in reductions (P &amp;lt; 0.01) in plasma triglycerides and cholesterol (by 27 and 29%, respectively), in VLDL (by 36 and 53%, respectively) and in LDL (by 58 and 33%, respectively). These results were associated with a 76% reduction in cellular cholesterol biosynthesis rate in peritoneal macrophages derived from the E0 mice that consumed the high dose of ginger extract for 10 wk (P &amp;lt; 0.01). Furthermore, peritoneal macrophages harvested from E0 mice after consumption of 25 or 250 µg of ginger extract/day had a lower (P &amp;lt; 0.01) capacity to oxidize LDL (by 45 and by 60%, respectively), and to take up and degrade oxidized LDL (by 43 and 47%, respectively). Consumption of 250 µg of ginger extract/day also reduced (P &amp;lt; 0.01) the basal level of LDL-associated lipid peroxides by 62%. In parallel, a 33% inhibition (P &amp;lt; 0.01) in LDL aggregation (induced by vortexing) was obtained in mice fed ginger extract. We conclude that dietary consumption of ginger extract by E0 mice significantly attenuates the development of atherosclerotic lesions. This antiatherogenic effect is associated with a significant reduction in plasma and LDL cholesterol levels and a significant reduction in the LDL basal oxidative state, as well as their susceptibility to oxidation and aggregation.', '{"arp_id": "ARP_AYU007299", "portal_id": 7299, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "130", "issue": "5", "pages": "1124 - 1131", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Atherosclerosis"], "original_url": "http://jn.nutrition.org/content/130/5/1124.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7299", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007299.pdf", "pdf_sha256": "0bce29acf1e37aa57546f5073f1eb517149eaf30f0fdc9e88662542848f040d1", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484560', '10.1093/jn/136.3.769S', 'AGED GARLIC EXTRACT IMPROVES BLOOD PRESSURE IN SPONTANEOUSLY HYPERTENSIVE RATS MORE SAFELY THAN RAW GARLIC1,2', 'Akiko Harauma, Toru Moriguchi.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: We studied the effects of two garlic sources on systolic blood pressure (SBP) using spontaneously hypertensive rats (SHRs). Beginning at 12 wk of age, male SHRs were fed diets containing either aged garlic extract (AGE) or raw garlic (RG) powder for 10 wk. Both AGE and RG reduced the increase of SBP compared with the control group from 4 wk after beginning the experimental diets. The effect of AGE was accompanied by a decrease of pulse pressure (PP), suggesting an improvement of the pliability of the artery, although RG did not affect PP. However, harmful effects were observed in the RG group, including a decrease in erythrocytes, an increase in reticulocytes, and generation of papilloma in the fore stomach. These results suggest that AGE may safely improve several factors related to blood vessel physiology and circulatory disease.', '{"arp_id": "ARP_AYU007304", "portal_id": 7304, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "769S - 773S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/136/3/769S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7304", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007304.pdf", "pdf_sha256": "8ba878cc222641e666f8c05e7af078b1291523112e9459fbdb3439265b2cd5c0", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11880572', '10.1093/jn/132.3.461', 'A SYSTEMATIC SCREENING OF TOTAL ANTIOXIDANTS IN DIETARY PLANTS1', 'Bente L. Halvorsen, Kari Holte, Mari C. W. Myhrstad, Ingrid Barikmo, Erlend Hvattum, Siv Fagertun Remberg, Anne-Brit Wold, Karin Haffner, Halvard Baugerod, Lene Frost Andersen, Jan . Moskaug, David R. Jacobs, Jr, 2.Rune Blomhoff.', 2002,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: A predominantly plant-based diet reduces the risk for development of several chronic diseases. It is often assumed that antioxidants contribute to this protection, but results from intervention trials with single antioxidants administered as supplements quite consistently do not support any benefit. Because dietary plants contain several hundred different antioxidants, it would be useful to know the total concentration of electrondonating antioxidants (i.e., reductants) in individual items. Such data might be useful in the identification of the most beneficial dietary plants. We have assessed systematically worldwide, including various fruits, berries, vegetables, cereals, nuts and pulses. When possible, we analyzed three or more samples of dietary plants from three different geographic regions in the world. Total antioxidants was assessed by the reduction of Fe3 to Fe2 (i.e., the FRAP assay), which occurred rapidly with all reductants half-reaction reduction potentials above that of Fe3 /Fe2 . The values, therefore, expressed the corresponding concentration of electron-donating antioxidants. Our results demonstrated that there is more than a 1000-fold difference among total antioxidants in various dietary plants. Plants that contain most antioxidants included members of several families, such as Rosaceae (dog rose, sour cherry, blackberry, strawberry, raspberry), Empetraceae (crowberry), Ericaceae (blueberry), Grossulariaceae (black currant), Juglandaceae (walnut), Asteraceae sunflower seed), Punicaceae (pomegranate) and Z and cereals contributed 43.6%, 27.1% and 11.7%, respectively, of the total intake of plant antioxidants. Vegetables contributed only 8.9%. The systematic analysis presented here will facilitate research into the nutritional role of the combined effect of antioxidants in dietary plants.', '{"arp_id": "ARP_AYU007310", "portal_id": 7310, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "132", "issue": "3", "pages": "461 - 471", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidants"], "original_url": "http://jn.nutrition.org/content/132/3/461.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7310", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007310.pdf", "pdf_sha256": "7ad6dcb5242717b2805908719c31c9da96611ed279222ca7e8e396b90fed3ee7", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16251611', '10.1093/jn/135.11.2560', 'GARLIC ORGANOSULFUR COMPOUNDS UPREGULATE THE EXPRESSION OF THE CLASS OF GLUTATHIONE S-TRANSFERASE IN RAT PRIMARY HEPATOCYTES1', '3. Chia-Wen Tsai, 4. Jaw-Ji Yang, 5.Haw-Wen Chen, Lee-Yan Sheen, Chong-Kuei Lii.', 2005,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The chemopreventive property of garlic is related in part to its induction of phase II detoxification enzymes. In the present study, we investigated the modulatory effect of 3 garlic organosulfur compounds, i.e., diallyl sulfide (DAS), diallyl disulfide (DADS), and diallyl trisulfide (DATS), which differ in their number of sulfur atoms, on the gene expression of the p class of glutathione S-transferase (GSTP). Hepatocytes isolated from male Sprague-Dawley rats were cultured with 50–200 µmol/L of DAS, DADS, or DATS for 24 h. DADS and DATS increased GST activity toward ethacrynic acid by 40 and 66%, respectively (P &amp;lt; 0.05). Moreover, both garlic allyl sulfides dose dependently induced GSTP mRNA and protein expression. DATS increased the protein level more than DADS (P &amp;lt; 0.05). In contrast, DAS did not affect the activity or the protein or mRNA levels of this phase II drug-metabolizing enzyme. In Clone 9 liver cells, the pTA-luciferase reporter assay showed that luciferase activity in DADS- and DATS-treated cells was 2.8- and 3.9-fold higher than that in control cells, respectively (P &amp;lt; 0.05). Again, luciferase activity was not affected by treatment with DAS. Deletion of -2.7 to -2.6 kb in the GSTP promoter region, which contains the GSTP enhancer (GPE) I element, abolished the upregulation of GSTP transcription by DADS and DATS. Deletion of GPE II, however, did not affect the induction of reporter activity. In conclusion, the effectiveness of 3 garlic allyl sulfides on GSTP expression was related to the number of sulfur atoms in the molecules, and GPE I was responsible for this upregulation.', '{"arp_id": "ARP_AYU007311", "portal_id": 7311, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "135", "issue": "11", "pages": "2560 - 2565", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Class Of Glutathione S-Transferase"], "original_url": "http://jn.nutrition.org/content/135/11/2560.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7311", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007311.pdf", "pdf_sha256": "e7d1ba419fbb557ddbcd2511a7029d76a00f36d885a9a5a2916ed3adcb57c230", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238827', '10.1093/jn/131.3.1109S', 'EFFECTS OF GARLIC PREPARATIONS ON THE GASTROINTESTINAL MUCOSA1', '2. Hoshino T, 3. Kashimoto N, 3. Kasuga S.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The effects of garlic preparations, including dehydrated raw garlic powder (RGP), dehydrated boiled garlic powder (BGP) and aged garlic extract (AGE), on the gastric mucosa were determined using a newly established endoscopic air-powder delivery system, which can deliver solid materials directly into the stomach. Among the three preparations, RGP caused severe damage, including erosion. BGP also caused reddening of the mucosa, whereas AGE did not cause any undesirable effects. The safety of enteric-coated garlic products was also determined. Direct administration of pulverized enteric-coated products on the gastric mucosa caused reddening of the mucosa. When an enteric-coated tablet was administered orally, it caused loss of epithelial cells at the top of crypts in the ileum. These results suggest that caution be used with regard to safety and effectiveness when choosing a garlic preparation because some preparations may have undesirable effects, including gastrointestinal problems.', '{"arp_id": "ARP_AYU007319", "portal_id": 7319, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1109S - 1113S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Endoscopy"], "original_url": "http://jn.nutrition.org/content/131/3/1109S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7319", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007319.pdf", "pdf_sha256": "d6c3fe1ed515d416403f0cc3212407362ed4879e22ed9182ffbd62b07921c9d4", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11481398', '10.1093/jn/131.8.2082', 'POMEGRANATE JUICE SUPPLEMENTATION TO ATHEROSCLEROTIC MICE REDUCES MACROPHAGE LIPID PEROXIDATION, CELLULAR CHOLESTEROL ACCUMULATION AND DEVELOPMENT OF ATHEROSCLEROSIS1', 'Marielle Kaplan, Tony Hayek, Ayelet Raz, Raymond Coleman, Leslie Dornfeld, Jacob Vaya, 2. Michael Aviram.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Inhibition of lipid peroxidation contributes to the attenuation of macrophage cholesterol accumulation, foam-cell formation and atherosclerosis. Evidence suggests that nutritional antioxidants such as pomegranate juice (PJ) can contribute to the reduction of oxidative stress and atherogenesis. The goals of the present study were to determine whether such beneficial effects of PJ exist when supplemented to apolipoprotein E-deficient (E0) mice with advanced atherosclerosis and to analyze the antiatherosclerotic activity of a tannin-fraction isolated from PJ. Mice (4-mo-old) were supplemented with PJ in their drinking water for 2 mo and compared with age-matched placebo-treated mice, as well as to young (4-mo-old) control mice, for their mouse peritoneal macrophage (MPM) oxidative state, cholesterol flux and mice atherosclerotic lesion size. PJ supplementation reduced each of the proatherogenic variables determined in the present study compared with age-matched placebo-treated mice. It significantly induced serum paraoxonase activity and reduced MPM lipid peroxide content compared with placebo-treated mice and control mice. PJ administration to E0 mice significantly reduced the oxidized (Ox)-LDL MPM uptake by 31% and MPM cholesterol esterification and increased macrophage cholesterol efflux by 39% compared with age-matched, placebo-treated mice. PJ consumption reduced macrophage Ox-LDL uptake and cholesterol esterification to levels lower than those in 4-mo-old, unsupplemented controls. PJ supplementation to E0 mice with advanced atherosclerosis reduced the lesion size by 17% compared with placebo-treated mice. In a separate study, supplementation of young (2-mo-old) E0 mice for 2 mo with a tannin fraction isolated from PJ reduced their atherosclerotic lesion size, paralleled by reduced plasma lipid peroxidation and decreased Ox-LDL MPM uptake. PJ supplementation to mice with advanced atherosclerosis reduced their macrophage oxidative stress, their macrophage cholesterol flux and even attenuated the development of atherosclerosis. Moreover, a tannin-fraction isolated from PJ had a significant antiatherosclerotic activity.', '{"arp_id": "ARP_AYU007331", "portal_id": 7331, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "8", "pages": "2082 - 2089", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidants"], "original_url": "http://jn.nutrition.org/content/131/8/2082.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7331", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007331.pdf", "pdf_sha256": "842d50f32852dc81f8e5364618ccebf8d9e0c2910ff42a2c409bf513a86b29b8", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484558', '10.1093/jn/136.3.759S', 'INHIBITION OF STEROL 4A-METHYL OXIDASE IS THE PRINCIPAL MECHANISM BY WHICH GARLIC DECREASES CHOLESTEROL SYNTHESIS1-3', 'Dev K. Singh, Todd D. Porter.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Clinical and experimental evidence indicates that garlic ingestion lowers blood cholesterol levels, and treatment of cells in culture with garlic and garlic-derived compounds inhibits cholesterol synthesis. To identify the principal site of inhibition in the cholesterolgenic pathway and the active components of garlic, cultured hepatoma cells were treated with aqueous garlic extract or its chemical derivatives, and radiolabeled cholesterol and intermediates were identified and quantified. Garlic extract reduced cholesterol synthesis by up to 75% without evidence of cellular toxicity. Levels of squalene and 2,3-oxidosqualene were not altered by garlic, indicating that the site of inhibition was downstream of lanosterol synthesis, and identical results were obtained with 14C-acetate and 14C-mevalonate, confirming that 3-hydroxy-3-methylglutaryl-CoA reductase activity was not affected in these shortterm studies. Several methylsterols that accumulated in the presence of garlic were identified by coupled gas chromatography–mass spectrometry as 4,49-dimethylzymosterol and a possible metabolite of 4-methylzymosterol; both are substrates for sterol 4a-methyl oxidase, pointing to this enzyme as the principal site of inhibition in the cholesterolgenic pathway by garlic. Of 9 garlic-derived compounds tested for their ability to inhibit cholesterol synthesis, only diallyl disulfide, diallyl trisulfide, and allyl mercaptan proved inhibitory, each yielding a pattern of sterol accumulation identical with that obtained with garlic extract. These results indicate that compounds containing an allyl-disulfide or allyl-sulfhydryl group are most likely responsible for the inhibition of cholesterol synthesis by garlic and that this inhibition is likely mediated at sterol 4a-methyl oxidase.', '{"arp_id": "ARP_AYU007335", "portal_id": 7335, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "759S - 764S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cholesterol Synthesis"], "original_url": "http://jn.nutrition.org/content/136/3/759S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7335", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007335.pdf", "pdf_sha256": "b89499740769a0de542903f1012697d2f701683c293f2511d7f5c054160c58ec", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484569', '10.1093/jn/136.3.806S', 'IN VITRO INTERACTIONS OF WATER-SOLUBLE GARLIC COMPONENTS WITH HUMAN CYTOCHROMES P4501-3', 'David J. Greenblatt, Richard A. Leigh-Pemberton, Lisa L. von Moltke.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Eight water-soluble components of aged garlic extract were evaluated to assess their potential to inhibit the activity of human cytochrome-P450 (CYP) enzymes. The in vitro model consisted of human liver microsomes with index reactions chosen to profile the activity of the following six CYP isoforms: CYP1A2, 2B6, 2C9, 2C19, 2D6, and 3A. With only 2 exceptions, none of the 8 garlic components produced &amp;gt;50% inhibition even at high concentrations (100 &amp;#181;mol/L). S-methyl-l-cysteine and S-allyl-l-cysteine at 100 &amp;#181;mol/L produced modest inhibition of CYP3A, reducing activity to 20–40% of control. However available clinical evidence does not indicate CYP3A inhibition in vivo. The findings suggest that drug interactions involving inhibition of CYP3A enzymes by aged garlic extract are very unlikely.', '{"arp_id": "ARP_AYU007344", "portal_id": 7344, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "806S - 809S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/136/3/806S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7344", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007344.pdf", "pdf_sha256": "5bd2c77501a328dca6fada01d1cd3b522c1584af83c905275b7016bfa46bbf8e", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11340096', '10.1093/jn/131.5.1438', 'DIETARY FAT AND GARLIC OIL INDEPENDENTLY REGULATE HEPATIC CYTOCHROME P450 2B1 AND THE PLACENTAL FORM OF GLUTATHIONE S-TRANSFERASE EXPRESSION IN RATS1', 'Haw-Wen Chen, Jaw-Ji Yang, Chia-Wen Tsai, Jyh-Jong Wu, Lee-Yan Sheen, Chu-Chyn Ou and 2.Chong-Kuei Lii.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The individual and combined effects of dietary fat and garlic oil on two drug-metabolizing enzymes, cytochrome P450 2B1 and the placental form of glutathione (GSH) S-transferase (PGST), in rat liver were examined in this study. Rats were fed a low corn oil, high corn oil or high fish oil diet and received various amount of garlic oil (0, 30, 80, 200 mg/kg body) orally three times per week for 6 wk. The fat energy in the low and high fat diets accounted for 11.6 and 45.7% of total energy, respectively. Final body weights did not differ among the three dietary fat groups and were not affected by garlic oil treatment. The fatty acid profile in hepatic phospholipids revealed higher eicosapentaenoic acid [20:5(n-3)] and docosahexaenoic acid [22:6(n-3)] levels in the fish oil–fed group than in the low and high corn oil–fed groups (P &amp;lt; 0.05). In contrast, the corn oil–fed groups had greater hepatic phospholipid arachidonic acid [20:4(n-6)] levels (P &amp;lt; 0.05). Both dietary fat and garlic oil significantly affected hepatic cytochrome 7-pentoxyresorufin O-dealkylase (PROD) activity and GST activity toward ethacrynic acid. Rats fed the high fish oil diet had 85 and 51% higher PROD activity compared with those fed the low or the high corn oil diet, respectively (P &amp;lt; 0.05). The GST activity in the high fish oil and the high corn oil groups was 33 and 18% higher than that in the low corn oil group (P &amp;lt; 0.05), respectively, and the GST activity in rats fed the high fish oil diet was higher than in those fed the high corn oil diet (P &amp;lt; 0.05). Garlic oil dose-dependently increased GST activity. No interaction between dietary fat and garlic oil on PROD or GST activity was noted. Northern and Western blot analysis revealed that dietary fish oil increased both cytochrome P450 2B1 and PGST mRNA and protein levels. Cytochrome P450 2B1 and PGST mRNA and protein levels were also dose-dependently increased by garlic oil treatment. The effects of garlic oil and dietary fat on P450 2B1 and PGST mRNA and protein expression were independent. These results indicate that dietary fat and garlic oil independently modulate P450 2B1 and PGST expression at transcriptional and/or post-transcriptional stages.', '{"arp_id": "ARP_AYU007350", "portal_id": 7350, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "5", "pages": "1438 - 1443", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cytochrome P450 2B1"], "original_url": "http://jn.nutrition.org/content/131/5/1438.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7350", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007350.pdf", "pdf_sha256": "3466ec5986808f7c2688b79d507b13cd87e74e7097580d391801620ddd08feda", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238801', '10.1093/jn/131.3.980S', 'AGED GARLIC EXTRACT, A MODULATOR OF CARDIOVASCULAR RISK FACTORS: A DOSE-FINDING STUDY ON THE EFFECTS OF AGE ON PLATELET FUNCTIONS1', '2. Steiner M, W. Li.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aged garlic extract (AGE) has been shown previously to have moderate cholesterol-lowering and blood pressure–reducing effects. We have now investigated whether platelet function, a potential risk factor for cardiovascular disease, can be inhibited by AGE administration. In a randomized, double-blind study of normal healthy individuals (n = 34), both men and women, the effect of AGE was evaluated in doses between 2.4 and 7.2 g/d vs. equal amounts of placebo. Platelet aggregation and adhesion were measured at 2-wk intervals throughout the study. Threshold concentrations for epinephrine and collagen increased moderately during AGE administration compared with the placebo and baseline periods. Only at the highest supplementation level did AGE show a slight increase in the threshold level of ADP-induced aggregation. Platelet adhesion to collagen, fibrinogen and von Willebrand factor was investigated by perfusing whole blood through a laminar flow chamber under controlled flow conditions. Adherence of platelets was inhibited by AGE in a dose-dependent manner when collagen was the adhesive surface perfused at low shear rates (~30 s-1). At high shear rates (1200 s-1), AGE also inhibited platelet adhesion to collagen but only at higher intake levels. Adhesion to von Willebrand factor was reduced only at 7.2 g/d AGE, but adherence to fibrinogen was potently inhibited at all levels of supplementation. Thus, AGE exerts selective inhibition on platelet aggregation and adhesion, platelet functions that may be important for the development of cardiovascular events such as myocardial infarction and ischemic stroke. We briefly review the effect of garlic preparations in general on cardiovascular risk factors and point out differences between AGE and other garlic preparations that we feel are important to explain the efficacy of AGE.', '{"arp_id": "ARP_AYU007351", "portal_id": 7351, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "980S - 984S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/131/3/980S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7351", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007351.pdf", "pdf_sha256": "4a30e156ecf38fd0f05c30882585ea1d0d8953ce817a70bbfac0ffd5bcde31c5", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238796', '10.1093/jn/131.3.955S', 'INTAKE OF GARLIC AND ITS BIOACTIVE COMPONENTS1', '2. Harunobu Amagase, 2. Brenda L. Petesch, 3. Hiromichi Matsuura, 3. Shigeo Kasuga, 3. Yoichi Itakura.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The health benefits of garlic likely arise from a wide variety of components, possibly working synergistically. The complex chemistry of garlic makes it plausible that variations in processing can yield quite different preparations. Highly unstable thiosulfinates, such as allicin, disappear during processing and are quickly transformed into a variety of organosulfur components. The efficacy and safety of these preparations in preparing dietary supplements based on garlic are also contingent on the processing methods employed. Although there are many garlic supplements commercially available, they fall into one of four categories, i.e., dehydrated garlic powder, garlic oil, garlic oil macerate and aged garlic extract (AGE). Garlic and garlic supplements are consumed in many cultures for their hypolipidemic, antiplatelet and procirculatory effects. In addition to these proclaimed beneficial effects, some garlic preparations also appear to possess hepatoprotective, immune-enhancing, anticancer and chemopreventive activities. Some preparations appear to be antioxidative, whereas others may stimulate oxidation. These additional biological effects attributed to AGE may be due to compounds, such as S-allylcysteine, S-allylmercaptocysteine, Na-fructosyl arginine and others, formed during the extraction process. Although not all of the active ingredients are known, ample research suggests that several bioavailable components likely contribute to the observed beneficial effects of garlic.', '{"arp_id": "ARP_AYU007355", "portal_id": 7355, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "955S - 962S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Allicin"], "original_url": "http://jn.nutrition.org/content/131/3/955S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7355", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007355.pdf", "pdf_sha256": "28f1e6539782257180d37fc957bd6837854a84c32f9a3b61c844ae09c9344024", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484550', '10.1093/jn/136.3.716S', 'CLARIFYING THE REAL BIOACTIVE CONSTITUENTS OF GARLIC1', 'Harunobu Amagase.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Compounds in garlic work synergistically to produce various effects, but, because of garlic’s chemical complexity, processing methods yield preparations with differing efficacy and safety. Although thiosulfinates such as allicin have been long misunderstood to be active compounds due to their characteristic odor, it is not necessary for garlic preparations to contain such odorous compounds to be effective, and they decompose and disappear during any processing. Garlic exhibits hypolipidemic, antiplatelet, and procirculatory effects. It prevents cold and flu symptoms through immune enhancement and demonstrates anticancer and chemopreventive activities. In addition, aged garlic extract possesses hepatoprotective, neuroprotective, antioxidative activities, whereas other preparations may stimulate oxidation. Additional effects may be caused by S-allylcysteine, S-allyl mercaptocysteine), saponins, Na-fructosyl arginine, and other substances formed during a long-term extraction process. Although not all of active ingredients of garlic are known, and allicin-like transient components are not directly active, ample research suggests that an allicin free garlic preparation that is standardized with a bioavailable component such as S-allylcysteine, is active and various effects of garlic may be attributed to it. Furthermore, various chemical constituents in garlic products, including nonsulfur compounds such as saponins, may contribute to the essential biological activities of garlic. Further studies are needed to confirm their bioavailability and associated activities.', '{"arp_id": "ARP_AYU007360", "portal_id": 7360, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "716S - 725S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/136/3/716S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7360", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007360.pdf", "pdf_sha256": "ad6d0c8a7a86aee0848b57ed050c430fa1b56bea802b0ce86086bd8ee5207e28", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11340102', '10.1093/jn/131.5.1471', 'GENDER MAY AFFECT THE ACTION OF GARLIC OIL ON PLASMA CHOLESTEROL AND GLUCOSE LEVELS OF NORMAL SUBJECTS1,2,3', 'Xiao-Hua Zhang, Derek Lowe, Paul Giles, Stephen Fell, Martin J. Connock, David J. Maslin.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Early trials of garlic preparations on blood lipids mainly supported a lipid-lowering effect, whereas later well-designed garlic tablet trials were mainly entirely null. However, enteric simulation tests suggest that this discordance may result from ineffective delivery of bioactive agents from the brands of garlic powder (GP) and cyclodextrin-bound garlic oil (GO) tablets tested in some recent negative trials. In contrast, enteric simulation tests show that the preformed bioactive agents present in “traditional” gelatin capsules of GO are efficiently released, although such capsules have rarely been investigated in lipid-lowering trials. It was hypothesized that gelatin capsules of GO given to normal subjects would improve specified coronary heart disease risk factors. Effects of a GP preparation were also investigated. Subjects (n = 51; men and women, mean age 27 y) were randomly assigned to receive either 8.2 mg/d of GO (allyl sulfides) or placebo for 11 wk. Another 27 subjects received garlic powder (GP) of similar biopotential (7.8 mg allicin/d). Outcome measures were 95% confidence intervals (CI) between GO and placebo groups for differences between baseline and subsequent sample times. Men and women combined showed no significant differences save for an improved total antioxidant capacity at 6 wk (P = 0.01). Hence, no benefit from GO after 11 wk is one plausible conclusion. However, there were significant differences in effect of GO between men and women for HDL cholesterol (HDL-C) (P = 0.004) and total cholesterol (TC)/HDL-C (P = 0.003). Women showed favorable effects in terms of CHD risk factors (i.e., increases in HDL-C and reductions in TC/HDL-C), whereas men had small adverse effects. There was a significant difference in the GO effect for glucose (P = 0.006), with a reduction seen for men and an increase for women. The gender effects were unexpected and such analyses were not planned in advance. Confirmation of these findings with larger numbers of subjects would have importance for the use of garlic against CHD and for the design of future garlic studies.', '{"arp_id": "ARP_AYU007376", "portal_id": 7376, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "5", "pages": "1471 - 1478", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidants"], "original_url": "http://jn.nutrition.org/content/131/5/1471.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7376", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007376.pdf", "pdf_sha256": "77330d5b267f6cc85ffac40d86da9186da84044d4726af876c7f3354e65f618a", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484574', '10.1093/jn/136.3.727S', 'PRECLINICAL PERSPECTIVES ON GARLIC AND CANCER', 'John A. Milner.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Evidence continues to point to the anticancer properties of fresh garlic extracts, aged garlic, garlic oil, and a number of specific organosulfur compounds generated byprocessing garlic.These anticarcinogenic and antitumorigenic characteristics appear to arise through both dose- and temporal-related changes in a number of cellular events involved with the cancer process, including those involving drug metabolism, immuno competence, cell cycle regulation, apoptosis, and angiogenesis. The ability of garlic and related allyl sulfur compounds to block tumors in the colon, lung, breast, and liver suggests general mechanisms that are not tissue specific. Whereas relatively few studies have compared the relative efficacy of water- and lipid-soluble allyl sulfur compounds, those that have when using chemically induced carcinogen models suggest little difference in response, whereas tumor proliferation/apoptosis is highly dependent on the species provided. A shift in sulfhydryl groups, alterations in glutathione:oxidized glutathione ratios, and resultant changes in cellular redox status may be involved in some of the phenotypic changes caused by allyl sulfur compounds. Such changes in thiols by allyl sulfurs may also account for the observed hyperphosphorylation of specific cell cycle proteins and the histone hyperacetylation that has been correlated with suppressed tumor cell proliferation. Whereas the anticarcinogenic and antitumorigenic data to date are impressive, additional studies are needed with more modest exposure to allyl sulfur compounds over prolonged periods. Likewise, additional studies are needed that incorporate transgenic and knockout models to assist in the identification of molecular targets for garlic and its associated allyl sulfur components.', '{"arp_id": "ARP_AYU007377", "portal_id": 7377, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "827S - 831S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Apoptosis"], "original_url": "http://jn.nutrition.org/content/136/3/827S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7377", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007377.pdf", "pdf_sha256": "734423ad6822c78ef2c86a8bef255932b89548b563e31152583f602c11339c45", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238818', '10.1093/jn/131.3.1067S', 'ENHANCED IMMUNOCOMPETENCE BY GARLIC: ROLE IN BLADDER CANCER AND OTHER MALIGNANCIES1', 'Donald L. Lamm, Dale R. Riggs.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Of the many beneficial actions of garlic, inhibition of the growth of cancer is perhaps the most remarkable. Our previous animal studies demonstrated that aged garlic extract was highly effective, and unlike the approved immunotherapy for human bladder cancer, bacillus Calmette-Gue&amp;#180; rin (BCG), garlic was effective when added to the diet. To elucidate the mechanism of this antitumor effect, the literature describing antitumor and immune-enhancing effects of garlic is reviewed. Garlic can detoxify carcinogens by stimulation of cytochrome P450 enzymes, antioxidant activity or sulfur compound binding. Studies demonstrate a direct toxic effect of garlic to sarcoma and gastric, colon, bladder and prostate cancer cells in tissue culture, but these effects cannot explain the inhibition of growth of transplanted cancer in animal models. The most likely explanation of this effect is immune stimulation. Comparison of the effects of garlic to BCG immunotherapy reveals many similarities. Both stimulate proliferation of lymphocytes and macrophage phagocytosis, induce the infiltration of macrophages and lymphocytes in transplanted tumors, induce splenic hypertrophy, stimulate release of interleukin-2, tumor necrosis factor-a and interferon-g, enhance natural killer cell, killer cell and lymphokine-activated killer cell activity. These activities represent effective stimulation of the immune response. Studies suggest that garlic may be useful in preventing the suppression of immune response that is associated with increased risk of malignancy. Data suggest that maintenance of immune stimulation can significantly reduce the risk of cancer. Clinical trials should be initiated to test the hypothesis that the immune stimulation and other beneficial effects of garlic are able to reduce the incidence of cancer.', '{"arp_id": "ARP_AYU007380", "portal_id": 7380, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1067S - 1070S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Bladder"], "original_url": "http://jn.nutrition.org/content/131/3/1067S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7380", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007380.pdf", "pdf_sha256": "d7463bb0242c90c5287fd17436facaffb0edf0b4cc8b45e12c5e83fb1339d08b", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484551', '10.1093/jn/136.3.726S', 'TETRAHYDRO-B-CARBOLINE DERIVATIVES IN AGED GARLIC EXTRACT SHOW ANTIOXIDANT PROPERTIES', '3. Makoto Ichikawa, Jiro Yoshida, Nagatoshi Ide, Takashi Sasaoka, Hiroyuki Yamaguchi, Kazuhisa Ono.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study used the hydroden peroxide scavenging assay to investigate antioxidant chemical constituents derived and separated from aged garlic extract, a unique garlic extract produced by soaking sliced garlic in an aqueous ethanol solution for &amp;gt;10 mo. Four types of 1, 2, 3, 4-tetrahydro-ß-carboline derivatives (THßCs); 1-methyl-1, 2, 3, 4-tetrahydro-ß-carboline-3-carboxylic acid, and 1-methyl-1, 2, 3, 4-tetrahydro-ß-carboline-1, 3-dicarboxylic acid (MTCdiC), from both diastereoisomers, were isolated and identified by use of liquid chromatography–mass spectrometry. All these compounds indicate strong hydrogen peroxide scavenging activities and inhibit 2, 2&#39;-azobis(2-amidinopropane) hydrochloride–induced lipid peroxidation. Particularly, (1S, 3S)-MTCdiC had the most potent hydrogen peroxide scavenging activity, more than ascorbic acid. The (1R, 3S)- and (1S, 3S)-MTCdiC at 50–100 µmol/L and 10–100 µmol/L inhibited LPS-induced nitrite production. Interestingly, THßCs were not detected in raw garlic and other processed garlic preparations, but they were generated and increased during the natural aging garlic extraction process. These data suggest that THßCs, which are formed during the natural aging process, are potent antioxidants in aged garlic extract and thus may be useful for the prevention of diseases associated with oxidative damage.', '{"arp_id": "ARP_AYU007459", "portal_id": 7459, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "726S - 731S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/136/3/726S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7459", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007459.pdf", "pdf_sha256": "62d835806e947b57c1e9f3db6eb9c1aee96e3c6a2c7ba81bae89291f58ac8082", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238805', '10.1093/jn/131.3.1000S', 'SAPONINS IN GARLIC AS MODIFIERS OF THE RISK OF CARDIOVASCULAR DISEASE', 'Hiromichi Matsuura.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Most chemical and biological studies about garlic have been conducted using organosulfur compounds. However, a variety of steroid saponins from garlic and related Allium species are being increasingly recognized for their importance in biological processes. This report demonstrates the isolation and structure determination of steroid saponins from garlic and aged garlic extract (AGE). In addition, the in vitro antifungal antitumor cytotoxicity and blood coagulability effects of steroid saponins from garlic and related Allium species are provided. Animal studies on the cholesterol-lowering effects of the saponin fractions from garlic are also summarized.', '{"arp_id": "ARP_AYU007466", "portal_id": 7466, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1000S - 1005S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cholesterol"], "original_url": "http://jn.nutrition.org/content/131/3/1000S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7466", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007466.pdf", "pdf_sha256": "db207cb4df9dadfcadee81a2d8d56ca938b42ba7d315cdbd4a0fa99627878dc3", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238807', '10.1093/jn/131.3.1010S', 'ANTIOXIDANT HEALTH EFFECTS OF AGED GARLIC EXTRACT', 'Carmia Borek.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Oxidative modification of DNA, proteins and lipids by reactive oxygen species (ROS) plays a role in aging and disease, including cardiovascular, neurodegenerative and inflammatory diseases and cancer. Extracts of fresh garlic that are aged over a prolonged period to produce aged garlic extract (AGE) contain antioxidant phytochemicals that prevent oxidant damage. These include unique water-soluble organosulfur compounds, lipid-soluble organosulfur components and flavonoids, notably allixin and selenium. Long-term extraction of garlic (up to 20 mo) ages the extract, creating antioxidant properties by modifying unstable molecules with antioxidant activity, such as allicin, and increasing stable and highly bioavailable water-soluble organosulfur compounds, such as S-allylcysteine and S-allylmercaptocysteine. AGE exerts antioxidant action by scavenging ROS, enhancing the cellular antioxidant enzymes superoxide dismutase, catalase and glutathione peroxidase, and increasing glutathione in the cells. AGE inhibits lipid peroxidation, reducing ischemic/reperfusion damage and inhibiting oxidative modification of LDL, thus protecting endothelial cells from the injury by the oxidized molecules, which contributes to atherosclerosis. AGE inhibits the activation of the oxidant-induced transcription factor, nuclear factor (NF)-kB, which has clinical significance in human immunodeficiency virus gene expression and atherogenesis. AGE protects DNA against free radical–mediated damage and mutations, inhibits multistep carcinogenesis and defends against ionizing radiation and UV-induced damage, including protection against some forms of UV-induced immunosuppression. AGE may have a role in protecting against loss of brain function in aging and possess other antiaging effects, as suggested by its ability to increase cognitive functions, memory and longevity in a senescenceaccelerated mouse model. AGE has been shown to protect against the cardiotoxic effects of doxorubicin, an antineoplastic agent used in cancer therapy and against liver toxicity caused by carbon tetrachloride (an industrial chemical) and acetaminophen, an analgesic. Substantial experimental evidence shows the ability of AGE to protect against oxidant-induced disease, acute damage from aging, radiation and chemical exposure, and long-term toxic damage. Although additional observations are warranted in humans, compelling evidence supports the beneficial health effects attributed to AGE, i.e., reducing the risk of cardiovascular disease, stroke, cancer and aging, including the oxidant-mediated brain cell damage that is implicated in Alzheimer’s disease.', '{"arp_id": "ARP_AYU007468", "portal_id": 7468, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1010S - 1015S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aging"], "original_url": "http://jn.nutrition.org/content/131/3/1010S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7468", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007468.pdf", "pdf_sha256": "0ca49d5012ad23ca2f8b369ea9e46a33bb3a0c977ecb33005e270113b40f8555", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484582', '10.1093/jn/136.3.864S', 'CANCER CHEMOPREVENTION BY GARLIC AND GARLIC-CONTAINING SULFUR AND SELENIUM COMPOUNDS', '1. Karam El-Bayoumy, 1. Raghu Sinha, 2. John T. Pinto, 1. Richard S. Rivlin.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: As early as 1550 B.C., Egyptians realized the benefits of garlic as a remedy for a variety of diseases. Many epidemiological studies support the protective role of garlic and related allium foods against the development of certain human cancers. Natural garlic and garlic cultivated with selenium fertilization have been shown in laboratory animals to have protective roles in cancer prevention. Certain organoselenium compounds and their sulfur analogs have been identified in plants. Organoselenium compounds synthesized in our laboratory were compared with their sulfur analogs for chemopreventive efficacy. Diallyl selenide was at least 300-fold more effective than diallyl sulfide in protecting against 7,12-dimethylbenz[a]anthracene (DMBA)-induced mammary adenocarcinomas in rats. In addition, benzyl selenocyanate inhibited the development of DMBA-induced mammary adenocarcinomas and azoxymethane-induced colon cancer in rats and benzo[a]pyrene-induced forestomach tumors in mice. The sulfur analog, benzyl thiocyanate, had no effect under the same experimental conditions. Furthermore, we showed that 1,4-phenylenebis(methylene)- selenocyanate, but not its sulfur analog, significantly inhibited DMBA-DNA adduct formation and suppressed DMBAinduced mammary carcinogenesis. Collectively, these results indicate that structurally distinctive organoselenium compounds are superior to their corresponding sulfur analogs in cancer chemoprevention. Additionally, synthetic aromatic selenocyanates are more effective cancer chemopreventive agents than the naturally occurring selenoamino acids. Because plants are capable of utilizing selenium in a manner similar to that in sulfur assimilation pathways, future studies should aim at determining whether, under appropriate conditions, these potent cancer chemopreventive synthetic selenium compounds can be synthesized by garlic and related allium foods.', '{"arp_id": "ARP_AYU007469", "portal_id": 7469, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "864S - 869S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Carcinogenesis"], "original_url": "http://jn.nutrition.org/content/136/3/864S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7469", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007469.pdf", "pdf_sha256": "9188a52406aa4575957b6b24b888e9099b8f39ab9a68175ef64f91e371bbd406", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16484580', '10.1093/jn/136.3.855S', 'AGED GARLIC EXTRACT INHIBITS DEVELOPMENT OF PUTATIVE PRENEOPLASTIC LESIONS IN RAT HEPATOCARCINOGENESIS', '1. Naoto Uda, Naoki Kashimoto, Isao Sumioka, Eikai Kyo, Shin-ichiro Sumi, Shoji Fukushimay.', 2006,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: A unique garlic preparation, aged garlic extract (AGE), was examined for its modifying effect on diethylnitrosamine (DEN)-induced neoplasia of the liver in male F344 rats, using the medium-term bioassay system based on the 2-step model of hepatocarcinogenesis. Carcinogenic potential was scored by comparing the numbers and areas of induced glutathione S-transferase placental form (GST-P)-positive hepatocellular foci. GST-P-positive foci were significantly decreased in rats treated with AGE at doses of 2, 5, and 10 mL/kg, i.g., 5 times per week during the promotion phase. In addition, to clarify the mechanism underlying the inhibitory effect of AGE, the effect of AGE on hepatocellular proliferation was evaluated using partially hepatectomized rats as a liver-regeneration model. The bromodeoxyuridine-labeling indices in the livers of the AGE group were significantly lower than those in the control group at 24 h, the maximum proliferation period after partial hepatectomy. These findings indicate that AGE inhibited the development of putative preneoplastic lesions in rat hepatocarcinogenesis, involving a slowing in the proliferation rate of liver cells after partial hepatectomy.', '{"arp_id": "ARP_AYU007470", "portal_id": 7470, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "136", "issue": "3 Supplement", "pages": "855S - 860S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extract"], "original_url": "http://jn.nutrition.org/content/136/3/855S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7470", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007470.pdf", "pdf_sha256": "16125f06c4c0e8534c8f306f0750b57230df8a4f9c7fb50d0b4f74dcff76eab0", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238823', '10.1093/jn/131.3.1093S', 'AMELIORATIVE EFFECT OF S-ALLYLCYSTEINE, A MAJOR THIOALLYL CONSTITUENT IN AGED GARLIC EXTRACT, ON LEARNING DEFICITS IN SENESCENCE-ACCELERATED MICE', 'Nobuyoshi Nishiyama, Toru Moriguchi, Naoaki Morihara, Hiroshi Saito.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study examined the effect of S-allylcysteine (SAC), a major thioallyl compound found in aged garlic extract, on the memory deficit and age-related changes of senescence-accelerated mice. Senescence-accelerated prone P8 mice fed a diet supplemented with 40 mg SAC/kg diet for 8 mo had a significantly attenuated decrease in the conditioned avoidance response compared with those not given SAC. In the elevated plus-maze test using senescence-accelerated prone P10 mice, the percentage of time spent on the open arm was greater compared with the senescence-resistant control mice. Chronic dietary treatment with 40 mg SAC/kg diet decreased the time in the open arm in senescence-accelerated prone P10 mice. These studies suggest that diet supplementation with SAC may reduce age-related learning disabilities and cognitive disorders in senescence-accelerated mice.', '{"arp_id": "ARP_AYU007471", "portal_id": 7471, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1093S - 1095S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aged Garlic Extracts"], "original_url": "http://jn.nutrition.org/content/131/3/1093S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7471", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007471.pdf", "pdf_sha256": "f1ca8f232d11fef1a788d6639c0339a90a85819ccf921ee180bb03eab4fdb49b", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11238824', '10.1093/jn/131.3.1096S', 'ISOLATION AND CHARACTERIZATION OF THE GENES UP-REGULATED IN ISOLATED NEURONS BY AGED GARLIC EXTRACT (AGE)', '2.Shin-ichiro Sumi, Tadamitsu Tsuneyoshi, Hiroaki Matsuo, Tadanori Yoshimatsu.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aged garlic extract (AGE) produces neurotrophic effects on cultured fetal rat hippocampal neurons. These studies examined the molecular events triggered by AGE that might account for a suppression of neuronal cell death. Genes differentially expressed by the addition of AGE in primary cultured hippocampal neurons isolated from fetal rat brain were screened using mRNA differential display. Four cDNA clones were significantly enhanced at their transcriptional level; they were designated as #24, #110, #153 and #155. Quantitative reverse transcription-polymerase chain reaction (RT-PCR), as well as dot-blot hybridization combined with RT-PCR, confirmed that the transcription from these four genes was elevated at least twofold, particularly the mRNA of #153, which was increased &amp;gt;20 times 72 h after the addition of AGE. A homology search of the respective cDNA sequences in the DNA database revealed that #153 is an a2-microglobulin–related protein (a2MRP) gene. The others genes were not identified. Induction of the a2MRP gene expression occurred within 24 h after addition of AGE. These findings suggest a possible mechanism by which AGE may regulate gene expression and bring about a neurotrophic effect. Further, our results suggest that a2MRP may function at the initial step of the molecular events triggered by AGE and play an important role in the survival of hippocampal neurons.', '{"arp_id": "ARP_AYU007472", "portal_id": 7472, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "3s", "pages": "1096S - 1099S", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["A2-Microglobulin–Related Protein"], "original_url": "http://jn.nutrition.org/content/131/3/1096S.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7472", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007472.pdf", "pdf_sha256": "44015e6a4c3a4c943e76d35f90fe165eae45cbba462e5b0dcd8a4afec255744a", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11584080', '10.1093/jn/131.10.2619', 'ADMINISTRATION OF RAW ONION INHIBITS PLATELET-MEDIATED THROMBOSIS IN DOGS', 'William H. Briggs, John D. Folts, Hashim E. Osman, 2. Irwin L. Goldman.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: A number of studies suggest that dietary intake of onions is of benefit to cardiovascular health. Onion juice inhibits in vitro human platelet aggregation. To study the in vivo effect of onion on platelet aggregation, 11 dogs were prepared with mechanically damaged and stenosed coronary arteries. Periodic platelet-mediated thrombus formation followed by embolization produced cyclic flow reductions (CFR). In five dogs, 0.09 &amp;#177; 0.01 mL/kg onion juice administered intravenously abolished CFR within 20 min. This was followed by a 60 &amp;#177; 14% (P = 0.002) reduction in collagen-induced ex vivo whole-blood platelet aggregation. Six dogs were given 2.0 g/kg raw onion homogenate intragastrically. CFR were eliminated within 2.5–3 h in five of the dogs. This was accompanied by a 44 &amp;#177; 24% (P = 0.04) reduction in ex vivo aggregation. These findings suggest that the consumption of raw onion may help prevent platelet-mediated cardiovascular disorders. However, in vitro incubations of onion juice demonstrated that the platelet inhibitory response was significantly greater in dog blood than in human blood.', '{"arp_id": "ARP_AYU007473", "portal_id": 7473, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "10", "pages": "2619 - 2622", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Dogs"], "original_url": "http://jn.nutrition.org/content/131/10/2619.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7473", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007473.pdf", "pdf_sha256": "3f463530866787e75771b23ad5fe40b74f8b1f4692eb69467d7f48097342aac9", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '19297423', '10.3945/jn.108.100966', 'CURCUMIN INHIBITS ADIPOGENESIS IN 3T3-L1 ADIPOCYTES AND ANGIOGENESIS AND OBESITY IN C57/BL MICE1-3', '4. Asma Ejaz, 4. Dayong Wu, 5. Paul Kwan, Mohsen Meydani.', 2009,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Angiogenesis is necessary for the growth of adipose tissue. Dietary polyphenols may suppress growth of adipose tissue through their antiangiogenic activity and by modulating adipocyte metabolism. We investigated the effect of curcumin, the major polyphenol in turmeric spice, on angiogenesis, adipogenesis, differentiation, apoptosis, and gene expression involved in lipid and energy metabolism in 3T3-L1 adipocyte in cell culture systems and on body weight gain and adiposity in mice fed a high-fat diet (22%) supplemented with 500 mg curcumin/kg diet for 12 wk. Curcumin (5–20 µmol/L) suppressed 3T3-L1 differentiation, caused apoptosis, and inhibited adipokine-induced angiogenesis of human umbilical vein endothelial cells. Supplementing the high-fat diet of mice with curcumin did not affect food intake but reduced body weight gain, adiposity, and microvessel density in adipose tissue, which coincided with reduced expression of vascular endothelial growth factor (VEGF) and its receptor VEGFR-2. Curcumin increased 5&#39;AMP-activated protein kinase phosphorylation, reduced glycerol-3-phosphate acyl transferase-1, and increased carnitine palmitoyltransferase-1 expression, which led to increased oxidation and decreased fatty acid esterification. The in vivo effect of curcumin on the expression of these enzymes was also confirmed by real-time RT-PCR in subcutaneous adipose tissue. In addition, curcumin significantly lowered serum cholesterol and expression of PPAR? and CCAAT/enhancer binding protein a, 2 key transcription factors in adipogenesis and lipogenesis. The curcumin suppression of angiogenesis in adipose tissue together with its effect on lipid metabolism in adipocytes may contribute to lower body fat and body weight gain. Our findings suggest that dietary curcumin may have a potential benefit in preventing obesity.', '{"arp_id": "ARP_AYU007477", "portal_id": 7477, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "139", "issue": "5", "pages": "919 - 925", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["3T3-L1 Adipocytes"], "original_url": "http://jn.nutrition.org/content/139/5/919.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7477", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007477.pdf", "pdf_sha256": "faeda37d35b1deb74c79d84987768c73f15c8c805bf7805627cb0e901be1d8c3", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '19321585', '10.3945/jn.108.102772', 'DIETARY CURCUMIN AND LIMONIN SUPPRESS CD4 T-CELL PROLIFERATION AND INTERLEUKIN-2 PRODUCTION IN MICE1-3', '4,5,7. Wooki Kim,4, 4,5. Yang-Yi Fan, 6. Roger Smith, 7. Bhimanagouda Patil, 7. Guddadarangavvanahally K. Jayaprakasha, 4,5,8,9. David N. McMurray, 4,5,7,8.Robert S. Chapkin.', 2009,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Phytochemicals may reduce chronic inflammation and cancer risk in part by modulating T-cell nuclear factor-?B (NF-?B) activation. Therefore, we examined the effects of curcumin (Cur) and limonin (Lim) feeding on NF-?B–dependent CD4+ T-cell proliferation. DO11.10 transgenic mice (n = 5–7) were fed diets containing 1% Cur or 0.02% Lim combined with either (n-6) PUFA [5% corn oil (CO)] or (n-3) PUFA [4% fish oil+1% corn oil (FO)] for 2 wk, followed by splenic CD4+ T-cell isolation and stimulation with ovalbumin peptide 323–339 (OVA) and antigen-presenting cells from mice fed a conventional nonpurified rodent diet. Both Cur and Lim diets suppressed (P &amp;lt; 0.05) NF-?B p65 nuclear translocation in activated CD4+ T-cells. In contrast, activator protein-1 (c-Jun) and nuclear factor of activated T-cells c1 were not affected compared with the CO control diet (no Cur or Lim). CD4+ T-cell proliferation in response to either mitogenic anti-CD3/28 monoclonal antibodies (mAb) or antigenic stimulation by OVA was also suppressed (P &amp;lt; 0.05) by Cur as assessed by carboxyfluorescein succinimidyl ester staining. In contrast, interleukin-2 production was not directly associated with NF-?B status. Interestingly, dietary combination with FO enhanced the suppressive effects (P &amp;lt; 0.05) of Cur or Lim with respect to CD4+ T-cell proliferation in response to anti-CD3/28 mAb. These results suggest that combination chemotherapy (FO+Cur or Lim) may favorably modulate CD4+ T-cell–mediated inflammation.', '{"arp_id": "ARP_AYU007478", "portal_id": 7478, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "139", "issue": "5", "pages": "1042 - 1048", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cd4+"], "original_url": "http://jn.nutrition.org/content/139/5/1042.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7478", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007478.pdf", "pdf_sha256": "0d22578fc1ef4b0b0ed4a1ecd086ca5e7a7f1f395c54a074af8116c93e29a918", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16046709', '10.1093/jn/135.8.1859', 'CURCUMIN BLOCKS INTERLEUKIN-1 (IL-1) SIGNALING BY INHIBITING THE RECRUITMENT OF THE IL-1 RECEPTOR-ASSOCIATED KINASE IRAK IN MURINE THYMOMA EL-4 CELLS1', 'Nadine Jurrmann, Regina Brigelius-Flohe, 1,2. Gaby-Fleur Bo.', 2005,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Curcumin is a dietary compound with diverse anti-inflammatory and anticarcinogenic effects in several experimental models. A mechanism by which curcumin exerts these actions might be the direct modification of protein thiols, thereby altering the activity of the affected proteins. An early event in inflammatory signaling cascades is the recruitment of the interleukin-1 (IL-1) receptor–associated kinase (IRAK) to the IL-1 receptor (IL-1RI) upon stimulation with IL-1. IRAK recruitment was shown recently to be inhibited by agents that modify thiols of IRAK. We asked, therefore, whether IRAK is also a target for curcumin. Curcumin indeed blocked IRAK thiols in a murine T-cell line stably overexpressing IRAK (EL-4IRAK), which resulted in the inhibition of IRAK recruitment to the IL-1RI and phosphorylation of IRAK and IL-1RI-associated proteins. Inhibitory effects were not reversible by thiol-reducing agents. Thus, modification by curcumin did not occur by oxidation but rather by alkylation, as is typical for electrophilic compounds reacting as Michael addition acceptors. The block in one of the earliest events in the IL-1 signaling cascade can explain the often observed inhibition of IL-1-mediated signaling steps by curcumin further downstream. Hence, thiol modification might be a crucial step in the anti-inflammatory functions of curcumin.', '{"arp_id": "ARP_AYU007480", "portal_id": 7480, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "135", "issue": "8", "pages": "1859 - 1864", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Curcumin"], "original_url": "http://jn.nutrition.org/content/135/8/1859.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7480", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007480.pdf", "pdf_sha256": "e445b345e6940deba0b482160eb8885e09c245ce3a9b0a4c8eeb146e4a815b89", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '11481399', '10.1093/jn/131.8.2090', 'CURCUMIN AND ESPECIALLY TETRAHYDROCURCUMIN AMELIORATE OXIDATIVE STRESS- INDUCED RENAL INJURY IN MICE', 'Kunihiko Okada, Chantima Wangpoengtrakul, Tomoyuki Tanaka, Shinya Toyokuni, Koji Uchida, 1. Toshihiko Osawa.', 2001,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Protective effects of curcumin (U1), one of the major yellow pigments in turmeric and its derivative, tetrahydrocurcumin (THU1), against ferric nitrilotriacetate (Fe-NTA)-induced oxidative renal damage were studied in male ddY mice. Single Fe-NTA treatment (5 mg Fe/kg body intraperitoneally) transiently causes oxidative stress, as shown by the accumulation of lipid peroxidation products and 8-hydroxy-2&#39;-deoxyguanosine in the kidney. Mice were fed with a diet containing 0.5 g/100 g U1 or THU1 for 4 wk. THU1 significantly inhibited 2-thiobarbituric acid reactive substances and 4-hydroxy-2-nonenal-modified proteins and 8-hydroxy-2&#39;-deoxyguanosine formation in the kidney; U1 inhibited only 4-hydroxy-2-nonenal-modified protein formation. To elucidate the mechanisms of protection by U1 and THU1, the pharmacokinetics and radical-scavenging capacities of U1 and THU1 were investigated by HPLC and electron spin resonance spin trapping with 5,5-dimethyl-1-pyrroline-N-oxide, respectively. Induction of antioxidant enzymes was also investigated. The amounts of THU1 and its conjugates (as sulfates and glucuronides) in the liver and serum were larger in the THU1 group than in the U1 group. The amounts of U1 and its conjugates were small even in the U1 group. These results suggest that THU1 is more easily absorbed from the gastrointestinal tract than U1. Furthermore, THU1 induced antioxidant enzymes, such as glutathione peroxidase, glutathione S-transferase and NADPH: quinone reductase, as well as or better than U1 and scavenged Fe-NTA-induced free radicals in vitro better than U1. These results suggest that U1 is converted to THU1 in vivo and that THU1 is a more promising chemopreventive agent.', '{"arp_id": "ARP_AYU007481", "portal_id": 7481, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "131", "issue": "8", "pages": "2090 - 2095", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Curcumin"], "original_url": "http://jn.nutrition.org/content/131/8/2090.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7481", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007481.pdf", "pdf_sha256": "d5dd86d93e6394db6dee5541e6bfe66b3f0a91a07ac2f917625c130de0f9b7a6", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '16251604', '10.1093/jn/135.11.2517', 'REDUCED ADIPOSITY IN BITTER MELON (MOMORDICA CHARANTIA)–FED RATS IS ASSOCIATED WITH INCREASED LIPID OXIDATIVE ENZYME ACTIVITIES AND UNCOUPLING PROTEIN EXPRESSION', 'Laureen L. Y. Chan, Qixuan Chen, Adi G. G. Go, Emily K. Y. Lam, 2. Edmund TSLi', 2005,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: To further explore the antiobesity effect of freeze-dried bitter melon (BM) juice, activities of mitochondrial lipid oxidative enzymes as well as the expression of uncoupling proteins and their transcription coactivator peroxisome proliferator-activated receptor-? coactivator-1 a (PGC-1a) were determined in diet-induced obese (DIO) rats. Rats were fed high-fat (HF) diets to induce obesity, and the effect of BM was assessed at doses of 0.75, 1.0, or 1.25% (wt:wt). In a dose-response experiment, BM-supplemented rats had lower energy efficiency (g weight gained/kJ consumed), visceral fat mass, serum glucose, and insulin resistance index, but higher plasma norepinephrine than unsupplemented rats (P &amp;lt; 0.05). Hepatic and skeletal muscle triglyceride concentrations were lower in supplemented HF diet–fed rats than in unsupplemented HF diet–fed rats (P &amp;lt; 0.05). An HF diet supplemented with BM elevated activities of hepatic and muscle mitochondrial carnitine palmitoyl transferase-I (CPT-I) and acyl-CoA dehydrogenase (AD) (P &amp;lt; 0.05). In another experiment, BM (1.0 g/100 g) lowered visceral fat mass but increased serum adiponectin concentration in HF diet–fed rats (P &amp;lt; 0.05). In the final study, rats were fed the HF diet with 0, 1.0 or 1.25% BM. Both groups of BM-supplemented rats had higher uncoupling protein 1 in brown adipose tissue (P &amp;lt; 0.05) and uncoupling protein 3 in red gastrocnemius muscle (P &amp;lt; 0.05), measured by Western blotting and RT-PCR, than the controls. The expression of the transcription coactivator PGC-1a in both tissues was also significantly elevated in the BM-supplemented rats (P &amp;lt; 0.05). The present results suggest that decreased adiposity in BM-supplemented rats may result from lower metabolic efficiency, a consequence of increased lipid oxidation and mitochondrial uncoupling.', '{"arp_id": "ARP_AYU007483", "portal_id": 7483, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "135", "issue": "11", "pages": "2517 - 2523", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Acyl-Coa Dehydrogenase"], "original_url": "http://jn.nutrition.org/content/135/11/2517.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7483", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007483.pdf", "pdf_sha256": "5b03ed6bf8b63850a0bd59e5346a03099d9f02ff5bb8696e7e20ca99811af83b", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '15795421', '10.1093/jn/135.4.702', 'MICROSOMAL TRIGLYCERIDE TRANSFER PROTEIN GENE EXPRESSION AND APOB SECRETION ARE INHIBITED BY BITTER MELON IN HEPG2 CELLS1,2', 'Pratibha V. Nerurkar, Laurel Pearson, Jimmy T. Efird, Khosrow Adeli, Ane G. Theriault, Vivek R. Nerurkar.', 2005,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Momordica charantia or bitter melon is traditionally used as an antidiabetic agent in Asia, Africa, and South America. Recent studies indicate that bitter melon can also lower plasma lipids and VLDL in diabetic animal models as well as animals fed a high-fat diet, suggesting an effect on lipoprotein metabolism. The aim of this study was to delineate the cellular and molecular mechanisms involved in the lipid-lowering properties of bitter melon and regulation of apolipoprotein B (apoB). Human hepatoma cells, HepG2, treated with bitter melon juice (BMJ) for 24 h reduced apoB secretion with and without the addition of lipids (P &amp;lt; 0.05). However, BMJ did not increase apoB secretion in cells treated with N-acetyl-leucyl-leucyl-norleucinal, indicating a lack of effect on the proteasomal degradation pathway. BMJ reduced the secretion of new triglycerides (P &amp;lt; 0.05) and decreased microsomal triglyceride transfer protein (MTP) mRNA expression, suggesting that lipid bioavailability and lipidation of lipoprotein assembly are likely involved in decreased apoB secretion. Interestingly, BMJ increased the nuclear translocation of the mature form of sterol regulatory element-binding protein-1c (SREBP-1c, P &amp;lt; 0.05), involved in MTP secretion. Our data suggest that BMJ is a potent inhibitor of apoB secretion and TG synthesis and secretion that may be involved in the plasma lipid- and VLDL-lowering effects observed in animal studies.', '{"arp_id": "ARP_AYU007485", "portal_id": 7485, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "135", "issue": "4", "pages": "702 - 706", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Apolipoprotein B"], "original_url": "http://jn.nutrition.org/content/135/4/702.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7485", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007485.pdf", "pdf_sha256": "b708beef421ec558242b319406273d139cdb758e64b8ab2194eea71d585e0de1", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '12840173', '10.1093/jn/133.7.2171', 'GARLIC (ALLIUM SATIVUM L.) MODULATES CYTOKINE EXPRESSION IN LIPOPOLYSACCHARIDE-ACTIVATED HUMAN BLOOD THEREBY INHIBITING NF-KB ACTIVITY1', 'Hans-Peter Keiss, 2. Verena M. Dirsch, 2. Thomas Hartung, 3. Thomas Haffner, 4. Laurence Trueman, 5. Jacques Auger, 6. Remi Kahane, Angelika M. Vollmar.', 2003,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Garlic is proposed to have immunomodulatory and anti-inflammatory properties. This paper shows that garlic powder extracts (GPE) and single garlic metabolites modulate lipopolysaccharide (LPS)-induced cytokine levels in human whole blood. GPE-altered cytokine levels in human blood sample supernatants reduced nuclear factor (NF)-?B activity in human cells exposed to these samples. Pretreatment with GPE (100 mg/L) reduced LPS-induced production of proinflammatory cytokines interleukin (IL)-1ß from 15.7 &amp;#177; 5.1 to 6.2 &amp;#177; 1.2 µg/L and tumor necrosis factor (TNF)-a from 8.8 &amp;#177; 2.4 to 3.9 &amp;#177; 0.8 µg/L, respectively, whereas the expression of the anti-inflammatory cytokine IL-10 was unchanged. The garlic metabolite diallydisulfide (1–100 µmol/L) also significantly reduced IL-1ß and TNF-a. Interestingly, exposure of human embryonic kidney cell line (HEK293) cells to GPE-treated blood sample supernatants (10 or 100 mg/L) reduced NF-?B activity compared with cells exposed to untreated blood supernatants as measured by a NF-?B-driven luciferase reporter gene assay. Blood samples treated with extract obtained from unfertilized garlic (100 mg/L) reduced NF-?B activity by 25%, whereas blood samples treated with sulfur-fertilized garlic extracts (100 mg/L) lowered NF-?B activity by 41%. In summary, garlic may indeed promote an anti-inflammatory environment by cytokine modulation in human blood that leads to an overall inhibition of NF-?B activity in the surrounding tissue.', '{"arp_id": "ARP_AYU007744", "portal_id": 7744, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "133", "issue": "7", "pages": "2171 - 2175", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cytokines"], "original_url": "http://jn.nutrition.org/content/133/7/2171.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7744", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007744.pdf", "pdf_sha256": "0d86acf089d5c9f881c87abcd531880bf74d823520d2b92c41fd5f07758f2266", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL STUDY ON BALASHOSHA WITH SPECIAL REFERENCE TO PROTEIN ENERGY MALNUTRITION BY SHOSHAJID GHRITA', '1. Sangita Prusty, 2. Mahena Singh, 3. Ajit Kumar Shasamal, 4. Richa Singh, 5. Ishwar Chana Rai.', 2014,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Children are the most important and crucial segment of our population. During these formative years foundation is laid for adult life. Moreover, the quality of our future human-resource is going to be determined largely by these children. Thus the well being of these children, on the threshold of physical and sexual maturity is vital for national development. This study includes preparation of shoshajid ghrita, chemical analysis of shoshajid ghrita, and clinical study on management of balashosha by shoshajid ghrita. According to UNICEF “The state of the world children” average and under 5 years mortality rate ranges from almost 200/1000 in least developed countries to less than 9/1000 in developed countries. Infant mortality rate in India is very high as reported, i.e. 95 per 1000 live births. It was 68 per 1000 live births in 2000. A malnourished child dies at every one second. India is the second most populous country in the world with the population 1.47 billion. 47% of the children under three years of age are malnourished over 200 million children in developing countries to more than half of the nearly 12 million under five death in developing countries each year. In the present work an attempt has been made to establish the efficacy of the drug shoshajid ghrita to manage the disease balashosha and also Protein Energy Malnutrition (PEM), which is a major public health problem in today’s society.', '{"arp_id": "ARP_AYU008598", "portal_id": 8598, "medical_system": "AYURVEDA", "journal": "World Journal of Pharmacy and Pharmaceutical Sciences", "volume": "3", "issue": "2", "pages": "2049 - 2058", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "VITAMIN/NUTRITIONAL DEFICIENCY(ICPC-T91|ICD-E40, E41, E42, E43, E44, E45, E46, E50, E51.1, E51.8, E51.9, E52, E53, E54, E55, E56, E58, E59, E60, E61, E63, E64)", "keywords": ["Balashosha"], "original_url": "http://wjpps.com/wjpps_controller/abstract_id/876", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8598", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008598.pdf", "pdf_sha256": "63c2f68414a51ddeacfc0f60b8f4ce562a415a9594de3da0baf8fe622776f6c7", "relevance_score": 41.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'STUDY ON THE IMMUNO-MODULATORY EFFECT OF HERBAL EXTRACT OF ASPARAGUS RACEMOSUS WILLD. IN BROILER CHICKS', '1. Kumari R, 1. Tiwary BK, 1. Prasad A, 2. Ganguly S.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present study was carried out to determine the immuno-modulatory effects of Asparagus racemosus extract treated feed and to analyze the role of T and B cells in host defense against Newcastle disease in one week old normal and immuno-compromized broiler chicks. After the treatment significant (P&amp;lt;0.01) positive effects were observed in both humoral and cell mediated immune responses of the birds which was found to be evident by increased antibody titer after Hemagglutination inhibition (HI) test. The variation in skin thickness was significantly (P&amp;lt;0.01) more among the herbal treated groups rather than the non-treated groups which was a clear marker for immuno-stimulation among the birds.', '{"arp_id": "ARP_AYU000536", "portal_id": 536, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "1", "issue": "1", "pages": "1 - 6", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Asparagus Racemosus"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=536", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000536.pdf", "pdf_sha256": "f6500a276ea97be7b0ff598d98bd4ec31041004a29fbc29b3c9c28df8285d6ae", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'MALARIA: NOVEL PLANT REMEDIES SHOW GREAT PROMISE IN TREATING THE DEADLY DISEASE', '1. Taba KM, 2. Paulus J, 1. Kayembe JS.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Clinical investigation of eight plant remedies used as traditional medicines in Kinshasa, D.R. Congo, to treat Malaria patients showed significant removal of parasites in the blood, as well as elimination of clinical detection of disease. The percentage recovery from Malaria depends on the type of remedy chosen: Cassia occidentalis Linn. (97%), Carica Papaya Linn. (94%), Cymbopogon citratus (DC.) Staff, 1906 (93%), Garcinia kola Heckel. (94%), Lantana camara L. (90%), Ocimum gratissimum L. (86%), Phyllanthus niruri L. (93%) and Vernonia amygdalina Delile. (67%). No identifiable side effects were noticed during and after treatment. In vitro study of alcohol extracts of these remedies showed an inhibition concentration of Plasmodium growth of 83% (12.5 6g/ml) for C. occidentalis Linn., 91% (25 6g/ml) for C. Papaya Linn., 93% (25 6g/ml) for C. citratus (DC.) Staff, 1906, 93% (25 6g/ml) for L. camara L., 100% (12.5 6g/ml) for O. gratissimum L., 100% (12.56g/ml) for P. niruri L. and 0% (25 6g/ml) for V. amygdalina Delile. Secondary metabolites were isolated from some plant remedies and their IC50 determined in vitro on P. falciparum. The highest IC50 was observed in alkaloid extract of P. niruri L. (8 6g/ml); terpenes extract of O. gratissimum L. (0.276g/ml); quinone extract of G. kola Heckel. (1.02 6g/ml) and flavonoid extract of G. kola Heckel. (1.56g/ml).', '{"arp_id": "ARP_AYU000542", "portal_id": 542, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "1", "issue": "3", "pages": "62 - 68", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "GENERAL/UNSPECIFIED", "disease": "MALARIA(ICPC-A73|ICD-B50, B51, B52, B53, B54)", "keywords": ["1906"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=542", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000542.pdf", "pdf_sha256": "a10f18f17c5360924530ad6634d1c76cdef9be6894556af96835eaef02f3575b", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECTS OF COMBINING CRUDE ETHANOLIC EXTRACT OF JATROPHA CURCUS L. LEAF AND SOME ANTIBIOTICS AGAINST SOME SELECTED MICROORGANISMS', '1. Akanwariwiak WG, 1. Addo-Fordjour P, 1.Musah AA.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Evidences are mounting concerning the resistance of microorganisms to antibiotics throughout the world. This development has awakened scientists to explore alternative approaches that target and block resistance. One way of accomplishing this has been the combination of plant extracts with antibiotics to increase their activity. The study was therefore, aimed at determining the effects of combining the leaf extract of Jatropha curcas L. with some antibiotics on certain selected microorganisms. The antimicrobial activity of the ethanolic extract of J. curcas leaf and its combination with selected antibiotics was assessed against certain microorganisms using the agar well diffusion method. The diameter of inhibition zone and minimum inhibitory concentration (MIC) were used as indicators of antimicrobial activity. The plant extract alone showed antimicrobial activity against all the test organisms, with diameter of inhibition zone ranging from 2–13.7 mm. The diameter of inhibition zone of the antibiotics alone ranged from 3.7–23 mm. The activity of the antibiotics varied upon combination with the plant extract, but the diameter of inhibition zone was between 6 and 25 mm. The antimicrobial activity of ciprofloxacin was increased significantly (MICs reduced significantly) when combined with the plant extract whereas that of tetracycline was reduced. In all, ciprofloxacin and ciprofloxacin-plant extract were the most effective treatments recording the lowest MICs. The most significant reduction of MICs was observed in the ciprofloxacin-plant extract combination.', '{"arp_id": "ARP_AYU000614", "portal_id": 614, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "1", "issue": "6", "pages": "140 - 148", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antimicrobial Activity"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=614", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000614.pdf", "pdf_sha256": "a56ea29fccd8ee7e1cada1e427b1196a65bbf6606eaf0cb3c9ddf63485f97ad1", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'IN VITRO ANTIFUNGAL ACTIVITY OF THE ETHANOLIC EXTRACT OF CERTAIN INDIAN MEDICINAL PLANTS.', 'Javid Iqbal Pandith.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Natural resources have since antiquity been extensively exploited for medicinal purposes. Numerous plant materials have been employed in folk medicine in attempts to control diseases. In many countries around the world the use of medicinal plants still contributes significantly in primary health care. Although there is currently little scientific evidence regarding the efficacy of such treatments, traditional medicine is still widely practiced by people living all over the world. The present study was designed to evaluate the antifungal activity of ethanolic extract of various plant species obtained from various regions and were assayed for in-vitro antifungal activity against human dermatophytes viz: Microsporum gypseum and Trichophyton mentragrophytes. The solvent extract of the plant material was made through Soxehlet Apparatus and was run up to 48 hrs and was tested in two opposite concentrations. Results obtained reveal that the 1:5 concentration of plant material to that of nutrient Broth medium was more effective against dermatophytes as compared to 2:5 ratio. The maximum inhibition was shown by Lindenbergia indica (46.51 %) against Microsporum gypseum in the ratio 1:5, whereas against Trichophyton mentragrophytes was shown by Achyranthus aspera (63.15 %) at the same concentration. However maximum inhibition in the ratio 2:5 against Microsporum gypseum and Trichophyton mentragrophytes was shown by Parthenium hysterophorus (37.20 %) and Lindenbergia indica (52.63 %) respectively.', '{"arp_id": "ARP_AYU000888", "portal_id": 888, "medical_system": "AYURVEDA", "journal": "International Journal of Pharma Research & Review", "volume": "1", "issue": "1", "pages": "16 - 20", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antifungal Activity"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=888", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000888.pdf", "pdf_sha256": "e6b3925f2a091b4d949e1f5fac63502355108d6f982682ff67d1265d21503075", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'INDUCTION OF APOPTOSIS IN MYELOGENOUS LEUKEMIC K562 CELLS BY ETHANOLIC LEAF EXTRACT OF ANNONA MURICATA L.', '1. Ezirim AU, 2. Okochi V I, 3. James AB, 4. Adebeshi OA, 5. Ogunnowo S, 6. Odeghe OB.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Prevalence of cancer, especially in Nigeria, is silently growing at exponential rates due to its nature and numerous risk factors associated with its development. Most chemotherapeutic drugs used today are expensive and toxic to normal cells, hence the need for alternative treatment options. In this present study, the efficacy of ethanolic extracts of Annona muricata leaves for its cytotoxicity potential and induction of apoptosis in K562 cancer cells, was investigated. Phytochemical screening verified presence of alkaloids, tannins, flavonoids, saponins, anthraquinones and cardiac glycosides. Using Neutral red uptake assay, the ethanolic extract showed peak cytotoxicity levels (P&amp;lt;0.001) at 2.5 mg/ml which decreased with increased concentrations. Caspase-3 activity was significantly enhanced (P&amp;lt;0.001) during apoptosis induced by the extract at low quantities, with the peak activity shown at 50 µg/ml. Apoptosis was confirmed by terminal deoxynucleotidyl transferase-mediated dUTP nick-end labelling (TUNEL) assay. Caspase-3 activity and TUNEL results suggested that the ethanolic extract of Annona muricata induced apoptosis in the myelogenous leukemic K562 cell line. This supports the therapeutic application of Annona muricata to be considered as a natural product source for the development of pro-apoptotic drugs.', '{"arp_id": "ARP_AYU001492", "portal_id": 1492, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "2", "issue": "3", "pages": "142 - 151", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Apoptosis"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1492", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001492.pdf", "pdf_sha256": "fff13c1a686127cff7ab7af0dff13e5b9e88a81ec0711e3211cd3899f3cd5de0", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTICATARACT ACTIVITY OF ERVATAMIA CORONARIA LEAF EXTRACT ON CHEMICALLY INDUCED CATARACTOGENESIS IN RATS', '1. Rathnakumar K, 2. Jaikumar S, 3. Duraisami R, 4. Sengottuvelu S.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The anticataract activity of the Ervatamia coronaria leaf extract was evaluated against naphthalene induced cataract in Wistar albino rats. Thirty rats in five groups were used for the study. Ervatamia coronaria leaf extract at dose levels (200 and 400 mg/kg) respectively and Vitamin E (50 mg/kg) were used as standard drugs while liquid paraffin was used for control. The test drugs were administered simultaneously with naphthalenefor 25 days. Naphthalene (0.5 g/kg for first 3 days and 1 g/kg thereafter for a period of 25 days) was used to induce cataract. The percentage of cataract incidence and opacity index were examined using ophthalmoscope. Naphthalene produced a marked mature cataract and an increase in the opacity index at various stages. The extract treated animals showed decrease in the onset and maturation of cataract against naphthalene challenge. From the results it was concluded that Ervatamia coronaria leaf extract protected the cataract maturation induced by naphthalene and it exhibited anticataract activity.', '{"arp_id": "ARP_AYU001497", "portal_id": 1497, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "2", "issue": "4", "pages": "213 - 218", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cataract"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1497", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001497.pdf", "pdf_sha256": "466a45c2b79e5e862cde6305a05f4f950e854e7c7817e1b6c1e50ef68ced2847", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'NATURAL PLANT PRODUCT BERBERINE/CISPLATIN BASED RADIOTHERAPY FOR CERVICAL CANCER: THE NEW AND EFFECTIVE METHOD TO TREAT CERVICAL CANCER', '1. Komal, 2. Singh Mayank, 3. Deshwal Vishal kumar.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Cervical cancer is the site of excessive inflammation which leads to extensive DNA damage and thus promotes carcinogenesis. Existing treatment regime for cervical cancer is radiotherapy along with platinum based drugs like cisplatin and carboplatin but it is associated with various side effects to normal cells and problem of radio-resistance. Berberine is a natural chemo-preventive agent extracted from Berberis aristata that has been shown to suppress and retard carcinogenesis by inhibiting inflammation. In this study we compared the cisplatin based radiotherapy with a Berberine/cisplatin based radiotherapy in cervical cancer in vitro. Treatment of cervical cancer cell lines SiHa and CaSki with Berberine/cisplatin combination followed by treatment by ionizing radiation (IR) resulted in increased apoptosis in comparison to cisplatin based radiotherapy. The combination therapy of Cisplatin/Berberine/IR resulted in upregulation of pro apoptotic proteins like Bax, p73 and down regulation of anti apoptotic Bcl Xl, inflammatory Cox 2, Cyclin D1 accompanied by increase in activity of Caspase -9 and -3. Reduction in Telomerase activity was also seen in all the HPV positive cells.', '{"arp_id": "ARP_AYU001504", "portal_id": 1504, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "2", "issue": "5", "pages": "278 - 291", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Berberine"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1504", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001504.pdf", "pdf_sha256": "3b26dfee3c4608690779a17c8f76a9bfffb5dd71f73e82ed4d22970ce4d1e07b", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PHYTOCHEMICAL ANALYSIS AND ANTIOXIDANT ACTIVITY OF THREE ETHNO MEDICINAL PLANTS OF PACHAIMALAIS, TIRUCHIRAPPALLI DISTRICT, TAMIL NADU', '1. Rekha S, 2. Parvathi A.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Pachaimalai, an unique hill of Tiruchirappalli district is situated in the Southern parts of the Eastern Ghats in Tamil Nadu, India. It is endowed with rich medicinal flora. The Malayali Gounder Tribes are the inhabitants of the hills who inherited rich traditional knowledge about curing properties of the hill flora. The present work was focused on the evaluation of phytochemical constituents and antioxidant activity of the leaves and fruits of Naravelia zeylanica, (L.) DC., Cardiospermum canescens, Wall. and Mallotus philippinensis, Muell. Arg. that are used by these tribes to cure wounds, herpes, viral and bacterial diseases. The phytochemical analysis revealed the presence of various phytochemicals like alkaloids, amino acids, flavonoids, indoles, phenols, polyphenolases, saponins, steroids, tannins and triterpenoids. Further, the quantitative estimation of phytoconstituents also showed markedly high amount of flavonoids, phenols, saponins, tannins, amino acids and sugars. The antioxidant activity of methanolic extracts evaluated by Diphenyl picryl hydrazyl (DPPH) free radical scavenging activity revealed rich amount of antioxidant content in the selected plants. The paper deals with the significance of these three plants in traditional medicine with respect to their phytochemicals.', '{"arp_id": "ARP_AYU001538", "portal_id": 1538, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "1", "issue": "11", "pages": "599 - 611", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant Activity"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1538", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001538.pdf", "pdf_sha256": "5f18d7e8617a270bbf741a81cd4e5feeeb14fb5b1925f61c0410674ef29d4228", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF PHYTOCHEMICAL AND ANTIOXIDANT ACTIVITY OF SOME MEDICINAL PLANTS OF FAMILY AMARANTHACEAE', 'Neha Sharma, Parul Sharma, Rekha Vijayvergia.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present investigation was undertaken to screen preliminary phytochemical screening and antioxidant potential of two medicinally important plants of family Amaranthaceae. The crude powder of the plants gave different characteristic colors with different chemicals. The methanolic crude extracts of Digera muricata and Gomphrena celosioides were screened for their free radical scavenging properties by DPPH (1,1-diphenyl-2-picryl hydrazyl) radical scavenging assay. The maximum activity was observed in stem of G. celosioides and roots of D. muricata.', '{"arp_id": "ARP_AYU001695", "portal_id": 1695, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "5", "issue": "9", "pages": "4713 - 4715", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1695", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001695.pdf", "pdf_sha256": "55bd37019c0b4705105c52d4477adab9c0e2c2cf124121f6deb56911f067bcc1", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'WOUND HEALING ACTIVITY OF ETHANOLIC EXTRACT OF EUPHORBIA HIRTA LEAVES ON EXCISION WOUND MODEL IN RATS', '1. Rathnakumar K, 2. Verma Ranbir, 3. Jaikumar S, 4. Sengottuvelu S.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The study was conducted to evaluate the wound healing effect of Euphorbia hirta leaves on excision wound model in Wistar albino rats. The ethanolic extract of Euphorbia hirta leaf was formulated as an ointment for topical application (5% and 10% W/W). The wound healing activity of the Euphorbia hirta leaf extract was studied by using excision wound, which was inflicted by cutting away 500 mm2 of the skin on the anterio-dorsal side of the rats under anesthesia. Povidone iodine ointment was used as reference standard for comparing the wound healing potential of Euphorbia hirta. The wound contraction was observed at different time intervals. Both the concentrations of Euphorbia hirta leaf extracts showed significant (P&amp;lt;0.001) wound contraction on excision wound model in rats.', '{"arp_id": "ARP_AYU001832", "portal_id": 1832, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "2", "issue": "8", "pages": "571 - 575", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Euphorbia Hirta"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1832", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001832.pdf", "pdf_sha256": "1d2f93ef166b0426cfcaf19401e55a09f54750595f521c71827943a65c3eebed", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIMICROBIAL POTENTIAL AND PHYTOCHEMICAL ANALYSIS OF MEDICINAL PLANTS FROM LONAR LAKE', '1. Tambekar DH, 1.Tiwari BK, 1. Shirsat SD, 1. Jaitalkar DS.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Lonar lake is situated in Buldhana district of Maharashtra (India), is surrounded by dense forest constituting many plants with high medicinal values. Because of the high alkalinity and diverse atmospheric conditions, we have selected the area around the Lonar lake for determining the antibacterial potential and phytochemical analysis of the medicinal plants available at Lonar lake. The plants used for the study were Syzigium cumini, Ficus benghalensis, Cynodon dactylon, Justicia adhatoda, Calotropis gigantean, Ficus racemosa, Tinospora cardifolia, Achyranthes aspera, Ficus religiosa, Santalum ovatum and Ziziphus oenoplia against some enteric bacteria (Escherichia coli, Staphylococcus aureus, Salmonella typhi, Salmonella enterica, Enterobacter aerogenes, Proteus vulgaris, Pseudomonas aeruginosa, Klebsiella pneumonia) in vitro by agar disc diffusion technique. Out of these plants acetone extract of Syzigium cumini and Justicia adhatoda showed maximum antibacterial activity against E. coli and Sal. enterica. Alcohol extract of Syzigium cumini, Tinospora cordifolia and Cynodon dactylon also showed antibacterial activity against E. coli, P. vulgaris, Sal. typhi, Sal. enterica. Syzigium cumini and Santalum ovatum had shown maximum antibacterial activity against E. coli and Sal. enterica. The phytochemical analysis had showed the presence of carbohydrates and proteins in all the plants, Amino acids, Steroids, Glycosides, Flavonoids, Alkaloids and Tannins were also found in some of the plants. According to the findings, it was concluded that all the economically affordable easily available selected 11 plants from Lonar lake possesses antibacterial potential, and proved useful herbal drugs. These plants would serve as effective agents to reduce common health problems without causing any adverse reactions and side effects.', '{"arp_id": "ARP_AYU001897", "portal_id": 1897, "medical_system": "AYURVEDA", "journal": "International Journal of Life Sciences Biotechnology and Pharma Research", "volume": "2", "issue": "3", "pages": "204 - 211", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antimicrobial Activity"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1897", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001897.pdf", "pdf_sha256": "16f08c1a6bfa0e32e135b99b534a94195dbd2b7b67ae33b021a09abefce07fa1", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PHYTOCHEMICAL ANALYSIS OF SOME INDIGENOUS WOUND HEALING PLANTS', '1. Jagan Mohan Reddy P, 2. Ismail Shareef M, 3. Gopinath SM, 4. Dayananda SK, 5. Ajay Mandal, 6. Purushotham KM.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Present investigation has been evaluated to find out active constituents of some indigenous plants such as Calotropis procera, Ricinus communis and Mentha piperita potent against ectoparasite. The results revealed that the % yield of Calotropis procera, Ricinus communis and Mentha piperita was 10.23, 22.79, 14.46 respectively and physical characteristic was sticky solid, dark greenish, agreeable in Calotropis procera, semi-solid, dark greenish, agreeable in Ricinus communis however, sticky semi solid, dark greenish, characteristic organic in Mentha piperita. The plants having alkaloids, saponins, flavonoids, glycosides, carbohydrates, fixed oils and fats, tannins and phenolic compounds as main active constituents in all the three plants which is very useful for preparing drug development against wound healing.', '{"arp_id": "ARP_AYU001960", "portal_id": 1960, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "3", "issue": "3", "pages": "101 - 104", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["% Yields"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1960", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001960.pdf", "pdf_sha256": "aa3bf3f44b7f61dbd3c31aa6f10088202b82d55c4118ee970bb72fa495a777f6", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'WOUND HEALING ACTIVITY OF ALOCASIA MACRORRHIZOS L G.Don PLANT - AN EXPERIMENTAL STUDY', 'Santosh kumar singh, Sonia Thakur, Neha Shukla, Sanju Singh.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: A tissue injury is invariably followed by varying degree of inflammatory changes in lipid peroxidation levels during different stages of cutaneous wound repair have been investigated earlier. It is observed that any drug that reduces the generation of free radicals by a drug (herbal or otherwise) during proliferative phase is a wound healing agent. The wound healing potency of methanolic extract of leaf of Alocasia macrorrhizos was evaluated by excision, incision and histopathological wound model on albino mice the wound healing activity was assessed for wound contraction, period of epithelialization and skin breaking strength of granulation tissue. The result obtained in the study revealed that methanolic leaf extract has significant wound healing potency as compared to standard.', '{"arp_id": "ARP_AYU002138", "portal_id": 2138, "medical_system": "AYURVEDA", "journal": "Global Journal of Research on Medicinal Plants & Indigenous Medicine", "volume": "3", "issue": "10", "pages": "381 - 388", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alocasia Macrorrhizos"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2138", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002138.pdf", "pdf_sha256": "692828b8b68c6a2efacdd38c66aa9d3dd46d9f7d03e4002e8ff840c1546a94a3", "relevance_score": 41.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A CLINICAL STUDY ON THE EFFICACY OF A HERBAL FORMULATION IN MADHUMEHA (DIABETES MELLITUS) W.S.R. TO ITS HYPOGLYCAEMIC EFFECT', '1. Shefali, 2. K. Govardhan.', 2011,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Madhumeha (Diabetes Mellitus) is non communicable fastest growing global pandemic and India is having maximum number of diabetics worldwide. The present study was single blind single group study with pretest and post test design. The study was undertaken to assess the efficacy of herbal formulation in Management of Madhumeha (Diabetes Mellitus) w.s.r. to its Hypoglycaemic effect. The study drug in current project was found highly effective in reducing Hyperglycaemia.', '{"arp_id": "ARP_AYU000125", "portal_id": 125, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "5", "issue": "3", "pages": "36 - 43", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes Mellitus"], "original_url": "https://journals.lww.com/joay/citation/2011/05030/joa_v_july_september_2011.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=125", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000125.pdf", "pdf_sha256": "424ddaf00336fa182700bfba6f3e923989adf468597fd3033ae22cad9f306309", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PILOT STUDY TO COMPARE TWO INDIGENIOUS DRUGS IN TYPE-II DIABETES MELLITUS W.S.R. MADHUMEHA', '1. Kashinath. Samagandi, 2. Jagriti Sharma, 3. Kamalesh Kumar Sharma, 4. Shiva Kumar, 5. Tapas Brata Tripathy.', 2011,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: It is a pilot study conducted on patients of Diabetes mellitus Type II which shows signs and symptoms similar to Madhumeha, which comes under the Vataja type of Prameha. This is the preliminary study conducted over the 10 subjects before trying over the larger samples. This study was taken by seeing the present statistics of the incidence and prevalence of diabetes mellitus in the community. Two indigenous drugs are, one is Whaet grass in the form of juice and another is the Nisha Amalaki compound in the form of the 500 mg tablets. Logic behind the selection of the wheat grass is by influence of traditional practice by rural peoples of Karnataka state, and Nisha amalaki by classical ayurveda excellance. Aims of the present study was to evaluate the anti-diabetic effect of Wheat grass juice and Nisha-Amalaki and to compare the effects of both Materials and methods of the study were planned on 2 groups .one group was administerd with Wheat grass juice, 2nd group with Nisha amalaki group. Result &amp;amp; Discussion of the study revealed that Wheat grass juice showed good result in relieving the subjective criteria&#39;s viz. Kshudhadhikyata, Daurbalya and Pipasadhikyata and objective criteria&#39;s FBS when compared to Nisha Amalaki group after 10 days.', '{"arp_id": "ARP_AYU000126", "portal_id": 126, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "5", "issue": "4", "pages": "64 - 68", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Madhumeha"], "original_url": "https://journals.lww.com/joay/citation/2011/05040/joa_v_october__december_2011.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=126", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000126.pdf", "pdf_sha256": "3fe161e20f46b23fd7816abec3d037197b22e2e4569454f90616a8d20654a6f1", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'THE CLINICAL STUDY TO EVALUATE EFFICACY OF PANCHATIKTA GHANA VATI & MUSTADI KWATHA IN THE MANAGEMENT OF MADHUMEHA W.S.R. TO DIABETES MELLITUS', '1. Nigam R, 2. Amit kumar Sharma, 3. Joshi RK, 4. Sharma AK.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Today the burden of diabetes is so high in india that our country is being called “the diabetes capital of the world”. Diabetes – “the rich man’s disease’ has become common among people of all economic classes, probably due to increase in adaptation of sedentary life style.It has turned out to be the biggest “silent killer” today in the world. In Madhumeha the patient passes urine which is sweet and astringent in test, whitish-pale in colour &amp;amp; unctuous. According to these properties of urine and etiological factors, clinical features, and pathogenesis, diabetes mellitus can be correlated with Mahumeha.According to International Diabetes Federation’s latest estimation, world prevalence of diabetes among adults (aged 20-79 years) were 6.4%, affecting 285 million adults, in 2010, and will increase to 7.7% and 439 million adults by 2030.The study was conducted on 38 clinically diagnosed patients of Diabetes Mellitus with an objective of clinical evaluation of the efficacy of Panchatikta Ghana Vati and Mustadi Kwatha in the management of Madhumeha. These patients were randomly divided into three groups of 12 in group I, 13 in group II and 13 in group III. 38 patients were registered for present clinical study but 8 patients was drop out in mid of therapy. Only 30 patients was completed all follow ups.Regarding overall improvement in clinical features of Madhumeha in Group I mild (36.70%) improvement was observed, moderate (58.39%) improvement in Group II &amp;amp; (70-45%) in Group III.The chosen drug was effective in reducing blood sugar&amp;amp; urine sugar both fasting and postprandial (in group I, II and group III) except in FBS &amp;amp; FUS in group I &amp;amp; significant in reducing GHb in group II &amp;amp; III &amp;amp;highly significant in reducing BMI &amp;amp; Body weight in group II &amp;amp; III of Madhumeha but significant reduction observed in group I.No adverse effects were noted in any of the patients during the trial period.', '{"arp_id": "ARP_AYU000166", "portal_id": 166, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "6", "issue": "4", "pages": "4 - 16", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes Mellitus"], "original_url": "https://journals.lww.com/joay/citation/2012/06040/joa_vi_october__december_2012.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=166", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000166.pdf", "pdf_sha256": "e41c3c6c19ca2e251f04d0601fd6a6ce91f4a4c90790526a1f934a6ea2352684", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIDIABETIC ACTIVITY OF STRYCHNUS POTATORUM LINN SEEDS AGAINST ALLOXAN INDUCED DIABETES MELLITUS IN RATS.', '1. Raghu S, Midhun T,1. Venkateswara Rao, 2. Chanasekar SB, 1. Jayakar B, 2. Sushma G.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Diabetes mellitus is a group of metabolic alterations characterized by hyperglycemia resulting from defects in insulin secretion, action or both. The present study was to identify the antidiabetic activity of ethanolic (EESP) and aqueous (AESP) extracts of Strychnos potatorum seeds against alloxan induced diabetes in rats. Results: The LD50 the extracts were found to be 2000 mg/kg b.w., p.o., The EESP and AESP extracts exhibited significant hypoglycemic and significant reductions in the biochemical parameters (Total cholesterol, Triglycerides, LDL and VLDL). The weight regain was also found to be significant in both the EESP as well as the AESP. Even though the study showed significant activity comparing with the standard glibenclamide, but activity of the extracts were found to be similar or slightly decreased as compared to the standard. The histopathology results confirmed the finds. These results showed the medicinal significance of the plant. Conclusion: The present study concluded that the Strychnos potatorum linn proved useful in the treatment of diabetes.', '{"arp_id": "ARP_AYU000640", "portal_id": 640, "medical_system": "AYURVEDA", "journal": "Journal of Pharmaceutical Research and Clinical Practice", "volume": "1", "issue": "1", "pages": "18 - 26", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "https://www.cabidigitallibrary.org/doi/full/10.5555/20123373984", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=640", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000640.pdf", "pdf_sha256": "836d9d5d8faa4b4e9b9abd1db8502899bcce3125e03ac40f38de0994f33d9d67", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIHYPERGLYCEMIC AND ANTIHYPERLIPIDEMIC EFFECT OF ETHYL ACETATE FLOWER EXTRACT OF CASSIA AURICULATA ON ALLOXAN INDUCED DIABETES IN MALE ALBINO RATS', '1. Syed Zameer Ahmed K, 1. Sivaraj A, 1. Vinoth kumar P, 1. Sundaresan S, 1. Natarajan A, 2. Devi K, 1. Abdul Rahuman A, 1. Senthil kumar B.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Cassia auriculata (Tamil: Avarai) is used extensively in the indigenous system of medicine as an anti-diabetic agent. The current investigation focuses on the serum insulin augmentation, anti-hyperglycemic and anti-hyperlipidemic property of ethyl acetate flower extract of C.auriculata on alloxan induced diabetes in male albino rats. The diabetes induced animals were fed with the flower extract at 350mg/ body wt. The ethyl acetate flower extract administrated animals revealed a significant (P&amp;lt;0.001) increment of serum insulin levels, higher reduction in hyperglycemia and hyperlipidemia when compared to the diabetic control rats (P&amp;lt;0.001). The histological studies of the endocrine region of pancreas of diabetic animals revealed shrinkage of &amp;#223;-cells of islets of langerhans. The ethyl acetate flower extract treated animals’ revealed restoration of &amp;#223;-cells.', '{"arp_id": "ARP_AYU000901", "portal_id": 901, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "3", "issue": "6", "pages": "1300 - 1303", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=901", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000901.pdf", "pdf_sha256": "78228f54ea80569f7ea18c71ba29df13cac7039a5f2c68d29d4b5c4462931728", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PROPHYLACTIC EFFECT OF SWIETENIA MAHAGONI JACQ SEEDS ON MULTIPLE LOW-DOSE STREPTOZOTOCIN INDUCED TYPE - I DIABETES IN MICE', '1. Sathish R, 2. Rani M, 3. Natarajan K, 4. Regupathi T, 1. Selvakumar S.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study investigated the protective effect of oral administration of Swietenia mahagoni seeds (Meliaceae) on the development of multiple low-dose of streptozotocin (MLDS) induced autoimmune Type1 diabetes in mice. The mice intraperitoneally injected with five daily sub-diabetogenic doses (40mg/kg) of streptozotocin (STZ) to develop hyperglycemia and pancreatic insulitis. The Ethanolic Extract of S. mahogany seeds (500mg/kg) were administered orally from 14days before and then continuously for next 7days after the first STZ injection. The blood and urine glucose levels were analyzed at 7,14 and 28th days after the first STZ injection. The prior chronic administration of S.mahagoni seeds (500mg/kg) significantly (P&amp;lt;0.05) prevented the prevalence of elevation in blood glucose level and there were no elevation in urine glucose level. Morphological examinations of the pancreas on day 28 of mice receiving S.mahagoni seeds prevented the infiltration of mononuclear cells into islets of MLDS mice. However the S.mahagoni seeds did not produce any hypoglycemic effect on normal mice. This study indicates S.mahagoni seeds may block the autoimmune process in the development of MLDS diabetes.', '{"arp_id": "ARP_AYU001068", "portal_id": 1068, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "3", "issue": "12", "pages": "3121 - 3122", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Mlds"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1068", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001068.pdf", "pdf_sha256": "951a2b27105475b2d587593ab511fc3aa64ef3cffa55b5d6dd3f61acba1274cf", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'THERAPEUTICAL EVALUATION OF SWIETENIA MAHAGONI JACQ. SEEDS AND SYZYGIUM CUMINI (LINN.) SKEELS. SEEDS IN MADHUMEHA WITH SPECIAL REFERENCE TO DIABETES MELLITUS - A COMPARATIVE STUDY', '1. Divya Khare, 2. Pradeep HR, 3. Krishna Kishore Kumar.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The present study was designed to evaluate the anti-diabetic effect of Swietenia mahagoni Jacq. seeds and Syzygium cumini (Linn.) Skeels. seeds in Type 2 Diabetes mellitus. The patients showing the classical symptoms of Madhumeha vis-&amp;#224;-vis Diabetes mellitus as described in the classical literature were randomly selected and divided into two groups. Group A received S. mahagoni seed powder in the form of capsules whereas Group B received S. cumini seed powder as capsules. The duration of treatment was 60 days. The subjective and objective parameters were assessed before and after treatment. Both the trial drugs, S. cumini and S. mahagoni showed definite demonstrable Madhumehahara (anti-diabetic) action as observed by clinical study. The drug S. mahagoni was more effective in all the parameters except in Pipasa (Polydipsia) where S. cumini showed better results.', '{"arp_id": "ARP_AYU001185", "portal_id": 1185, "medical_system": "AYURVEDA", "journal": "Rasamruta", "volume": "4", "issue": "12", "pages": "1 - 15", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Diabetes"], "original_url": "http://www.rasayu.com/e-journal/pdf/Rasamruta-4-12.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1185", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001185.pdf", "pdf_sha256": "65c2905259b2b7a7392a3db9e7da0cec4171928e9923aececfcec6db8e9f6a6d", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOGLYCEMIC AND ANTIHYPERLIPIDEMIC ACTIVITY OF LEAVES AND STEMS OF ALTERNANTHERA PHILOXEROIDES IN ALLOXAN INDUCED DIABETES', '1. Sampath Kumar P, 1. Dheeba B, 1. Stalin S, 1. Maragatham M, 2. Kannan M.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The oral antihyperglycemic effect of the ethanolic extracts of leaves and stems of Alternanthera philoxeroides was investigated in alloxan induced diabetic mice. The administration of ethanolic extracts of leaves (200mg/kg) and stems (200mg/kg) of Alternanthera philoxeroides significantly reduced the plasma glucose level (p&amp;lt;0.01) at 62.5% and 53% respectively in alloxan induced diabetic mice (150mg/kg). Moreover the treatment of leaves and stems of Alternanthera philoxeroides significantly reduces the level of cholesterol, triglycerides and liver enzymes such as serum glutamic-oxaloacetic transaminase (SGOT), serum glutamic-pyruvic transaminase (SGPT), alkaline phosphatase (ALP) and acid phosphatase (ACP), which were increased in alloxan induced diabetic mice. These results concludethat the leaves of Alternanthera philoxeroides possess better hypoglycemic effects than the stems of Alternanthera philoxeroides.', '{"arp_id": "ARP_AYU001242", "portal_id": 1242, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "6", "pages": "1793 - 1795", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1242", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001242.pdf", "pdf_sha256": "5a5fbeb58ca27700fb379074775bed278daf46e1f9fe84be319b487b089ee1e6", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PROTECTIVE ROLE OF COFFEE BEANS IN DIABETES MELLITUS MODEL OF RATS', 'Shradha Bisht, Sisodia SS.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: Effects of Coffea arabica seed extract on blood glucose level and serum lipid profile changes in normal and streptozotocin -induced diabetic rats have been studied with a view to elucidate its possible effect on diabetes and diabetes associated cardiovascular disease.. Materials and methods:Experimental animals were divided into four groups. Diabetes was induced in II, III, IV group by a single intravenous injection of streptozotocin (50 mg/kg body weight). Group I and II were kept as control and diabetic control respectively and were given 0.5 ml of 5% Tween 80 only, daily, once a day. Group III rats were further treated with ethanolic extract of Coffea arabica (200 mg/kg body weight, orally) for a period of 40 days. Group IV rats were treated with Glibenclamide at the dose of 500 µg/ kg. Oral glucose tolerance test was performed before starting the experiment.Results: Treatment of diabetic animals with crude ethanolic extract of seeds of Coffea arabica, significantly lowered blood glucose level, and maintained body weight and lipid-profile parameters towards near normal range. Conclusion:The results demonstrated that the coffea arabica seed ethanol extract exhibited antidiabetic and antidyslipidemic effect. To find out the exact mechanism of action, chemical and pharmacological studies are required to be carried out further. Active principal responsible for such effects should be also isolated.', '{"arp_id": "ARP_AYU001467", "portal_id": 1467, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "10", "pages": "3717 - 3720", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cardiovascular Disease"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1467", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001467.pdf", "pdf_sha256": "b9714d4a470106b7c169829c7a494e567f1d18ff93dee8fab0cc09dc70193357", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF METFORMIN AND VERNONIA AMYGDALINA LEAF EXTRACT LOADED PEGYLATED- MUCIN FORMULATION ON HAEMATOLOGICAL, KIDNEY AND LIVER INDICES OF HEALTHY AND DIABETES RATS', 'Momoh MA, Adikwu MU, Ibezim EC, Attama AA.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study investigates the effect of the various formulations of metformin and Vernonia amygdalina extract loaded with PEGylated-mucin on haematological and liver indices in alloxan made diabetic rats. The effect on body weight, food and water consumption, organ weight, hematology and clinical biochemistry were studied. There were no significant differences in the body weight, organ weights and feeding habits between control and treated animals. Hematological analysis showed no marked differences in any of the parameters examined in either the control or treated groups. Chemical constituents show that anthracene glycosides, flavonoids, proteins, carbohydrates, reducing sugars, saponins and tannins were present. The liver enzymes showed no significant different from that of the control and the LD50 was of &amp;gt; 650 mg/kg. This study suggests that the formulations were safe and can be used as alternative in the treatment.', '{"arp_id": "ARP_AYU001487", "portal_id": 1487, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "10", "pages": "3455 - 3459", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Pegylated-Mucin"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1487", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001487.pdf", "pdf_sha256": "a3430f7527f645620d5e7486e50def05a989c96f3469ef20d371edd77f872728", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'OCIMUM SANCTUM AND MORUS ALBA LEAVES AND PUNICA GRANATUM SEEDS IN DIET AMELIORATE DIABETES-INDUCED CHANGES IN KIDNEY', 'Abignan Gurukar MS, Nandini CD, Mahadevamma S, Salimath PV.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The effect of Ocimum sanctum (Tulsi) leaves, Morus alba L. (mulberry) leaves and Punica granatum (Pomegranate) seeds were evaluated for diabetes mediated effect on kidney of streptozotocin-induced diabetic rats. Rats (both control and diabetic) were fed with tulsi leaves, mulberry leaves and pomegranate seeds individually at 10%, 10% and 7.5 %, respectively, in AIN-76 diet, for a period of two months. Dietary supplements in the diet were able to ameliorate the increase in various parameters such as blood glucose, albumin excretion, glomerular filtration rate and kidney index. All the above mentioned dietary supplements had positive influence on extracellular matrix components such as laminin and fibronectin of kidney to various extents. The results indicated that plant materials of dietary origin are able to circumvent diabetes-induced changes in extracellular matrix components there by bringing about beneficial effects in the kidney.', '{"arp_id": "ARP_AYU001704", "portal_id": 1704, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "5", "issue": "9", "pages": "4729 - 4733", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["And Pomegranate Seeds"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1704", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001704.pdf", "pdf_sha256": "162ac96296fff2c994248c3024b6187e681e8609736da2928c094fc2eb819a9a", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HEPATOPROTACTIVE ACTIVITY OF AQUEOUS EXTRACT OF SYZYGIUM CUMINI SEED ON STREPTOZOTOCIN INDUCED DIABETES IN RATS', '1. Swadhin Ranjan Behera, 2. Sekkizhar M, 3. Sarath Babu K.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The effects of aqueous seed extract of Syzygium cumini (S.C) on hepatoprotection in streptozotocin (STZ) –induced diabetic rats were investigated. G-A serves as control, G-B serves diabetic control, G-C administered standard oral hypoglycemic drug, G-D and E administered two graded doses of seed extract. STZ was administered to rats after 72 hours blood glucose was estimated. Rats showed more than 200mg/dl glucose level considered in to diabetic rats. The selected diabetic rats were divided in to G-B, C, D and E. The G-B considered diabetic control group and G-C, D and E groups given their respective drugs for 120 days. On 120th day blood was collected from the all the groups and liver enzymes like AST, ALT, ALP, GGT were estimated by using auto-analyzer. Study results showed increased liver enzymes in G-B compared to all the groups. Standard and S.C 500mg/kg groups showed significant decrease in liver enzymes compared to other groups. Low dose of seed extract had less protective effect compared to high dose. From the study results, it can conclude that administration aqueous extract of S.C seed powder showed liver protective effect. There is requirement of more studies to isolate active compound form the seed powder.', '{"arp_id": "ARP_AYU001994", "portal_id": 1994, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic and Herbal Medicine", "volume": "4", "issue": "2", "pages": "1470 - 1477", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetes"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1994", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001994.pdf", "pdf_sha256": "3362e65adca4ddf9f27514e7f34273f835ae7a419b180289abf18c3004df525f", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'MANAGEMENT OF NEWLY DIAGNOSED TYPE 2 DIABETES BY TRIGONELLA FOENUM-GRAECUM', '1. Bhaktha Geetha, 2. Nayak Shivananda, 1. Shantaram Manjula.', 2011,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The objective of our study was to determine the role of fenugreek seed powder in the management of newly diagnosed type 2 diabetes. We selected 38 patients with grouped as: Group I (n=19) consumed 25 g. fenugreek twice daily (before breakfast and dinner) and on moderate exercise for two months, Group II (n=19) subjects were on dietary control. Blood sample collected before and after the treatment were analyzed for lipid profile and fasting blood sugar (FBS). Atherogenic index of plasma (AIP) was computed for each patient at baseline. The subjects received fenugreek seed powder and on exercise showed significant reduction in the FBS, cholesterol, triglyceride and LDL cholesterol which were statistically significant. There was a significant increase in the HDL cholesterol. The AIP value was statistically significant with subjects who received fenugreek seed powder and on exercise. FBS and triglyceride were reduced with the subjects who were on diet control. Our data showed that the management of type 2 diabetes would be easier with therapeutic approach of fenugreek seeds.', '{"arp_id": "ARP_AYU005226", "portal_id": 5226, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Ayurveda and Pharmacy", "volume": "2", "issue": "4", "pages": "1231 - 1234", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Aip"], "original_url": "http://ijrap.net/index.php/login/abstractt?id=577", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=5226", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU005226.pdf", "pdf_sha256": "eb96cb64ce28f363087b7db6fac31f415bb9bf849e31cbd89c30738581b2bdd4", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF AQUEOUS FLOWER EXTRACT OF CATHARANTHUS ROSEUS ON ALLOXAN INDUCED DIABETES IN MALE ALBINO RATS', '1. Natarajan A, 1. Syed Zameer Ahmed K, 1. Sundaresan S, 2. Sivaraj A, 3. Devi K, 2. Senthil Kumar B.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Catharanthus roseus is widely used in Indian Ayurvedic medicine for the treatment of diabetes mellitus. The present study was carried out to investigate the antidiabetic and hyperlipidemic potential of Catharanthus roseus on alloxan induced diabetes in male albino rats. Oral administration of aqueous extract of Catharanthus roseus at a dose of 250 mg, 350 mg, and 450 mg/kg body weight for 30 days to diabetic rats resulted in significant reduction in blood glucose, reduction in lipid profile and also prevented a decrease in body weight. Histological observation demonstrated significant fatty changes and inflammatory cell infiltrates in pancreas of diabetic rats. But, supplementation with Catharanthus roseus to diabetic rats significantly reduced the fatty changes and inflammatory cell infiltrates.', '{"arp_id": "ARP_AYU005896", "portal_id": 5896, "medical_system": "AYURVEDA", "journal": "International Journal of Pharmaceutical Sciences and Drug Research", "volume": "4", "issue": "2", "pages": "150 - 153", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "https://ijpsdr.com/index.php/ijpsdr/article/view/207", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=5896", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU005896.pdf", "pdf_sha256": "3ba3e2cf92131835abfb54928a3a64b144834e57ea4f4cb7c78a8ebc299a51cb", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-HYPERGLYCEMIC EFFECT OF SCOPARIA DULCIS IN STREPTOZOTOCIN INDUCED DIABETES', 'Das H, Chakraborty U.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aqueous extract of Scoparia dulcis could significantly reduce blood sugar levels in white rats which had been previously induced with diabetes by streptozotocin. Extract was administered at doses of 125 and 250 mg/kg body weight/twice a day respectively for a period of 3 weeks. Diabetic rats had much reduced body weight than normal rats. Administration of the extracts at the dose of 250 mg/kg body wt. /twice a day resulted in a marked decrease in the levels of fasting blood glucose and urine sugar, with a concomitant increase in body weight. The extract also produced a significant decrease in peroxidation products, viz., thiobarbituric acid reactive substances. Reduced glutathione and glycogen content, which had shown significant decrease following induction of diabetes, were found to be increased in the hepatic tissue of STZ-diabetic rats treated with the extract. Results suggest that aqueous extract of Scoparia dulcis can act as anti-hyperglycemic agent in STZ-diabetic rats.', '{"arp_id": "ARP_AYU007662", "portal_id": 7662, "medical_system": "AYURVEDA", "journal": "Research Journal of Pharmaceutical, Biological and Chemical Sciences", "volume": "2", "issue": "2", "pages": "334 - 342", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Hyperglycaemic"], "original_url": "https://www.rjpbcs.com/pdf/2011_2(2)/42.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7662", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007662.pdf", "pdf_sha256": "7e3178bb964c64a4fc9c851a7e7f43eea7c24996877bb65360e595af4436b921", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF ANTIDIABETIC ACTIVITY OF ETHANOLIC EXTRACT OF AGANOSMA CYMOSA AND ITS ANTIOXIDANT PROPERTY IN STREPTOZOTOCIN INDUCED DIABETES RATS', '1. Sangeetha Jayaraman, 1. Abbulu Konde, 2. Sudhakar Muvvala.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present study was carried out to illustrate the antidiabetic potential of ethanolic extract of Aganosma cymosa and to establish its antioxidant property. The antidiabetic activity of ethanolic extract of Aganosma cymosa in two different doses (200mg/kg and 400mg/kg, b.w.) was compared with standard Glibenclamide. The treatment for 28 days with standard and test doses showed significant (P&amp;lt;0.05) decrease in the blood glucose level. Test dose 2 (400mg/kg, b.w.) showed highly significant (P&amp;lt;0.0001) results when compared to diabetic control. The increased serum triglycerides, total cholesterol and Bilirubin levels were found decreased in standard and test dose treated groups, while the HDL level in the treated group was found elevated. The serum enzymes Aspartate aminotransferase (AST), Alanine aminotransferase (ALT) and Alkaline phosphatase (ALP) were found significantly reduced when compared to diabetic control. The results were supported with the Histopathological studies of the pancreas, which showed remarkable changes in the restoration of islets of langerhans. The plant extract also exhibited a very good antioxidant activity by maintaining the levels of Catalase (CAT), Superoxide Dismutase (SOD), Reduced Glutathione (GSH), Glutathione peroxidase (GPx) and Lipid peroxidase (LPO).', '{"arp_id": "ARP_AYU008441", "portal_id": 8441, "medical_system": "AYURVEDA", "journal": "World Journal of Pharmacy and Pharmaceutical Sciences", "volume": "2", "issue": "4", "pages": "2085 - 2096", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aganosma Cymosa"], "original_url": "http://www.wjpps.com/admin/assets/article_issue/137535624925%20WJPPS%20618.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8441", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008441.pdf", "pdf_sha256": "3d36e814f6c001afe5841f6e7ef3d2f9981649b39a68992499763394114806f1", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF A HIGHLY STANDARDIZED WITHANIA SOMNIFERA EXTRACT ON ENDOTHELIAL DYSFUNCTION AND BIOMARKERS OF OXIDATIVE STRESS IN PATIENTS WITH TYPE 2 DIABETES MELLITUS: A RANDOMIZED, DOUBLE BLIND, PLACEBO CONTROLLED STUDY', '1. Pingali Usharani, 2. Nishat Fatima, 3. Chiranjeevi Uday Kumar, 3. Kishan PV.', 2014,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Background: Type 2 Diabetes mellitus is a multisystem disorder with oxidative stress and endothelial dysfunction. Withania somnifera Dunal (Ashwagandha) is shown to have potent antioxidant, hypoglycemic and hypolipidemic effects in several studies. The present study was planned to compare the effect of Withania somnifera on endothelial dysfunction and biomarkers in patients with diabetes mellitus. Materials and Methods: After taking IEC approval and written informed consent, 66 eligible patients, who are on metformin therapy, were randomized to receive either one capsule of highly standardized aqueous extract of Withania somnifera 250mg twice daily, one capsule of Withania somnifera 500mg twice daily or Placebo for a duration of 12 weeks. Primary efficacy parameter was a change in endothelial function (measured as change in reflection index of more than 6 %) performed by salbutamol challenge test at baseline and after 12 weeks of treatment. Secondary end points were change in biomarkers of oxidative stress (malondialdehyde, nitric oxide and glutathione), high sensitivity C-reactive protein and change in lipid profile. Safety lab parameters were measured, at baseline and after 12 weeks of treatment. Results: A total of 60 patients completed the study. Twelve weeks of treatment with Withania somnifera 250mg and 500mg produced significant reduction in reflection index (-2.52&amp;#177;1.32% to -7.49&amp;#177;3.49%) and (-2.24&amp;#177;1.00% to -9.03&amp;#177; 2.42%) respectively, suggesting improvement in endothelial function versus placebo (-2.11&amp;#177;1.62% to -0.81&amp;#177; 2.86%). Similarly a significant improvement in biomarkers of oxidative stress, systemic inflammation, lipid parameters and HbA1c levels, compared to baseline and placebo, was observed with Withania somnifera. All treatments are well tolerated. Conclusion: Withania somnifera showed significant improvement in endothelial function, reduction in biomarkers of oxidative stress and systemic inflammation and can be used as a therapeutic adjunctive in patients with type 2 Diabetes mellitus.', '{"arp_id": "ARP_AYU008600", "portal_id": 8600, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurveda and Pharma Research", "volume": "2", "issue": "3", "pages": "22 - 32", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Ashwagandha"], "original_url": "https://ijapr.in/index.php/ijapr/article/view/240", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8600", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008600.pdf", "pdf_sha256": "677235c809d1f62765d0e51cfca4038607763d3315ab179c2197b2649fd1756b", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOGLYCAEMIC ACTIVITY OF PSIDIUM GUAJAVA LINN. FLOWERS AGAINST ALLOXAN INDUCED DIABETES IN MALE ALBINO RATS', 'Priyadharshini G, Anuradha R.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Over the past decade, herbal medicinehave been accepted universally and they have an impact on both world health and international trade. Diabetes mellitus is a metabolic disorder in the endocrine system. Plants provide a potential source of hypoglycemic drugs and are widely used in several traditional systems of medicine to prevent diabetes.Qualitative phytochemical analysis of aqueous extract of flower of psidium guajava was carried out with a view of developing leads for a new therapeutic products. The study was designed to investigate the hypoglycaemic effects of oral administration of aqueous extracts of psidium guajava flower in alloxan induced diabetic rats. After oral administration of the flower extract to diabetic rats, the blood glucose level significantly reduced, which is much faster and more than that of metformin. The aqueous extracts of flower of psidium guajava significantly reduced plasma glucose, creatinine, urea, AST, ALT, ACP, ALP, LPO, glucose-6- phosphatase and fructose1,6 bisphosphatase but increased level of serum insulin, protein, CAT, SOD, glycogen synthase and hexokinase. For all the above biochemical parameters observed and it was reverted toits normal level after flower extract treatment. The present investigation suggests that flowers of psidium guajava exhibit hypoglycaemic activity in alloxan induced diabetes in experimental rats.', '{"arp_id": "ARP_AYU008720", "portal_id": 8720, "medical_system": "AYURVEDA", "journal": "World Journal of Pharmacy and Pharmaceutical Sciences", "volume": "3", "issue": "6", "pages": "1321 - 1336", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "http://www.wjpps.com/admin/assets/article_issue/1401592894.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8720", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008720.pdf", "pdf_sha256": "1fa51f8fd94b7e3fdaf993da2a13cc1b648c61f64a64502c1eefdd8f3a30bff4", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF ANTIDIABETIC POTENTIAL OF MADHURAKSHAK; A POLYHERBAL FORMULATION AGAINST STREPTOZOTOCIN INDUCED DIABETES MELLITUS', '1. Madan S, 2. Gullaiya S, 3. Sharma D, 4. Kamraj M.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Several traditional treatment strategies have been recommended in the alternative system of medicine for the treatment of diabetes mellitus. Present investigation was undertaken to evaluate and examine the antidiabetic potential of Madhurakshak(Mdr), a polyherbal formulation containing extracts from twelve different herbs viz., Pterocarpus marsupium, Cinnamomum tamala, Eugenia jambolana, Gymnema sylvestre, Piper nigrum, Azadiracheta indiaca, Trigonella foenumgraecum, Momordica charantia, Phyllanthus emblica, Terminalia chebula, Terminalia belerica and shudh shilajit in streptozotocin ( STZ 40mg/kg i.p. single dose) induced type I diabetic rats. Effects of Madhurakshak Powder (600 mg/kg, oral), Mdr concentrate (300mg/kg, oral) and standard herbal drug Diabecon (250 mg/kg, oral) were evaluated on chronic (28 days) administration in STZ induced diabetic rats. This evaluation was based on various parameters studied which included blood glucose, Liver parameters (creatinine, urea, AST, ALT and ALP), Serum markers (serum triglyceride, cholesterol, LDL, bilirubin, HDL&amp;amp; Total Protein) and histopathological studies. Our results concluded that MdrPowder and Mdr concentrate were both able to depict their antidiabetic potential and were able to bring back the deranged level of liver and serum markers to near normal. This was backed by histopathological studies which revealed the possible beta cell protection potency of this polyherbal formulation.', '{"arp_id": "ARP_AYU008799", "portal_id": 8799, "medical_system": "AYURVEDA", "journal": "World Journal of Pharmacy and Pharmaceutical Sciences", "volume": "3", "issue": "3", "pages": "1160 - 1172", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antidiabetic"], "original_url": "http://wjpps.com/wjpps_controller/abstract_id/1028", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8799", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008799.pdf", "pdf_sha256": "9803103495a9cdc25d6ff79572d9462412643daa7af76f5f0dfdf81fa5d77239", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'KAMPA (TANDAVA ROGA) AS UPADRAVA IN MADHUMEHA WSR TO CHOREA AS A PRESENTING SYMPTOM IN DIABETES MELLITUS: A CASE REPORT', '1. Rajeshwari RV, 2. Muralidhar P Pujar, 3. Diwakar P Joshi.', 2014,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Diabetes mellitus is a long term disease with variable clinical manifestations, progression and number of complications but chorea as a presenting symptom in diabetes mellitus is very rare. In this paper an attempt has been made to highlight similar conditions explained in our classics. Tandavaroga explained by Sharangadhara has features similar to that of chorea. Hyperglycemia induced chorea can be understood as vataja prameha (Madhumeha) causing Kampa as Upadrava. This paper aims to convey proper differential diagnosis of involuntary movement disorders of new onset and emphasizes screening of diabetes mellitus in patients who develop sudden onset of chorea.', '{"arp_id": "ARP_AYU008897", "portal_id": 8897, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Holistic Medicine", "volume": "2", "issue": "8", "pages": "24 - 26", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Ayurveda"], "original_url": "http://www.jahm.co.in/index.php/jahm/article/view/203", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8897", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008897.pdf", "pdf_sha256": "7bcbcd32f852b20a6105aecccf03555f6b678fd14c21c2f08231970da14ee6d9", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'POTENTIAL HYPOGLYCEMIC & HYPOLIPIDEMIC EFFECT OF MORUS INDICA AND ASYSTASIA GANGETICA IN ALLOXAN INDUCED DIABETES MELLITUS.', '1. Pradeep Kumar R, 2. Sujatha D, 1. Mohamed Saleem TS, 1. Madhusudhana Chetty C, 2. Ranganayakulu D.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present research was made to investigate the potential hypoglycemic and hypolipidemic effect of Morus Indi-ca and Asystasia gangetica in alloxan induced diabetes mellitus. Diabetes was induced by alloxan (150 mg/kg i.p) in to rats. Ethanolic extract of leaves of Morus Indica and Asystasia gangetica was administered to alloxan induced diabetic rats. Glibenclamide used as a reference standard. Blood glucose, triglycerides, cholesterol, HDL-cholesterol, LDL-cholesterol and total proteins were estimated from the serum by using standard kits. All groups show significant increase in the level of biochemical parameters were decreased by administration of ethanolic extract of leaves of Morus Indica and Asystasia gangetica. From this study it has been concluded that the ethanol-ic extracts of leaves of Morus Indica and Asystasia gangetica having good hypoglycemic and hypolipidemic effect.', '{"arp_id": "ARP_AYU009129", "portal_id": 9129, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Pharmaceutical Sciences", "volume": "1", "issue": "1", "pages": "51 - 56", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "https://ijrps.com/home/article/view/2035", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9129", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009129.pdf", "pdf_sha256": "a3902d9d2d3c2fbff9b72658154f0e6c969ef3dfc9fca20b0537b933a5a60d42", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF ETHANOLIC EXTRACT OF CINNAMOMUM TAMALA LEAVES ON WOUND HEALING IN STZ INDUCED DIABETES IN RATS', '1. Rupesh Soni, 1. Mehta NM, 2. Srivastava DN.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: Diabetes is a chronic hyperglycemic metabolic disorder; leads to generates many complications including delay in wound healing after any injury. These non healing wound ends upto organ or limb salvage. The available modern allopathic medications are not able to full control over these complications. There are several evidences that complication associated with diabetes can easily be treated by using herbal or folklore medicines. The leaves of Cinnamomum tamala used by traditional peoples in the treatment of hyperlipidemia, diabetes, and associated wound healing problems. The aim of our study was to find the active extract from various extracts of C. tamala leaves responcible for wound healing activity in diabetic rats.Methods: The wistar albino rats were made diabetic by single i.p. injection of streptozotocin (60 mg/kg). The excision, incision and dead space wound were created on back side of rats. The ethanolic extract of C. tamala leaves was applied topically in excision wound model while in incision and dead space wound model the ethanolic extract of C. tamala leaves (100 mg/kg) was give orally for 16 days.Results: In the excision wound model the wound area and day of epithelization both were significantly decreased in ethanolic extract of C. tamala leaves treated rats. In incision wound model the significantly higher tensile strength was observed in rats treaded orally with ethanolic extract treated. There were significant increase in weight of wet &amp;amp; dry granulation tissue with increased amount of hydroxyproline, collagen and elastin was observed in treated rats by ethanolic extract of C. tamala leavesConclusion: The results suggested that the ethanolic extract of leaves of Cinnamomum tamala can be used in treatment of dalayed wound healing in diabetic rats.', '{"arp_id": "ARP_AYU009211", "portal_id": 9211, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "6", "issue": "4", "pages": "39 - 42", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cinnamomum Tamala"], "original_url": "https://innovareacademics.in/journals/index.php/ajpcr/article/view/211", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9211", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009211.pdf", "pdf_sha256": "79260e6610ca5406777993c9520797d520eeb74d3e961b679417c640992678fb", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF ANTIDIABETICPOTENTIAL OF IPOMOEA TURPETHUM R.BR. AND IPOMOEA BATATA L. (CONVOLVULACEAE) IN ALLOXAN INDUCED DIABETES IN RATS: ACOMPARATIVE STUDY._x005F_x005F_x005F_x005F_x005F_x005F_x005F_x000D_', 'Nishikant A Raut, Alkesh R Kasliwal, Naresh JGaikwad.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: In order to explore the intra-genera variation for biological activity, the antidiabetic activity of Ipomoea turpethum and Ipomoea batata was carried out in alloxan induced diabetes in rats. Dried powderedmaterial of both plants was defatted with petroleum ether 60-80 &amp;#176;C and cold macerated with hydro-ethanolfor seven days. These extracts were screened for antidiabetic activity using alloxan induced diabetes in rats.Diabetes was induced by intra-peritoneal administration of alloxan monohydrate (120 mg/kg) on days 1 and12 and blood glucose levels were estimated on 15th day. Hydro-ethanol extracts of both the plants at the doseof 500 mg/kg, oral, significantly lowered the blood glucose levels in diabetic rats treated for 7 days. The antidiabetic activity of these plants was insignificantly different from each other. This suggests that, differentspecies from same genera may have similar chemical constituents and pharmacological activity.', '{"arp_id": "ARP_AYU010457", "portal_id": 10457, "medical_system": "AYURVEDA", "journal": "Research Journal of Pharmaceutical, Biological and Chemical Sciences", "volume": "5", "issue": "6", "pages": "137 - 141", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Comparative Evaluation"], "original_url": "http://www.rjpbcs.com/pdf/2014_5(6)/[19].pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=10457", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU010457.pdf", "pdf_sha256": "a689443292afb12efe3c5e7a7180021db0d42ada3e2fcdaa97c68389f8cf10ba", "relevance_score": 41.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF ANXIETY IN DIFFERENT DEHAPRAKRITI (BODY CONSTITUTION) & EFFECT OF TINOSPORA CORDIFOLIA (GUDUCHI)', '1. Das Mahapatra Kousik, 2. Sharma Naresh Kr, 3. Gandharv Satish. Kumar, 4. Kumar Baldev, 5. Dave Hetal H.', 2011,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Anxiety of same origin does not affect the two individuals equally. Moreover the effect of same drug is not equal on those individuals. Just because of their dehaprakriti that perception of anxiety and effect of drug are being different. Tinospora is an effective Anxiolytic therapy. Methods: 30 (Intend to treat population (ITT) clinically anxious patients were taken as random sample, out of which 4 patients have discontinued their medicines. N=26 individuals have continued the usual stipulated course of medicine in a dose of 3gms/day for 60m days. Follow up taken in every 1.5 days. All patients were been assessed by &amp;quot;Sinha Anxiety Scale (SAS)&amp;quot;. The primary efficacy variable was the change in mean number of true points SAS. Results: Tinospora treatment was associated with a reduction in mean number of true points SAS. A significantly greater percentage of Tinospora using patients (68%) experienced better relief by 5th week. Very few patients have experienced mild weakness and hypoglycemia. Follow up taken in every 15 days. Conclusion: This pilot study suggests that Tinospora may be an effective Anxiolytic therapy. It was well tolerated in this population. Further randomized studies would be required to definitely establish the efficacy of Tinospora.', '{"arp_id": "ARP_AYU000148", "portal_id": 148, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "5", "issue": "4", "pages": "43 - 50", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "PSYCHOLOGICAL", "disease": "ANXIETY DISORDER/ANXIETY STATE(ICPC-P74|ICD-F41.0, F41.1, F41.3, F41.8, F41.9)", "keywords": ["Alkaloids"], "original_url": "https://journals.lww.com/joay/citation/2011/05040/joa_v_october__december_2011.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=148", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000148.pdf", "pdf_sha256": "b2f3e6794cc26078f46acc8973bc914ba0c56e903a3c1ff5bcc4747937d4ab4c", "relevance_score": 41.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '31000988', '10.4103/ayu.AYU_171_16', 'VARIATION IN SKIN HYDRATION ON THE BASIS OF DEHA PRAKRITI (BODY CONSTITUTION): A CROSS-SECTIONAL OBSERVATIONAL STUDY.', '1. Umarkar V. Suwarna, 2. Vyas M. Deepak,3. Kulkarni B. Sheela,4. Sathe D. Kalpana.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Prakriti (body constitution) is an important concept of Ayurveda which is decided at the time of birth. It shows differences in physical, physiological and psychological characteristics of an individual. Variation in skin characteristics is found as per Prakriti. Aim: The aim of the present work was to study hydration of skin over volar forearm in people with different Prakriti with the help of skin diagnostic SD 27 instrument. Subjects and Methods: This was a cross-sectional study conducted at Cosmetic Technology Department in unmarried healthy female students of (18–30 years). A total of 904 volunteers were screened, of which 621 volunteers were further examined for Deha Prakriti for screening of single Dosha dominant Prakriti. 58 Vata, 70 Pitta and 61 Kapha dominant Prakriti were eligible for further study, but on actual day of skin examination, 50 volunteers in each group completed the study. Skin hydration was measured by skin diagnostic SD 27 instrument.Results: It was found that maximum people with Vata (92%) and Pitta dominant Prakriti (70%) had less hydration while (48%) Kapha dominant Prakriti volunteers had normal to dehydrated skin. Chi-square test was used for analysis. The Chi-square value is 45.9 and P = 0.0001, which is highly significant. Conclusion: The skin of Vata and Pitta dominant Prakriti had less hydration while hydration was well maintained in Kapha dominant Prakriti than that of Vata and Pitta Prakriti people.', '{"arp_id": "ARP_AYU023450", "portal_id": 23450, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "39", "issue": "3", "pages": "127 - 131", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Kapha"], "original_url": "https://journals.lww.com/aayu/fulltext/2018/39030/variation_in_skin_hydration_on_the_basis_of_deha.3.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23450", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023450.pdf", "pdf_sha256": "728f567b88e1c829d19da7d2cb5c777a87d105456cbee7efbdc10db9f9f907b4", "relevance_score": 41.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '31000991', '10.4103/ayu.AYU_230_18', 'ASSOCIATION OF KAPHAJA AND KAPHA-PITTAJA PRAKRITI AND METHYLENETETRAHYDROFOLATE REDUCTASE C677T ALLELE WITH TYPE 2 DIABETES.', '1. Archana Gupta, 2. Akhtar Ali, 1. Priyadarshini Tewari, 3. Neeraj Kumar Agrawal, 2. Rashmi Patel, 1. Parameswarappa Shivappa Byadgi.', 2018,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background and Objectives: Type 2 diabetes is a multifactorial disorder that results from the interaction between genetic predisposition and environmental factors. Different Prakriti (body constitution) individuals have different susceptibility for the diseases, and this Prakriti is determined by both genetic and environmental factor. This study was undertaken to determine the association status of Methylenetetrahydrofolate reductase (MTHFR) C677T and A1298C with type 2 diabetes and Prakriti. Materials and Methods: After informed consent, 54 patients with type 2 diabetes and 56 individuals as normal controls were analyzed. Their constitution and pathological data were collected and MTHFR C677T and A1298C genotypes were determined. Results: Kapha/Kapha-Pittaja Prakriti were associated and found to be strong risk factors (Chi-square test = 39.67, P &amp;lt; 0.00001, odds ratio [OR] = 16.133, 95% confidence interval [CI] = 6.32–41.20) for type 2 diabetes. MTHFR C677T was associated (Chi-square test = 7.743, P= 0.02) with type 2 diabetes where the major CC genotype was found to be a risk for type 2 diabetes (OR = 3.78, 95% CI = 1.14–12.45). A1298C was not associated with type 2 diabetes (Chi-square test = 2.264,P= 0.322). None of the Prakriti was associated with C677T and A1298C variants. Interpretation and Conclusion: In the present study, an extremely strong association between Prakriti (Kaphaja/Kapha-Pittaja) and type 2 diabetes (P &amp;lt; 0.00001) was detected. The present study gives a strong clue for the association of Prakriti (body constitutional) and clinical phenotype.', '{"arp_id": "ARP_AYU023452", "portal_id": 23452, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "39", "issue": "3", "pages": "146 - 150", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Methylenetetrahydrofolate Reductase"], "original_url": "https://journals.lww.com/aayu/fulltext/2018/39030/association_of_kaphaja_and_kapha_pittaja_prakriti.6.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=23452", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU023452.pdf", "pdf_sha256": "a3c34bf8b09deca8825669859b21b96026b0308ae89f0d886bff133e51bdacc2", "relevance_score": 41.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '28302415', '101016/j.jaim.2016.12.001', 'A PROSPECTIVE STUDY TO ASSESS THE ASSOCIATION BETWEEN GENOTYPE, PHENOTYPE AND PRAKRITI IN INDIVIDUALS ON PHENYTOIN MONOTHERAPY.', 'Ket J. Thaker, Prajakta P. Gandhe, Charuta J. Godbole, Shital R. Bendkhale, Nitin B. Mali, Urmila M. Thatte, Nithya J. Gogtay.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background:Genetic polymorphisms in drug metabolizing enzymes (DMEs) impart distinct drug metabolizing capacity and a unique phenotype to an individual. Phenytoin has large inter-individual variability in metabolism due to polymorphisms in CYP2C9 and CYP2C19. As per Ayurveda, Prakriti imparts a unique phenotype to an individual.Objective:To assess whether Prakriti can substitute phenotyping [therapeutic drug monitoring (TDM)] and genotyping in individualizing therapy with phenytoin in epilepsy patients.Methods and materials:This was a cross-sectional study conducted over a period of three years. Prakriti was assessed using standardized and validated software. Polymorphisms in CYP2C9 and CYP2C19 were assessed using Polymerase Chain Reaction (PCR)-Restriction fragment length polymorphism (PCR-RFLP). Plasma concentrations of phenytoin (phenotype) were determined using reverse phase-high performance liquid chromatography (RF-HPLC).Results:Total 351 patients were enrolled for the study. Kapha vata (KV) (39%) was the predominantly observed Prakriti followed by vata kapha (VK) (20.8%) and vata pitta (VP) (8.83%) among the patients. The CYP2C9 and CYP2C19 genotype distributions were in accordance with Hardy–Weinberg equilibrium. There was no association between Prakriti and genotypes and Prakriti and phenotype (p &amp;gt; 0.05 each). Patients with CYP2C9 *1/*3 genotype were thrice more likely to have toxic plasma concentrations of phenytoin as compared to those with wild-type genotype (*1/*1) (Adjusted odds ratio – 3.36; 95% C.I. 1.61, 7.01). However, no such association was observed between polymorphisms of CYP2C19 and phenotype.Conclusions:We did not find any association between Prakriti and either phenotype or genotypes suggesting that Prakriti assessment would be of limited utility in individualizing phenytoin therapy in epilepsy patients.', '{"arp_id": "ARP_AYU025150", "portal_id": 25150, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Integrative Medicine", "volume": "8", "issue": "1", "pages": "37 - 41", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ayurveda"], "original_url": "http://www.sciencedirect.com/science/article/pii/S0975947616303527", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=25150", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU025150.pdf", "pdf_sha256": "eb6e5b00d318c3766551ed3eb74464e091d93dae44c70412a6989a0943ef2a8d", "relevance_score": 41.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'COMPARATIVE CLINICAL STUDY OF ARKA VATI 1 AND ARKA VATI 2 IN PATIENTS OF AGNIMANDYA (IMPAIRED DIGESTION)', '1. Vishnu Prasad Gautam, 2. Mukesh Dubey, 3. Ranjip Kumar Dass, 4. Govind Prasad Gupta, 5. Moharpal Meena.', 2013,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: Various studies in the general population and primary health care have reported that most of the people are suffering from loss of appetite due to drastic changes in life style and also due to lack of physical work. It occurs due to inhibition of secretion of digestive enzymes.Aims and Objectives: To compare the efficacy of arka vati No. 1 &amp;amp; arka vati No. 2 on agnimandya due to kapha dosha.Methods and Materials: Forty students suffering from agnimandya due to kapha dosha &amp;amp; other causes were studied. Total duration for trial treatment was 40 day. The patients were administered with arka vati.Result: It is observed that positive values are highly significant in all the symptoms of agnimandya except lazyness hence it can be concluded that the administration of arka vati is effective in agnimandya. The results are encouraging and support the classical claim that arka vati is effective in reducing the symptoms of agnimandya and it can be used extensively in the treatment.Conclusion: On the basis of the result observed it may be concluded that the arka vati is having significant effect in ameliorating the disease agnimandya.', '{"arp_id": "ARP_AYU008151", "portal_id": 8151, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Holistic Medicine", "volume": "1", "issue": "7", "pages": "7 - 12", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "FLATULENCE/GAS/BELCHING (ICPC-D08| ICD-R14)", "keywords": ["Agnimandya"], "original_url": "http://www.jahm.co.in/index.php/jahm/article/view/122", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8151", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008151.pdf", "pdf_sha256": "f065a1ffe448faeff72139361be03b1a5656ba9adc57c7556db500e847bff6d5", "relevance_score": 41.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ETHANOLIC EXTRACT OF THE LEAVES OF HOUTTUYNIA CORDATA THUNB. PRODUCES ANTIDIARRHOEAL AND GASTROINTESTINAL MOTILITY SLOWING EFFECTS IN ALBINO RATS', '1. Basak M, 1. Sarkar BR, 1. Dey BK, 2. Mohanty JP, 3. Das T, 4. Uriah T, 3. Shil D, 1. Sahariah BJ.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The antidiarrhoeal effects of ethanolic leaf extract of Houttuynia cordata Thunb. were evaluated in rat. Studies were investigated on castor oil- induced diarrhoea and gastrointestinal motility activity in rat. The extract (200 and 400 mg/kg) elicited a greater anti-motility than 5 mg/kg atropine (P &amp;lt; 0.05) and significantly (P &amp;lt;0.05) protected rats against castor oil- induced diarrhoea. The frequency of defaecation as well as the wetness of faecal droppings was significantly (P &amp;lt; 0.05) reduced. The oral LD50 of the extract was found to be greater than 5000mg/kg in mice. The result obtained shows that the ethanol leaf extract of Houttuynia cordata Thunb may contain some biologically active principles that are active against diarrhoea and this may be the basis for management of gastrointestinal disorders.', '{"arp_id": "ARP_AYU003606", "portal_id": 3606, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Phytochemistry&Pharmacology", "volume": "1", "issue": "4", "pages": "235 - 238", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antidiarrhoeal"], "original_url": "https://scienztech.org/index.php/ijrpp/article/view/794", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3606", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003606.pdf", "pdf_sha256": "4801d49f0bb3afbbd3c347bc04ab757ed06d1cedc1bc4fb481712001f8c2d23f", "relevance_score": 41.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'SUPPRESSION OF GUT GLUCOSE ABSORPTION AND ENHANCEMENT OF GUT FLUID ABSORPTION IN ALLOXAN - INDUCED DIABETIC RATS TREATED WITH CRUDE ALOE VERA GEL.', '1. Akpan UP, 2. Nna VU, 2. Ofem OE, 2. Antai AB, 2. Osim EE.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study was aimed at determining the effect of treatment of type 1 diabetes mellitus (T1DM) with crude Aloe vera gel on gut fluid and glucose absorption which are determinants of post-prandial hyperglycemia. Twenty four male albino Wistar rats weighing 180 - 200 g were randomly assigned 1 of 4 groups (n = 6) thus, control, diabetic untreated (DM) group, diabetic group treated (DMT) with crude Aloe vera gel at a dose of 0.4 ml/100g body weight per oral route and control group treated (CT) with crude Aloe vera gel at a dose of 0.4 ml/100g body weight per oral route. all animals had access to food and tap water ad libitum. After 21 days of administration, animals were sacrificed by cervical decapitation. Determination of fluid transfer and glucose uptake was done using appropriate methods. Histology of small intestine was also done using standard techniques. Serosal fluid transfer was significantly (P &amp;lt; 0.05) lower in DMT group compared with control. Gut fluid uptake was significantly (P &amp;lt; 0.05) higher in DMT group compared to control and CT group. Mucosal and serosal glucose concentrations before incubation were significantly (P &amp;lt; 0.05) lower in DM group compared to control. Mucosal glucose concentration after incubation was significantly (P &amp;lt; 0.05, P &amp;lt; 0.05, P &amp;lt; 0.01) increased in DM, DMT and CT group respectively, compared to control. Serosal glucose concentration after incubation was significantly (P &amp;lt; 0.01, P &amp;lt; 0.001, P &amp;lt; 0.01) increased in DM, DMT and CT group respectively, compared to control. Gut glucose transfer was significantly (P &amp;lt; 0.05, P &amp;lt; 0.05, P &amp;lt; 0.01) lowered in DMT group compared to control, DM and CT group respectively We therefore conclude that crude Aloe vera gel potentiates the effect of T1DM in increasing gut fluid uptake. Crude Aloe vera gel also reduces gut glucose transfer in DM group, which is a beneficial effect to reduce post-prandial hyperglycemia.', '{"arp_id": "ARP_AYU008214", "portal_id": 8214, "medical_system": "AYURVEDA", "journal": "Research Journal of Pharmaceutical, Biological and Chemical Sciences", "volume": "5", "issue": "3", "pages": "647 - 655", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Aloe Vera"], "original_url": "https://www.rjpbcs.com/pdf/2014_5(3)/[73].pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8214", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008214.pdf", "pdf_sha256": "cdfd76d94baa8252b30e9ef133c0c7e6e120686c167659383980fe887fc03b00", "relevance_score": 41.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'SAFETY OF GLICLAZIDE WITH THE AQUEOUS EXTRACT OF VINCA ROSEA ON PHARMACODYNAMIC ACTIVITY IN NORMAL AND ALLOXAN INDUCED DIABETIC RATS', '1. Ganga Raju M, 2. Satyanarayana S, 3. Eswar Kumar K.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present study was carried out to evaluate the hypoglycemic activity and antihyperglycemic activity of aqueous extracts of whole of Vinca rosea in normal and in alloxan induced diabetic rats. The aqueous extract of Vinca rosea (30mg/Kg, 100mg/Kg, 300mg/Kg bd.wt) and the dose(100mg/Kg) that produced an optimal reduction (30-40%)of blood glucose was selected for the study. Blood samples were collected at desired intervals of time and analyzed for blood glucose by GOD/POD method. Gliclazide, a second generation sulfonylurea was selected for the interaction study with that of the Vinca rosea. The doses of gliclazide (1mg/Kg, 2mg/Kg and 4mg/Kg bd. wt) were given to normal and diabetic rats and the dose (2mg/Kg bd. wt) that produced an optimal reduction of blood glucose was selected for the study. The prior administration of Vinca rosea significantly increased the hypoglycemic and antihyperglycemic activity of gliclazide.', '{"arp_id": "ARP_AYU001547", "portal_id": 1547, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "5", "issue": "3", "pages": "1555 - 1558", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Gliclazide"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1547", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001547.pdf", "pdf_sha256": "505f529ea8e20426e0bb167e8fa2d61ff0909e5b60ee34ba3ea3dff822edb538", "relevance_score": 41.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL STUDY TO EVALUATE THE EFFICACY AND SAFETY OF HYPERCUM IN HYPERTENSION AND ASSOCIATED QUALITY OF LIFE - AN OPEN LABELED PROOF OF CONCEPT STUDY', '1. Harisha S, 2. Kiran.Vuppala, 3. Anil Kumar Sharma.', 2014,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Background: High blood pressure has emerged as a leading cause for death and disability worldwide. Management of hypertension effectively has been a distant reality. Hypercum, a rationale combination of herbs has shown to reduce BP effectively along with other benefits as studied in the ancient literatures and research publication. Objectives: The aim of the study is to evaluate the safety and efficacy of “Hypercum” on mild to moderate hypertension, associated with comorbid conditions. Methods: An open labeled nonrandomized proof of concept study enrolled 16 hypertensive patients, who met the selection criteria. The efficacy was assessed by measuring the blood pressure at baseline and on every 15 days till the BP got controlled and then every month and followed up for 84 days. The effect of Hypercum on other co-morbid conditions was also evaluated. The quality of life was also assessed using SF-30. Planned student‘t’ test was applied. Results: At screening (before the enrollment for the study) the mean systolic blood pressure (SBP) was 161.25 mmHg and their mean diastolic blood pressure (DBP) was 106.88mmHg. The mean baseline systolic blood pressure, the mean diastolic blood pressure and the mean arterial blood pressure (MAP) were 152.50 mmHg, 99 mmHg and 113.88 mmHg respectively. The mean value of these parameters SBP, DBP and MAP decreased to 122.50 mmHg, 81.67 mmHg and 92.58 mmHg respectively at visit 5 that is at Day 84. There was significant reduction in systolic blood pressure, diastolic blood pressure and mean arterial blood pressure from baseline to the entire visit that is Day14, Day28, Day56 and Day84. Conclusion: “Hypercum” is effective in treating the mild to moderate hypertension associated with co-morbid conditions with positive outcome on the quality of life.', '{"arp_id": "ARP_AYU008945", "portal_id": 8945, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Holistic Medicine", "volume": "2", "issue": "4", "pages": "12 - 16", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "CIRCULATORY", "disease": "HYPERTENSION UNCOMPLICATED(ICPC-K86|ICD-I10)", "keywords": ["Blood Pressure"], "original_url": "http://www.jahm.co.in/index.php/jahm/article/view/170", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8945", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008945.pdf", "pdf_sha256": "ef916e4e7229f7808b797f1a8a05929c1269f00f739bcd42d388f669bbe72f8a", "relevance_score": 41.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'STUDIES ON THE PROCESS OF DETOXIFICATION AND SAFETY EVALUATION OF SHODHIT AND ASHODHIT DATURA METEL SEEDS FOR THE USE IN AYURVEDIC PREPARATIONS', '1. Vibhavari Chhatre, 1. Tanuja Nesari, 2. Gauresh Somani, 2. Rahul Chaudhari, 2. Sadhana Sathaye.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Datura metel Linn. is a well known and frequently used herbal drug in Ayurveda. Seeds of D. metel are poisonous and according to Ayurvedic literature, they should be used in medicines after appropriate shodhan (purification or detoxification procedures). The present study evaluates various physicochemical parameters and HPLC analysis with special reference to hyoscine and atropine content for D. metel seeds (DMS), ashodhit (before shodhan) and shodhit (after shodhan) samples, as well as for shodhan reagent (cow urine). DMS, ashodhit as well as shodhit, were further evaluated for acute oral toxicity in mice and for cardiotoxicity in the isolated heart preparation of frog. The percentage of water soluble extractives, alcohol soluble extractives, and total alkaloids were found reduced in the shodhit DMS. HPLC analysis also showed the depletion of toxic alkaloids like atropine and hyoscine in the shodhit DMS as compared to ashodhit DMS. Shodhit DMS showed no toxicity on isolated heart preparation of frog as compared to ashodhit DMS. Thus, the present study reflects the importance of shodhan methods or the toxic drugs by means of which reduction of toxic constituents is achieved as advocated by Ayurveda.', '{"arp_id": "ARP_AYU009156", "portal_id": 9156, "medical_system": "AYURVEDA", "journal": "International Journal of Research in Pharmaceutical Sciences", "volume": "3", "issue": "4", "pages": "670 - 677", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Atropine"], "original_url": "https://ijrps.com/home/article/view/3490", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=9156", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU009156.pdf", "pdf_sha256": "2b07a5b3ac96908266efac88811032a1c36819ff16e5b2ba89a67c4f7b72f1c3", "relevance_score": 41.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFICACY AND SAFETY OF NETRA BINDOO FOR SEASONAL ALLERGIC CONJUNCTIVITIS', '1. Meena Atray, 2. Vyas KP, 3. Jitena Prasad Atray.', 2013,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: A placebo con/rolled study was done in which 60 patients of seasonal allergic conjunctivitis were divided in two groups (group-I and group-2) All 30 patients of group-I were treated with Netra bindoo and 30 patients of group- 2 were treated with Normal saline (placebo). The patients were diagnosed on the basis of symptoms. slit lamp examination and demonstration of eosinophils in the ocular discharge. The scores for all eight eye symptoms (Itching, redness, lacrimation, swollen eye lids, burning of eyes, foreign body sensation, photophobia and discharge) were recorded on day-a, day-l, day-S, day-? and day-I-t, compared and statistically analysed. Patients lvere evaluated/or appearance of any adverse effect on every visit. All 60 patients completed the trial. The mean sum scores of three major symptoms (Itching, redness and lacrimation) and of all eight eye symptoms lvere compared. Significant reduction in mean sum scores was found in group-I. The difference in mean Sll/11 scores between day-O and day-? in both groups was analysed statistically and found significant (p &amp;lt; .00l). None of the patient experienced any significant adverse effect. From the results of this study it can be concluded that Netra bindoo is well tolerated and offers significant efficacy in patients with seasonal allergic conjunctivitis.', '{"arp_id": "ARP_AYU020931", "portal_id": 20931, "medical_system": "AYURVEDA", "journal": "Journal of Research in Ayurveda and Siddha", "volume": "34", "issue": "1-4", "pages": "33 - 42", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "EYE", "disease": "CONJUNCTIVITIS ALLERGIC(ICPC-F71|ICD-H10.1)", "keywords": ["Allergic Conjunctivitis"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20931", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020931.pdf", "pdf_sha256": "138cbab2cdf0aa418d44b5dc570df15c37a8eb0311cda5a2b40239e0b778c10e", "relevance_score": 41.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'AMELIORATING EFFECT OF SEMECARPUS ANACARDIUM ON TCA CYCLE ENZYMES IN HIGH FAT DIET STZ INDUCED TYPE 2 DIABETIC RAT MODEL', 'Haseena Banu Hedayathullah Khan, Kaladevi Siddhi Vinayagam, Varun Venkatesh, Shanthi Palanivelu, Sachdanandam Panchanatham.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Semecarpus anacardium also known as bhalatakka is used traditionally in Indian systems of medicine against various ailments. The anti diabetic effect of the drug Semecarpus anacardium Linn nut milk extract (SA) was studied in a high fat diet STZ induced Type 2 diabetic rat model. The reduction in blood glucose levels, HbA1c, increase in insulin levels and also improvement in glucose tolerance, HOMA- IR , HOMA - &amp;#226; proved the anti diabetic effect of the drug. The drug was also effective in ameliorating the alterations in TCA cycle enzymes. Histopathological studies proved the protective effect of the drug on the pancreas. Hence, it can be inferred that the drug SA possess anti diabetic effect and also it can be effective in preventing the metabolic alterations associated with diabetes mellitus. The presence of flavonoid compounds is probably related to the potent anti diabetic effect.', '{"arp_id": "ARP_AYU000526", "portal_id": 526, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "12", "pages": "4577 - 4580", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Homa- Ir"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=526", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000526.pdf", "pdf_sha256": "ee99cc5de673ffa75667d79d8a5259a6a16e0a92578c393311540ba46de6221d", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF ARGYREIA SPECIOSA ROOTS ON ATHEROGENIC DIET INDUCED OBESITY IN RATS', 'Shiv Kumar, Alagawadi KR.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Argyreia speciosa roots are widely used in Indian traditional system of medicine for the treatment of obesity. The present study was designed to evaluate the antiobesity effects of ethanolic extract of Argyreia speciosa roots in rats fed with atherogenic diet. Obesity was induced in albino rats by feeding atherogenic diet daily for 42 days in addition to normal diet. Treatment was continued for 6 weeks. Body weight was measured initially and then every week thereafter. Food intake was measured during last five consecutive days. On day 42, serum lipid levels were estimated and then the animals were killed by an overdose of ether, liver and parametrial adipose tissues were removed and weighed immediately. The liver triglyceride content was estimated. The influence of ethanolic extract of Argyreia speciosa on pancreatic lipase activity was also determined. Body weight at 2-6 weeks and the final parametrial adipose tissue weights were significantly lowered in rats treated with Argyreia speciosa extract 500 mg/kg/day as compared with atherogenic diet control rats. The extract also significantly reduced the serum levels of total cholesterol (TC), low density lipoproteins (LDL) and triglycerides (TG), which were elevated in rats fed with atherogenic diet alone. In addition, the extract inhibited the induction of fatty liver with accumulation of hepatic triglycerides. The extract also showed significant inhibition of pancreatic lipase activity. In conclusion, Argyreia speciosa roots extract produced antiobesity effects in atherogenic diet induced obese rats, which might be due to inhibition of lipid absorption from small intestine through the inhibition of pancreatic lipase activity.', '{"arp_id": "ARP_AYU000838", "portal_id": 838, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "3", "issue": "7", "pages": "1524 - 1527", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antiobesity"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=838", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000838.pdf", "pdf_sha256": "1633e9dbee7a4856e09e5920187bbfbced631f027bdc7f2179b2e16a99cf9ace", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-INFLAMMATORY AND ANTIOXIDANT EFFECTS OF ZINGIBER OFFICINALE (GINGER) INCORPORATED DIET IN RATS.', 'Anosike, Chioma A, Ossai, Emmanuel C, Joshua.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This work shows the effect of Zingiber officinale (ginger) rhizomes on induced inflammation. A total of 30 rats of either sex were used for the in vivo analysis. The dried (ground) ginger plant was incorporated into the rat feed in the concentration of 5%, 10%, 20% (w/w) and then were used to feed the animals, which were placed in groups of five rats in each cage (control, 5% ginger, 10% ginger, 20% ginger, 5mg indomethacin, 0.5ml of 5mg/kg indomethacin groups respectively), for a period of 14 days. The results from the anti-inflammatory test showed that the plant Z. officinale had significant reduction on induced rat paw oedema (p&amp;lt;0.05). The result from the analysis of the blood samples also showed that the plant Z. officinale had significant increase (p&amp;lt;0.05) on the activity of superoxide dismutase (SOD) and significant reduction (p&amp;lt;0.05) on levels of malondialdehyde (MDA) in the plasma but no significant difference (p&amp;gt;0.05) on the levels of vitamin C. SOD activity and MDA levels were found to show significant increase and decrease respectively in a dose related manner as compared with the control. The plant, Z. officinale, was able to reduce oedema volume, the levels of lipid peroxidation and increased the activity of the enzyme, SOD, after induction of inflammation.', '{"arp_id": "ARP_AYU001006", "portal_id": 1006, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "3", "issue": "8", "pages": "1817 - 1822", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1006", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001006.pdf", "pdf_sha256": "b429c06aa10ccc10df21fdb629829700cf36f28771616da1f98177ca2f7601b7", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'SAPONINS RICH AQUEOUS EXTRACT OF GYMNEMA SYLVESTRE R.BR REDUCES HIGH FAT DIET INDUCED OBESITY IN WISTAR RATS', '1. Rama Manohar Reddy, I,2. Vijaya T, 1. Pushpa Latha B, 3. Dattatreya Rao S.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objectives: The antiobesity effect of saponin rich Gymnema sylvestre R.Br aqueous leaf extract (SGE) on rats fed with high fat diet for a period of eight weeks was investigated. Materials and Methods: Saponin rich G. sylvestre R.Br aqueous leaf extract was administered at a dose of 100 mg/kg body weight once a day to the high fat diet induced wistar rats. Changes in body weight, organ weights and plasma biochemical profile viz; total cholesterol, triglycerides, high density lipoproteins (HDL) cholesterol, very low density lipoproteins (VLDL), low density lipoproteins (LDL) cholesterol were compared between control and rats treated with synthetic drug and herbal extract. Results: Our result showed significant reduction in body weight gain, organ weights and other related plasma parameters in rats treated with saponin rich G. sylvestre R.Br aqueous leaf extract. Conclusion: Saponin rich G. sylvestre R.Br aqueous leaf extract was found as efficient as Orlistat, a synthetic drug used in obesity treatment.', '{"arp_id": "ARP_AYU001152", "portal_id": 1152, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "4", "pages": "1237 - 1239", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Body Weight"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1152", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001152.pdf", "pdf_sha256": "aa94bb4f139a90427f608af41e1a035ac90efc16ccd7eab851d9e76280800d56", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'IN VIVO ANTIOXIDANT AND LIPID PEROXIDATION EFFECT OF VARIOUS EXTRACTS FROM WHOLE PLANT OF BAUHINIA PURPUREA (LINN) IN RAT FED WITH HIGH FAT DIET', '1. Shajiselvin CD, 2. Kottai Muthu A.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The study was carried out to determine the in vivo antioxidant and lipid peroxidation effect of various extracts of whole plant of Bauhinia purpurea (Linn). High fat diet rats showed significantly (P&amp;lt;0.001) reduced the levels of tissues enzymatic antioxidant and enhanced the level of non enzymatic antioxidant (Glutathione). The level of TBARS are elevated in HFD rats (group II) when compared with control group. Administration of ethyl acetate extract of Bauhinia purpurea in high fat diet rats were showed significantly (p&amp;lt;0.001) increased the levels of antioxidant Enzymes such as Superoxide dismutase (SOD), Catalase (CAT), Glutathione peroxidase (GPx), Glutathione reductase (GR) and reduced the level of non enzymatic antioxidant Glutathione (GSH) when compared with HFD rats (Group II). The ethyl acetate extract of Bauhinia purpurea in high fat diet rats were found lowered the concentration of TBARS when compared with HFD rats (Group II). In comparison of all the three extract treated group with standard group, the ethyl acetate extract of Bauhinia purpurea was showed significant (p&amp;lt;0.001) result than that of other groups. Based on the results, we concluded that the ethyl acetate extract of Bauhinia purpurea is a significant source of natural antioxidant, which might be helpful in preventing the progress of various oxidative stresses.', '{"arp_id": "ARP_AYU001311", "portal_id": 1311, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "10", "pages": "3280 - 3281", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Bauhinia Purpurea"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1311", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001311.pdf", "pdf_sha256": "c5a29590e03c0553ffcc856e9a9de5474b9ea650befcef604d29841f299210fd", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF SAPONIN RICH EXTRACT OF ACHYRANTHES ASPERA ON HIGH FAT DIET FED MALE WISTAR RATS', '1. Pushpa Latha B, 1. I. Rama Manohar Reddy, 2. Vijaya T, 3. Dattatreya Rao S, 4. Mannur Ismail S, 1. Girish BP.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: To study the anti-obesity effect of saponin rich extract of Achyranthes aspera on male wistar rats after feeding them for eight weeks with high fat diet. Methods: The rats were divided into four groups: control group fed on normal standard diet (N); high fat diet control group (HF); saponin rich ethanol extract treated group fed on high fat diet (HF+ASE) and Orlistat treated group fed on high fat diet (HF+OL). The effect of extract on following parameters was recorded – food and water consumption, body weights, organ weights, serum biochemical profile and atherogenic index. Results: In case of rats treated with saponin rich extract there was a significant reduction (p&amp;lt;0.05) in food intake, gain in body and visceral organ weights, serum levels of total cholesterol (TC), triglycerides (TG), very low density lipoproteins (VLDL), low density lipoproteins (LDL) and atherogenic index which were elevated in HF diet control rats. Significant raise (P&amp;lt;0.05) was observed in case of High density lipoproteins (HDL) levels in extract treated rats when compared to HF diet control rats.Conclusion: These results suggest that the saponin rich extract of A. aspera could prevent the changes induced by high fat diet and may act as effective antiobese agent.', '{"arp_id": "ARP_AYU001458", "portal_id": 1458, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "9", "pages": "3190 - 3193", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Achyranthes Aspera"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1458", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001458.pdf", "pdf_sha256": "ab75ad68798ef21ef73bbf2a77feb48dbe19eaf1b4b5697436ec589abda0b980", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'IN VIVO ANTIOXIDANT AND LIPID PEROXIDATION EFFECT OF VARIOUS EXTRACTS FROM ROOT OF CLERODENDRUM PHLOMIDIS (LINN.) IN RAT FED WITH HIGH FAT DIET', 'Sathish M, Tharani CB, 1. Nagireddy Divya, 1. Lokeswari V.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The aim of the present study was to investigate the in vivo antioxidant and lipid peroxidation effect of various extracts from root of Clerodendrum phlomidis (Linn) in rat fed with high fat diet. High fat diet rats showed significantly (P&amp;lt;0.001) reduced the levels of tissues enzymatic antioxidant and enhanced the level of non enzymatic antioxidant (Glutathione). The level of TBARS are elevated in HFD rats (group II) when compared with control group. High fat diet induces the oxidative stress in cell by producing reactive oxygen species. Administration of ethanolic extract of Clerodendrum phlomidis in high fat diet rats were showed increased the levels of antioxidant enzymes such as superoxide dismutase (SOD), catalase (CAT), glutathione peroxidase (GPx), glutathione reductase (GR) and reduced the level of non enzymatic antioxidant glutathione (GSH) when compared with HFD rats (Group II). The ethanolic extract Clerodendrum phlomidis in high fat diet rats were found lowered the concentration of TBARS when compared with HFD rats. Based on the results, we concluded that the ethanolic extract of Clerodendrum phlomidis is a significant source of natural antioxidant, which might be helpful in preventing the progress of various oxidative stresses.', '{"arp_id": "ARP_AYU001477", "portal_id": 1477, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "4", "issue": "9", "pages": "3030 - 3032", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cat"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1477", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001477.pdf", "pdf_sha256": "7762810293991f56551b5937edf8b43fbd791d126548982b503130e53e7e726e", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ETHANOLIC EXTRACT OF MANGIFERA INDICA SEED KERNEL AMELIORATES VISCERAL FAT VIA IMPROVEMENT IN LIPID METABOLISM IN HIGH FAT DIET INDUCED OBESE MICE', '1. Kankanampati Krishnaveni, 1. Rosaline Mishra, 2. Pushkala K, 3. Velayudam D, 1. Suman Kapur.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aim: Present study was aimed at evaluating the effect of ethanolic extract of Mangifera indica seed kernel (MESK) on induction of obesity and other symptoms associated with visceral obesity syndrome in High-Fat Diet induced obese mice.Methods: HFD fed obese (DIO) Swiss-albino mice (N=6/ group) were treated with a single oral dose of 0.75µg/kg/day of dried MESK or 120µg/kg/day of Orlistat for a 6 weeks period. Mangifera indica Seed kernels were extracted using Ethanol: Water as solvent and the crude extract was subjected to several phytochemical screenings. Results: Oral treatment with MESK significantly altered the % body weight change, as judged by BMI and LI, WAT (p&amp;lt; 0.0001) and dyslipidemia as indicated by lowering of serum cholesterol (TC) and triglycerides (TG) in DIO mice, as compared to untreated DIO mice and normal diet fed mice. MESK treatment was also found to improve FPG levels and increase fecal lipid excretion which was comparable to that observed in mice treated with Orlistat. Preliminary phytochemical screening revealed presence of neutral lipid (tri-, di- and monoacylglycerols, and free fatty acids and steroids in the hexane fraction and presence of polar lipid along with several non-lipid substances in the ethyl acetate fraction. The extract also tested positive for presence of saponins, phenolics, flavonoids, steroids and reducing sugars while it showed complete absence of anthroquinones. Conclusion: Our findings suggest that MESK can counter the effect of environmental factors such as high fat diet intake and has a potential to be used as an anti-obesity dietary supplement with desirable glucose and lipid metabolism modulating properties.', '{"arp_id": "ARP_AYU001664", "portal_id": 1664, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "5", "issue": "10", "pages": "4974 - 4978", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Dio Mice"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1664", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001664.pdf", "pdf_sha256": "81797bf7596a0659ce02755bab7f1429c5a8ca15f0f25e123a16c0ceaa951618", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOLIPIDEMIC EFFECT OF QUISQUALIS INDICA (LINN) AERIAL PARTS ON PASSIVE SMOKING & CHOLESTEROL DIET FED ANIMALS', '1,2. Jyoti Sahu, 1,2. Pushpena Kumar Patel, 1. Balkrishna Dubey.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: In the present study the effect of two different doses (100 mg/kg and 200 mg/kg) of methanolic and aqueous extracts of aerial part of Quisqualis indica on passive smoking and cholesterol diet (coconut, biscuit and milk powder) induced hyperlipidemia in rats has been investigated. Methods: In this study the plant Quisqualis indica aerial part was extracted in soxhlet apparatus with methanol and aqueous by following the successive extraction method and presence of various phytochemical constituent in plant extracts like flavonoids, alkaloid, amino acids, glycosides, acidic compounds etc had been estimated by using standard method. The hypolipidemic activity was analysed by reading the blood serum level in UV at 505 nm after treated with reagent present in auto span diagnostic kit. Results: Results showed that the simultaneously consumption of both cholesterol diet and passive smoking had increased more bad fats when compared to a particular one. Plant extracts had reduce the harmful lipid layer in blood serum at varying concentration and dose dependent manner which shows that the plant carries the hypolipidemic properties but the methanolic extracts at 200 mg/kg had been markly showed effect comparable hypolipidemic as that of standard Atorvastatin (10 mg/kg).', '{"arp_id": "ARP_AYU001678", "portal_id": 1678, "medical_system": "AYURVEDA", "journal": "Journal of Pharmacy Research", "volume": "5", "issue": "9", "pages": "4671 - 4675", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Atorvastatin"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1678", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001678.pdf", "pdf_sha256": "073525119cc55edde5f63ebc0e75b593ed8bf81a6941d693c89c6f9b1430dc7d", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF HYPOLIPIDEMIC EFFECT OF VARIOUS EXTRACTS OF WHOLE PLANT OF CLERODENDRUMPANICULATUM IN RAT FED WITH HIGH FAT DIET', 'Shaji Selvin CD, Rakhi AR.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The aim of the present study was to investigate the effect of the methanolic extract of leaves of Clerodendrum Paniculatum in reducing the cholesterol levels in experimentally induced hyperlipidemic rats.The acute toxicity study was found that methanolic extract was safe up to 2000mg/kg, so one tenth of this dose was consider as evaluationdose. The methanolic extract of Clerodendrum Paniculatum was administered in single doses of 200mg/kg/day and double dose of 400mg/kg/day to rats fed with high fat diet to assess its possible lipid-lowering potential.The elevated levels of total cholesterol, ester &amp;amp; free cholesterol, phospholipids, triglycerides, lowdensity lipoprotein, and very low-density lipoprotein due to HFD. Administration of methanolic extract of Clerodendrum Paniculatum(400mg/kg)was significantly (P&amp;lt;0.001)reduced the lipid profile and lipoprotein levels. A significant reduction in HDLcholesterol was noticed in HFD fed groups (II); however, a significant increased the HDL level was produced by the administration of methanolic extract of Clerodendrum Paniculatum (dose 400mg/kg). There was a noticed increase in the body weight in HFD fedgroup (II), which was reduced by the administration of methanolic extract of ClerodendrumPaniculatum(dose 400mg/kg).The methanolic extract of Clerodendrum Paniculatum could protect against atherosclerosis and decrease the atherogenic index Therefore, it was concluded that the methanolic extract of leaves of Clerodendrum Paniculatum has definitecardio protective effect against hyperlipidemia.', '{"arp_id": "ARP_AYU002052", "portal_id": 2052, "medical_system": "AYURVEDA", "journal": "European Journal of Biomedical and Pharmaceutical Sciences", "volume": "1", "issue": "1", "pages": "87 - 96", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Clerodendrum Paniculatum"], "original_url": "http://www.ejbps.com/ejbps/abstract_id/36", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2052", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002052.pdf", "pdf_sha256": "9d076463ef61d3c639ef26e70961371f99b4736462badc9ef93e6b443b70f86a", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '14613573', '10.1186/1477-3163-2-6', 'PROTECTION AGAINST DIETHYLNITROSOAMINE-INDUCED HEPATOCARCINOGENESIS BY AN INDIGENOUS MEDICINE COMPRISED OF NIGELLA SATIVA, HEMIDESMUS INDICUS AND SMILAX GLABRA: A PRELIMINARY STUDY', '1. Samantha S Iddamaldeniya, 1. Nalinie Wickramasinghe, 2. Ira habrew, 3. Neelakanthi Ratnatunge, 4. Mayuri G Thammitiyagodage.', 2003,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: A decoction comprised of Nigella sativa seeds, Hemidesmus indicus root and Smilax glabra rhizome is used to treat cancer patients in Sri Lanka. However, the anti-carcinogenic properties of this decoction have not been experimentally confirmed. The purpose of this study was to determine whether the above decoction could protect against chemically induce hepatocarcinogenesis.Methods: The effects of this decoction on diethylnitrosamine (DEN) induced hepatocarcinogenesis were examined in male Wistar rats using the medium term bioassay system of Ito, based on a 2-step model of hepatocarcinogenesis. Rats were randomly divided into 6 groups of 10 each. Groups 1 to 4 were injected with DEN (200 mg/kg) to initiate carcinogenesis. Twentyfour hours later groups 1 and 2 were administered the decoction at 4 g/kg body weight/day (dose 1) and 6 g/kg body weight/day (dose 2), respectively. Group 3 and group 4 were given distilled water instead of the decoction and a suspension of garlic powder (20 g/kg body weight/day) in distilled water (positive control), respectively. Group 5 and 6 were injected with normal saline and twenty-four hours later group 5 was given distilled water (normal control) while group 6 was given decoction dose 2 (decoction control). Oral feeding continued for two weeks after which all rats were subjected to 2/3 partial hepatectomy to promote carcinogenesis. Oral feeding continued for eight more weeks. At the end of the 10th week, rats were sacrificed and samples of livers taken for immunohistochemical studies. Carcinogenic potential was scored by comparing the number, area and staining intensity of glutathione S-transferase placental form (GST-P) positive foci and the number of cells/cm2 of the positive foci in the livers of the six groups of rats.Results: The number and area of DEN-mediated GST-P positive foci, number of cells/cm2 of foci and staining intensity of the foci were significantly (P &amp;gt; 0.001) reduced by the decoction and garlic in the order dose 2 = garlic &amp;gt;dose 1.Conclusion: Overall results indicate that the decoction comprised of N. sativa, S. glabra and H. indicus has the potential to protect rat liver against DEN induced hepatocarcinogenesis', '{"arp_id": "ARP_AYU005092", "portal_id": 5092, "medical_system": "AYURVEDA", "journal": "Journal of Carcinogenesis", "volume": "2", "issue": "1", "pages": "- - -", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["A Preliminary Study"], "original_url": "https://carcinogenesis.com/textasp2003/2/1/6/42435", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=5092", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU005092.pdf", "pdf_sha256": "edec2a2d210f822a84247df5edf0d8f64270e85fa7b3b1823393b9ade72506d5", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF BOUGAINVILLEA SPECTABILIS LEAVES ON SERUM LIPIDS IN ALBINO RATS FED WITH HIGH FAT DIET', 'Saikia H, Lama A.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Dyslipidemia is major problem among population those have sedentary life style as well as in diabetics. Bougainvillea spectabilis is most commonly found in India as an ornamental plant and has got anti-diabetic action due to presence of one insulin mimicking agent D-pinitol (3-O-methyl-chiroinositol). The present investigation was undertaken to evaluate the effect of alcoholic extract of leaves of Bougainvillea spectabilis (AEBSL) on serum lipid profile in albino rats fed with high fat diet (HFD) and to compare it with a standard hypolipidaemic drug simvastatin. Thirty healthy albino rats of both sexes (100-200 g) were randomized into 5 groups of 6 animals each. The groups were treated as follows: Group A: normal diet (ND); Group B: HFD (vanaspati ghee + coconut oil mixture in ratio of 3:2 at 10 ml/kg/day); Group C: HFD+ AEBSL (100 mg/kg/day); Group D: HFD + AEBSL (200 mg/kg/day); Group E: HFD + simvastatin (1.8 mg/kg/day). Lipid profile was estimated after 8 weeks of treatment. AEBSL showed a significant (p&amp;lt;0.01) reduction in total cholesterol (TC), Triglyceride (TG), Low density lipoprotein (LDL), Very low density lipoprotein (VLDL) levels and significant (p&amp;lt;0.01) increase in high density lipoproteins (HDL) in hypercholesteromic rats (Group C and Group D). AEBSL 200 mg/kg/day found to be more effective than AEBSL 100 mg/kg/day. There is also significant improvement in atherogenic index (p&amp;lt;0.01) and increases the percentage of protection AEBSL treated animals. Alcoholic extract of leaves of Bougainvillea spectabilis leaves have excellent lipid lowering potentiality.', '{"arp_id": "ARP_AYU005669", "portal_id": 5669, "medical_system": "AYURVEDA", "journal": "International Journal of Pharmaceutical Sciences and Drug Research", "volume": "3", "issue": "2", "pages": "141 - 145", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anti-Hyperlipidemic Activity"], "original_url": "https://ijpsdr.com/index.php/ijpsdr/article/view/266", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=5669", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU005669.pdf", "pdf_sha256": "7970266708466eb168da77f478b11b4f5e6e50f2e00f8426fef8328f009e0867", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'IN-VIVO ANTIOXIDANT AND LIPID PEROXIDATION EFFECT OF WHOLE PLANT OF IONIDIUM SUFFRUTICOSUM (GING.) IN RATS FED WITH HIGH FAT DIET', 'Satheeshkumar D, Kottai muthu A, Manavalan R.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The objective of the present investigation was to evaluate the in vivo antioxidant and lipid peroxidation effect of various extracts from whole plant of Ionidium suffruticosum (Ging.) in rat fed with high fat diet. Various extracts (Petroleum ether, Ethyl acetate and Methanol) of Ionidium suffruticosum (200 mg/kg body weight) was administered orally to rats fed with high-fat diet (HFD) daily for 9 weeks and the tissue (liver, heart and aorta) samples were collected at the end of experimental period. High fat diet rats showed significantly (P&amp;lt;0.001) reduced the levels of tissues enzymatic antioxidant and non enzymatic antioxidant (Glutathione). The level of thiobarbituric acid reactive substances (TBARS) are elevated in HFD rats (group II) when compared with control rats (group I). After administration of methanolic extract of Ionidium suffruticosum in high fat diet rats were showed significantly (P&amp;lt;0.001) increased the levels of antioxidant enzymes such as Superoxide dismutase (SOD), Catalase (CAT), Glutathione peroxidase (GPx), Glutathione reductase (GR) and incresed the level of non enzymatic antioxidant Glutathione (GSH) when compared with HFD rats (Group II). The methanolic extract of Ionidium suffruticosum in high fat diet rats were found reduced the concentration of TBARS than that of HFD rats (group II). Similar result was not observed in other two extract treatment groups. Based on the results, we concluded that the methanolic extract of Ionidium suffruticosum is a significant source of natural antioxidant, which might be helpful in preventing the progress of various oxidative stresses.', '{"arp_id": "ARP_AYU006015", "portal_id": 6015, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "5", "issue": "Suppl 2", "pages": "132 - 135", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant"], "original_url": "https://innovareacademics.in/journal/ajpcr/Vol5Suppl2/951.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6015", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006015.pdf", "pdf_sha256": "bfd1e6e25333b8eff2526e90583a8dcc4627858d1365c93bf4f34a28f95e2cdd", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOLIPIDEMIC EFFECT OF ACHYRANTHES ASPERA ON HIGH FAT DIET INDUCED ATHEROGENIC RATS', 'Venkatalakshmi P, Vedha Valli N, Sangeetha S.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Present investigation was undertaken to evaluate the hypolipidemic activity of aqueous extract of Achyranthes aspera in high fat diet induced atherogenic rats. High fat diet produced a significant increase in total cholesterol, VLDL, LDL, PL, Triglycerides, Free fatty acids and decrease in HDL. It also increased HMG CoA reductase activity. Reduction in the activity of Lipo protein lipase was observed. High fat diet also decreased the levels of SOD, CAT and reduced glutathione with associated increase in lipid peroxidation. Treatment with Achyranthes aspera (200mg./kg b.wt.,) altered the deranged metabolic profile and was effective in producing hypolipidemia.', '{"arp_id": "ARP_AYU006144", "portal_id": 6144, "medical_system": "AYURVEDA", "journal": "Research Journal of Pharmaceutical, Biological and Chemical Sciences", "volume": "3", "issue": "3", "pages": "75 - 84", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Achyranthes Aspera"], "original_url": "https://www.rjpbcs.com/pdf/2012_3(3)/[11].pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6144", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006144.pdf", "pdf_sha256": "76bab5849d7b3a97e9b9423c42672a17a8c8a335408198792948b3eafc82966c", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-OBESITY ACTIVITY OF SHOREA ROBUSTA G. LEAVES EXTRACT ON HIGH FAT DIET INDUCED OBESITY IN ALBINO RATS', 'Supriya K, Sarita Kotagiri, Vrushabena Swamy BM, Archana Swamy P, 1. Vishwanath KM.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Obesity is often defined simply as a condition of abnormal or excessive fat accumulation in adipose tissue, to the extent that health may be impaired. In the past 20 years, the prevalence rates of obesity have tripled in developing countries. Shorea robusta Geartn is a medicinal plant demonstrated to exert multiple health benefits. Hence, present study was undertaken to evaluate anti-obesity effect of hydro-alcoholic extract of Shorea robusta (HASR) leaves on high fat diet induced obesity in albino rats. Obesity was induced by administration of high fat diet for 4 weeks along with normal diet and obtained obese rats were treated with Shorea robusta in a dose of 200, 400 and 600mg/kg p.o for next 4 weeks. Physical parameters such as body weight, feed intake, various organs and adipose tissue weight and various biochemical parameters like serum glucose, triglyceride, cholesterol, LDL-C, HDL-C, VLDL-C, atherogenic index, SGPT and SGOT were evaluated and compared with both normal control and obesity control groups. From result, it was concluded that hydro-alcoholic Shorea robusta leaves extract is a potential drug which can be used for treatment of obesity and favours the correction of disturbed lipid profile.', '{"arp_id": "ARP_AYU006170", "portal_id": 6170, "medical_system": "AYURVEDA", "journal": "Research Journal of Pharmaceutical, Biological and Chemical Sciences", "volume": "3", "issue": "3", "pages": "542 - 554", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Adipose Tissue Weight"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6170", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006170.pdf", "pdf_sha256": "ae873e860f93308ccf4e5229348b4de7a16f75424f8c8a2ac74177ec79fa581a", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF METHANOLIC EXTRACT OF TUBEROUS ROOT OF IPOMOEA DIGITATA (LINN) ON HYPERLIPIDEMIA INDUCED BY RAT FED WITH HIGH FAT DIET', 'Kottai Muthu A, Alagumanivasagam G, Satheesh Kumar D, Manavalan R.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The aim of the present study was to investigate the effect of the methanolic extract of tuberous root of Ipomoea digitata in reducing the cholesterol levels in experimentally induced hyperlipidemic rats. The elevated levels of total cholesterol, ester &amp;amp; free cholesterol, phospholipids, triglycerides, low-density lipoprotein, and very low-density lipoprotein due to HFD. Administration of methanolic extract of Ipomoea digitata (300mg/kg)was significantly (P&amp;lt;0.001)reduced the lipid profile and lipoprotein levels. A significant reduction in HDL-cholesterol was noticed in HFD fed groups (II); however, a significant increased the HDL level was produced by the administration of methanolic extract of Ipomoea digitata (dose 300mg/kg). There was a noticed increase in the body weight in HFD fed group (II), which was reduced by the administration of methanolic extract of Ipomoea digitata (dose 300mg/kg). Therefore, it was concluded that the methanolic extract of tuberous root of Ipomoea digitata has definite cardio protective effect against hyperlipidemia.', '{"arp_id": "ARP_AYU007672", "portal_id": 7672, "medical_system": "AYURVEDA", "journal": "Research Journal of Pharmaceutical, Biological and Chemical Sciences", "volume": "2", "issue": "3", "pages": "183 - 191", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Hfd"], "original_url": "https://www.rjpbcs.com/pdf/2011_2(3)/23.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7672", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007672.pdf", "pdf_sha256": "d35d36bea6e9edbd27bbdb872bbdc58145cbdcac695b9035a0fbb056be9bed6b", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTI-HYPERLIPIDEMIC ACTIVITY OF AQUEOUS EXTRACT OF TERMINALIA CHEBULA & GAUMUTRA IN HIGH CHOLESTEROL DIET FED RATS', '1. Dipa A. Israni, 2. Kirti V. Patel, 2. Tejal R. Gandhi.', 2010,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Terminalia chebula RETZ. (Combretaceae), a native plant in India and Southeast Asia commonly known as Haritaki has been reported to exhibit a variety of biological activities. In the present study, aqueous extract of Terminalia chebula and its combination with Gaumutra were investigated for anti-hyperlipidemic activity in Sprague-dawley rats. Hyperlipidemia was induced by giving high cholesterol diet (2% cholesterol, 1% sodium cholate and 2% coconut oil) for thirty days in standard rat chow diet. Rats on high cholesterol diet showed significant increase (p&amp;lt;0.05) in serum and tissue cholesterol, LDL-C, VLDL-C, triglyceride, atherogenic index and decrease HDL-C levels. Treatment with Terminalia chebula (300mg/kg, p.o) and its combination with Gaumutra (30mg/kg, p.o) showed significant decrease (p&amp;lt;0.05) in serum and tissue serum and tissue cholesterol, LDL-C, VLDL-C, triglyceride, atherogenic index and increase HDL-C levels. Histological study showed that Terminalia. chebula caused decrease in aortic plaque and fatty liver formation but its combination with Gaumutra showed no significant effect in aorta and liver as compared to high cholesterol diet fed rats. Thus Terminalia. chebula and its combination with Gaumutra both are effective as an antihyperlipidemic agent.', '{"arp_id": "ARP_AYU007842", "portal_id": 7842, "medical_system": "AYURVEDA", "journal": "Pharma Science Monitor", "volume": "1", "issue": "1", "pages": "48 - 59", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Gaumutra"], "original_url": "https://www.pharmasm.com/download1_archive.php?articleid=9&amp;download_file=48-59.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7842", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007842.pdf", "pdf_sha256": "3119a573c4e2d4d566bcec5f467d76f07aea949eef39313b3c610200bc4a0fbd", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'STUDY OF THE ANTIHYPERLIPIDEMIC, ANTIOXIDATIVE AND ANTIATHEROGENIC ACTIVITY OF AEGLE MARMELOS LINN. IN RABBIT RECEIVING HIGH FAT DIET', 'Swarnamoni Das, Abdul Hakim, Ajay Mittal.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Aegle marmelos Linn. has been traditionally used as antihyperlipidemic. So we want to prove it scientifically. Twenty rabbits of either sex were taken and divided into four groups five in each as - Normal Control- received normal diet, Experimental Control- received high fat diet, Test drug - received high fat diet plus ethanolic extract of Aegle marmelos Linn.500 mg/Kg /day orally and Standard Drug- received high fat diet plus Atorvastatin 2.1 mg/Kg/day orally for 12 weeks and then animals were sacrificed. Blood sample collected and lipid profile, Catalase, Superoxide Dismutase and Malondialdehyde levels were measured. The antiatherogenic effect was assessed by atherogenic index and histopathology of aorta. Data were statistically analysed by one way ANOVA followed by multiple Dunnett’s test. Aegle marmelos Linn. significantly decreased serum lipids towards normal levels. It also increased catalase and SOD activity and decreased Malondialdehyde activity. Aegle marmelos Linn. has antihyperlipidemic, antioxidant and antiatherogenic effects.', '{"arp_id": "ARP_AYU007907", "portal_id": 7907, "medical_system": "AYURVEDA", "journal": "Asian Journal of Pharmaceutical and Clinical Research", "volume": "5", "issue": "4", "pages": "69 - 72", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antiatherogenesis"], "original_url": "https://innovareacademics.in/journal/ajpcr/Vol5Issue4/1239.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7907", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007907.pdf", "pdf_sha256": "26e129a80581337c808523babb0379092298efa1efc095b482d45919f5f8fa53", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A COMPARATIVE CASE STUDY ON ROLE OF PURIFICATORY THERAPY AND DIET IN SHVITRA (VITILIGO)', '2. Mallika Kurat Jayavarma, 1. Priyanka BV.', 2013,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Summary: Cases of shvitra vis-&amp;#224;-vis vitligo, approached with the complaints like white patches over lips, limbs and neck, which were managed successfully by adopting the well planned therapies followed by diet control.Key message: These case studies are new avenue for future research in successful management of shvitra vis-&amp;#224;-vis vitiligo by adopting treatment based on principles of ayurveda.', '{"arp_id": "ARP_AYU007921", "portal_id": 7921, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Holistic Medicine", "volume": "1", "issue": "4", "pages": "23 - 28", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "SKIN DISEASE OTHER(ICPC-S99|ICD-L10, L11, L12, L13, L14, L26, L28, L30.2, L30.5, L41, L43, L44, L45, L51, L52, L53.0, L53.1, L53.2, L53.3, L53.8, L54, L60.2, L60.3, L60.8, L68, L71, L72.0, L72.2, L72.8, L72.9, L73.0, L73.1, L73.8, L73.9, L80, L81.1, L81.4, L81.5, L81.6, L81.7, L81.8, L81.9, L82, L8)", "keywords": ["Ayurveda"], "original_url": "http://www.jahm.co.in/index.php/jahm/article/view/110", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7921", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007921.pdf", "pdf_sha256": "717a6d2d597213673185a57f6e7b75e94975172f4fd46ed82dc50985088a871f", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF ANTIDIABETIC ACTIVITY OF METHANOLIC EXTRACT OF FLOWERS OF CASSIA SIAMEA IN ALLOXAN INDUCED DIABETIC RATS OF BASAL DIET AND MAIDA MIXED DIET', 'Pushpavathi P, Janarthan M, Firasat Ali.', 2013,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: This study was carried out to evaluate the antihyperglycemic effect of the Methanol extracts of the flowers of C. siamea on alloxan induced rats of normal diet and maida mixed diet. The extracts were orally administered daily at 200 and 400 mg kg-1 body weight for three weeks. The effects of the extracts on Fasting Blood Glucose (FBG) level were determined weekly. All rats in the diabetic groups (both basal diet and maida mixed diet) had FBG levels well within the diabetic range (&amp;gt;150 mg dL-1) at the initial stage of the experiment but after three weeks of treatment with extracts or metformin. The FBG significantly dropped in dose-dependent manner, and also correct the lipid profile and liver enzymes. The results suggest that the Methanol extracts of the flowers of Cassia siamea restored the metabolic changes in alloxan-induced diabetic rats.', '{"arp_id": "ARP_AYU008397", "portal_id": 8397, "medical_system": "AYURVEDA", "journal": "Indian Journal of Research in Pharmacy and Biotechnology", "volume": "1", "issue": "5", "pages": "625 - 628", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Alloxan"], "original_url": "https://www.ijrpb.com/issues/Volume%201_Issue%205/ijrpb%201(5)%2010%20pushpavathi%20625-628.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8397", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008397.pdf", "pdf_sha256": "fecdc42cecca77426634765119314c3c15000d3253949832806cffa66bc8285f", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'HYPOLIPIDEMIC EFFECT OF CALOTROPIS GIGANTEA SEEDS EXTRACT ON HIGH FAT DIET INDUCED ATHEROGENIC RATS', '1. Jatin Jaiswal, 1. Hemant Bhardwaj, 2. Rao ChV, 3. Nisha Sharma.', 2014,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: The present study was designed to evaluate the hypolipidemic activity of Calotropis gigantea seeds on high fat diet induced atherogenic rats. Methods: The acute toxicity studies were performed on mice while adopting the OECD-420 Guidelines (fixed dose procedure). The hypolipidemic effect of plant seed extracts was evaluated on the standard 28 days model. Results: Treatment with methanolic extract of Calotropis gigantea (MECG) seeds at the dose 200 mg/kg and 400 mg/kg body weight showed the significant decrease in the total cholesterol levels, triglycerides levels, VLDL-c and LDL-c levels, whereas there was slight increase in HDL-c levels.The activities were also compared with the effects produced by the standard anti-hyperlipidemic drug, atorvastatin 10 mg/kg. Conclusion: The present findings indicate that the seeds of Calotropis gigantea has a potent hypolipidemic effect on HFD induced atherogenic rats.', '{"arp_id": "ARP_AYU008697", "portal_id": 8697, "medical_system": "AYURVEDA", "journal": "World Journal of Pharmacy and Pharmaceutical Sciences", "volume": "3", "issue": "6", "pages": "1139 - 1147", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Calotropis Gigantea"], "original_url": "http://www.wjpps.com/admin/assets/article_issue/1401590535.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8697", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008697.pdf", "pdf_sha256": "924126ca9a2576cb694f27e719aef5bae7015648b1df7b7f97deca67387b157e", "relevance_score": 41.0, "topic_domain": "traditional_diets_food"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A PILOT CLINICAL TRIAL OF SUSHRUTOKTA GARBHINI AHAR AS A PREVENTIVE MEASURE IN PREGNANT WOMEN HAVING HISTORY OF PREGNANCY LOSS IN THE FIRST TRIMESTER', '1. Suhas Herlekar, 2. Rujuta Dubey, 2. Hemalata Shende, 3. Bhausaheb Vikhe.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The term ‘miscarriage’ is used to describe a pregnancy that fails to progress, resulting in death and expulsion of the embryo. When this happens more than once, it is termed as ‘recurrent pregnancy loss’. Sushrutacharya in his Samhita has described this condition and has also suggested methods to prevent it.Charaka Acharya says that if appropriate care is taken during early pregnancy, along with proper drugs, healthy diet and good exercise, then the woman gives rise to a healthy child. The principle aim of this trial is to evaluate the importance of administration of selected drugs and their combination during the pregnancy to prevent the miscarriage and avoid pregnancy loss.A liquid herbal formulation mentioned by Sushrutacharya was prepared in cow’s milk, boiled, cooled to room temperature and administered to pregnant women orally at different stages of pregnancy. It was observed that in comparison to modern treatment this therapy had much better results and satisfactory clinical output.', '{"arp_id": "ARP_AYU001191", "portal_id": 1191, "medical_system": "AYURVEDA", "journal": "Rasamruta", "volume": "4", "issue": "10", "pages": "1 - 15", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "PREGNANCY, CHILDBEARING, FAMILY PLANNING", "disease": "PREGNANCY HIGH RISK(ICPC-W84|ICD-O24.0, O24.1, O24.2, O24.3, O24.9, O25, O30, O31, O32, O33, O34, O35, O36, O40, O43, O44, O99.0, O99.1, O99.2, O99.3, O99.4, O99.5, O99.6, O99.7, Z35)", "keywords": ["Pregnancy Loss First Trimester"], "original_url": "http://www.rasayu.com/e-journal/pdf/Rasamruta-4-10.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1191", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001191.pdf", "pdf_sha256": "28d6b4f535c701866ac49dd2ad0d237e1b439662e533f9303f9e9c227ee9baa7", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF GANDHARVAHASTHADI KWATHA IN THE MANAGEMENT OF GRUDHRASI - A PROSPECTIVE OPEN CONTROLLED CLINICAL TRIAL', '1. Christy J Thundiparambil, 2. Sunitha Poly, 3. Pramod V Kulkarni, 4. R. Ilanchezhian, 5. C. Roshy Joseph.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Grudhrasi is a painful condition chiefly affecting the lower back area which radiates downwards to one leg or both the legs. Gandarvahasthadi Kwatha is a potent orally administrable pharmaceutical drug combination of Gandarahastha, Chiruvilwa, Hutaswa, Vishwam, Pathya, Punamava, Yavashaka, Bhumithalam, commonly used in the treatment of various vata vyadhi’s. The main objective of the study was to assess the efficacy of Gandharvahasthadi Kwatha as a trial drug in the management of Grudhrasi. The sample size of the study was 100. Results of 100 patients with Grudhrasi in study group were analyzed. The results were statistically analyzed before &amp;amp; after treatment and follow up with help of student‘t’ test. In all the symptoms the paired‘t’ test had denoted that the treatment is highly significant (p&amp;lt;0.001), which implies that Gandharvahasthadi kwatha is effective in the treatment of Grudhrasi.', '{"arp_id": "ARP_AYU001802", "portal_id": 1802, "medical_system": "AYURVEDA", "journal": "Ayurpharm  International Journal of Ayurveda and Allied Sciences", "volume": "1", "issue": "6", "pages": "124 - 131", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "BACK SYNDROME WITH RADIATING PAIN(ICPC-L86|ICD-M47.1, M47.2, M51, M54.3, M54.4)", "keywords": ["Gandharvahasthadi Kwatha"], "original_url": "-", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1802", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001802.pdf", "pdf_sha256": "9ca4eb39cb3ccfba2d10e21090fe1dc6a3f561cdd5404a912ace18a869e6e6e9", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL TRIAL OF BASTI IN AMAVATA', 'Kamlesh Kumar Pandey, Antapurkar Shital, P Yadaiah.', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: In this study 40 amavata patients have been selected and randomly divided into two groups. First group was given Bruhat Saindhvadi Tail Matra Basti for 8 days whereas second group was given niruha basti (in term of yoga basti) for 8 days. Total duration of treatment was one month. In Bruhat saindhvadi tail matra basti (Group 1) 60% patients have shown excellent result, 15% patients have shown good results and 10% patients have shown fair results. While in Yog Basti (Group 2) 55% patients have shown excellent results, 15% patients have shown good results and 15% patients have shown fair results. No patient found unchanged. So we can say that both the groups have shown excellent results for Amavata.', '{"arp_id": "ARP_AYU004973", "portal_id": 4973, "medical_system": "AYURVEDA", "journal": "Bharatiya Vaigyanik evam Audyogik Anusandhan Patrika", "volume": "18", "issue": "1", "pages": "98 - 102", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "RHEUMATOID/SEROPOSITIVE ARTHRITIS(ICPC-L88|ICD-M05, M06, M08, M45)", "keywords": ["Amavata"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/10146", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4973", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU004973.pdf", "pdf_sha256": "35dad81ef768ae02513a2dcaf1290653a1a23b2e25843776ed2fdb3f865a16ed", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF AYURVEDIC TREATMENT ON TROPHIC ULCERS OF LEPROSY - A COMPARATIVE CLINICAL TRIAL', '1. Sarita Gaikwad, 2. Pradip Y.Gaikwad.', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: A comparative clinical trial on trophic ulcers in leprosy was undertaken to examine the effect of ayurvedic treatment on healing of trophic ulcers. There were 31 subjects in the study group and 31 in control group. The subjects were given ayurvedic treatment and the control subjects were treated conventional allopathic line treatment. The study proved that the ayurvedic treatment is a better alternative for treating trophic ulcers in leprosy.', '{"arp_id": "ARP_AYU018098", "portal_id": 18098, "medical_system": "AYURVEDA", "journal": "Aryavaidyan", "volume": "23", "issue": "3", "pages": "139 - 143", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "CHRONIC ULCER SKIN(ICPC-S97|ICD-I83.0, I83.2, L89, L97, L98.4)", "keywords": ["Ayurvedic Treatment"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18098", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018098.pdf", "pdf_sha256": "afb72f0eda80a08e76955b475ca10e47066c7d22993668ad05977ed33abef8b8", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'IMPORATANCE OF EVIDENCE-BASED AYURVEDIC TREATMENT - A CLINICAL TRIAL ON PSORIASIS', 'Madhu PM.', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Well established randomized clinical trails involving large number of patients are the tool for evaluation of theories or efficacy of herbal medicines. According to the theories and concepts of traditional medicine, prevention, diagnosis, improvement and treatment of illness are often based on the specific needs of the individual patient. So even a single case study itself is significant. In this context, an observational clinical study was conducted on 20 patients of psoriasis. It is amazing that our traditional medical knowledge could impart better outcomes in the management of psoriasis with scientific back ground.', '{"arp_id": "ARP_AYU019151", "portal_id": 19151, "medical_system": "AYURVEDA", "journal": "Aryavaidyan", "volume": "23", "issue": "4", "pages": "213 - 215", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "PSORIASIS(ICPC-S91|ICD-L40)", "keywords": ["Evidence-Based Ayurvedic Treatment"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19151", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019151.pdf", "pdf_sha256": "36bd9156dbc4d92d826f6b75a90253372d053b03938f300c0ab2270f369b2bfd", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF VYOSADI GUGGULU IN BORDERLINE HIGH HYPERCHOLESTEROLEMIA/ HYPERLIPIDEMIA - AN OPEN CLINICAL TRIAL.', 'Rao BCS, S. Sahoo, Sudhakar D.', 2012,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Hypercholesterolemia is a known risk factor for coronary artery disease (CAD). It is imperative; therefore, that both primary and secondary prevention of CAD must include measures to treat hypercholesterolemia. Considering the continuing debate on the effectiveness and possible adverse effects of many synthetic cholesterol lowering drugs, the present study was carried out to assess the effect of Vyosadi guggulu on hypercholesterolemia [Total cholesterol, LDL, BDL, VLDL and Triglycerides (TG)]. 32 persons of hypercholesterolemia of either sex and up to an age group of 60 years (who had the borderline high lipid profile), were included in this three months&#39; study. The results showed highly significant decrease in total cholesterol, LDL, VLDL and TG.', '{"arp_id": "ARP_AYU019274", "portal_id": 19274, "medical_system": "AYURVEDA", "journal": "Aryavaidyan", "volume": "26", "issue": "1", "pages": "22 - 26", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "LIPID DISORDER(ICPC-T93|ICD-E78)", "keywords": ["Coronary Artery Disease (Cad)"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19274", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019274.pdf", "pdf_sha256": "19b00f3573bb56db467c60b560e36768359101bdd7f4dd324cc814c85f473760", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL TRIAL ON I.G FORMULA AS A PROPHYLACTIC MEDICINE IN VISHAMA JWARA VIS-A-VIS MALARIA', '1. Bharathi K, 2. Kanchana Srinivasan, 3. Revathi R, 4. Acharya MV.', 2010,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Malaria is a widespread tropical disorder characterized by relapsing febrile illness, chills, rigors, headache etc. Controlling / eradication of the disease is difficult to achieve and recurrence is the commonest phenomenon in endemic areas. Around 1.1 million deaths are due to Malaria worldwide. Malaria can be compared with Vishamajwara based on the irregular onset and remission. Present study is the prophylactic trial of Malaria. Study carried out with a poly-herbal formulation called ‘Indukanthaghritam’ on 67 patients, of which, 35 (74.46%) showed Good response, 11 (23.40%) patients Fair response and 01 (2.12%) did not show any response. Due to irregular drug intake and follow lip, 09 patients dropped out from the study, and 11 patients were LAMA. To create evidence based therapy, assessment of serum immunoglobulins done before and after treatment.', '{"arp_id": "ARP_AYU020902", "portal_id": 20902, "medical_system": "AYURVEDA", "journal": "Journal of Research in Ayurveda and Siddha", "volume": "31", "issue": "4", "pages": "13 - 22", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "GENERAL/UNSPECIFIED", "disease": "MALARIA(ICPC-A73|ICD-B50, B51, B52, B53, B54)", "keywords": ["Vishama Jwara"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20902", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020902.pdf", "pdf_sha256": "a088bfb2507859363ff4671680808f8cce6bd6e1758e16fbf25c6a183718159d", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL TRIAL ON VYOSHADI GUGGULU IN THE PREVENTION AND MANAGEMENT OF MEDOROGA (OBESITY)', '1. Ramji Singh, 1. Singh SK, 1. Singh S, 1. Tiwari RK, 2. Dubey GP.', 2011,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Medoroga (obesity) is a syndrome which is characterized by deposition of Excess fat in the body. It is a mainly genetic predisposed disorder in which there is increased body weight, body mass along with exertional dyspnoea, varicose vein and reduction in sexual and psychological fitness of the body. Secondarily diet enriched in fat and carbohydrate, metabolic disorders due to imbalance between energy in take and energy expenditure leads to obesity also. The classical literature has discussed many complications of Medoroga like Premeha, Prmeha Pidika, Bhagandara, Vidradhi Vataroga etc. A series of Clinical trials have been conducted with Arogya Vardhani vati, Guggulu and its various extraction different lipid functions in the blood. It has been observed that Petroleum eather extract of Guggulu and Phytogenic Principle (Ketosteroids) showed the definite hypolipidemic anti obesity and antianthosclerotic effect in the experimental studies. In the present clinical study out of 243 registered cases for trial, 29 showed good response, 69fair response, 92 poor response and 24 cases showed no response while 29 cases drop out.', '{"arp_id": "ARP_AYU020922", "portal_id": 20922, "medical_system": "AYURVEDA", "journal": "Journal of Research in Ayurveda and Siddha", "volume": "32", "issue": "3-4", "pages": "131 - 144", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "OBESITY(ICPC-T82|ICD-E66)", "keywords": ["Medoroga Obesity"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20922", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020922.pdf", "pdf_sha256": "401cbaceaf05165e9a16d00929447204e7a0bd6b0797b3a7def858ad88a4fe37", "relevance_score": 41.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.13040/IJPSR.0975-8232.3(1).268-72', 'IN VITRO ANTIMICROBIAL ACTIVITY NUTRITIONAL PROFILE OF MEDICINAL PLANT OF GARHWAL, HIMALAYA', 'Sarla Saklani, Subhash Chana.', 2012,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present study is aimed at evaluating the in vitro antibacterial and antifungal activities of petroleum ether, chloroform, ethyl acetate, acetone, methanol, ethanol and water extracts of medicinal plant, Pyrus pashia were tested against (different gram positive and gram negative) ten bacterial strains and three fungal strains using by disc diffusion method. The different fractions of bark, fruit and leaf of Pyrus pashia, the ethanolic bark extracts of Pyrus pashia showed significant activity 17&amp;#177;1mm, 15&amp;#177;1mm and 14&amp;#177;1mm against Klebsiella pneumonia, Shigella flexneri and Escherichia coli. The medicinal plant fruit contain ash value, (total ash 1.10 &amp;#177; 0.05%), moisture 60.36&amp;#177;0.25%, crude fat 1.62&amp;#177;0.20% and crude fiber 5.26&amp;#177;0.05%, extractive values were studied fresh part weight. The preliminary phytochemical analysis test showed the presence of carbohydrates (28.38&amp;#177;0.12%) and glycosides, alkaloid, flavonoids, saponins, tannins, unsaturated triterpenoids and sterol, resin.', '{"arp_id": "ARP_AYU003494", "portal_id": 3494, "medical_system": "AYURVEDA", "journal": "International Journal of Pharmaceutical Sciences and Research", "volume": "3", "issue": "1", "pages": "268 - 272", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antimicrobial"], "original_url": "https://ijpsr.com/bft-article/in-vitro-antimicrobial-activity-nutritional-profile-of-medicinal-plant-of-garhwal-himalaya/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3494", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003494.pdf", "pdf_sha256": "0f8054710e99a4dab9470aa41a56aafbfceef0a1c58afe107222797bf84590d9", "relevance_score": 40.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'BOMBAX CEIBA CALYCES REGULATE CARBOHYDRATE AND LIPID DIGESTING ENZYMES ACTIONS, DISPLAY INSULIN SENSITIZING AND ANTIOXIDANT ACTIVITIES IN VITRO: A NUTRITIONAL AND PHYTOCHEMICALS EXAMINATION.', '1,2. Komati Anusha, 1,2,3. Ajay Anand, 1,2. Katragadda Suresh Babu, 1,2. Ashok Kumar Tiwari.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Calyces of Bombax ceiba (Salmali, ???????) are used as vegetable by traditional Indian folks. However, scientific investigations for this vegetable are not available in literature. This research presents nutritional and phytochemicals composition in raw calyxes’ powder and antihyperglycemic, antihyperlipidemic, insulin-sensitizing and, antioxidant properties in aqueous methanolic extract of calyx applying various in vitro methods. Calyx powder displayed rich source of macro- and micronutrients with energy value 322 Kcal. /100 g. Aqueous methanol extract of calyces exhibited potent antihyperglycemic activities by inhibiting pancreatic a-amylase and intestinal a-glucosidase enzymes, antihyperlipidemic by inhibiting pancreatic lipase and insulin sensitizing property by inhibiting PTP1ß. It was found to be potent scavenger of chemical and physiological free radicals and, presented antioxidant activities by preventing H2O2 induced erythrocytes membrane lipid peroxidation and hemolysis. It also prevented H2O2 induced genomic DNA damage. The calyx powder presented 979 µg/100 g total antioxidant value. This report presents original analysis of nutritional and phytochemical composition along with biological activities in B. ceiba calyx.', '{"arp_id": "ARP_AYU003755", "portal_id": 3755, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "21", "issue": "2", "pages": "323 - 331", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Antioxidant Property"], "original_url": "http://nopr.niscpr.res.in/handle/123456789/59659", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3755", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003755.pdf", "pdf_sha256": "c910192c9b39d23249be44f8924fecc9c9989ec3bdde8740eaceb95b7042beb4", "relevance_score": 40.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/2229-5119.83963', 'HEPATOPROTECTIVE ACTIVITY OF TWO INDIAN MEDICINAL PLANTS FROM WESTERN GHATS, TAMIL NADU', 'Balakrishnan N, Balasubaramaniam A, Sangameswaran B, 1. Bhaskar VH.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: The roots of Carissa carandas Linn. (Apocynaceae) and Pergularia daemia (Forsk.) Chiov. (Asclepiadaceae) were used by the tribes of Western Ghats, Tamil Nadu, for the treatment of various liver disorders. Materials and Methods: In the present study, the ethyl acetate fraction of the ethanol extract from roots of C. carandas (CCF) and P. daemia (PDF) were studied against carbon tetrachloride-, paracetamol-, and ethanol-induced hepatotoxicity in rats. Results: Significant hepatoprotective effects were obtained against liver damage induced by all the three toxins, as evident from changed biochemical parameters like serum transaminases (SGOT and SGPT), alkaline phosphate (ALP), total bilirubin, total protein, and total cholesterol. Parallel to these changes, the ethyl acetate fraction prevented toxin-induced oxidative stress by significantly maintaining the levels of reduced glutathione (GSH) and malondialdehyde (MDA), and a normal architecture of the liver, compared to toxin controls. Conclusion: The results indicate that CCF and PDF could be useful in preventing chemically induced acute liver injury.', '{"arp_id": "ARP_AYU001012", "portal_id": 1012, "medical_system": "AYURVEDA", "journal": "Journal of Natural Pharmaceuticals", "volume": "2", "issue": "2", "pages": "92 - 98", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Carbon Tetrachloride"], "original_url": "https://primo.qatar-weill.cornell.edu/permalink/974WCMCIQ_INST/1e7q4lh/cdi_openaire_primary_doi_7d9ba8362b978529612b7a5569a7007d", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1012", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001012.pdf", "pdf_sha256": "7b76e7e4582d019f306e55d705929f0c69ba7c3312dbad8f7ae2fe7728adaa71", "relevance_score": 40.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '8880292', NULL, 'RANDOMIZED PLACEBO-CONTROLLED, SINGLE BLIND TRIAL OF HOLY BASIL LEAVES IN PATIENTS WITH NONINSULIN-DEPENDENT DIABETES MELLITUS.', 'Agrawal P, Rai V, Singh RB.', 1996,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Experimental studies on albino rats reported that leaf extract of Ocimum sanctum and Ocimum album (holy basil) had hypoglycemic effect. To explore further evidence we studied the effects of treatment with holy basil leaves on fasting and postprandial blood glucose and serum cholesterol levels in humans through randomized, placebo-controlled, crossover single blind trial. Results indicated a significant decrease in fasting and postprandial blood glucose levels during treatment with holy basil leaves compared to during treatment with placebo leaves. Fasting blood glucose fell by 21.0 mg/dl, confidence interval of difference -31.4 - (-)11.2 (p &amp;lt; 0.001), and postprandial blood glucose fell by 15.8 mg/dl, confidence interval -27.0 - (-)5.6 (p &amp;lt; 0.02). The lower values of glucose represented reductions of 17.6% and 7.3% in the levels of fasting and postprandial blood glucose, respectively. Urine glucose levels showed similar trend. Mean total cholesterol levels showed mild reduction during basil treatment period. The findings from this study suggest that basil leaves may be prescribed as adjunct to dietary therapy and drug treatment in mild to moderate NIDDM.', '{"arp_id": "ARP_AYU002598", "portal_id": 2598, "medical_system": "AYURVEDA", "journal": "International Journal of Clinical Pharmacology and Therapeutics", "volume": "34", "issue": "9", "pages": "406 - 409", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Basil"], "original_url": "http://www.ncbi.nlm.nih.gov/pubmed/8880292", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2598", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002598.pdf", "pdf_sha256": "5c0d25720af6c0c7373641493d6480e498e2d0f80dbca003e32fe224b9e4c3cc", "relevance_score": 40.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v13i2.2633', 'INFLUENCE OF DEHA-PRAKRITI (BODY CONSTITUTION) IN THE MANIFESTATION OF DISEASE IN CONTEXT TO AMAVATA (RHEUMATOID ARTHRITIS) - AN APPRAISAL.', '1. Rajkumar Chintala, 2. Bhagavathi NNL.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Deha-Prakriti (DP) is Ayurveda’s one-of-a-kind contribution, established at conception and cannot be changed throughout one’s life. There are seven varieties of DP. Vataja, Pittaja, Kaphaja (Shleshmala), Samsargaja [combination of two Dosha] i.e. Vata-Pittaja, Pitta-Kaphaja, Kapha-Vataja, Sannipataja [combination of three Dosha] i.e. Vata-Pitta-Kapha. The first and most important aspect of Dashavidha-parikshyabhavas (ten important examination factors to be known by the physician) is the DP assessment since it plays a crucial part in Rogi-Pariksha (evaluation of the patient) and Roga-Pariksha (assessment of the disease). DP allows a physician to assess the condition of Koshtha (digestion system), Agni (digestive capacity), Bala (strength), and Ayu (life-span) in both healthy and diseased people. It may also help a physician forecast illness susceptibility, severity of signs and symptoms, disease activity scores, and bio-markers such as hematological, pathological, and biochemical indicators. Based on the severity, a physician may prepare the appropriate diet-chart, medication, dose, Anupana (co-drink to the primary medicine), and treatment technique (either Shodhana karma- purificatory measure or Shamana karma- Palliative measure). In light of the above facts, the current study aims to explore the DP-based susceptibility to Amavata, its severity, and the research strategy for future studies. An overview of evidence-based study on developing Deha-Prakriti with diverse illness conditions may be provided in this work, allowing for the revalidation of ayurvedic literature-based assertions.', '{"arp_id": "ARP_AYU015601", "portal_id": 15601, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "13", "issue": "2", "pages": "258 - 267", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Amavata"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/2633", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15601", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015601.pdf", "pdf_sha256": "d40d3b5338d8f71adf9e7e76365f69705777442b6d2a4ded08ff71545c9c9cf6", "relevance_score": 40.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2019/23286', 'AFFILIATION AMONG INFANTILE AGE, MORBIDITY AND PRAKRITI (PHYSICAL CONSTITUTION): A LONGITUDINAL PRELIMINARY STUDY.', '1. Niraj Srivastava, 2. Sangeeta Gehlot, 3. Singh BM.', 2022,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Background: Prakriti has important role in prevention, diagnosis, treatment of disease and forecast of future disorders. Infants are more prone to develop various health problems like infections, due to poor immune system. This study shows relation between infantile age morbidity and their Prakriti (physical constitution) in present scenario. Material and Methods: For this longitudinal study 100 infants were registered for Prakriti assessment and their relationship with incidence of diseases. Performa for Prakriti assessment in infants was developed by Department of Kaumarbhritya/Balroga and Department of Kriya Sharira. This study was conducted in Kaumarbhritya OPD, SS Hospital, Banaras Hindu University (BHU). Observation and Result: In the present study, rate of morbidity in infantile age was found maximum in Vata Prakriti (6.6 episodes/infant/year) and minimum in Kapha Prakriti (1.54 episodes/infant/year). Incidence of morbidity was 2.41 episodes/infant/year. The commonest morbidities were respiratory tract infections (40.66%) and diarrhea (30.29%). Respiratory tract infection is most common morbidity in Vata Prakriti (33.3%), Kapha Prakriti (73.5%), Vata-Pitta Prakriti (48.1%) and Vata Kapha Prakriti (53.3%) infants. Diarrhea was the most common morbidity in Pitta Prakriti (32.2%) and Pitta-Kapha Prakriti (50.0%) infants. Discussion and Conclusion: Rate of morbidity was found more in Vata Prakriti and less in Kapha Prakriti infants which justifies the concept of Ayurveda that feature of Vata Prakriti is Shighravikara and Kapha Prakriti have Ashighravikara. Vata and Kapha Prakriti infants mostly suffer from respiratory tract infection and Pitta Prakriti infants mostly suffer from diarrhea. In present study incidence of morbidity was 2.41 episodes/infant/year and most common morbidity was respiratory tract infection and diarrhea.', '{"arp_id": "ARP_AYU015607", "portal_id": 15607, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "19", "issue": "1", "pages": "43 - 48", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "-", "disease": "-", "keywords": ["Ayurveda"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/23286", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15607", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015607.pdf", "pdf_sha256": "866d3fc085dd5f7b011c518dc97e106d84b06df4db82527d6096280f65fabdd2", "relevance_score": 40.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2019/23395', 'VARIATIONS OF HUMAN MILK COMPOSITIONS AS PER PRAKRITI (PSYCHOSOMATIC CONSTITUTION): A PILOT STUDY.', '1. Deeksha Singh, 2. Sangeeta Gehlot, 3. Singh BM, 4. Rai DC.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Introduction: Mother’s milk is considered to be the supreme food for neonates, infants and toddler. It is also regarded as the finest gift form a mother to her baby. The individual characteristic of a person enumerating external and internal body features is known as Prakriti. It is the sense of personality or constitution or temperament of an individual. The aim of the present study was to assess variations of human milk composition as per PrakritiMaterials and Methods: Total 64 lactating mothers of 20-35 years age group, not suffering from any acute or chronic illness and who were on similar diet regardless of their mode of delivery were registered and included in the study while lactating mothers not falling in this age group or who were taking any specific drug for the illness or suffering from any disease including- moderate (9.97-7 g/dl) to severe (6.94-4 g/dl) anemia were excluded from the study. Result: On applying One Way ANOVA, the mean values of fat percentage in milk varied significantly as per Prakriti (p = 0.0287). On applying Post Hoc Test the significant pairs were for Vata vs. Pitta (&amp;lt;0.05) and Vata vs Kapha (&amp;lt;0.05) Prakriti. In all other parameters of milk, no significant variation was found. Conclusion: We can conclude that the composition of mother&amp;#226;€™s milk varies as per Prakriti.', '{"arp_id": "ARP_AYU015616", "portal_id": 15616, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "19", "issue": "3", "pages": "135 - 138", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ayurveda"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/23395", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15616", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015616.pdf", "pdf_sha256": "fb09ad8275f1cecdebbac373a500f579dc0dd47283e80cfe95048c746011b695", "relevance_score": 40.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.18311/jnr/2019/23584', 'CONCEPTS OF PRAKRITI (HUMAN CONSTITUTION) AND ITS ASSOCIATION WITH HEMATOLOGICAL PARAMETERS, BODY MASS INDEX (BMI), BLOOD GROUPS AND GENOTYPES.', '1. Niraj Srivastava, 2. Varsha Saxena.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Ayurveda is an ancient system of personalized medicine, documented and practiced in India since 1500 B.C. According to this system an individual’s basic constitution to a large extent determines predisposition and prognosis to diseases as well as the therapy and life-style regime. Ayurveda describes seven broad Prakriti (Physical constitution) Prakriti is defined as the sum of physical, physiological, psychological traits of an individual which represents genotypes. Objective: In this article we have attempted to narrate concepts of Prakriti and its relation with hematological parameter, body mass index, blood groups and genotypes. Material and Method: Present article is based on critical review of Ayurvedic textual information, published research works, modern literature and research works conducted at various institutes. The possible correlation has been made between collected information and has been presented in systematic way. Result: In Pitta Prakriti individual’s hematological parameters like Hemoglobin (Hb%), Packed cell volume (PCV), and Red blood corpuscles (RBC) count are significantly on the higher side of normal range in comparison to Vata and Kapha Prakriti. Higher level of cluster of differentiation (CD) 14 markers in Pitta Prakriti, CD25 and CD56 in Kapha Prakriti individuals. Vata Prakriti individuals have “A” blood group, maximum Pitta Prakriti individuals have “O” blood group while maximum Kapha Prakriti individuals have “B” blood group and genotype correlation shows that HLA DRB1 ((human leukocyte antigen, dimer beta chain) gene polymorphism, CYP2C19 (Cytochrome P450 2C19) gene polymorphism and PGM1 (Phosphoglucomutase 1) polymorphism have scientific variations with the human Prakriti concept. Conclusion: Prakriti of individual has strong relation with Hematological parameters (CBC, lipid profile, Liver function test (LFT)), Body mass index (BMI), anthropometry, blood groups and genotypes.', '{"arp_id": "ARP_AYU015621", "portal_id": 15621, "medical_system": "AYURVEDA", "journal": "Journal of Natural Remedies", "volume": "19", "issue": "4", "pages": "162 - 168", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Blood Groups"], "original_url": "https://www.informaticsjournals.com/index.php/jnr/article/view/23584", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=15621", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU015621.pdf", "pdf_sha256": "2c56ef0ebbdea52689dacd5c90745d8d90df987141b7439f2862c53beddfcbb2", "relevance_score": 40.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.47552/ijam.v14i3.3896', 'VARIATIONS IN THE SEVERITY OF SYMPTOMS, DAS28, AND DISABILITY INDEX AMONG DIFFERENT VATA PREDOMINANT DEHA-PRAKRITI INDIVIDUALS OF AMAVATA (RHEUMATOID ARTHRITIS) - AN ANALYTICAL OBSERVATIONAL STUDY.', '1. Rajkumar Chinthala, 2. Kamble SB, 3. Bhagavathi NNL, 2. Baghel AS.', 2023,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Subgrouping of diseased population, based on Deha-Prakriti (DP), phenotypic classification of Ayurveda will explore the variation in the disease severity, which further aid in the management of the disease more precisely and selectively. But there is a paucity in the data generation. Amavata (~Rheumatoid Arthritis) is one of such diseases, resulting from the conglomeration of Ama and aggravated Vata gets lodged in the joints. Aim &amp;amp; Objective: To evaluate variations in the severity of symptoms, duration of morning stiffness, DAS28 (Disease Activity Score in 28 Joints), and Disability Index (DI) among different Vata predominant Deha-Prakriti (DP) individuals of Amavata (~Rheumatoid Arthritis). Materials &amp;amp; Methodology: The study was conducted among 155 clinically diagnosed patients of Amavata, who were screened for DP assessment through the CCRAS-PAS scale. Those who were found to have Vata predominant DP were sub-grouped into Single Vataja (V), Vata-Pittaja (VP), and Vata-Kaphaja (VK) DP, based on the proportion of the doshas in the output of scale. Demographic profile, the severity of the symptoms, duration of the morning stiffness, DAS28, and DI were assessed and calculated using SPSS software version 20.0, p=0.05 was considered statistically significant. Results: Kruskal-Walli’s test revealed that Single Vata predominant DP patients were found to have severe Sandhi-shula (Joint pain) (p&amp;lt;0.0001), Shunatanga (Numbness of the joint) (p-value at 0.0069), Nidra-Viparyaya (Irregular sleep patterns) (p-value at 0.0012) than VP and VK DP individuals. Sandhi-Shotha (Joint swelling) (p-value at 0.0299), Angamarda (generalized body pains) (p-value at 0.0130), Alasya (laziness) (p&amp;lt;0.0001), Gaurava (Heaviness) (p&amp;lt;0.0001), and Apaka (delayed digestion) (p-value at 0.0254) were found severe in VK DP, whereas Trishna (Thirsty) (p&amp;lt;0.0001), Nidraviparyaya (p-value at 0.0012) were more severe in VP DP individuals. One-way ANOVA revealed that the duration of morning stiffness (2.03&amp;#177;0.2 hours, p-value at 0.446), DAS28 (6.85&amp;#177;0.175, p-value at 0.0035), and DI (1.87&amp;#177;0.54, p-value at 0.0003) were found significantly high in single Vataja than VP and VK Deha-Prakriti. Conclusion: The disease severity in terms of duration of morning stiffness, DAS28, and DI were found more severe in Single Vataja DP. The severity of the signs and symptoms also varied according to DP.', '{"arp_id": "ARP_AYU017164", "portal_id": 17164, "medical_system": "AYURVEDA", "journal": "International Journal of Ayurvedic Medicine", "volume": "14", "issue": "3", "pages": "683 - 695", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Amavata"], "original_url": "https://ijam.co.in/index.php/ijam/article/view/3896", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=17164", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU017164.pdf", "pdf_sha256": "4d61de3843fd7094e9d191dd5a98ecf181f6609a631bc508384060661388cf3b", "relevance_score": 40.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, '10.4103/ayu.ayu_239_22', 'DEVELOPMENT OF A STANDARDIZED ASSESSMENT SCALE FOR ASSESSING PRAKRITI (PSYCHOSOMATIC CONSTITUTION).', '1. Singh Renu, 1. Sharma Lalita, 2. Ota Sarada, 3. Gupta Bharti, 4. Singhal Richa, 5. Rana Rakesh, 6. Thrigulla Saketh Ram, 1. Lavaniya Vinod Kumar, 2. Makhija Deepa, 7. Sharma Sakshi, 8. Godatwar Pawan Kumar, 9. Bhojani Meera K, 10. Nair Santhosh S. R, 11. Mali Vaishali, 12. Baghel Arjun Singh, 13. Mishra Shalinee Kumari, 14. Sharma Bhuvnesh, 15. Monika, 16. Das Banamali, 17. Meher Sudhanshu Kumar, 18. Gundeti Manohar S, 18. Marlewar Sneha, 19. Prasad Avvaru Jaivenkata Sai, 19. Dhoke, Sujata, 20. Ravte, Rohit Kumar, 21. Sahu Dipsundar, 22. Harti Shivakumar S, 23. Vyas Mahesh, 24. Srikanth Narayanam, 25. Kumar Adarsh, 26. Dhiman Kartar Singh.', 2022,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Background: Personalized approach in prescribing health advocacies and treatment of diseases based on Prakriti vis-a-vis human constitution is unique to Ayurveda. Standardization in the assessment of Prakriti is the need of the hour. The methodology for designing the Prakriti assessment scale (PAS) from Ayurveda classics has been published. The present manuscript describes the development of a standardized PAS encompassing its validation and reliability testing.Aim: The aim of this study was to develop and validate an assessment scale to assess Ayurvedic Prakriti in accordance with the standardized methodology of questionnaire development.Material and methods: The study was conducted on a designed PAS for its validation in terms of face, content, construct, and criterion validity. The reliability testing of the validated PAS has been evaluated through intra-rater and inter-rater reliability testing estimated using the Kappa statistic.Results: The standardized PAS consisting of 91 predictors grouped into 30 domains in four traits (physical, physiological, psychological, and behavioral) has been developed. The standard operative procedures (SoP) for the Prakriti assessment have been documented in the form of a manual (copyright L-76725/2018). The user-friendly AYUR Prakriti web portal to administer the scale has also been developed (http://ccras.res.in/ccras_pas/).Conclusion: In an era of personalized medicine, standardization of the assessment of Prakriti through the PAS may facilitate a paradigm shift in the practice of Ayurveda.', '{"arp_id": "ARP_AYU025008", "portal_id": 25008, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "43", "issue": "4", "pages": "109 - 129", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ayur Prakriti Web Portal"], "original_url": "https://journals.lww.com/aayu/fulltext/2022/43040/development_of_a_standardized_assessment_scale_for.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=25008", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU025008.pdf", "pdf_sha256": "6ba543429a6c03e8ab12ce3b20ed21d603b61fb342b91c8867bd844fef237922", "relevance_score": 40.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22556892', NULL, 'GASTROINTESTINAL EFFECTS OF CROTON TIGLIUM IN EXPERIMENTAL ANIMALS', 'Pillai NR.', 1999,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Croton tiglium used as a cathartic in Ayurvedic system of indigenous medicine, wasinvestigated for its effects in experimental animals. 50% EtOH extract of the dried nuts of theplant was used of the study. The extract exhibited a dose dependent cathartic effect in albinorats, the extract also showed an increase to gut movement with an increased contractilemovement on rabbit jejunum, partially blocked by atropine these preliminary findings suggest tatthe ethanol extract of the croton dried nuts elicit a purgative effect by increasing the gut motility,partially via muscarnic receptor activation.', '{"arp_id": "ARP_AYU007925", "portal_id": 7925, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "18", "issue": "3-4", "pages": "205 - 209", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Croton Tiglium"], "original_url": "https://journals.lww.com/asol/abstract/1999/18030/gastro_intestinal_effects_of_croton_tiglium_in.6.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7925", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007925.pdf", "pdf_sha256": "14bc26d19403eaba44303578644ecf2469b24f52562815c5c5b3ea1b2d93238c", "relevance_score": 40.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '2906506', NULL, 'BRAIN-GUT PEPTIDES IN SAUNA-INDUCED HYPERTHERMIA.', '--', 1988,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The release of brain-gut peptides during sauna bathing was studied in seven women. All women underwent a 20 min sauna bath. Their sublingual temperature rose from 36.9 +/- 0.1 degrees C to 38.6 +/- 0.2 degrees C (mean +/- SEM). A significant increase in circulating plasma vasoactive intestinal polypeptide (VIP) was observed during heat exposure, whereas plasma pancreatic polypeptide (PP), motilin and blood glucose rose and stayed significantly elevated first during the ensuing 60 min (P less than 0.05 in all cases). A similar increase in plasma insulin failed to reach statistical significance, whereas the plasma levels of somatostatin and cholecystokinin (CCK) remained unchanged. It is suggested that the plasma VIP levels are related to compensatory mechanisms during heat exposure with vasodilatation and heat loss.', '{"arp_id": "ARP_Y&N000755", "portal_id": 44186, "medical_system": "YOGA & NATUROPATHY", "journal": "doi:", "volume": "132", "issue": "4", "pages": "519 - 523", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "GENERAL/UNSPECIFIED", "disease": "NO DISEASE(ICPC-A97|ICD-Z00, Z02)", "keywords": [], "original_url": "https://onlinelibrary.wiley.com/doi/10.1111/j.1748-1716.1988.tb08359.x", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=44186", "pdf_status": "downloaded", "pdf_filename": "ARP_Y&N000755.pdf", "pdf_sha256": "5ef86a98665c83c20c189f770870b2b459e08b909ba9006e521d7bc60f2ed7c8", "relevance_score": 40.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '9053413', NULL, 'COMPARATIVE DOUBLE MASKED RANDOMISED PLACEBO CONTROLLED CLINICAL TRIAL OF A HERBAL EYE DROP PREPARATION IN TRACHOMA AND CONJUNCTIVITIS.', 'Das GK, Pandey RM, Biswas NR.', 1995,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: A double blind controlled clinical trial has been done with a herbal eye drop preparation in case of trachoma stage III and chronic conjunctivitis of the eyes. In both trachoma and chronic conjunctivitis, the herbal eye drop formulation proved its superiority over placebo. Side-effects (burning sensations) were observed with normal saline which was used as placebo. But no side-effects were observed in the patients of trachoma and conjunctivitis who got the active drug. Both objective and subjective improvements were observed with the herbal eye drop preparation.', '{"arp_id": "ARP_AYU002389", "portal_id": 2389, "medical_system": "AYURVEDA", "journal": "Journal of the Indian Medical Association", "volume": "93", "issue": "10", "pages": "383 - 384", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "EYE", "disease": "CONJUNCTIVITIS INFECTIOUS(ICPC-F70|ICD-A74.0, B30, H10.0, H10.2, H10.3, H10.4, H10.5, H10.8, H10.9, H13)", "keywords": ["Conjunctivitis"], "original_url": "https://pubmed.ncbi.nlm.nih.gov/9053413", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2389", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002389.pdf", "pdf_sha256": "cca3e444a84a4d76c8015840f8b9f5620907e08f6e2b971282e1698267c779d5", "relevance_score": 40.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '8810206', NULL, 'COMPARATIVE DOUBLE BLIND MULTICENTRIC RANDOMISED PLACEBO CONTROLLED CLINICAL TRIAL OF A HERBAL PREPARATION OF EYE DROPS IN SOME OCULAR AILMENTS.', 'Biswas NR, Beri S, Das GK, Mongre PK.', 1996,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: A double masked placebo controlled multicentric randomised clinical trial was conducted in 157 patients suffering from different eye ailments namely, cataract, dry eye syndrome, ocular asthenia, refractive errors and allergic conjunctivitis with a herbal eye drop preparation and placebo. In both dry eye syndrome and ocular asthenia the herbal eye drop preparation was found better than placebo. In a few cases of cataract, the vision seems to be improved. In early myopia it seems to correct the refractive errors while in high myopic conditions it controlled the progressive deteriorations. Subjective improvements were also noted with hypermetropia, presbyopia and astigmatism. Its healing capacity in allergic conjunctivitis was certainly better than placebo. It had no short term or long term side-effects. It is considered to be a useful drug in all conditions studied.', '{"arp_id": "ARP_AYU002405", "portal_id": 2405, "medical_system": "AYURVEDA", "journal": "Journal of the Indian Medical Association", "volume": "94", "issue": "3", "pages": "101 - 102", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "EYE", "disease": "REFRACTIVE ERROR(ICPC-F91|ICD-H52)", "keywords": ["Eye Drops"], "original_url": "https://pubmed.ncbi.nlm.nih.gov/8810206", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2405", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002405.pdf", "pdf_sha256": "1bf0a698b950934ac1fc3f92513ca1c217f407baccc4d32616c02594cd23c1bf", "relevance_score": 40.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22557698', NULL, 'CLINICAL TRIAL OF CERTAIN AYURVEDIC MEDICINES INDICATED IN VITILIGO', '1. Donata Sr, Kesavan M, 1.Austin Sr, 1. Mohan KS, 1. Rajagopalan K, 2. Ramadasan Kuttan.', 1990,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: An Ayurvedic preparation consisting of dried ginger, black pepper, pippali andleadwort root fermented in cow’s urine was given internally and a paste made of several meicalherbs including Psoralea corylifolia for external application was tried in patients with vitiligo. 4out of 10 patients had relief within six months of treatment. Three patients had relief withadverse reaction on the skin and other did not respond. The preparations did not have anyadverse effect in the body as seen from haematological parameters and biochemical tests.', '{"arp_id": "ARP_AYU018773", "portal_id": 18773, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "9", "issue": "4", "pages": "202 - 206", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "SKIN DISEASE OTHER(ICPC-S99|ICD-L10, L11, L12, L13, L14, L26, L28, L30.2, L30.5, L41, L43, L44, L45, L51, L52, L53.0, L53.1, L53.2, L53.3, L53.8, L54, L60.2, L60.3, L60.8, L68, L71, L72.0, L72.2, L72.8, L72.9, L73.0, L73.1, L73.8, L73.9, L80, L81.1, L81.4, L81.5, L81.6, L81.7, L81.8, L81.9, L82, L8)", "keywords": ["Ayurvedic Preparation"], "original_url": "https://journals.lww.com/asol/abstract/1990/09040/clinical_trial_of_certain_ayurvedic_medicines.4.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18773", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018773.pdf", "pdf_sha256": "69f10e8bc247d2fe3a06a8eb2a17d025546733cf45c48abedd9e585eeca6e219", "relevance_score": 40.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22556542', NULL, 'CLINICAL TRIAL OF CANDANASAVA, IN THE TREATMENT OF URINARY TRACT INFECTION', 'Goel KN, Singh RH.', 1991,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Candanasava gives significant relief to urinary tract infection. Like otherAyurvedic drugs Candanasava might be acting not merely as an urinary antiseptic but also as ahost-modifying factor, thus rendering the host-urinary tract resistant to infection and making thebacterial infection pathogenetically less virulent.', '{"arp_id": "ARP_AYU018785", "portal_id": 18785, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "10", "issue": "4", "pages": "248 - 252", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "URINARY SYSTEM", "disease": "CYSTITIS/URINARY INFECTION OTHER(ICPC-U71|ICD-N30, N39.0)", "keywords": ["Candanasava"], "original_url": "https://journals.lww.com/asol/abstract/1991/10040/clinical_trial_of_candanasava,_in_the_treatment_of.7.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18785", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018785.pdf", "pdf_sha256": "8e3e205ae4c48fed681ff38e372d13969644107cc3d4986c57f3c7a4a4b42da6", "relevance_score": 40.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22556981', NULL, 'TREATMENT OF TROPICAL EOSINOPHILIA WITH AN AYURVEDIC COMPOUND-A CLINICAL TRIAL', 'Ramakrishna Shetty B, Seshai C, Sitaraman R, Rajagopalan V, Janaki K, Venkataraghanan S.', 1983,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The effect of an ayurvedic preparation consisting of swasakutara, Curcuma longa(Haridra) and Withania Somnifera (Asvagandha) is assessed in 12 patients of tropical eosinophilia. The modern control drug Hetrazan is used in another batch of 11 patients for comparison. The ayurvedic compound causes completed relief of most of the clinical signs and symptoms associated with the disease and reduces E.S.R. significantly. However the drug has no effect on the level of circulating eosinophils', '{"arp_id": "ARP_AYU018881", "portal_id": 18881, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "2", "issue": "4", "pages": "194 - 198", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "RESPIRATORY", "disease": "RESPIRATORY DISEASE OTHER(ICPC-R99|ICD-J33, J34.1, J34.2, J34.3, J34.8, J38, J39, J47, J60, J61, J62, J63, J64, J65, J66, J67, J68, J69, J70, J80, J81, J82, J84, J92, J93, J96, J98, J99, Z90.2, Z94.2, Z94.3)", "keywords": ["Ayurvedic Compound"], "original_url": "https://journals.lww.com/asol/abstract/1983/02040/treatment_of_tropical_eosinophilia_with_an.5.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18881", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018881.pdf", "pdf_sha256": "37c497ff2e27a8767f6a7b3b0fa4232098802d52c22c9fc91c9fd296091435c3", "relevance_score": 40.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '22557371', NULL, 'CLINICAL TRIAL OF ADHATODA VASICA SYRUP(VASA) IN THE PATIENTS OF NON-ULCER DYSPEPSIA(AMLAPITTA)', 'Chaturvedi GN, Rai NP, Ram Dhani, Tiwari SK.', 1983,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The efficacy of Vasa (Adhatoda vasica) in the form of syrup against Non-ulcer Dyspepsia (Amlapitta) through a clinical trial is attempted here This trial showed hopeful results. The drug has reduced the total and free HCL in the patients of hyperacidity and hyperchlorhydria.', '{"arp_id": "ARP_AYU018882", "portal_id": 18882, "medical_system": "AYURVEDA", "journal": "Ancient Science of Life", "volume": "3", "issue": "1", "pages": "19 - 23", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "FLATULENCE/GAS/BELCHING (ICPC-D08| ICD-R14)", "keywords": ["Adhatoda Vasica Syrup"], "original_url": "https://journals.lww.com/asol/abstract/1983/03010/clinical_trial_of_adhatoda_vasica_syrup__vasa__in.4.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=18882", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU018882.pdf", "pdf_sha256": "66f9b6303178f19069fd7f399607c1b2d8a0a3220926c275d00c4ce6ced43c5b", "relevance_score": 40.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '10024610', '10.1093/jn/129.2.336', 'ALLYL-CONTAINING SULFIDES IN GARLIC INCREASE UNCOUPLING PROTEIN CONTENT IN BROWN ADIPOSE TISSUE, AND NORADRENALINE AND ADRENALINE SECRETION IN RATS1', '1. Yuriko Oi, Teruo Kawada, Chiaki Shishido, Keiko Wada, Yutaka Kominato, Syoji Nishimura, Toyohiko Ariga, Kazuo Iwai.', 1999,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The effects of garlic supplementation on triglyceride metabolism were investigated by measurements of the degree of thermogenesis in interscapular brown adipose tissue (IBAT), and noradrenaline and adrenaline secretion in rats fed two types of dietary fat. In Experiment 1, rats were given isoenergetic high-fat diets containing either shortening or lard with or without garlic powder supplementation (8 g/kg of diet). After 28 d feeding, body weight, plasma triglyceride levels and the weights of perirenal adipose tissue and epididymal fat pad were significantly lower in rats fed diets supplemented with garlic powder than in those fed diets without garlic powder. The content of mitochondrial protein and uncoupling protein (UCP) in IBAT, and urinary noradrenaline and adrenaline excretion were significantly greater in rats fed a lard diet with garlic powder than in those fed the same diet without garlic. Other than adrenaline secretion, differences due to garlic were significant in rats fed shortening, also. In Experiment 2, the effects of various allyl-containing sulfides present in garlic on noradrenaline and adrenaline secretion were evaluated. Administration of diallyldisulfide, diallyltrisulfide and alliin, organosulfur compounds present in garlic, significantly increased plasma noradrenaline and adrenaline concentrations, whereas the administration of disulfides without allyl residues, diallylmonosulfide and S-allyl-L-cysteine did not increase adrenaline secretion. These results suggest that in rats, allyl-containing sulfides in garlic enhance thermogenesis by increasing UCP content in IBAT, and noradrenaline and adrenaline secretion', '{"arp_id": "ARP_AYU007326", "portal_id": 7326, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "129", "issue": "2", "pages": "336 - 342", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Adrenaline"], "original_url": "http://jn.nutrition.org/content/129/2/336.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7326", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007326.pdf", "pdf_sha256": "d2000be9f8f9e68ef3f4c36a8809ff9f7d7dcbfe30ad11015fdeca75e75158c4", "relevance_score": 39.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '10082770', '10.1093/jn/129.3.657', 'HEATING GARLIC INHIBITS ITS ABILITY TO SUPPRESS 7,12- DIMETHYLBENZ(A)ANTHRACENE-INDUCED DNA ADDUCT FORMATION IN RAT MAMMARY TISSUE1 - 4', 'Kun Song, John A. Milner.', 1999,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The present studies compared the impact of heating, either by microwave or convection oven, on the ability of garlic to reduce the in vivo bioactivation of 7,12-dimethylbenz(a)anthracene (DMBA) in 55-d-old female Sprague-Dawley rats. In study 1, rats were fed a semipurified casein-based diet and treated by gastric gavage thrice weekly for 2-wk with crushed garlic (0.7 g in 2 mL corn oil) or the carrier prior to DMBA treatment (50 mg/kg body weight). Providing crushed garlic reduced by 64% (P, 0.05) the quantity DMBA-induced DNA adducts present in mammary epithelial cells compared to controls. In study 2, microwave treatment for 60 s, but not 30 s, decreased (P,0.05) the protection provided by garlic against DMBA-induced adduct formation. In study 3, following crushed garlic to stand for 10 min prior to microwave heating for 60 s significantly (P ,0.05) restored its anticarcinogenic activity. Microwave heating of garlic for 30 s resulted in a 90% loss of alliinase activity. Heating in a convection oven (study 4) also completely blocked the ability of uncrushed garlic to retard DMBA bioactivation. Study 5 revealed that providing either 0.105 mmol diallyl disulfide or S-allyl cysteine by gastric gavage thrice weekly for 2 wk was effective in retarding DMBA bioactivation but isomolar alliin was not. These studies provide evidence that alliinase may be important for the formation of allyl sulfur compounds that contribute to a depression in DMBA metabolism and bioactivation.', '{"arp_id": "ARP_AYU007375", "portal_id": 7375, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "129", "issue": "3", "pages": "657 - 661", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["12-Dimethylbenz(A)Anthracene"], "original_url": "http://jn.nutrition.org/content/129/3/657.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7375", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007375.pdf", "pdf_sha256": "581abf7127610ea183ee06321a03bc5bbc19c0e269ee0edbbd79eb9392e52e31", "relevance_score": 39.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '7057262', '10.1093/jn/112.2.241', 'EFFECTS OF GARLIC ON LIPID METABOLISM IN RATS FED CHOLESTEROL OR LARD1', 'Chi, Koh ET, Stewart TJ.', 1981,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Effects of garlic on lipid metabolism were studied in three experiments using different aged male rats fed a diet containing 1% cholesterol or 15% lard. Lyophilized garlic was supplemented at 2% and 4% of the diet. Plasma glucose was not changed by dietary treatments. Rats fed cholesterol and lard diets increased plasma cholesterol and triglycerides compared to controls. Garlic decreased plasma cholesterol in cholesterol- and lard-fed rats, but decreased plasma triglycerides only in the lard-fed group. Garlic supplementation decreased very low density lipoprotein cholesterol and increased high density lipoprotein cholesterol. The liver weight, total liver lipid and cholesterol were increased in rats fed the cholesterol diet but a supplementation of garlic decreased those parameters by about 30%. Dietary cholesterol and lard decreased hepatic glucose-6-phosphate dehydrogenase and malic enzyme activities: the garlic supplementation further decreased these enzyme activities. Garlic feeding increased the excretion of the neutral steroids in both 16-week and 10-week-old rats and bile acids in only 16-week-old pair-fed rats. Garlic at the 2% level was similarly effective on lipid metabolism as at 4%. These results demonstrate that garlic increases the excretion of neutral and acidic steroids and exerts hypocholesterolemic effects in cholesterol-fed rats.', '{"arp_id": "ARP_AYU007379", "portal_id": 7379, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "112", "issue": "2", "pages": "241 - 248", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Bile Acids"], "original_url": "http://jn.nutrition.org/content/112/2/241.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7379", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007379.pdf", "pdf_sha256": "d879e01f861fb2c09716f112938d8efd04caaafd36c4c5f4776588c37a541df1", "relevance_score": 39.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '5476433', '10.1093/jn/100.11.1307', 'EFFECT OF CURCUMIN ON SERUM AND LIVER CHOLESTEROL LEVELS IN THE RAT', 'Subba Rao D, Chana Sekhara N, Satyanarayana Mn, Srinivasan M.', 1970,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: In rats fed cholesterol and curcumin, the coloring principle in turmeric, levels of serum and liver cholesterol fell to one-half or one-third of those in rats fed cholesterol and no curcumin. Deposition of cholesterol was found most in liver sections from rats fed cholesterol and least in specimens from animals con currently fed curcumin. Curcumin increased fecal excretion of bile acids and cholesterol, both in normal and hypercholesteremic rats. This biliary drainage is a plausible explanation for the reduction of tissue cholesterol on curcumin feeding. Alpha- and &amp;#195;Ÿ-lipoproteins in blood plasma showed meaningful response to addition of curcumin. The imbalance in these two lipoproteins brought about by cholesterol feeding was nearly corrected by simultaneous feeding of curcumin. The above beneficial effects of curcumin were about the same with 0.1% or 0.5% of curcumin in the diet, suggesting that the effective level of curcumin may be even lower than 0.1%. Curcumin maintained body and liver weights, correcting the ill effects in this respect caused by ingested cholesterol. The effect of curcumin in keeping down cholesterol in conditions which otherwise induced hypercholesteremia was not through alterations in cecalmicroflora which are known to dismute and utilize bile acids in the gut.', '{"arp_id": "ARP_AYU007476", "portal_id": 7476, "medical_system": "AYURVEDA", "journal": "The Journal of Nutrition", "volume": "100", "issue": "11", "pages": "1307 - 1315", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Cholesterol Levels"], "original_url": "http://jn.nutrition.org/content/100/11/1307.full.pdf", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7476", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007476.pdf", "pdf_sha256": "4249c717841ab3f76a505b4a130d21135a475cee01f619f36cda72bd7c4d36a1", "relevance_score": 39.0, "topic_domain": "ayurveda_nutrition"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL EVALUATION OF VANGA BHASMA PREPARED BY TWO DIFFERENT METHODS IN THE MANAGEMENT OF MADHUMEHA (DIABETES MELLITUS)', '1. Jalpa H. Jani, 2. Patgiri BJ, 3. Ravishankar B, 4. Prajapati PK.', 2009,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Madhumeha is a widely evidential disease since ancient age till today and evidence is increasing day by day with lips and bounce with their complications and complexes. Diabetes mellitus is similar to Madhumeha which is sub-type of Vataja prameha. A clinical trail was carried out on 50 patients having classical signs and symptoms of Madhumeha. The patients were selected irrespective of their age, sex, religion etc., and were divided randomly into two groups i.e., group A and B treated with Vanga bhasma prepared by Arthagajaputa and Vastra puta method respectively. The obtained results were analyzed on the basis of improvement in classical features. Investigation parameters (haemotological and biochemical) were also considered as supporting criteria for assessment. Hypoglyceamia is one of the commonest adverse effects of the available allopathic antihyper glycaemic drugs. It is the need of time to assess the hypoglycemic as well as anti-hyperglycaemic activity of the Ayurvedic pramehaghna (anti diabetic) drug too and this study is a step towards the goal. Vanga bhasma prepared by puta method shows significant improvement on subjective as well as on objective parameters.', '{"arp_id": "ARP_AYU000004", "portal_id": 4, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "3", "issue": "1", "pages": "34 - 40", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "DIABETES NON-INSULIN DEPENDENT(ICPC-T90|ICD-E11, E12, E13, E14)", "keywords": ["Anti-Hyperglycemic Effect"], "original_url": "https://journals.lww.com/joay/citation/2009/03010/joa_iii_january_march_2009.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=4", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000004.pdf", "pdf_sha256": "e3ab1fce1008b3b3d68344f63bdb4efd68492f72e3a4b01d3f286ad1b7191075", "relevance_score": 39.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'AN EXPERIMENTAL STUDY ON THE LIQUID EXTRACT OF DHAVA (ANOGEISSUS LATIFOLIA WALL) WITH SPECIAL REFERENCE TO ITS ROLE IN THE MANAGEMENT OF MADHUMEHA (DIABETES MELLITUS)', '1. Neelima Sharma, 2. Dwivedi KN.', 2008,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: The study was conducted in &#39;36&#39; wistar albino rats with an objective to access the hypoglycaernic effects of liquid extract of plant Dhava in three groups of wistar albino rats. Out of these three in two groups hyperglycaernia was produced and one group was normoglycaemic rats. It was observed that statistically significant improvement was noticed in the rats of two hyperglycaemic groups, while in normoglycaemic one statistically insignificant result was obtained. From the results obtained it was concluded that the liquid extract of Plant Dhava showed satisfactory improvement in hyperglycaemic rats.', '{"arp_id": "ARP_AYU000098", "portal_id": 98, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "2", "issue": "1", "pages": "24 - 29", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Anogeissus Latifolia Wall"], "original_url": "https://journals.lww.com/joay/citation/2008/02010/joa_ii_january_march_2008.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=98", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000098.pdf", "pdf_sha256": "c7ae8c771bd08c0a3ae673fa66dc73920fd5638c81ab2c43dc8df637f710f174", "relevance_score": 39.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'A REVIEW OF PATHOPHYSIOLOGY (PATHWAYS) AND TREATMENT OF DIABETIC RETINOPATHY AS A COMPLICATION OF DIABETES (PRAMEHA UPADRAVA) WITH SPECIAL REFERENCE TO THE USE OF VASANT KUSUMAKAR RAS.', '1. Sanjay Tamoli, 2. Kohli KR.', 2017,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background : - Keywords : Diabetic Retinopathy , Prameha , Vasant Kusumakar Ras (Vkr) URL (for Abstract/ Full paper) : https://journals.lww.com/joay/citation/2013/07010/joa_vii_january_march_2013.1.aspx DOI : No Access : -', '{"arp_id": "ARP_AYU000372", "portal_id": 372, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda", "volume": "11", "issue": "1", "pages": "43 - 52 48", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Diabetic Retinopathy"], "original_url": "https://journals.lww.com/joay/citation/2013/07010/joa_vii_january_march_2013.1.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=372", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU000372.pdf", "pdf_sha256": "24e5aecd30d659a54d03949c84e3a76955571dbc043763d4f34f3055f0ed6a02", "relevance_score": 39.0, "topic_domain": "diabetes_obesity_metabolic"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'DOES FUNCTIONS OF PITTA DOSHA SUBTYPE_x005F_x005F_x005F_x005F_x005F_x005F_x005F_x000D_
VARY AS PER PRAKRITI  A CROSS SECTIONAL STUDY_x005F_x005F_x005F_x005F_x005F_x005F_x005F_x000D_', '1. Sonam Agrawal 2. Sangeeta Gehlot', 2018,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Introduction: The Tridosha theory, which is the cornerstone of Ayurvedic physiology, governs all the functions of human body and mind. Tridosha are responsible in determining one’s Prakriti and their functional status may vary in different Prakriti Therefore, this study was planned to find out the variation in functional status of different types of Pitta, using certain objective parameters. Material and Methods: 201 young healthy volunteers of both genders of age group 20-35 years, belonging to different Prakriti were selected during the period of January 2016 to January 2017, after obtaining their written consent from the student community. Serum level of triglycerides, cholesterol, total protein and glucose level was estimated for Pachaka Pitta, hemoglobin concentration for Ranjaka Pitta, visual acuity for Alochaka Pitta, memory and reaction time for Sadhaka Pitta and RGB value for Bhrajaka Pitta were measured. Result: The function of Ranjaka, Bhrajaka and Sadhaka Pitta was found better in Pitta Prakriti individuals followed by Kapha Prakriti and least in Vata Prakriti individuals. As mean values of hemoglobin, RGB values and STM and LTM, were highest in Pitta Prakriti and lowest in Vata Prakriti individuals. Incidence of emmetropia and myopia do not vary significantly. For the functional status of Pachaka Pitta no inference can be drawn which may be due to various confounding factors affecting biochemical parameters, small sample size and homogenous population. Conclusion: Functional status of Pitta Dosha do vary as per Prakriti. This study should be conducted with large sample size to get a reference range of all these parameters in different Prakriti, which can also be used as a tool to assess the functional status of Pitta Dosha and Prakriti too.', '{"arp_id": "ARP_AYU019436", "portal_id": 19436, "medical_system": "AYURVEDA", "journal": "The Journal of Research and Education in Indian Medicine", "volume": "5", "issue": "2", "pages": "51 - 57", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "-", "disease": "-", "keywords": ["Memory"], "original_url": "https://www.jreim-ayushjournal.com/fulltext/82-1506163089.pdf?1629280741", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19436", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019436.pdf", "pdf_sha256": "3dfb72df7e47a6d8406b5f9a7589721a4cb27c82c7e5a01ad7547a881bcc617a", "relevance_score": 39.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '20015960', '10.1093/ecam/nep206', 'TRADITIONAL MEDICINE TO MODERN PHARMACOGENOMICS: AYURVEDA PRAKRITI TYPE AND CYP2C19 GENE POLYMORPHISM ASSOCIATED WITH THE METABOLIC VARIABILITY', '1. Yogita Ghodke, 2. Kalpana Joshi,1. Bhushan Patwardhan.', 2011,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Traditional Indian medicine—Ayurveda—classifies the human population into three major constituents or Prakriti known as Vata, Pitta and Kapha types. Earlier, we have demonstrated a proof of concept to support genetic basis for Prakriti. The descriptions in Ayurveda indicate that individuals with Pitta Prakriti are fast metabolizers while those of Kapha Prakriti are slow metabolizers. We hypothesized that different Prakriti may have different drug metabolism rates associated with drug metabolizing enzyme (DME) polymorphism. We did CYP2C19 (Phase I DME) genotyping in 132 unrelated healthy subjects of either sex by polymerase chain reaction-restriction fragment length polymorphism (PCR-RFLP) technique. We observed significant association between CYP2C19 genotype and major classes of Prakriti types. The extensive metabolizer (EM) genotype (*1/*1, *1/*2, *1/*3) was found to be predominant in Pitta Prakriti (91%). Genotype (*1/*3) specific for EM group was present only in Pitta Prakriti. Poor metabolizer (PM) genotype (*2/*2, *2/*3, *3/*3) was highest (31%) in Kapha Prakriti when compared with Vata (12%) and Pitta Prakriti (9%). Genotype (*2/*3) which is typical for PM group was significant in Kapha Prakriti (odds ratio = 3.5, P =?.008). We observed interesting correlations between CYP2C19 genotypes and Prakriti with fast and slow metabolism being one of the major distinguishing and differentiating characteristics. These observations are likely to have significant impact on phenotype-genotype correlation, drug discovery, pharmacogenomics and personalized medicine.', '{"arp_id": "ARP_AYU022108", "portal_id": 22108, "medical_system": "AYURVEDA", "journal": "Evidence Based Complementary and Alternative Medicine", "volume": "2011", "issue": "-", "pages": "- - -", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ayurveda Prakriti"], "original_url": "http://www.hindawi.com/journals/ecam/2011/249528/", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=22108", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU022108.pdf", "pdf_sha256": "59cd90a1fd082bc5f87deba2ddb66ab298fe393761b961caca8df7b8842a6953", "relevance_score": 39.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '24812475', '10.4103/0975-9476.128857', 'IMMUNOPHENOTYPING OF NORMAL INDIVIDUALS CLASSIFIED ON THE BASIS OF HUMAN DOSHA PRAKRITI', 'Harish Rotti, Kanive Parashiva Guruprasad, 1.Jayakrishna Nayak, Shama Prasada Kabekkodu, Harpreet Kukreja, Sandeep Mallya, Jyothi Nayak, 2.Ramachana C. Bhradwaj, 2.G. G. Gangadharan, 1.B. V. Prasanna, Ritu Raval, 3.Asha Kamath, Puthiya Mundyat Gopinath, 4.Paturu Kondaiah, Kapaettu Satyamoorthy.', 2014,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Background: Human variations related to immune response and disease susceptibility is well-documented in Ayurveda. Prakriti (body constitution) is the basic constitution of an individual established at the time of birth and distinguishes variations, into three broad phenotype categories such as vata, pitta and kapha. Variation in immune response is often attributed to and measured from the difference in cluster differentiation (CD) markers expressed in lymphocytes. Currently, there are no reports available on the expression of CD markers related to prakriti. Objective: This is a pilot study performed to evaluate a panel of lymphocyte subset CD markers in dominant prakriti individuals. Materials and Methods: Immunophenotyping was carried out using whole blood from a total of healthy 222 subjects, who are grouped into kapha (n = 95), pitta (n = 57) and vata (n = 70) prakritis. CD markers such as CD3, CD4, CD8, CD14, CD25, CD56, CD69, CD71 and HLA-DR were analyzed using flow cytometry method. Differences between groups were analyzed using one-way ANOVA or Kruskal-Wallis analysis of variance (ANOVA) and multiple comparisons between groups were performed by Bonferroni or Mann-Whitney U test with corrections for type I error respectively. Significance was evaluated by ANOVA and Pearson’s correlation. Results: We observed a significant difference (P &amp;lt; 0.05) in the expression of CD markers such as CD14 (monocytes), CD25 (activated B cells) and CD56 (Natural killer cells) between different prakriti groups. CD25 and CD56 expression was signifi cantly higher in kapha prakriti samples than other prakriti groups. Similarly, slightly higher levels of CD14 were observed in pitta prakriti samples. Conclusion: Significant difference in the expression of CD14, CD25 and CD56 markers between three different prakriti is demonstrated. The increased level of CD25 and CD56 in kapha prakriti may indicate ability to elicit better immune response, which is in conformity with textual references in Ayurveda.', '{"arp_id": "ARP_AYU025069", "portal_id": 25069, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Integrative Medicine", "volume": "5", "issue": "1", "pages": "43 - 49", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "-", "disease": "-", "keywords": ["Cluster Differentiation 14"], "original_url": "https://doi.org/10.4103/0975-9476.128857", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=25069", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU025069.pdf", "pdf_sha256": "c8cf9b04b57e172b83bc052bd9d9b09fe6a7f2125465ad64c449a4b84f835ff6", "relevance_score": 39.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '25336848', '10.4103/0975-9476.140478', 'DETERMINANTS OF PRAKRITI, THE HUMAN CONSTITUTION TYPES OF INDIAN TRADITIONAL MEDICINE AND ITS CORRELATION WITH CONTEMPORARY SCIENCE', '1. Harish Rotti, 1.Ritu Raval, 2.Suchitra Anchan, 1.Ravishankara Bellampalli, 3. Sameer Bhale, 4. Ramachana Bharadwaj, 2. Balakrishna K Bhat, 3. Amrish P Dedge, 3.Vikram Ram Dhumal, 4. Gangadharan GG, 4. Girijakumari TK, 1.Puthiya M Gopinath, 5.Periyasamy Govindaraj, 6. Swagata Halder, 3.Kalpana S Joshi, 1.Shama Prasada Kabekkodu, 2. Archana Kamath, 7. Paturu Kondaiah, 1. Harpreet. Kukreja, 2. Rajath Kumar KL, 8. Sreekumaran Nair, 4. Venugopalan Nair SN, 2. Jayakrishna Nayak, 2. Prasanna BV, 2. Rashmishree M, 2. Sharanprasad K, 5. Kumarasamy Thangaraj, 9. Bhushan Patwardhan, 1.Kapaettu Satyamoorthy, 1. Marthanda Varma Sankaran Valiathan', 2014,
    'systematic_review', 'Grade A — Systematic Review / Meta-Analysis', 0, 'Background: Background: Constitutional type of an individual or prakriti is the basic clinical denominator in Ayurveda, which defines physical, physiological, and psychological traits of an individual and is the template for individualized diet, lifestyle counseling, and treatment. The large number of phenotype description by prakriti determination is based on the knowledge and experience of the assessor, and hence subject to inherent variations and interpretations. Objective: In this study we have attempted to relate dominant prakriti attribute to body mass index (BMI) of individuals by assessing an acceptable tool to provide the quantitative measure to the currently qualitative ayurvedic prakriti determination. Materials and Methods: The study is cross sectional, multicentered, and prakriti assessment of a total of 3416 subjects was undertaken. Healthy male, nonsmoking, nonalcoholic volunteers between the age group of 20-30 were screened for their prakriti after obtaining written consent to participate in the study. The prakriti was determined on the phenotype description of ayurvedic texts and simultaneously by the use of a computer-aided prakriti assessment tool. Kappa statistical analysis was employed to validate the prakriti assessment and Chi-square, Cramer’s V test to determine the relatedness in the dominant prakriti to various attributes. Results: We found 80% concordance between ayurvedic physician and software in predicting the prakriti of an individual. The kappa value of 0.77 showed moderate agreement in prakriti assessment. We observed a significantcorrelations of dominant prakriti to place of birth and BMI with Chi-square, P &amp;lt; 0.01 (Cramer&#39;s V-value of 0.156 and 0.368, respectively). Conclusion: The present study attempts to integrate knowledge of traditional ayurvedic concepts with the contemporary science. We have demonstrated analysis of prakriti classification and its association with BMI and place of birth with the implications to one of the ways for human classification.', '{"arp_id": "ARP_AYU025089", "portal_id": 25089, "medical_system": "AYURVEDA", "journal": "Journal of Ayurveda and Integrative Medicine", "volume": "5", "issue": "3", "pages": "167 - 175", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE A", "body_system": "-", "disease": "-", "keywords": ["Ayusoft"], "original_url": "https://doi.org/10.4103/0975-9476.140478", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=25089", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU025089.pdf", "pdf_sha256": "2b5cf006b39101121a225dc325fe880cbaca296e8d516ec617db77a3420691a0", "relevance_score": 39.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    '1800188', '10.1159/000200705', 'A DOUBLE-BLIND TRIAL OF A CELANDIN, ALOEVERA AND PSYLLIUM LAXATIVE PREPARATION IN ADULT PATIENTS WITH CONSTIPATION', 'Odes HS, Madar Z.', 1991,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The aim of this study was to evaluate the effect of a novel laxative preparation, composed of celandin, aloevera and psyllium in patients with chronic constipation. Thirty-five men and women were randomized to receive capsules containing celandin-aloevera-psyllium, or placebo, in a double-blind trial lasting 28 days. Symptoms in the last 2 weeks of the treatment period were compared to those in the 14-day pre-trial basal period. In the celandin, aloevera and psyllium group, bowel movements became more frequent, the stools were softer and laxative dependence was reduced. In the placebo group, all these parameters were unchanged. Abdominal pain was not reduced in either group. The results of this study show that the preparation is an effective laxative in the treatment of constipation.', '{"arp_id": "ARP_AYU026479", "portal_id": 26479, "medical_system": "AYURVEDA", "journal": "Digestion", "volume": "49", "issue": "2", "pages": "65 - 71", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "DIGESTIVE", "disease": "FISTULA IN ANO (ICD-K-60.3)", "keywords": ["Aloe Vera"], "original_url": "https://karger.com/dig/article-abstract/49/2/65/101838/A-Double-Blind-Trial-of-a-Celandin-Aloevera-and?redirectedFrom=fulltext", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=26479", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU026479.pdf", "pdf_sha256": "9ee23c9823d4228bb30434a7b11a84eb36c665c622ea714a9a3c693849baf2db", "relevance_score": 39.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PROKINETIC EFFECT OF POLYHERBAL FORMULATION ON GASTROINTESTINAL TRACT', '1. Srinivasan D, 2. Ramaswamy S, 3. Sengottuvelu S.', 2009,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: PHF, a polyherbal formulation, consist of seven known herbs namely, Aegle marmelos, Elettaria cardamomum, Glycyrrhiza glabra, Citrus aurantifolia, Rosa damascene, Cissus quadrangularis and Saccharum officinarum. The PHF was evaluated for acute toxicity, gastrointestinal motility and gastric emptying rate in mice and rats. Based on acute toxicity study, the PHF was considered as safe and 3 dose (100, 200 and 400 mg/kg) levels were employed for further pharmacological studies. The gastrointestinal prokinetics effect of PHF in various dose levels (100, 200 and 400 mg/kg., p.o) was studied by charcoal meal gastrointestinal transit and laxative effect in mice. The gastric emptying rate of PHF in rat was studied by disappearance of phenol red from stomach. The results illustrate that PHF at 200 and 400 mg/kg significantly (p&amp;lt;0.001) enhanced the gastrointestinal transit. PHF at 400 mg/kg (p&amp;lt;0.01) significantly enhanced the purging index, which is the measure of laxative activity. PHF at 200 mg/kg (p&amp;lt;0.05) less significantly enhanced the purging index. In gastric emptying rate, PHF dose dependently increased the gastric emptying. From the above findings, PHF may be used as gastrointestinal prokinetics and to improve the intestinal motility.', '{"arp_id": "ARP_AYU006632", "portal_id": 6632, "medical_system": "AYURVEDA", "journal": "Pharmacognosy Magazine", "volume": "5", "issue": "17", "pages": "37 - 42", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Gastrointestinal Motility And Gastric Emptying"], "original_url": "https://phcog.com/article/view/2009/5/17/37-42", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=6632", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU006632.pdf", "pdf_sha256": "ee4c79df17105be1b8f455359e8734060c725aade35f11497f1c6e93650d4d1d", "relevance_score": 39.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFECT OF THE CRUDE EXTRACTS OF AMOORA ROHITUKA STEM BARK ON GASTROINTESTINAL TRANSIT IN MICE', 'Chowdhury R, Rashid RB.', 2003,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Objective: To study the laxative effects of organic extracts of Amoora rohituka stem bark and their actions on gastrointestinal transit in mice.Methods: The animals were fed with crude extract suspensions and examined for hourly laxation for 5h with the withdrawal of food and water. In Gl motility test, the test materials were given intraperitoneally followed by administration of BaSO4 milk after 15 min. The treated mice were sacrificed, the small intestine was removed and its length was measured from the pyloric sphincter to the ileocaecal junction.Results: The petroleum, ether, dichloromethane and methanol extracts of A. rohituka demonstrated good laxative potential at 400, 250 and 400 mg/kg respectively and the data obtained after 1h of drug administration were statistically significant. The petroleum ether and methanol extracts also showed significant gastrointestinal hypermotility following barium sulphate milk in mice. The data showed dose dependency and were well correlated with the findings of laxative screening.Conclusion: The crude extracts of A. rohituka have laxative principle(s) comparable to those of a stimulant laxative, sennoside B.', '{"arp_id": "ARP_AYU007146", "portal_id": 7146, "medical_system": "AYURVEDA", "journal": "Indian Journal of Pharmacology", "volume": "35", "issue": "5", "pages": "304 - 307", "category": "PRECLINICAL RESEARCH", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["A Rohituka"], "original_url": "https://journals.lww.com/iphr/abstract/2003/35050/effect_of_the_crude_extracts_of_amoora_rohituka.5.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=7146", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU007146.pdf", "pdf_sha256": "acb531738b0278c2d3cc7113bb4098509aa1e27d6effb9b9f575fb8a610a13da", "relevance_score": 39.0, "topic_domain": "digestion_gut_health"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFICACY AND SAFETY OF AN AYURVEDIC REGIMEN IN MEDOROGA', '1. Prasad SVLN, 1. Prahalad Rao V, 1. Punita V, 1. Murali Manohar Raju Y, 1. Sharmila UV, 2. Anand B.', 2009,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: A study with an Ayurveda regimen consisting of Navaka guggulu, Sthaulyahara kashayam, a diet pattern and walk exercise for a treatment period of 3 mandalams (120 days) in medoroga was conducted to probe the efficacy and safety aspects of the regimen. 71 patients of medoroga were recruited for the study, and 34 patients formed the sample conforming to certain inclusion and exclusion criteria. Assessment of efficacy at the end of the 120-day treatment period vis-&amp;#224;-vis baseline was done using a self-designed proforma considering the symptoms in accordance with the Ayurvedic system and the physical parameters chest (uras) circumference, abdomen (udara) circumference and hip (sphik) circumference as enunciated in the classical texts. Certain hepatic and renal function tests were done to examine the safety profile of the treatment regimen. At the end of the treatment period, noteworthy symptomatic improvement was found in the patients; statistically significant (p&amp;lt;0.001) reduction in the physical parameters was noticed; and values of the hepatic and renal parameters remained in their respective normal ranges. No side effects were reported by the patients over the treatment period. The study is affirmative of the efficacy and safety of the Ayurvedic treatment regimen when administered for a period of 120 days to patients of medoroga. The importance of doing exercise in addition to intake of the medicines and a diet pattern in medoroga is emphasized.', '{"arp_id": "ARP_AYU002999", "portal_id": 2999, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "8", "issue": "3", "pages": "379 - 386", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "ENDOCRINE / METABOLIC / NUTRITIONAL", "disease": "OBESITY(ICPC-T82|ICD-E66)", "keywords": ["Ayurvedic Drugs"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/5065", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2999", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002999.pdf", "pdf_sha256": "f71b8b33c1f1d8228e84a02db05ea07a1672e42a8be48b941038ae664cb454c2", "relevance_score": 39.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFICACY AND SAFETY OF RA-11 (O) - A HERBAL ANALGESIC CREAM', '1. Wadnap Neelesh, 1. Johnson Jasmin, 2. Bhatt Narena, 3. Chitre Deepa.', 2006,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: The plant based multi-component formulation; RA-11 (O) has been conceived and developed from Ayurvedic science for topical application in patients with joints pain and swelling. The clinical study was undertaken to test the safety and efficacy of RA-11 (O). Thirty patients, who had joints pain and swelling, with restriction of movement, and were able to understand and sign the informed consent form, were included in the study. The patients were advised to apply the study drug thrice daily for 14 days. There was significant reduction in the Visual Analog Scale score for joints pain on 7th and 14th day (p&amp;lt;0.001). The physician’s assessment of disease showed improvement with 9 patients being a symptomatic on 7th day of treatment and 25 patients being a symptomatic on 14th day of treatment. The patient’s assessment of disease showed a similar resolution of symptoms with 6 patients noting no symptoms on 7th day of treatment (p&amp;lt;0.01) and 23 patients being a symptomatic on 14th day of treatment (p&amp;lt;0.001). Body weight and vital parameters were unaffected over the course of the study. Skin irritation test showed no irritation in any of the patients and no dermal side effects were observed on follow up over 14 days. The domains of pain, freedom of movement and global assessment, which are the core variables in any study of joints pain and swelling; showed significant improvement in the study. RA-11 (O) has been reported as a safe and effective topical cream for relief of joints pain and swelling.', '{"arp_id": "ARP_AYU003005", "portal_id": 3005, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "5", "issue": "3", "pages": "384 - 387", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "RHEUMATOID/SEROPOSITIVE ARTHRITIS(ICPC-L88|ICD-M05, M06, M08, M45)", "keywords": ["Analgesic Cream"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/6912", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3005", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003005.pdf", "pdf_sha256": "9f46e777ae2ee85ec6592482d0cdefac94c30ed102472f1aa0d6111870cb4ff3", "relevance_score": 39.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'ANTIMALARIAL ACTIVITY AND CLINICAL SAFETY OF TRADITIONALLY USED NYCTANTHES ARBOR-TRISTIS LINN.', '1. Karnik SR, 2. Tathed PS, 3. Antarkar DS, 3. Gidse CS, 3. Vaidya RA, 3. Vaidya ADB.', 2008,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Traditional systems of medicine, such as Ayurveda and Chinese medicine in Asia have been provided novel concepts and modalities for healthcare. Critical bedside observations by astute physicians have been followed up by systematic trans-disciplinary research. Such clinical hits of novel biodynamic actions can lead to new drug candidates. In the study, this path was taken up to document antimalarial activity of Nyctanthes arbor-tristis Linn. (Parijat). Nyctanthes arbor-tristis Linn., a popular plant with fragrant flowers described in Ayurveda is being sporadically used for malaria by several Ayurvedic physicians. Patients with malaria were treated with the paste of five fresh leaves of Nyctanthes arbor-tristis Linn, Given orally three times in a day for 7-10 days. The relief of symptoms and signs of malaria and the features of Visham jwara were graded basally and daily. Of 120 patients, ninety two (76.7%) showed complete clinical and parasitic cure within 7 days. Other 20 patients, who then continued on the same treatment, were cured by 10 days. Those patients who did not respond clinically and by parasite clearance were treated with standard antimalarial therapy. Parasite clearance was gradual and showed a direct temporal relationship with the level of initial parasitemia. The paste was well tolerated and no severe side effects were reported. Nyctanthes arbor-tristis Linn, with the dose used showed significant clinical antimalarial activity and good tolerability. A standardized formulation has to be prepared for further studies with critical markers of disease severity as well as parasite clearance.', '{"arp_id": "ARP_AYU003015", "portal_id": 3015, "medical_system": "AYURVEDA", "journal": "Indian Journal of Traditional Knowledge", "volume": "7", "issue": "2", "pages": "330 - 334", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "GENERAL/UNSPECIFIED", "disease": "MALARIA(ICPC-A73|ICD-B50, B51, B52, B53, B54)", "keywords": ["Antimalarial Activity"], "original_url": "https://nopr.niscpr.res.in/handle/123456789/1596", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=3015", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU003015.pdf", "pdf_sha256": "25aefac6b7a0c2f8e216766191ee828988b85619a6653a4d0f66d7caf0c39512", "relevance_score": 39.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EFFICACY, SAFETY AND TOLERABILITY OF HIGH DOSES OF BHALLATAKA IN THE MANAGEMENT OF GRIDHRASI (SCIATICA)', '1. Madhavikutty P, 2. Shanthakumari K, 3. Ramachanan Nair P, 4. Vijayan NP, 5. Tewari NS.', 2001,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Pulling pain starting from hip and radiating through back of the whole leg up to foot is the main symptom of Gridhrasi (sciatica). In Gridhrasi, the main vitiated Dosha is Vata and Vatakapha. The present study aims to find out the optimum dose of Sudha Bhallataka and to establish its anti inflammatory action in the management of Gridhrasi. In this study, starting from lowest dose of 50 mg. to an optimum dose of 12 gm. has been tried in different groups. Both Vardhamana type and Shamana type schedules have been attempted. The result in all the six groups have been recorded statistically significant (P&amp;lt;0.001). The trial in optimum dose has shown better results in comparison to the lowest dose.', '{"arp_id": "ARP_AYU020223", "portal_id": 20223, "medical_system": "AYURVEDA", "journal": "Journal of Research in Ayurveda and Siddha", "volume": "22", "issue": "3-4", "pages": "145 - 160", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "MUSCULOSKELETAL", "disease": "BACK SYNDROME WITH RADIATING PAIN(ICPC-L86|ICD-M47.1, M47.2, M51, M54.3, M54.4)", "keywords": ["Bhallataka"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20223", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020223.pdf", "pdf_sha256": "c41778e39fd70610ce8a4dcdba433f56eff2e152d7f1dc5f900b9cad4718e07d", "relevance_score": 39.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'EVALUATION OF THE CLINICAL EFFECT AND SAFETY OF AYURVEDIC MANAGEMENT IN PAKSHAVADHA (HEMIPLEGIA) - APRAGMATIC APPROACH', '1. Jaya N, 2. Mitra A, 3. Madhavikutty P, 4. Deep VC, 5. Kusuma G.', 2008,
    'randomized_controlled_trial', 'Grade B — Randomized Controlled Trial', 0, 'Background: Panchakarma therapy, the holistic treatment procedure of Ayurveda has been practiced from the ancient time in several clinical manifestations in geriatric including Pakshavadha (hemiplegia), Sandhivata (osteoarthritis), Pangu (paraplegia), other Vatavyadhies (neuromuscular disorders) and other several chronic ailments related to neurological and muscular-skeleton disorders. Ayurvedic Management especially Panchakarma treatment as well as Keraleeya specialities have established its identity in global aspect as the most palatable approach for support and care in old age problems. In this present clinical study, 198 cases of Pakshavadha were studied at the In-patient department of Central Research Institute (Ay.), Cheruthuruthy, Kerala. The trail patients were put into three different treatment groups for 45 days treatment schedule, whereas, study group I consisted with conventional Panchakarma therapy and group II and group III have been dealt with two separate Samana therapies. All study groups were assessed by on the basis of arbitrary neurological scoring as per their subjective and objective improvement. From this study, it has been seen that all study groups had significant improvement as per their treatment regimen. Moreover, as per global assessment and feeling of well being of the patients, it may be concluded that study group I with conventional Panchakarma procedures and Rasausadhies along with Keraleeya specialties in group III were more effective when compared with other group. This study may be treated as the pioneer approach for evaluation of effectiveness of Ayurvedic treatment along with Panchakarma procedure with modern scientific outlook.', '{"arp_id": "ARP_AYU020297", "portal_id": 20297, "medical_system": "AYURVEDA", "journal": "Journal of Research in Ayurveda and Siddha", "volume": "29", "issue": "1", "pages": "85 - 100", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE B", "body_system": "NEUROLOGICAL", "disease": "FACIAL PARALYSIS/BELL&#39;S PALSY(ICPC-N91|ICD-G51, G53)", "keywords": ["Pakshavadha (Hemiplegia)"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=20297", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU020297.pdf", "pdf_sha256": "623f7ff2bd646068a3c0499e6f3844cb19c774191752ec7c9f19e9e0dd35c03e", "relevance_score": 39.0, "topic_domain": "herb_safety_interactions"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'CLINICAL TRIAL OF LEPIDIUM SATIVUM LINN (CHANDRASHURA) IN THE MANAGEMENT OF SANDHIVATA (OSTEOARTHRITIS)', '1. Nita D Raval, 2. Pandya TN.', 2009,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: Lepidium sativum is used in many part of Gujarat as an effective remedy for the disease Sandhivata, Amavata and Katishula. Ayurvedic texts as well as modern texts also reported its analgesic and anti inflammatory properties. In order to validate this claim, a detailed comprehensive study of seed of the plant is done. In this study total 98 patients were divided in two groups. Trial drug group was treated with Chandrashura churna and in placebo group, patients were given capsules containing starch for one month. The patients were subjected to the evaluation of cardinal sign and symptoms of Sandhivata on the basis of scores according to their severity, frequency and duration before and after treatment. Result shows that Chandrashura provides very good relief in cardinal signs and symptoms like Sandhishula (Pain in joint), Sandhishotha (Swelling), Sandhigraha (Stiffness), Sandhisphutana (Crepitus), Sparshashyata (Tenderness), and Aakunchan prasaranjanya vedana (Difficulty in movement).', '{"arp_id": "ARP_AYU002470", "portal_id": 2470, "medical_system": "AYURVEDA", "journal": "AYU", "volume": "30", "issue": "2", "pages": "153 - 157", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "MUSCULOSKELETAL", "disease": "OSTEOARTHROSIS OF KNEE(ICPC-L90|ICD-M17)", "keywords": ["Chandrashura"], "original_url": "https://journals.lww.com/aayu/abstract/2009/30020/clinical_trial_of_lepidium_sativum_linn.9.aspx", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=2470", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU002470.pdf", "pdf_sha256": "b4d03b7693d22b26a1d04fb8c54cd0e7fe6d5635167343488c68035115e3a109", "relevance_score": 39.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
) ON CONFLICT DO NOTHING;
INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'KSHARASUTRA APPLICATION IN THE MANAGEMENT OF PILONIDAL SINUS (NADIVRANA) - A CLINICAL TRIAL', 'Bhaskar Rao M.', 2001,
    'clinical_trial', 'Grade C — Controlled Clinical Study / Cohort', 0, 'Background: This article reports ksharasutra application in pilonidal sinus is a choice of surgical treatment with no recurrences.', '{"arp_id": "ARP_AYU008138", "portal_id": 8138, "medical_system": "AYURVEDA", "journal": "Aryavaidyan", "volume": "14", "issue": "4", "pages": "227 - 230", "category": "CLINICAL RESEARCH", "sub_category": "CLINICAL RESEARCH EVIDENCE GRADE C", "body_system": "SKIN", "disease": "PILONIDAL CYST/FISTULA(ICPC-S85|ICD-L05)", "keywords": ["Ksharasutra"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=8138", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU008138.pdf", "pdf_sha256": "da65a9908e4f561bb4f3ca96f0615981f8fb0d4b96edd67a839f76472759561d", "relevance_score": 39.0, "topic_domain": "clinical_trials_reviews"}'::jsonb
