    'review', 'Evidence Synthesis & Literature Review', 0, 'Background : - Keywords : Ayurveda , Ethno-Botany , Himalayas , Medicinal Plants , Ukhimath URL (for Abstract/ Full paper) : https://www.jaypeedigital.com/abstractArticleContentBrowse/JDRAS/52/5/2/22095/abstractArticle/Article DOI : 10.5005/jdras-10059-0096 Access : -', '{"arp_id": "ARP_AYU001330", "portal_id": 1330, "medical_system": "AYURVEDA", "journal": "Journal of Drug Research in Ayurvedic Sciences", "volume": "5", "issue": "2", "pages": "132 - 138", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Ayurveda"], "original_url": "https://www.jaypeedigital.com/abstractArticleContentBrowse/JDRAS/52/5/2/22095/abstractArticle/Article", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=1330", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU001330.pdf", "pdf_sha256": "d3d6a4e7395733047a426d74d4ad68428f10e0c457f72c9d01dca0b68edea4ac", "relevance_score": 30.0, "topic_domain": "medicinal_plants_phytochemistry"}'::jsonb
