INSERT INTO public.evidence_chunks (
    pmid, doi, title, authors_or_journal, publication_year,
    study_design, evidence_grade, chunk_index, chunk_content, metadata
) VALUES (
    NULL, NULL, 'PRAKRITI STUDY (STUDY OF CONSTITUTION AND TEMPERAMENT) IN THE TREATMENT OF TWO CONSTITUTIONAL DISEASES - PARINAMASULA AND MADHUMEHA (PEPTIC ULCER AND DIABETES MELLITUS)', '1. Venkataraghavan S, 2. Rajagopalan V, 3. Janaki K.', 1981,
    'review', 'Evidence Synthesis & Literature Review', 0, 'Background: Sixty cases of Parinamasula and sixty cases of Madhumeha have been studied for distribution 01&amp;quot; doshic pattern in prakriti for evolving suitable corrective measures for prevention and effective treatment of such constitutional diseases. (Cont..)', '{"arp_id": "ARP_AYU019159", "portal_id": 19159, "medical_system": "AYURVEDA", "journal": "Nagarjun", "volume": "14", "issue": "6", "pages": "246 - 250", "category": "FUNDAMENTAL RESEARCH AND OTHERS", "sub_category": "-", "body_system": "-", "disease": "-", "keywords": ["Madhumeha (Diabetes Mellitus)"], "original_url": "Full Paper in PDF Uploaded", "portal_url": "https://arp.ayush.gov.in/arp/View_Res_Landing_Url?rp6=19159", "pdf_status": "downloaded", "pdf_filename": "ARP_AYU019159.pdf", "pdf_sha256": "cd1033ce35fc1c731b3e9e6110caf6858429a430937d6bcf39f343a422c81ba2", "relevance_score": 28.0, "topic_domain": "prakriti_biomarkers"}'::jsonb
